@Test(timeOut = 10000)
void testRecoverIndividualDeletedMessages() throws Exception {
    BookKeeper bookkeeper = mock(BookKeeper.class);
    ManagedLedgerConfig config = new ManagedLedgerConfig();
    config.setUnackedRangesOpenCacheSetEnabled(true);
    NavigableMap<Long, LedgerInfo> ledgersInfo = new ConcurrentSkipListMap<>();
    ledgersInfo.put(1L, createLedgerInfo(1, 100, 1024));
    ledgersInfo.put(3L, createLedgerInfo(3, 50, 512));
    ledgersInfo.put(5L, createLedgerInfo(5, 200, 2048));
    ledgersInfo.put(10L, createLedgerInfo(10, 2, 32));
    ledgersInfo.put(20L, createLedgerInfo(20, 10, 256));
    ManagedLedgerImpl ledger = mock(ManagedLedgerImpl.class);
    doReturn(ledgersInfo).when(ledger).getLedgersInfo();
    doReturn(config).when(ledger).getConfig();
    ManagedCursorImpl cursor = spy(new ManagedCursorImpl(bookkeeper, ledger, "test-cursor"));
    LongPairRangeSet<Position> deletedMessages = cursor.getIndividuallyDeletedMessagesSet();
    Method recoverMethod = ManagedCursorImpl.class.getDeclaredMethod("recoverIndividualDeletedMessages", List.class);
    recoverMethod.setAccessible(true);
    // (1) [(1:5..1:10]]
    List<MessageRange> messageRangeList = new ArrayList();
    messageRangeList.add(createMessageRange(1, 5, 1, 10));
    List<Range<Position>> expectedRangeList = new ArrayList();
    expectedRangeList.add(createPositionRange(1, 5, 1, 10));
    recoverMethod.invoke(cursor, messageRangeList);
    assertEquals(deletedMessages.size(), 1);
    assertEquals(deletedMessages.asRanges(), expectedRangeList);
    // (2) [(1:10..3:0]]
    messageRangeList.clear();
    messageRangeList.add(createMessageRange(1, 10, 3, 0));
    expectedRangeList.clear();
    expectedRangeList.add(createPositionRange(1, 10, 1, 99));
    expectedRangeList.add(createPositionRange(3, -1, 3, 0));
    recoverMethod.invoke(cursor, messageRangeList);
    assertEquals(deletedMessages.size(), 2);
    assertEquals(deletedMessages.asRanges(), expectedRangeList);
    // (3) [(1:20..10:1],(20:2..20:9]]
    messageRangeList.clear();
    messageRangeList.add(createMessageRange(1, 20, 10, 1));
    messageRangeList.add(createMessageRange(20, 2, 20, 9));
    expectedRangeList.clear();
    expectedRangeList.add(createPositionRange(1, 20, 1, 99));
    expectedRangeList.add(createPositionRange(3, -1, 3, 49));
    expectedRangeList.add(createPositionRange(5, -1, 5, 199));
    expectedRangeList.add(createPositionRange(10, -1, 10, 1));
    expectedRangeList.add(createPositionRange(20, 2, 20, 9));
    recoverMethod.invoke(cursor, messageRangeList);
    assertEquals(deletedMessages.size(), 5);
    assertEquals(deletedMessages.asRanges(), expectedRangeList);
}

@Test(dataProvider = "compressionTypeProvider")
public void testEncodeAndDecode(String compressionType) throws IOException {
    long ledgerId = 10000;
    MLDataFormats.ManagedCursorInfo.Builder builder = generateManagedCursorInfo(ledgerId, 1000);
    MetaStoreImpl metaStore;
    if (INVALID_TYPE.equals(compressionType)) {
        IllegalArgumentException compressionTypeEx = expectThrows(IllegalArgumentException.class, () -> {
            new MetaStoreImpl(null, null, null, new MetadataCompressionConfig(compressionType));
        });
        assertEquals(compressionTypeEx.getMessage(), "No enum constant org.apache.bookkeeper.mledger.proto.MLDataFormats.CompressionType." + compressionType);
        return;
    } else {
        metaStore = new MetaStoreImpl(null, null, null, new MetadataCompressionConfig(compressionType));
    }
    MLDataFormats.ManagedCursorInfo managedCursorInfo = builder.build();
    byte[] compressionBytes = metaStore.compressCursorInfo(managedCursorInfo);
    log.info("[{}] Uncompressed data size: {}, compressed data size: {}", compressionType, managedCursorInfo.getSerializedSize(), compressionBytes.length);
    if (compressionType == null || compressionType.equals(CompressionType.NONE.name())) {
        assertEquals(compressionBytes.length, managedCursorInfo.getSerializedSize());
    }
    // parse compression data and unCompression data, check their results.
    MLDataFormats.ManagedCursorInfo info1 = metaStore.parseManagedCursorInfo(compressionBytes);
    MLDataFormats.ManagedCursorInfo info2 = metaStore.parseManagedCursorInfo(managedCursorInfo.toByteArray());
    assertEquals(info1, info2);
}

@Test(dataProvider = "compressionTypeProvider")
public void testCompressionThreshold(String compressionType) throws IOException {
    int compressThreshold = 512;
    long ledgerId = 10000;
    // should not compress
    MLDataFormats.ManagedCursorInfo smallInfo = generateManagedCursorInfo(ledgerId, 1).build();
    assertTrue(smallInfo.getSerializedSize() < compressThreshold);
    // should compress
    MLDataFormats.ManagedCursorInfo bigInfo = generateManagedCursorInfo(ledgerId, 1000).build();
    assertTrue(bigInfo.getSerializedSize() > compressThreshold);
    MetaStoreImpl metaStore;
    if (INVALID_TYPE.equals(compressionType)) {
        IllegalArgumentException compressionTypeEx = expectThrows(IllegalArgumentException.class, () -> {
            new MetaStoreImpl(null, null, null, new MetadataCompressionConfig(compressionType, compressThreshold));
        });
        assertEquals(compressionTypeEx.getMessage(), "No enum constant org.apache.bookkeeper.mledger.proto.MLDataFormats.CompressionType." + compressionType);
        return;
    } else {
        metaStore = new MetaStoreImpl(null, null, null, new MetadataCompressionConfig(compressionType, compressThreshold));
    }
    byte[] compressionBytes = metaStore.compressCursorInfo(smallInfo);
    // not compressed
    assertEquals(compressionBytes.length, smallInfo.getSerializedSize());
    byte[] compressionBigBytes = metaStore.compressCursorInfo(bigInfo);
    // compressed
    assertTrue(compressionBigBytes.length != smallInfo.getSerializedSize());
}

