    map.put("c", "3");
    futures.add(executeWithRetry(() -> c1.setCursorProperties(map), ManagedLedgerException.BadVersionException.class, 3));
    futures.add(executeWithRetry(() -> c1.putCursorProperty("a", "2"), ManagedLedgerException.BadVersionException.class, 3));
    futures.add(executeWithRetry(() -> c1.removeCursorProperty("c"), ManagedLedgerException.BadVersionException.class, 3));
