        }

        @Override
        public void operationFailed(ManagedLedgerException exception) {
            failed.set(true);
            latch.countDown();
        }
    });
    latch.await();
    if (failed.get()) {
        fail("Cursor recovery should not fail");
    }
    assertEquals(c.getMarkDeletedPosition(), markDeleteBeforeRecover);
