    ManagedLedgerConfig config = new ManagedLedgerConfig();
    config.setEnsembleSize(1).setWriteQuorumSize(1).setAckQuorumSize(1).setMetadataEnsembleSize(1).setMetadataAckQuorumSize(1).setLedgerRolloverTimeout(rolloverTimeForCursorInSeconds);
    ManagedLedger ledger = factory.open("my-ledger" + testName, config);
    ManagedCursor cursor = ledger.openCursor("c1");
    Position pos = ledger.addEntry("entry-0".getBytes());
