@Test(timeOut = 5000)
public void openEncounteredShutdown() throws Exception {
    ManagedLedgerFactoryImpl factory = new ManagedLedgerFactoryImpl(metadataStore, bookKeeper);
    CountDownLatch callbackInvoked = new CountDownLatch(2);
    factory.asyncOpen(ledgerName, new AsyncCallbacks.OpenLedgerCallback() {

        @Override
        public void openLedgerComplete(ManagedLedger ledger, Object ctx) {
            callbackInvoked.countDown();
        }

        @Override
        public void openLedgerFailed(ManagedLedgerException exception, Object ctx) {
            callbackInvoked.countDown();
        }
    }, null);
    factory.asyncOpenReadOnlyCursor(ledgerName, PositionFactory.EARLIEST, new ManagedLedgerConfig(), new AsyncCallbacks.OpenReadOnlyCursorCallback() {

        @Override
        public void openReadOnlyCursorComplete(ReadOnlyCursor cursor, Object ctx) {
            callbackInvoked.countDown();
        }

        @Override
        public void openReadOnlyCursorFailed(ManagedLedgerException exception, Object ctx) {
            log.info("openReadOnlyCursorFailed");
            callbackInvoked.countDown();
        }
    }, null);
    log.info("Shutdown factory...");
    factory.shutdownAsync().get();
    //make zk returned after factory shutdown
    slowZk.countDown();
    //
    Assert.assertTrue(callbackInvoked.await(5, TimeUnit.SECONDS));
    //ManagedLedgerFactoryClosedException should be thrown after factory is shutdown
    Assert.assertThrows(ManagedLedgerException.ManagedLedgerFactoryClosedException.class, () -> factory.open(ledgerName));
    Assert.assertThrows(ManagedLedgerException.ManagedLedgerFactoryClosedException.class, () -> factory.openReadOnlyCursor(ledgerName, PositionFactory.EARLIEST, new ManagedLedgerConfig()));
}

@Test(timeOut = 20000)
public void testGetManagedLedgerInfoWithClose() throws Exception {
    ManagedLedgerConfig conf = new ManagedLedgerConfig();
    conf.setMaxEntriesPerLedger(1);
    ManagedLedgerImpl ledger = (ManagedLedgerImpl) factory.open("testGetManagedLedgerInfo", conf);
    ManagedCursor c1 = ledger.openCursor("c1");
    Position p1 = ledger.addEntry("entry1".getBytes());
    Position p2 = ledger.addEntry("entry2".getBytes());
    Position p3 = ledger.addEntry("entry3".getBytes());
    ledger.addEntry("entry4".getBytes());
    c1.delete(p2);
    c1.delete(p3);
    ledger.close();
    ManagedLedgerInfo info = factory.getManagedLedgerInfo("testGetManagedLedgerInfo");
    assertEquals(info.ledgers.size(), 5);
    assertEquals(info.ledgers.get(0).ledgerId, 3);
    assertEquals(info.ledgers.get(1).ledgerId, 4);
    assertEquals(info.ledgers.get(2).ledgerId, 5);
    assertEquals(info.ledgers.get(3).ledgerId, 6);
    for (ManagedLedgerInfo.LedgerInfo linfo : info.ledgers) {
        assertNotNull(linfo.timestamp);
    }
    assertEquals(info.cursors.size(), 1);
    CursorInfo cursorInfo = info.cursors.get("c1");
    assertEquals(cursorInfo.markDelete.ledgerId, 3);
    assertEquals(cursorInfo.markDelete.entryId, -1);
    assertEquals(cursorInfo.individualDeletedMessages.size(), 2);
    MessageRangeInfo mri = cursorInfo.individualDeletedMessages.get(0);
    assertEquals(mri.from.ledgerId, p2.getLedgerId());
    assertEquals(mri.from.entryId, -1);
    assertEquals(mri.to.ledgerId, p2.getLedgerId());
    assertEquals(mri.to.entryId, 0);
}

