    Position p4 = ledger.addEntry("entry-4".getBytes());
    assertEquals(entryCache.getSize(), 7 * 4);
    assertEquals(cacheManager.getSize(), entryCache.getSize());
    c2.setReadPosition(p4);
    c2.markDelete(p3);
