    for (; i < 25; i++) {
        String content = "entry-" + i;
        ledger.addEntry(content.getBytes());
    }
    assertEquals(ledger.getLedgersInfoAsList().size(), 3);
    metadataStore.failConditional(new MetadataStoreException.BadVersionException("err"), (op, path) -> path.equals("/managed-ledgers/my_test_ledger") && op == FaultInjectionMetadataStore.OperationType.PUT);
    assertThrows(ManagedLedgerException.ManagedLedgerFencedException.class, () -> ledger.offloadPrefix(ledger.getLastConfirmedEntry()));
    assertEquals(ledger.getLedgersInfoAsList().size(), 3);
    // the offloader actually wrote the data on the storage
    assertEquals(ledger.getLedgersInfoAsList().stream().filter(e -> e.getOffloadContext().getComplete()).map(e -> e.getLedgerId()).collect(Collectors.toSet()), offloader.offloadedLedgers());
    // but the ledgers should not be marked as offloaded in local memory, as the write to metadata failed
    ledger.getLedgersInfoAsList().stream().allMatch(l -> !l.hasOffloadContext());
    // check that the ledger is fenced
    assertEquals(ManagedLedgerImpl.State.Fenced, ledger.getState());
}

