    assertEquals(stats.getCount(), 1);
    assertEquals(stats.getBuckets(), new long[] { 1, 0, 0, 0 });
    stats.refresh();
    assertEquals(stats.getAvg(), 15.0);
    assertEquals(stats.getSum(), 15);
    assertEquals(stats.getCount(), 1);
