    restartClusterAfterTest();
    pulsar.getConfiguration().setMaxSubscriptionsPerTopic(0);
    final String myNamespace = newUniqueName(defaultTenant + "/ns");
    admin.namespaces().createNamespace(myNamespace, Set.of("test"));
    final String topic = "persistent://" + myNamespace + "/testMaxSubPerTopic";
    pulsarClient.newProducer().topic(topic).create().close();
    final int maxSub = 2;
    admin.namespaces().setMaxSubscriptionsPerTopic(myNamespace, maxSub);
    PersistentTopic persistentTopic = (PersistentTopic) pulsar.getBrokerService().getTopicIfExists(topic).get().get();
    Awaitility.await().until(() -> persistentTopic.getHierarchyTopicPolicies().getMaxSubscriptionsPerTopic().get() == maxSub);
    List<Consumer<?>> consumerList = new ArrayList<>(maxSub);
    for (int i = 0; i < maxSub; i++) {
        Consumer<?> consumer = pulsarClient.newConsumer().topic(topic).subscriptionName(UUID.randomUUID().toString()).subscribe();
        consumerList.add(consumer);
    }
    //Create a client that can fail quickly
    try (PulsarClient client = PulsarClient.builder().operationTimeout(2, TimeUnit.SECONDS).serviceUrl(brokerUrl.toString()).build()) {
        @Cleanup
        Consumer<byte[]> subscribe = client.newConsumer().topic(topic).subscriptionName(UUID.randomUUID().toString()).subscribe();
        fail("should fail");
    } catch (Exception ignore) {
    }
    //After removing the restriction, it should be able to create normally
    admin.namespaces().removeMaxSubscriptionsPerTopic(myNamespace);
    Awaitility.await().until(() -> persistentTopic.getHierarchyTopicPolicies().getMaxSubscriptionsPerTopic().get() == 0);
    Consumer<?> consumer = pulsarClient.newConsumer().topic(topic).subscriptionName(UUID.randomUUID().toString()).subscribe();
    consumerList.add(consumer);
    for (Consumer<?> c : consumerList) {
        c.close();
    }
}

