    final String persistentTopicName = TopicName.get("persistent", NamespaceName.get(namespace), "get_topics_mode_" + UUID.randomUUID()).toString();
    final String nonPersistentTopicName = TopicName.get("non-persistent", NamespaceName.get(namespace), "get_topics_mode_" + UUID.randomUUID()).toString();
