@Test(groups = "flaky")
public void testForceDeletePartitionedTopicWithSub() throws Exception {
    final int numPartitions = 10;
    TenantInfoImpl tenantInfo = new TenantInfoImpl(Set.of("role1", "role2"), Set.of("test"));
    admin.tenants().createTenant("tenant-xyz", tenantInfo);
    admin.namespaces().createNamespace("tenant-xyz/ns-abc", Set.of("test"));
    admin.namespaces().setAutoTopicCreation("tenant-xyz/ns-abc", AutoTopicCreationOverride.builder().allowAutoTopicCreation(true).topicType("partitioned").defaultNumPartitions(5).build());
    RetentionPolicies retention = new RetentionPolicies(10, 10);
    admin.namespaces().setRetention("tenant-xyz/ns-abc", retention);
    final String topic = "persistent://tenant-xyz/ns-abc/topic-" + RandomStringUtils.randomAlphabetic(5) + "-testDeletePartitionedTopicWithSub";
    final String subscriptionName = "sub";
    ((TopicsImpl) admin.topics()).createPartitionedTopicAsync(topic, numPartitions, true, null).get();
    log.info("Creating producer and consumer");
    Consumer<byte[]> consumer = pulsarClient.newConsumer().topic(topic).subscriptionName(subscriptionName).subscribe();
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).enableBatching(false).topic(topic).create();
    log.info("producing messages");
    for (int i = 0; i < numPartitions * 100; ++i) {
        producer.newMessage().key("" + i).value("value-" + i).send();
    }
    producer.flush();
    log.info("consuming some messages");
    for (int i = 0; i < numPartitions * 5; i++) {
        Message<byte[]> m = consumer.receive(1, TimeUnit.MINUTES);
    }
    log.info("trying to delete the topic {}", topic);
    admin.topics().deletePartitionedTopic(topic, true);
    log.info("closing producer and consumer");
    producer.close();
    consumer.close();
    // topic autocreate might sneak in after the delete / before close
    // but the topic metadata should be consistent to go through deletion again
    if (admin.topics().getList("tenant-xyz/ns-abc").stream().anyMatch(t -> t.contains(topic))) {
        try {
            admin.topics().deletePartitionedTopic(topic, true);
        } catch (PulsarAdminException.NotFoundException nfe) {
            // pass
        }
        assertEquals(0, admin.topics().getList("tenant-xyz/ns-abc").stream().filter(t -> t.contains(topic)).count());
        assertEquals(0, pulsar.getPulsarResources().getTopicResources().getExistingPartitions(TopicName.getPartitionedTopicName(topic)).get().stream().filter(t -> t.contains(topic)).count());
        assertFalse(admin.topics().getPartitionedTopicList("tenant-xyz/ns-abc").contains(topic));
    } else {
        log.info("trying to create the topic again");
        ((TopicsImpl) admin.topics()).createPartitionedTopicAsync(topic, numPartitions, true, null).get();
    }
}

