        Message<byte[]> message = consumer.receive();
        consumer.acknowledge(message);
    }
    admin.topics().resetCursor(topicName, "my-sub", firstTimestamp);
    int receivedAfterReset = 0;
    // Should received messages from 5-9
    for (int i = 5; i < 10; i++) {
        Message<byte[]> message = consumer.receive();
