/**
 * Validates Pulsar-admin performs auto cert refresh.
 * @throws Exception
 */
@Test
public void testCertRefreshForPulsarAdmin() throws Exception {
    String adminUser = "admin";
    String user2 = "user1";
    File keyFile = File.createTempFile("temp", ".key-pk8");
    Path keyFilePath = Paths.get(keyFile.getAbsolutePath());
    int autoCertRefreshTimeSec = 1;
    try {
        Files.copy(Paths.get(getTlsFileForClient(user2 + ".key-pk8")), keyFilePath, StandardCopyOption.REPLACE_EXISTING);
        @Cleanup
        PulsarAdmin admin = PulsarAdmin.builder().allowTlsInsecureConnection(false).enableTlsHostnameVerification(false).serviceHttpUrl(brokerUrlTls.toString()).autoCertRefreshTime(autoCertRefreshTimeSec, TimeUnit.SECONDS).authentication("org.apache.pulsar.client.impl.auth.AuthenticationTls", String.format("tlsCertFile:%s,tlsKeyFile:%s", getTlsFileForClient(adminUser + ".cert"), keyFile)).tlsTrustCertsFilePath(CA_CERT_FILE_PATH).build();
        // try to call admin-api which should fail due to incorrect key-cert
        try {
            admin.tenants().createTenant("tenantX", new TenantInfoImpl(Set.of("foobar"), Set.of("test")));
            Assert.fail("should have failed due to invalid key file");
        } catch (Exception e) {
            //OK
        }
        // replace correct key file
        Files.delete(keyFile.toPath());
        Thread.sleep(2 * autoCertRefreshTimeSec * 1000);
        Files.copy(Paths.get(getTlsFileForClient(adminUser + ".key-pk8")), keyFilePath);
        MutableBoolean success = new MutableBoolean(false);
        retryStrategically((test) -> {
            try {
                admin.tenants().createTenant("tenantX", new TenantInfoImpl(Set.of("foobar"), Set.of("test")));
                success.setValue(true);
                return true;
            } catch (Exception e) {
                return false;
            }
        }, 5, 1000);
        Assert.assertTrue(success.booleanValue());
        Assert.assertEquals(Set.of("tenantX"), admin.tenants().getTenants());
    } finally {
        Files.delete(keyFile.toPath());
    }
}

