public void testBasic() throws Exception {
    // no map
    BookiesRackConfiguration conf = (BookiesRackConfiguration) admin.bookies().getBookiesRackInfo();
    assertTrue(conf.isEmpty());
    String bookie0 = "127.0.0.1:3181";
