@Test(dataProvider = "subscriptionMode")
public void addSubscriptionPropertiesTest(SubscriptionMode subscriptionMode) throws Exception {
    String topic = "persistent://my-property/my-ns/topic" + UUID.randomUUID();
    admin.topics().createNonPartitionedTopic(topic);
    Map<String, String> map = new HashMap<>();
    map.put("1", "1");
    map.put("2", "2");
    String subName = "my-sub";
    Consumer<byte[]> consumer = pulsarClient.newConsumer().subscriptionMode(subscriptionMode).topic(topic).receiverQueueSize(1).subscriptionProperties(map).subscriptionName(subName).subscribe();
    PersistentSubscription subscription = (PersistentSubscription) pulsar.getBrokerService().getTopicReference(topic).get().getSubscription(subName);
    Map<String, String> properties = subscription.getSubscriptionProperties();
    assertEquals(properties, map);
    // after updating mark delete position, the properties should still exist
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topic).create();
    for (int i = 0; i < 10; i++) {
        producer.send("msg".getBytes(StandardCharsets.UTF_8));
    }
    Message message = consumer.receive(1, TimeUnit.SECONDS);
    assertNotNull(message);
    consumer.acknowledge(message);
    MessageIdImpl messageId = (MessageIdImpl) message.getMessageId();
    Awaitility.await().untilAsserted(() -> {
        assertEquals(subscription.getCursor().getMarkDeletedPosition().getLedgerId(), messageId.getLedgerId());
        assertEquals(subscription.getCursor().getMarkDeletedPosition().getEntryId(), messageId.getEntryId());
    });
    properties = subscription.getSubscriptionProperties();
    assertEquals(properties, map);
    consumer.close();
    producer.close();
    // restart broker, consumer use old properties
    restartBroker();
    Consumer<byte[]> consumer2 = pulsarClient.newConsumer().topic(topic).subscriptionMode(subscriptionMode).receiverQueueSize(1).subscriptionProperties(map).subscriptionName(subName).subscribe();
    PersistentSubscription subscription2 = (PersistentSubscription) pulsar.getBrokerService().getTopicReference(topic).get().getSubscription(subName);
    Awaitility.await().untilAsserted(() -> {
        Map<String, String> properties2 = subscription2.getSubscriptionProperties();
        assertEquals(properties2, map);
    });
    consumer2.close();
    // create a new consumer with new properties, the new properties should be ignored
    Map<String, String> map3 = new HashMap<>();
    map3.put("3", "3");
    map3.put("4", "4");
    Consumer<byte[]> consumer3 = pulsarClient.newConsumer().topic(topic).subscriptionMode(subscriptionMode).receiverQueueSize(1).subscriptionProperties(map3).subscriptionName(subName).subscribe();
    Map<String, String> properties3 = subscription.getSubscriptionProperties();
    assertEquals(properties3, map);
    consumer3.close();
    //restart and create a new consumer with new properties, the new properties must not be updated
    // for a Durable subscription, but for a NonDurable subscription we pick up the new values
    restartBroker();
    Consumer<byte[]> consumer4 = pulsarClient.newConsumer().subscriptionMode(subscriptionMode).topic(topic).receiverQueueSize(1).subscriptionProperties(map3).subscriptionName(subName).subscribe();
    PersistentSubscription subscription4 = (PersistentSubscription) pulsar.getBrokerService().getTopicReference(topic).get().getSubscription(subName);
    Map<String, String> properties4 = subscription4.getSubscriptionProperties();
    if (subscriptionMode == SubscriptionMode.Durable) {
        assertEquals(properties4, map);
    } else {
        assertEquals(properties4, map3);
    }
    consumer4.close();
    //consumer subscribe without subscriptionProperties set, it will get the old one for a Durable Subscription
    // it will use the new (empty) set for a NonDurable Subscription
    // so for Non-Durable subscriptions you have always to re-connect with the same properties
    consumer4 = pulsarClient.newConsumer().topic(topic).subscriptionMode(subscriptionMode).receiverQueueSize(1).subscriptionName(subName).subscribe();
    subscription4 = (PersistentSubscription) pulsar.getBrokerService().getTopicReference(topic).get().getSubscription(subName);
    properties4 = subscription4.getSubscriptionProperties();
    if (subscriptionMode == SubscriptionMode.Durable) {
        assertEquals(properties4, map);
    } else {
        assertTrue(properties4.isEmpty());
    }
    consumer4.close();
    //restart broker, properties for Durable subscription are reloaded from Metadata
    restartBroker();
    consumer4 = pulsarClient.newConsumer().topic(topic).subscriptionMode(subscriptionMode).receiverQueueSize(1).subscriptionName(subName).subscribe();
    subscription4 = (PersistentSubscription) pulsar.getBrokerService().getTopicReference(topic).get().getSubscription(subName);
    properties4 = subscription4.getSubscriptionProperties();
    if (subscriptionMode == SubscriptionMode.Durable) {
        assertEquals(properties4, map);
    } else {
        assertTrue(properties4.isEmpty());
    }
    consumer4.close();
    //restart broker and create a new consumer with new properties, the properties will not be updated
    restartBroker();
    consumer4 = pulsarClient.newConsumer().topic(topic).receiverQueueSize(1).subscriptionMode(subscriptionMode).subscriptionProperties(map).subscriptionName(subName).subscribe();
    PersistentSubscription subscription5 = (PersistentSubscription) pulsar.getBrokerService().getTopicReference(topic).get().getSubscription(subName);
    properties4 = subscription5.getSubscriptionProperties();
    // for the NonDurable subscription here we have the same properties because they
    // are sent by the Consumer
    assertEquals(properties4, map);
    consumer4.close();
    String subNameShared = "my-sub-shared";
    Map<String, String> mapShared = new HashMap<>();
    mapShared.put("6", "7");
    // open two consumers with a Shared Subscription
    Consumer consumerShared1 = pulsarClient.newConsumer().topic(topic).receiverQueueSize(1).subscriptionMode(subscriptionMode).subscriptionType(SubscriptionType.Shared).subscriptionProperties(mapShared).subscriptionName(subNameShared).subscribe();
    PersistentSubscription subscriptionShared = (PersistentSubscription) pulsar.getBrokerService().getTopicReference(topic).get().getSubscription(subNameShared);
    properties = subscriptionShared.getSubscriptionProperties();
    assertEquals(properties, mapShared);
    // add a new consumer, the properties are not updated
    Map<String, String> mapShared2 = new HashMap<>();
    mapShared2.put("8", "9");
    Consumer consumerShared2 = pulsarClient.newConsumer().topic(topic).receiverQueueSize(1).subscriptionMode(subscriptionMode).subscriptionType(SubscriptionType.Shared).subscriptionProperties(mapShared2).subscriptionName(subNameShared).subscribe();
    properties = subscriptionShared.getSubscriptionProperties();
    assertEquals(properties, mapShared);
    // add a third consumer, the properties are NOT updated
    Map<String, String> mapShared3 = new HashMap<>();
    mapShared3.put("10", "11");
    Consumer consumerShared3 = pulsarClient.newConsumer().topic(topic).receiverQueueSize(1).subscriptionMode(subscriptionMode).subscriptionType(SubscriptionType.Shared).subscriptionProperties(mapShared3).subscriptionName(subNameShared).subscribe();
    properties = subscriptionShared.getSubscriptionProperties();
    // verify that the properties are not updated
    assertEquals(properties, mapShared);
    consumerShared1.close();
    consumerShared2.close();
    consumerShared3.close();
}

