    clearAuthorizationOperationChecker();
    for (AuthAction action : AuthAction.values()) {
        superUserAdmin.namespaces().grantPermissionOnNamespace(namespace, subject, Set.of(action));
        Assert.assertThrows(PulsarAdminException.NotAuthorizedException.class, () -> subAdmin.namespaces().grantPermissionOnSubscription(namespace, subscription, Set.of(role)));
        Assert.assertThrows(PulsarAdminException.NotAuthorizedException.class, () -> subAdmin.namespaces().getPermissionOnSubscription(namespace));
        Assert.assertThrows(PulsarAdminException.NotAuthorizedException.class, () -> subAdmin.namespaces().revokePermissionOnSubscription(namespace, subscription, role));
        superUserAdmin.namespaces().revokePermissionsOnNamespace(namespace, subject);
    }
    superUserAdmin.topics().delete(topic, true);
}

