public void testCreateNamespaces() throws Exception {
    try {
        asyncRequests(response -> namespaces.createNamespace(response, this.testTenant, "other-colo", "my-namespace", BundlesData.builder().build()));
        fail("should have failed");
    } catch (RestException e) {
        // Ok, cluster doesn't exist
    }
    List<NamespaceName> nsnames = new ArrayList<>();
    nsnames.add(NamespaceName.get(this.testTenant, "use", "create-namespace-1"));
    nsnames.add(NamespaceName.get(this.testTenant, "use", "create-namespace-2"));
    nsnames.add(NamespaceName.get(this.testTenant, "usc", "create-other-namespace-1"));
    createTestNamespaces(nsnames, BundlesData.builder().build());
    try {
        asyncRequests(response -> namespaces.createNamespace(response, this.testTenant, "use", "create-namespace-1", BundlesData.builder().build()));
        fail("should have failed");
    } catch (RestException e) {
        // Ok, namespace already exists
    }
    try {
        asyncRequests(response -> namespaces.createNamespace(response, "non-existing-tenant", "use", "create-namespace-1", BundlesData.builder().build()));
        fail("should have failed");
    } catch (RestException e) {
        // Ok, tenant doesn't exist
    }
    try {
        asyncRequests(response -> namespaces.createNamespace(response, this.testTenant, "use", "create-namespace-#", BundlesData.builder().build()));
        fail("should have failed");
