@Test
public void testGlobalNamespaceReplicationConfiguration() throws Exception {
    Set<String> repCluster = (Set<String>) asyncRequests(rsp -> namespaces.getNamespaceReplicationClusters(rsp, this.testGlobalNamespaces.get(0).getTenant(), this.testGlobalNamespaces.get(0).getCluster(), this.testGlobalNamespaces.get(0).getLocalName()));
    assertEquals(repCluster, new HashSet<>());
    asyncRequests(rsp -> namespaces.setNamespaceReplicationClusters(rsp, this.testGlobalNamespaces.get(0).getTenant(), this.testGlobalNamespaces.get(0).getCluster(), this.testGlobalNamespaces.get(0).getLocalName(), List.of("use", "usw")));
    repCluster = (Set<String>) asyncRequests(rsp -> namespaces.getNamespaceReplicationClusters(rsp, this.testGlobalNamespaces.get(0).getTenant(), this.testGlobalNamespaces.get(0).getCluster(), this.testGlobalNamespaces.get(0).getLocalName()));
    assertEquals(repCluster, List.of("use", "usw"));
    try {
        asyncRequests(rsp -> namespaces.setNamespaceReplicationClusters(rsp, this.testGlobalNamespaces.get(0).getTenant(), this.testGlobalNamespaces.get(0).getCluster(), this.testGlobalNamespaces.get(0).getLocalName(), List.of("use", "invalid-cluster")));
        fail("should have failed");
    } catch (RestException e) {
        assertEquals(e.getResponse().getStatus(), Status.FORBIDDEN.getStatusCode());
    }
    try {
        asyncRequests(rsp -> namespaces.setNamespaceReplicationClusters(rsp, this.testGlobalNamespaces.get(0).getTenant(), this.testGlobalNamespaces.get(0).getCluster(), this.testGlobalNamespaces.get(0).getLocalName(), List.of("use", "global")));
        fail("should have failed");
    } catch (RestException e) {
        // Ok, global should not be allowed in the list of replication clusters
        assertEquals(e.getResponse().getStatus(), Status.PRECONDITION_FAILED.getStatusCode());
    }
    try {
        asyncRequests(rsp -> namespaces.setNamespaceReplicationClusters(rsp, this.testTenant, "global", this.testGlobalNamespaces.get(0).getLocalName(), List.of("use", "invalid-cluster")));
        fail("should have failed");
    } catch (RestException e) {
        // Ok, invalid-cluster is an invalid cluster id
        assertEquals(e.getResponse().getStatus(), Status.FORBIDDEN.getStatusCode());
    }
    admin.tenants().updateTenant(testTenant, new TenantInfoImpl(Set.of("role1", "role2"), Set.of("use", "usc")));
    try {
        asyncRequests(rsp -> namespaces.setNamespaceReplicationClusters(rsp, this.testTenant, "global", this.testGlobalNamespaces.get(0).getLocalName(), List.of("use", "usw")));
        fail("should have failed");
    } catch (RestException e) {
        // Ok, usw was not configured in the list of allowed clusters
        assertEquals(e.getResponse().getStatus(), Status.FORBIDDEN.getStatusCode());
    }
    // Sometimes watcher event consumes scheduled exception, so set to always fail to ensure exception is
    // thrown for api call.
    mockZooKeeperGlobal.setAlwaysFail(Code.SESSIONEXPIRED);
    try {
        asyncRequests(rsp -> namespaces.setNamespaceReplicationClusters(rsp, this.testTenant, "global", this.testGlobalNamespaces.get(0).getLocalName(), List.of("use")));
        fail("should have failed");
    } catch (RestException e) {
        assertEquals(e.getResponse().getStatus(), Status.INTERNAL_SERVER_ERROR.getStatusCode());
    } finally {
        mockZooKeeperGlobal.unsetAlwaysFail();
    }
    // clear caches to load data from metadata-store again
    MetadataCacheImpl<Policies> policiesCache = (MetadataCacheImpl<Policies>) pulsar.getPulsarResources().getNamespaceResources().getCache();
    AbstractMetadataStore store = (AbstractMetadataStore) policiesCache.getStore();
    mockZooKeeperGlobal.failConditional(Code.SESSIONEXPIRED, (op, path) -> {
        return op == MockZooKeeper.Op.SET && path.equals("/admin/policies/my-tenant/global/test-global-ns1");
    });
    policiesCache.invalidateAll();
    store.invalidateAll();
    try {
        asyncRequests(rsp -> namespaces.setNamespaceReplicationClusters(rsp, this.testTenant, "global", this.testGlobalNamespaces.get(0).getLocalName(), List.of("use")));
        fail("should have failed");
    } catch (RestException e) {
        assertEquals(e.getResponse().getStatus(), 500);
    }
    try {
        asyncRequests(rsp -> namespaces.getNamespaceReplicationClusters(rsp, this.testTenant, "global", "non-existing-ns"));
        fail("should have failed");
    } catch (RestException e) {
        assertEquals(e.getResponse().getStatus(), Status.NOT_FOUND.getStatusCode());
    }
    try {
        asyncRequests(rsp -> namespaces.setNamespaceReplicationClusters(rsp, this.testTenant, "global", "non-existing-ns", List.of("use")));
        fail("should have failed");
    } catch (RestException e) {
        assertEquals(e.getResponse().getStatus(), Status.NOT_FOUND.getStatusCode());
    }
