@Test
public void testUnloadAndCompactAndTrim() {
    final String random = UUID.randomUUID().toString();
    final String topic = "persistent://public/default/" + random;
    final String subject = UUID.randomUUID().toString();
    final String token = Jwts.builder().claim("sub", subject).signWith(SECRET_KEY).compact();
    superUserAdmin.topics().createPartitionedTopic(topic, 2);
    @Cleanup
    final PulsarAdmin subAdmin = PulsarAdmin.builder().serviceHttpUrl(getPulsarService().getWebServiceAddress()).authentication(new AuthenticationToken(token)).build();
    // test superuser
    superUserAdmin.topics().unload(topic);
    superUserAdmin.topics().triggerCompaction(topic);
    superUserAdmin.topics().trimTopic(TopicName.get(topic).getPartition(0).getLocalName());
    superUserAdmin.topicPolicies().getSchemaCompatibilityStrategy(topic, false);
    // test tenant manager
    tenantManagerAdmin.topics().unload(topic);
    tenantManagerAdmin.topics().triggerCompaction(topic);
    tenantManagerAdmin.topics().trimTopic(TopicName.get(topic).getPartition(0).getLocalName());
    tenantManagerAdmin.topicPolicies().getSchemaCompatibilityStrategy(topic, false);
    // test nobody
    Assert.assertThrows(PulsarAdminException.NotAuthorizedException.class, () -> subAdmin.topics().unload(topic));
    Assert.assertThrows(PulsarAdminException.NotAuthorizedException.class, () -> subAdmin.topics().triggerCompaction(topic));
    Assert.assertThrows(PulsarAdminException.NotAuthorizedException.class, () -> subAdmin.topics().trimTopic(TopicName.get(topic).getPartition(0).getLocalName()));
    Assert.assertThrows(PulsarAdminException.NotAuthorizedException.class, () -> subAdmin.topicPolicies().getSchemaCompatibilityStrategy(topic, false));
    // Test only super/admin can do the operation, other auth are not permitted.
    for (AuthAction action : AuthAction.values()) {
        superUserAdmin.topics().grantPermission(topic, subject, Set.of(action));
        Assert.assertThrows(PulsarAdminException.NotAuthorizedException.class, () -> subAdmin.topics().unload(topic));
        Assert.assertThrows(PulsarAdminException.NotAuthorizedException.class, () -> subAdmin.topics().triggerCompaction(topic));
        Assert.assertThrows(PulsarAdminException.NotAuthorizedException.class, () -> subAdmin.topics().trimTopic(topic));
        Assert.assertThrows(PulsarAdminException.NotAuthorizedException.class, () -> subAdmin.topicPolicies().getSchemaCompatibilityStrategy(topic, false));
        superUserAdmin.topics().revokePermissions(topic, subject);
    }
    superUserAdmin.topics().deletePartitionedTopic(topic, true);
}

