@Test(timeOut = 20000)
public void testRestart() throws Exception {
    final String topic = testTopic + UUID.randomUUID();
    admin.topics().createNonPartitionedTopic(topic);
    // set namespace level inactive topic policies
    InactiveTopicPolicies inactiveTopicPolicies = new InactiveTopicPolicies(InactiveTopicDeleteMode.delete_when_subscriptions_caught_up, 100, true);
    admin.namespaces().setInactiveTopicPolicies(myNamespace, inactiveTopicPolicies);
    Awaitility.await().untilAsserted(() -> Assert.assertEquals(admin.namespaces().getInactiveTopicPolicies(myNamespace).getInactiveTopicDeleteMode(), InactiveTopicDeleteMode.delete_when_subscriptions_caught_up));
    // set namespace retention policies
    final RetentionPolicies retentionPolicies = new RetentionPolicies(10, -1);
    admin.namespaces().setRetention(myNamespace, retentionPolicies);
    Awaitility.await().untilAsserted(() -> Assert.assertEquals(admin.namespaces().getRetention(myNamespace), retentionPolicies));
    // set topic level inactive topic policies
    inactiveTopicPolicies = new InactiveTopicPolicies(InactiveTopicDeleteMode.delete_when_no_subscriptions, 200, false);
    admin.topicPolicies().setInactiveTopicPolicies(topic, inactiveTopicPolicies);
    InactiveTopicPolicies finalInactiveTopicPolicies = inactiveTopicPolicies;
    Awaitility.await().untilAsserted(() -> Assert.assertEquals(admin.topicPolicies().getInactiveTopicPolicies(topic), finalInactiveTopicPolicies));
    // set topic level retention policies
    final RetentionPolicies finalRetentionPolicies = new RetentionPolicies(20, -1);
    admin.topicPolicies().setRetention(topic, finalRetentionPolicies);
    Awaitility.await().untilAsserted(() -> Assert.assertEquals(admin.topicPolicies().getRetention(topic), finalRetentionPolicies));
    // restart broker, policy should still take effect
    restartBroker();
    // Trigger the cache init.
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topic).create();
    // check inactive topic policies and retention policies.
    Awaitility.await().untilAsserted(() -> {
        PersistentTopic persistentTopic = (PersistentTopic) pulsar.getBrokerService().getTopicIfExists(topic).get().get();
        ManagedLedgerConfig managedLedgerConfig = persistentTopic.getManagedLedger().getConfig();
        Assert.assertEquals(persistentTopic.getInactiveTopicPolicies(), finalInactiveTopicPolicies);
        Assert.assertEquals(managedLedgerConfig.getRetentionSizeInMB(), finalRetentionPolicies.getRetentionSizeInMB());
        Assert.assertEquals(managedLedgerConfig.getRetentionTimeMillis(), TimeUnit.MINUTES.toMillis(finalRetentionPolicies.getRetentionTimeInMinutes()));
    });
    producer.close();
}

