    } catch (NotFoundException expected) {
    }
    // create consumer and subscription
    @Cleanup
    PulsarClient client = PulsarClient.builder().serviceUrl(pulsar.getWebServiceAddress()).statsInterval(0, TimeUnit.SECONDS).build();
