public void testNamespaceSplitBundleConcurrent() throws Exception {
    // Force to create a topic
    final String namespace = "prop-xyz/use/ns1";
    final String topicName = "persistent://" + namespace + "/ds2";
    Producer<byte[]> producer = pulsarClient.newProducer(Schema.BYTES).topic(topicName).enableBatching(false).messageRoutingMode(MessageRoutingMode.SinglePartition).create();
