@Test
public void testRedirectOfGetCoordinatorInternalStats() throws Exception {
    PulsarAdmin localAdmin = this.admin;
    Map<String, String> map = localAdmin.lookups().lookupPartitionedTopic(SystemTopicNames.TRANSACTION_COORDINATOR_ASSIGN.toString());
    for (int i = 0; map.containsValue(getPulsarServiceList().get(i).getBrokerServiceUrl()); i++) {
        if (!map.containsValue(getPulsarServiceList().get(i + 1).getBrokerServiceUrl()))
            if (localAdmin != null) {
                localAdmin.close();
            }
        localAdmin = spy(createNewPulsarAdmin(PulsarAdmin.builder().serviceHttpUrl(pulsarServiceList.get(i + 1).getWebServiceAddress())));
    }
    if (pulsarClient != null) {
        pulsarClient.shutdown();
    }
    //init tc stores
    pulsarClient = PulsarClient.builder().serviceUrl(getPulsarServiceList().get(0).getBrokerServiceUrl()).statsInterval(0, TimeUnit.SECONDS).enableTransaction(true).build();
    for (int i = 0; i < NUM_PARTITIONS; i++) {
        localAdmin.transactions().getCoordinatorInternalStats(i, false);
    }
    localAdmin.close();
}

