        String segmentTopicBroker = admin.lookups().lookupTopic(NAMESPACE1 + "/" + SystemTopicNames.TRANSACTION_BUFFER_SNAPSHOT_SEGMENTS);
        String indexTopicBroker = admin.lookups().lookupTopic(NAMESPACE1 + "/" + SystemTopicNames.TRANSACTION_BUFFER_SNAPSHOT_INDEXES);
        if (segmentTopicBroker.equals(indexTopicBroker)) {
            String topicBroker = admin.lookups().lookupTopic(topic1);
            if (!topicBroker.equals(segmentTopicBroker)) {
                break;
            }
        } else {
            break;
        }
    }
    @Cleanup
