    assertNotNull(stats.segmentInternalStats);
    assertTrue(stats.segmentInternalStats.managedLedgerName.contains(SystemTopicNames.TRANSACTION_BUFFER_SNAPSHOT_SEGMENTS));
    assertNotNull(stats.segmentIndexInternalStats);
