@Test
public void testGetPositionStatsInPendingAckStatsFroBatch() throws Exception {
    String topic = "persistent://public/default/test";
    String subscriptionName = "my-subscription-batch";
    initTransaction(1);
    pulsar.getBrokerService().getManagedLedgerConfig(TopicName.get(topic)).get().setDeletionAtBatchIndexLevelEnabled(true);
    @Cleanup
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).enableBatching(true).batchingMaxMessages(3).// set batch max publish delay big enough to make sure entry has 3 messages
    batchingMaxPublishDelay(3, TimeUnit.SECONDS).topic(topic).create();
    @Cleanup
    Consumer<String> consumer = pulsarClient.newConsumer(Schema.STRING).subscriptionName(subscriptionName).enableBatchIndexAcknowledgment(true).subscriptionType(SubscriptionType.Shared).isAckReceiptEnabled(true).topic(topic).subscribe();
    List<MessageId> messageIds = new ArrayList<>();
    List<CompletableFuture<MessageId>> futureMessageIds = new ArrayList<>();
    List<String> messages = new ArrayList<>();
    for (int i = 0; i < 3; i++) {
        String message = "my-message-" + i;
        messages.add(message);
        CompletableFuture<MessageId> messageIdCompletableFuture = producer.sendAsync(message);
        futureMessageIds.add(messageIdCompletableFuture);
    }
    for (CompletableFuture<MessageId> futureMessageId : futureMessageIds) {
        MessageId messageId = futureMessageId.get();
        messageIds.add(messageId);
    }
    Transaction transaction = pulsarClient.newTransaction().withTransactionTimeout(5, TimeUnit.DAYS).build().get();
    Message<String> message1 = consumer.receive();
    Message<String> message2 = consumer.receive();
    BatchMessageIdImpl messageId = (BatchMessageIdImpl) message2.getMessageId();
    consumer.acknowledgeAsync(messageId, transaction).get();
    PositionInPendingAckStats positionStatsInPendingAckStats = admin.transactions().getPositionStatsInPendingAck(topic, subscriptionName, messageId.getLedgerId(), messageId.getEntryId(), 1);
    assertEquals(positionStatsInPendingAckStats.state, PositionInPendingAckStats.State.PendingAck);
    positionStatsInPendingAckStats = admin.transactions().getPositionStatsInPendingAck(topic, subscriptionName, messageId.getLedgerId(), messageId.getEntryId(), 2);
    assertEquals(positionStatsInPendingAckStats.state, PositionInPendingAckStats.State.NotInPendingAck);
    positionStatsInPendingAckStats = admin.transactions().getPositionStatsInPendingAck(topic, subscriptionName, messageId.getLedgerId(), messageId.getEntryId(), 10);
    assertEquals(positionStatsInPendingAckStats.state, PositionInPendingAckStats.State.InvalidPosition);
}

