    for (int i = 0; i < 2; ++i) {
        final ServiceUnitId serviceUnit = makeBundle(Integer.toString(i));
        final String broker = primaryLoadManager.selectBrokerForAssignment(serviceUnit).get();
        if (broker.equals(primaryBrokerId)) {
