@Test
public void testBacklogAndRetentionCheck() throws PulsarServerException {
    ServiceConfiguration config = new ServiceConfiguration();
    config.setClusterName("test");
    config.setMetadataStoreUrl("memory:local");
    config.setMetadataStoreConfigPath("memory:local");
    PulsarService pulsarService = new PulsarService(config);
    // Check the default configuration
    try {
        pulsarService.start();
    } catch (Exception e) {
        assertFalse(e.getCause() instanceof IllegalArgumentException);
    } finally {
        pulsarService.close();
    }
    // Only set retention
    config.setDefaultRetentionSizeInMB(5);
    config.setDefaultRetentionTimeInMinutes(5);
    pulsarService = new PulsarService(config);
    try {
        pulsarService.start();
    } catch (Exception e) {
        assertFalse(e.getCause() instanceof IllegalArgumentException);
    } finally {
        pulsarService.close();
    }
    // Set both retention and backlog quota
    config.setBacklogQuotaDefaultLimitBytes(4 * 1024 * 1024);
    config.setBacklogQuotaDefaultLimitSecond(4 * 60);
    pulsarService = new PulsarService(config);
    try {
        pulsarService.start();
    } catch (Exception e) {
        assertFalse(e.getCause() instanceof IllegalArgumentException);
    } finally {
        pulsarService.close();
    }
    // Set invalidated retention and backlog quota
    config.setBacklogQuotaDefaultLimitBytes(6 * 1024 * 1024);
    pulsarService = new PulsarService(config);
    try {
        pulsarService.start();
    } catch (Exception e) {
        assertTrue(e.getCause() instanceof IllegalArgumentException);
    } finally {
        pulsarService.close();
    }
    config.setBacklogQuotaDefaultLimitBytes(4 * 1024 * 1024);
    config.setBacklogQuotaDefaultLimitSecond(6 * 60);
    pulsarService = new PulsarService(config);
    try {
        pulsarService.start();
    } catch (Exception e) {
        assertTrue(e.getCause() instanceof IllegalArgumentException);
    } finally {
        pulsarService.close();
    }
    // Only set backlog quota
    config.setDefaultRetentionSizeInMB(0);
    config.setDefaultRetentionTimeInMinutes(0);
    pulsarService = new PulsarService(config);
    try {
        pulsarService.start();
    } catch (Exception e) {
        assertFalse(e.getCause() instanceof IllegalArgumentException);
    } finally {
        pulsarService.close();
    }
}

@Test
void shouldAddTokensWithConfiguredRate() {
    asyncTokenBucket = AsyncTokenBucket.builder().capacity(100).rate(10).initialTokens(0).clock(clockSource).build();
    incrementSeconds(5);
    assertEquals(asyncTokenBucket.getTokens(), 50);
    incrementSeconds(1);
    assertEquals(asyncTokenBucket.getTokens(), 60);
    incrementSeconds(4);
    assertEquals(asyncTokenBucket.getTokens(), 100);
    // No matter how long the period is, tokens do not go above capacity
    incrementSeconds(5);
    assertEquals(asyncTokenBucket.getTokens(), 100);
    // Consume all and verify none available and then wait 1 period and check replenished
    asyncTokenBucket.consumeTokens(100);
    assertEquals(asyncTokenBucket.tokens(true), 0);
    incrementSeconds(1);
    assertEquals(asyncTokenBucket.getTokens(), 10);
}

