/**
 * Verifies batch-message acking is thread-safe
 *
 * @throws Exception
 */
@Test(dataProvider = "containerBuilder")
public void testConcurrentBatchMessageAck(BatcherBuilder builder) throws Exception {
    int numMsgs = 10;
    final String topicName = "persistent://prop/ns-abc/testConcurrentAck-" + UUID.randomUUID();
    final String subscriptionName = "sub-1";
    Consumer<byte[]> consumer = pulsarClient.newConsumer().topic(topicName).subscriptionName(subscriptionName).subscriptionType(SubscriptionType.Shared).subscribe();
    consumer.close();
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topicName).batchingMaxPublishDelay(5, TimeUnit.SECONDS).batchingMaxMessages(numMsgs).enableBatching(true).batcherBuilder(builder).create();
    List<CompletableFuture<MessageId>> sendFutureList = new ArrayList<>();
    for (int i = 0; i < numMsgs; i++) {
        byte[] message = ("my-message-" + i).getBytes();
        sendFutureList.add(producer.sendAsync(message));
    }
    FutureUtil.waitForAll(sendFutureList).get();
    PersistentTopic topic = (PersistentTopic) pulsar.getBrokerService().getTopicReference(topicName).get();
    final Consumer<byte[]> myConsumer = pulsarClient.newConsumer().topic(topicName).subscriptionName(subscriptionName).subscriptionType(SubscriptionType.Shared).subscribe();
    // assertEquals(dispatcher.getTotalUnackedMessages(), 1);
    @Cleanup("shutdownNow")
    ExecutorService executor = Executors.newFixedThreadPool(10);
    final CountDownLatch latch = new CountDownLatch(numMsgs);
    final AtomicBoolean failed = new AtomicBoolean(false);
    for (int i = 0; i < numMsgs; i++) {
        executor.submit(() -> {
            try {
                Message<byte[]> msg = myConsumer.receive(1, TimeUnit.SECONDS);
                myConsumer.acknowledge(msg);
            } catch (Exception e) {
                failed.set(false);
            }
            latch.countDown();
        });
    }
    latch.await();
    PersistentDispatcherMultipleConsumers dispatcher = (PersistentDispatcherMultipleConsumers) topic.getSubscription(subscriptionName).getDispatcher();
    // check strategically to let ack-message receive by broker
    retryStrategically((test) -> dispatcher.getConsumers().get(0).getUnackedMessages() == 0, 50, 150);
    assertEquals(dispatcher.getConsumers().get(0).getUnackedMessages(), 0);
    executor.shutdownNow();
    myConsumer.close();
    producer.close();
}

@Test
public void testOrderingOfKeyBasedBatchMessageContainer() throws PulsarClientException, ExecutionException, InterruptedException {
    final String topicName = "persistent://prop/ns-abc/testKeyBased";
    final String subscriptionName = "sub-1";
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topicName).batchingMaxPublishDelay(5, TimeUnit.SECONDS).batchingMaxMessages(30).enableBatching(true).batcherBuilder(BatcherBuilder.KEY_BASED).create();
    Consumer<byte[]> consumer = pulsarClient.newConsumer().topic(topicName).subscriptionName(subscriptionName).subscriptionType(SubscriptionType.Key_Shared).subscribe();
    List<CompletableFuture<MessageId>> sendFutureList = new ArrayList<>();
    String[] keys = new String[] { "key-1", "key-2", "key-3" };
    for (int i = 0; i < 10; i++) {
        byte[] message = ("my-message-" + i).getBytes();
        for (String key : keys) {
            sendFutureList.add(producer.newMessage().key(key).value(message).sendAsync());
        }
    }
    FutureUtil.waitForAll(sendFutureList).get();
    String receivedKey = "";
    int receivedMessageIndex = 0;
    for (int i = 0; i < 30; i++) {
        Message<byte[]> received = consumer.receive();
        if (!received.getKey().equals(receivedKey)) {
            receivedKey = received.getKey();
            receivedMessageIndex = 0;
        }
        assertEquals(new String(received.getValue()), "my-message-" + receivedMessageIndex % 10);
        consumer.acknowledge(received);
        receivedMessageIndex++;
    }
    for (int i = 0; i < 10; i++) {
        byte[] message = ("my-message-" + i).getBytes();
        for (String key : keys) {
            sendFutureList.add(producer.newMessage().key(UUID.randomUUID().toString()).orderingKey(key.getBytes()).value(message).sendAsync());
        }
    }
    FutureUtil.waitForAll(sendFutureList).get();
    receivedKey = "";
    receivedMessageIndex = 0;
    for (int i = 0; i < 30; i++) {
        Message<byte[]> received = consumer.receive();
        if (!new String(received.getOrderingKey()).equals(receivedKey)) {
            receivedKey = new String(received.getOrderingKey());
            receivedMessageIndex = 0;
        }
        assertEquals(new String(received.getValue()), "my-message-" + receivedMessageIndex % 10);
        consumer.acknowledge(received);
        receivedMessageIndex++;
    }
    consumer.close();
    producer.close();
}

