@Test
public void testFetchPartitionedTopicMetadataWithCacheRefresh() throws Exception {
    final String configMetadataStoreConnectString = WhiteboxImpl.getInternalState(pulsar.getConfigurationMetadataStore(), "zkConnectString");
    final ZooKeeper anotherZKCli = new ZooKeeper(configMetadataStoreConnectString, 5000, null);
    // Set policy of auto create topic to PARTITIONED.
    final String ns = defaultTenant + "/ns_" + UUID.randomUUID().toString().replaceAll("-", "");
    final TopicName topicName1 = TopicName.get("persistent://" + ns + "/tp1");
    final TopicName topicName2 = TopicName.get("persistent://" + ns + "/tp2");
    admin.namespaces().createNamespace(ns);
    AutoTopicCreationOverride autoTopicCreationOverride = new AutoTopicCreationOverrideImpl.AutoTopicCreationOverrideImplBuilder().allowAutoTopicCreation(true).topicType(TopicType.PARTITIONED.toString()).defaultNumPartitions(3).build();
    admin.namespaces().setAutoTopicCreationAsync(ns, autoTopicCreationOverride);
    // Make the cache of namespace policy is valid.
    admin.namespaces().getAutoSubscriptionCreation(ns);
    // Trigger the zk node "/admin/partitioned-topics/{namespace}/persistent" created.
    admin.topics().createPartitionedTopic(topicName1.toString(), 2);
    admin.topics().deletePartitionedTopic(topicName1.toString());
    // Since there is no partitioned metadata created, the partitions count of metadata will be 0.
    PartitionedTopicMetadata partitionedTopicMetadata1 = pulsar.getBrokerService().fetchPartitionedTopicMetadataAsync(topicName2).get();
    assertEquals(partitionedTopicMetadata1.partitions, 0);
    // Create the partitioned metadata by another zk client.
    // Make a error to make the cache could not update.
    makeLocalMetadataStoreKeepReconnect();
    anotherZKCli.create("/admin/partitioned-topics/" + ns + "/persistent/" + topicName2.getLocalName(), "{\"partitions\":3}".getBytes(StandardCharsets.UTF_8), ZooDefs.Ids.OPEN_ACL_UNSAFE, CreateMode.PERSISTENT);
    stopLocalMetadataStoreAlwaysReconnect();
    // Get the partitioned metadata from cache, there is 90% chance that partitions count of metadata is 0.
    PartitionedTopicMetadata partitionedTopicMetadata2 = pulsar.getBrokerService().fetchPartitionedTopicMetadataAsync(topicName2).get();
    // Note: If you want to reproduce the issue, you can perform validation on the next line.
    // assertEquals(partitionedTopicMetadata2.partitions, 0);
    // Verify the new method will return a correct result.
    PartitionedTopicMetadata partitionedTopicMetadata3 = pulsar.getBrokerService().fetchPartitionedTopicMetadataAsync(topicName2, true).get();
    assertEquals(partitionedTopicMetadata3.partitions, 3);
    // cleanup.
    admin.topics().deletePartitionedTopic(topicName2.toString());
    anotherZKCli.close();
}

@Test
public void testShutDownWithMaxConcurrentUnload() throws Exception {
    int bundleNum = 3;
    cleanup();
    conf.setDefaultNumberOfNamespaceBundles(bundleNum);
    setup();
    final String topic = "persistent://prop/ns-abc/successTopic";
    admin.topics().createPartitionedTopic(topic, 12);
    Producer<byte[]> producer = pulsarClient.newProducer(Schema.BYTES).topic(topic).create();
    BundlesData bundlesData = admin.namespaces().getBundles("prop/ns-abc");
    assertEquals(bundlesData.getNumBundles(), bundleNum);
    List<String> list = admin.brokers().getActiveBrokers("test");
    assertEquals(list.size(), 1);
    admin.brokers().shutDownBrokerGracefully(1, false);
    //We can only unload one bundle per second, so it takes at least 2 seconds.
    Awaitility.await().atLeast(bundleNum - 1, TimeUnit.SECONDS).untilAsserted(() -> {
        assertEquals(pulsar.getBrokerService().getTopics().size(), 0);
    });
    Awaitility.await().atMost(60, TimeUnit.SECONDS).untilAsserted(() -> {
        assertNull(pulsar.getBrokerService());
        assertEquals(pulsar.getState(), PulsarService.State.Closed);
    });
    try {
        producer.send("1".getBytes(StandardCharsets.UTF_8));
        fail("sending msg should timeout, because broker is down and there is only one broker");
    } catch (Exception e) {
        assertTrue(e instanceof PulsarClientException.TimeoutException);
    }
    producer.close();
    resetState();
}

@Test
public void testOwnedNsCheck() throws Exception {
    final String topic = "persistent://prop/ns-abc/successTopic";
    BrokerService service = pulsar.getBrokerService();
    final CountDownLatch latch1 = new CountDownLatch(1);
    service.getOrCreateTopic(topic).thenAccept(t -> {
        latch1.countDown();
        fail("should fail as NS is not owned");
    }).exceptionally(exception -> {
        assertTrue(exception.getCause() instanceof IOException);
        latch1.countDown();
        return null;
    });
    latch1.await();
    admin.lookups().lookupTopic(topic);
    final CountDownLatch latch2 = new CountDownLatch(1);
    service.getOrCreateTopic(topic).thenAccept(t -> {
        try {
            assertNotNull(service.getTopicReference(topic));
        } catch (Exception e) {
            fail("should not fail");
        }
        latch2.countDown();
    }).exceptionally(exception -> {
        latch2.countDown();
        fail("should not fail");
        return null;
    });
    latch2.await();
}

@Test
public void testBrokerServicePersistentTopicStats() throws Exception {
    // this test might fail if there are stats from other tests
    resetState();
    final String topicName = "persistent://prop/ns-abc/successTopic";
    final String subName = "successSub";
    TopicStats stats;
    SubscriptionStats subStats;
    Consumer<byte[]> consumer = pulsarClient.newConsumer().topic(topicName).subscriptionName(subName).acknowledgmentGroupTime(0, TimeUnit.SECONDS).subscribe();
    Thread.sleep(ASYNC_EVENT_COMPLETION_WAIT);
    PersistentTopic topicRef = (PersistentTopic) pulsar.getBrokerService().getTopicReference(topicName).get();
    assertNotNull(topicRef);
    rolloverPerIntervalStats();
    stats = topicRef.getStats(false, false, false);
    subStats = stats.getSubscriptions().values().iterator().next();
    // subscription stats
    assertEquals(stats.getSubscriptions().keySet().size(), 1);
    assertEquals(subStats.getMsgBacklog(), 0);
    assertEquals(subStats.getConsumers().size(), 1);
    // storage stats
    assertEquals(stats.getOffloadedStorageSize(), 0);
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topicName).create();
    Thread.sleep(ASYNC_EVENT_COMPLETION_WAIT);
    for (int i = 0; i < 10; i++) {
        String message = "my-message-" + i;
        producer.send(message.getBytes());
    }
    Thread.sleep(ASYNC_EVENT_COMPLETION_WAIT);
    rolloverPerIntervalStats();
    stats = topicRef.getStats(false, false, false);
    subStats = stats.getSubscriptions().values().iterator().next();
    // publisher stats
    assertEquals(subStats.getMsgBacklog(), 10);
    assertEquals(stats.getPublishers().size(), 1);
    assertTrue(stats.getPublishers().get(0).getMsgRateIn() > 0.0);
    assertTrue(stats.getPublishers().get(0).getMsgThroughputIn() > 0.0);
    assertTrue(stats.getPublishers().get(0).getAverageMsgSize() > 0.0);
    assertNotNull(stats.getPublishers().get(0).getClientVersion());
    // aggregated publish stats
    assertEquals(stats.getMsgRateIn(), stats.getPublishers().get(0).getMsgRateIn());
    assertEquals(stats.getMsgThroughputIn(), stats.getPublishers().get(0).getMsgThroughputIn());
    double diff = stats.getAverageMsgSize() - stats.getPublishers().get(0).getAverageMsgSize();
    assertTrue(Math.abs(diff) < 0.000001);
    // consumer stats
    assertTrue(subStats.getConsumers().get(0).getMsgRateOut() > 0.0);
    assertTrue(subStats.getConsumers().get(0).getMsgThroughputOut() > 0.0);
    // aggregated consumer stats
    assertEquals(subStats.getMsgRateOut(), subStats.getConsumers().get(0).getMsgRateOut());
    assertEquals(subStats.getMsgThroughputOut(), subStats.getConsumers().get(0).getMsgThroughputOut());
    assertEquals(stats.getMsgRateOut(), subStats.getConsumers().get(0).getMsgRateOut());
    assertEquals(stats.getMsgThroughputOut(), subStats.getConsumers().get(0).getMsgThroughputOut());
    assertNotNull(subStats.getConsumers().get(0).getClientVersion());
    assertEquals(stats.getOffloadedStorageSize(), 0);
    Message<byte[]> msg;
    for (int i = 0; i < 10; i++) {
        msg = consumer.receive();
        consumer.acknowledge(msg);
    }
    consumer.close();
    Thread.sleep(ASYNC_EVENT_COMPLETION_WAIT);
    rolloverPerIntervalStats();
    stats = topicRef.getStats(false, false, false);
    subStats = stats.getSubscriptions().values().iterator().next();
    assertEquals(stats.getOffloadedStorageSize(), 0);
    assertEquals(subStats.getMsgBacklog(), 0);
}

