/**
 * Verifies: client side throttling.
 *
 * @throws Exception
 */
@Test
public void testLookupThrottlingForClientByClient() throws Exception {
    final String topicName = "persistent://prop/ns-abc/newTopic";
    PulsarServiceNameResolver resolver = new PulsarServiceNameResolver();
    resolver.updateServiceUrl(pulsar.getBrokerServiceUrl());
    ClientConfigurationData conf = new ClientConfigurationData();
    conf.setConcurrentLookupRequest(1);
    conf.setMaxLookupRequest(2);
    @Cleanup("shutdownNow")
    EventLoopGroup eventLoop = EventLoopUtil.newEventLoopGroup(20, false, new DefaultThreadFactory("test-pool", Thread.currentThread().isDaemon()));
    long reqId = 0xdeadbeef;
    // Using an AtomicReference in order to reset a new CountDownLatch
    AtomicReference<CountDownLatch> latchRef = new AtomicReference<>();
    latchRef.set(new CountDownLatch(1));
    try (ConnectionPool pool = new ConnectionPool(InstrumentProvider.NOOP, conf, eventLoop, () -> new ClientCnx(InstrumentProvider.NOOP, conf, eventLoop) {

        @Override
        protected void handleLookupResponse(CommandLookupTopicResponse lookupResult) {
            try {
                latchRef.get().await();
            } catch (InterruptedException e) {
                // ignore
            }
            super.handleLookupResponse(lookupResult);
        }

        @Override
        protected void handlePartitionResponse(CommandPartitionedTopicMetadataResponse lookupResult) {
            try {
                latchRef.get().await();
            } catch (InterruptedException e) {
                // ignore
            }
            super.handlePartitionResponse(lookupResult);
        }
    })) {
        // for PMR
        // 2 lookup will succeed
        long reqId1 = reqId++;
        ByteBuf request1 = Commands.newPartitionMetadataRequest(topicName, reqId1, true);
        CompletableFuture<?> f1 = pool.getConnection(resolver.resolveHost()).thenCompose(clientCnx -> clientCnx.newLookup(request1, reqId1));
        long reqId2 = reqId++;
        ByteBuf request2 = Commands.newPartitionMetadataRequest(topicName, reqId2, true);
        CompletableFuture<?> f2 = pool.getConnection(resolver.resolveHost()).thenCompose(clientCnx -> {
            CompletableFuture<?> future = clientCnx.newLookup(request2, reqId2);
            // pending other responses in `ClientCnx` until now
            latchRef.get().countDown();
            return future;
        });
        f1.get();
        f2.get();
        // 3 lookup will fail
        latchRef.set(new CountDownLatch(1));
        long reqId3 = reqId++;
        ByteBuf request3 = Commands.newPartitionMetadataRequest(topicName, reqId3, true);
        f1 = pool.getConnection(resolver.resolveHost()).thenCompose(clientCnx -> clientCnx.newLookup(request3, reqId3));
        long reqId4 = reqId++;
        ByteBuf request4 = Commands.newPartitionMetadataRequest(topicName, reqId4, true);
        f2 = pool.getConnection(resolver.resolveHost()).thenCompose(clientCnx -> clientCnx.newLookup(request4, reqId4));
        long reqId5 = reqId++;
        ByteBuf request5 = Commands.newPartitionMetadataRequest(topicName, reqId5, true);
        CompletableFuture<?> f3 = pool.getConnection(resolver.resolveHost()).thenCompose(clientCnx -> {
            CompletableFuture<?> future = clientCnx.newLookup(request5, reqId5);
            // pending other responses in `ClientCnx` until now
            latchRef.get().countDown();
            return future;
        });
        f1.get();
        f2.get();
        try {
            f3.get();
            fail("At least one should fail");
        } catch (ExecutionException e) {
            Throwable rootCause = e;
            while (rootCause instanceof ExecutionException) {
                rootCause = rootCause.getCause();
            }
            if (!(rootCause instanceof org.apache.pulsar.client.api.PulsarClientException.TooManyRequestsException)) {
                throw e;
            }
        }
        // for Lookup
        // 2 lookup will succeed
        latchRef.set(new CountDownLatch(1));
        long reqId6 = reqId++;
        ByteBuf request6 = Commands.newLookup(topicName, true, reqId6);
        f1 = pool.getConnection(resolver.resolveHost()).thenCompose(clientCnx -> clientCnx.newLookup(request6, reqId6));
        long reqId7 = reqId++;
        ByteBuf request7 = Commands.newLookup(topicName, true, reqId7);
        f2 = pool.getConnection(resolver.resolveHost()).thenCompose(clientCnx -> {
            CompletableFuture<?> future = clientCnx.newLookup(request7, reqId7);
            // pending other responses in `ClientCnx` until now
            latchRef.get().countDown();
            return future;
        });
        f1.get();
        f2.get();
        // 3 lookup will fail
        latchRef.set(new CountDownLatch(1));
        long reqId8 = reqId++;
        ByteBuf request8 = Commands.newLookup(topicName, true, reqId8);
        f1 = pool.getConnection(resolver.resolveHost()).thenCompose(clientCnx -> clientCnx.newLookup(request8, reqId8));
        long reqId9 = reqId++;
        ByteBuf request9 = Commands.newLookup(topicName, true, reqId9);
        f2 = pool.getConnection(resolver.resolveHost()).thenCompose(clientCnx -> clientCnx.newLookup(request9, reqId9));
        long reqId10 = reqId++;
        ByteBuf request10 = Commands.newLookup(topicName, true, reqId10);
        f3 = pool.getConnection(resolver.resolveHost()).thenCompose(clientCnx -> {
            CompletableFuture<?> future = clientCnx.newLookup(request10, reqId10);
            // pending other responses in `ClientCnx` until now
            latchRef.get().countDown();
            return future;
        });
        f1.get();
        f2.get();
        try {
            f3.get();
            fail("At least one should fail");
        } catch (ExecutionException e) {
            Throwable rootCause = e;
            while (rootCause instanceof ExecutionException) {
                rootCause = rootCause.getCause();
            }
            if (!(rootCause instanceof org.apache.pulsar.client.api.PulsarClientException.TooManyRequestsException)) {
                throw e;
            }
        }
    }
}

