@Test
public void testCurrentLedgerRolloverIfFull() throws Exception {
    final String topicName = "persistent://prop/ns-abc/CurrentLedgerRolloverIfFullTest";
    @Cleanup
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topicName).producerName("CurrentLedgerRolloverIfFullTest-producer-name").create();
    @Cleanup
    Consumer<byte[]> consumer = pulsarClient.newConsumer().topic(topicName).subscriptionName("CurrentLedgerRolloverIfFullTest-subscriber-name").subscribe();
    Topic topicRef = pulsar.getBrokerService().getTopicReference(topicName).get();
    Assert.assertNotNull(topicRef);
    PersistentTopic persistentTopic = (PersistentTopic) pulsar.getBrokerService().getOrCreateTopic(topicName).get();
    ManagedLedgerConfig managedLedgerConfig = persistentTopic.getManagedLedger().getConfig();
    managedLedgerConfig.setRetentionTime(1, TimeUnit.SECONDS);
    managedLedgerConfig.setMaxEntriesPerLedger(2);
    managedLedgerConfig.setMinimumRolloverTime(1, TimeUnit.MILLISECONDS);
    managedLedgerConfig.setMaximumRolloverTime(1, TimeUnit.SECONDS);
    int msgNum = 10;
    for (int i = 0; i < msgNum; i++) {
        producer.send(new byte[1024 * 1024]);
    }
    ManagedLedgerImpl managedLedger = (ManagedLedgerImpl) persistentTopic.getManagedLedger();
    Assert.assertEquals(managedLedger.getLedgersInfoAsList().size(), msgNum / 2);
    for (int i = 0; i < msgNum; i++) {
        Message<byte[]> msg = consumer.receive(2, TimeUnit.SECONDS);
        Assert.assertNotNull(msg);
        consumer.acknowledge(msg);
    }
    // all the messages have been acknowledged
    // and all the ledgers have been removed except the the last ledger
    Awaitility.await().pollInterval(Duration.ofMillis(500L)).untilAsserted(() -> {
        Assert.assertEquals(managedLedger.getLedgersInfoAsList().size(), 1);
        Assert.assertNotEquals(managedLedger.getCurrentLedgerSize(), 0);
    });
    // trigger a ledger rollover
    Field stateUpdater = ManagedLedgerImpl.class.getDeclaredField("state");
    stateUpdater.setAccessible(true);
    stateUpdater.set(managedLedger, ManagedLedgerImpl.State.LedgerOpened);
    managedLedger.rollCurrentLedgerIfFull();
    // the last ledger will be closed and removed and we have one ledger for empty
    Awaitility.await().pollInterval(Duration.ofMillis(1000L)).untilAsserted(() -> {
        Assert.assertEquals(managedLedger.getLedgersInfoAsList().size(), 1);
        Assert.assertEquals(managedLedger.getTotalSize(), 0);
    });
}

@Test
public void testNoBacklogOnDeduplication() throws Exception {
    final String topic = BrokerTestUtil.newUniqueName("persistent://public/default/tp");
    admin.topics().createNonPartitionedTopic(topic);
    final PersistentTopic persistentTopic = (PersistentTopic) pulsar.getBrokerService().getTopic(topic, false).join().get();
    final ManagedLedgerImpl ml = (ManagedLedgerImpl) persistentTopic.getManagedLedger();
    // deduplication enabled:
    //   broker level: "false"
    //   topic level: "true".
    // So it is enabled.
    admin.topicPolicies().setDeduplicationStatus(topic, true);
    Awaitility.await().untilAsserted(() -> {
        ManagedCursorImpl cursor = (ManagedCursorImpl) ml.getCursors().get(PersistentTopic.DEDUPLICATION_CURSOR_NAME);
        assertNotNull(cursor);
    });
    // Verify: regarding deduplication cursor, messages will be acknowledged automatically.
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(topic).create();
    producer.send("1");
    producer.send("2");
    producer.send("3");
    producer.close();
    ManagedCursorImpl cursor = (ManagedCursorImpl) ml.getCursors().get(PersistentTopic.DEDUPLICATION_CURSOR_NAME);
    Awaitility.await().atMost(Duration.ofSeconds(deduplicationSnapshotFrequency * 3)).untilAsserted(() -> {
        Position LAC = ml.getLastConfirmedEntry();
        Position cursorMD = cursor.getMarkDeletedPosition();
        assertTrue(LAC.compareTo(cursorMD) <= 0);
    });
    // cleanup.
    admin.topics().delete(topic);
}

@Test
public void testSnapshotCounterAfterUnload() throws Exception {
    final int originalDeduplicationSnapshotFrequency = deduplicationSnapshotFrequency;
    deduplicationSnapshotFrequency = 3600;
    cleanup();
    setup();
    // Create a topic and wait deduplication is started.
    final String topic = BrokerTestUtil.newUniqueName("persistent://public/default/tp");
    admin.topics().createNonPartitionedTopic(topic);
    final PersistentTopic persistentTopic1 = (PersistentTopic) pulsar.getBrokerService().getTopic(topic, false).join().get();
    final ManagedLedgerImpl ml1 = (ManagedLedgerImpl) persistentTopic1.getManagedLedger();
    admin.topicPolicies().setDeduplicationStatus(topic, true);
    Awaitility.await().untilAsserted(() -> {
        ManagedCursorImpl cursor1 = (ManagedCursorImpl) ml1.getCursors().get(PersistentTopic.DEDUPLICATION_CURSOR_NAME);
        assertNotNull(cursor1);
    });
    final MessageDeduplication deduplication1 = persistentTopic1.getMessageDeduplication();
    // 1. Send 999 messages, it is less than "brokerDeduplicationEntriesIntervaddl".
    // 2. Unload topic.
    // 3. Send 1 messages, there are 1099 messages have not been snapshot now.
    // 4. Verify the snapshot has been taken.
    // step 1.
    final Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(topic).create();
    for (int i = 0; i < brokerDeduplicationEntriesInterval - 1; i++) {
        producer.send(i + "");
    }
    int snapshotCounter1 = WhiteboxImpl.getInternalState(deduplication1, "snapshotCounter");
    assertEquals(snapshotCounter1, brokerDeduplicationEntriesInterval - 1);
    admin.topics().unload(topic);
    PersistentTopic persistentTopic2 = (PersistentTopic) pulsar.getBrokerService().getTopic(topic, false).join().get();
    ManagedLedgerImpl ml2 = (ManagedLedgerImpl) persistentTopic2.getManagedLedger();
    MessageDeduplication deduplication2 = persistentTopic2.getMessageDeduplication();
    admin.topicPolicies().setDeduplicationStatus(topic, true);
    Awaitility.await().untilAsserted(() -> {
        ManagedCursorImpl cursor = (ManagedCursorImpl) ml2.getCursors().get(PersistentTopic.DEDUPLICATION_CURSOR_NAME);
        assertNotNull(cursor);
    });
    // step 3.
    producer.send("last message");
    ml2.trimConsumedLedgersInBackground(new CompletableFuture<>());
    // step 4.
    Awaitility.await().untilAsserted(() -> {
        int snapshotCounter3 = WhiteboxImpl.getInternalState(deduplication2, "snapshotCounter");
        assertTrue(snapshotCounter3 < brokerDeduplicationEntriesInterval);
        // Verify: the previous ledger will be removed because all messages have been acked.
        assertEquals(ml2.getLedgersInfo().size(), 1);
    });
    // cleanup.
    producer.close();
    admin.topics().delete(topic);
    deduplicationSnapshotFrequency = originalDeduplicationSnapshotFrequency;
    cleanup();
    setup();
}

