@Test(dataProvider = "topics")
public void waitForExclusiveTest(String type, boolean partitioned) throws Exception {
    String topic = newTopic(type, partitioned);
    Producer<String> p1 = pulsarClient.newProducer(Schema.STRING).topic(topic).producerName("p1").accessMode(ProducerAccessMode.WaitForExclusive).create();
    CompletableFuture<Producer<String>> fp2 = pulsarClient.newProducer(Schema.STRING).topic(topic).producerName("p2").accessMode(ProducerAccessMode.WaitForExclusive).createAsync();
    // This sleep is made to ensure P2 is enqueued before P3. Because of the lookups
    // there's no strict guarantee they would be attempted in the same order otherwise
    Thread.sleep(1000);
    CompletableFuture<Producer<String>> fp3 = pulsarClient.newProducer(Schema.STRING).topic(topic).producerName("p3").accessMode(ProducerAccessMode.WaitForExclusive).createAsync();
    Thread.sleep(1000);
    // The second producer should get queued
    assertFalse(fp2.isDone());
    assertFalse(fp3.isDone());
    p1.close();
    // Now P2 should get created
    Producer<String> p2 = fp2.get(1, TimeUnit.SECONDS);
    assertFalse(fp3.isDone());
    p2.close();
    // Now P3 should get created
    Producer<String> p3 = fp3.get(1, TimeUnit.SECONDS);
    p3.close();
}

