@Test
public void testBlockByPublishRateLimiting() throws Exception {
    conf.setMaxMessagePublishBufferSizeInMB(1);
    super.baseSetup();
    assertEquals(pulsar.getBrokerService().getPausedConnections(), 0);
    final String topic = "persistent://prop/ns-abc/testBlockByPublishRateLimiting";
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topic).producerName("producer-name").create();
    Topic topicRef = pulsar.getBrokerService().getTopicReference(topic).get();
    Assert.assertNotNull(topicRef);
    assertEquals(pulsar.getBrokerService().getPausedConnections(), 0);
    pulsarTestContext.getMockBookKeeper().addEntryDelay(5, TimeUnit.SECONDS);
    // Block by publish buffer.
    byte[] payload = new byte[1024 * 1024];
    for (int i = 0; i < 10; i++) {
        producer.sendAsync(payload);
    }
    Awaitility.await().untilAsserted(() -> assertEquals(pulsar.getBrokerService().getPausedConnections(), 1));
    CompletableFuture<Void> flushFuture = producer.flushAsync();
    // Block by publish rate.
    // After 1 second, the message buffer throttling will be lifted, but the rate limiting will still be in place.
    assertEquals(pulsar.getBrokerService().getPausedConnections(), 1);
    try {
        flushFuture.get(2, TimeUnit.SECONDS);
        fail("Should have timed out");
    } catch (TimeoutException e) {
        // Ok
    }
    flushFuture.join();
    Awaitility.await().untilAsserted(() -> assertEquals(pulsar.getBrokerService().getPausedConnections(), 0));
}

@Test
public void testMessageExpiryAfterTopicUnload() throws Exception {
    int numMsgs = 50;
    final String topicName = "persistent://prop/ns-abc/testttl";
    final String subscriptionName = "ttl-sub-1";
    pulsarClient.newConsumer().topic(topicName).subscriptionName(subscriptionName).subscribe().close();
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topicName).enableBatching(// this makes the test easier and predictable
    false).create();
    List<CompletableFuture<MessageId>> sendFutureList = new ArrayList<>();
    for (int i = 0; i < numMsgs; i++) {
        byte[] message = ("my-message-" + i).getBytes();
        sendFutureList.add(producer.sendAsync(message));
    }
    FutureUtil.waitForAll(sendFutureList).get();
    MessageIdImpl firstMessageId = (MessageIdImpl) sendFutureList.get(0).get();
    MessageIdImpl lastMessageId = (MessageIdImpl) sendFutureList.get(sendFutureList.size() - 1).get();
    producer.close();
    // unload a reload the topic
    // this action created a new ledger
    // having a managed ledger with more than one
    // ledger should not impact message expiration
    admin.topics().unload(topicName);
    admin.topics().getStats(topicName);
    PersistentTopicInternalStats internalStatsBeforeExpire = admin.topics().getInternalStats(topicName);
    CursorStats statsBeforeExpire = internalStatsBeforeExpire.cursors.get(subscriptionName);
    log.info("markDeletePosition before expire {}", statsBeforeExpire.markDeletePosition);
    assertEquals(statsBeforeExpire.markDeletePosition, PositionFactory.create(firstMessageId.getLedgerId(), -1).toString());
    Awaitility.await().timeout(30, TimeUnit.SECONDS).pollDelay(3, TimeUnit.SECONDS).untilAsserted(() -> {
        this.runMessageExpiryCheck();
        log.info("***** run message expiry now");
        // verify that the markDeletePosition was moved forward, and exacly to the last message
        PersistentTopicInternalStats internalStatsAfterExpire = admin.topics().getInternalStats(topicName);
        CursorStats statsAfterExpire = internalStatsAfterExpire.cursors.get(subscriptionName);
        log.info("markDeletePosition after expire {}", statsAfterExpire.markDeletePosition);
        assertEquals(statsAfterExpire.markDeletePosition, PositionFactory.create(lastMessageId.getLedgerId(), lastMessageId.getEntryId()).toString());
    });
}

