@Test
public void testSubscriptionsOnNonPersistentTopic() throws Exception {
    final String topicName = "non-persistent://prop/ns-abc/topic_" + UUID.randomUUID();
    final String exclusiveSubName = "exclusive";
    final String failoverSubName = "failover";
    final String sharedSubName = "shared";
    final String keySharedSubName = "key_shared";
    @Cleanup
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(topicName).create();
    producer.send("This is a message");
    NonPersistentTopic topic = (NonPersistentTopic) pulsar.getBrokerService().getTopicReference(topicName).get();
    NonPersistentTopic mockTopic = Mockito.spy(topic);
    pulsar.getBrokerService().getTopics().put(topicName, CompletableFuture.completedFuture(Optional.of(mockTopic)));
    Mockito.doAnswer(inv -> {
        SubscriptionOption option = inv.getArgument(0);
        if (option.isDurable()) {
            return CompletableFuture.failedFuture(new IllegalArgumentException("isDurable cannot be true when subscribe " + "on non-persistent topic"));
        }
        return inv.callRealMethod();
    }).when(mockTopic).subscribe(Mockito.any());
    @Cleanup
    Consumer<String> exclusiveConsumer = pulsarClient.newConsumer(Schema.STRING).topic(topicName).subscriptionName(exclusiveSubName).subscriptionType(SubscriptionType.Exclusive).subscriptionMode(SubscriptionMode.Durable).subscribe();
    @Cleanup
    Consumer<String> failoverConsumer1 = pulsarClient.newConsumer(Schema.STRING).topic(topicName).subscriptionName(failoverSubName).subscriptionType(SubscriptionType.Failover).subscriptionMode(SubscriptionMode.Durable).subscribe();
    @Cleanup
    Consumer<String> failoverConsumer2 = pulsarClient.newConsumer(Schema.STRING).topic(topicName).subscriptionName(failoverSubName).subscriptionType(SubscriptionType.Failover).subscriptionMode(SubscriptionMode.Durable).subscribe();
    @Cleanup
    Consumer<String> sharedConsumer1 = pulsarClient.newConsumer(Schema.STRING).topic(topicName).subscriptionName(sharedSubName).subscriptionType(SubscriptionType.Shared).subscriptionMode(SubscriptionMode.Durable).subscribe();
    @Cleanup
    Consumer<String> sharedConsumer2 = pulsarClient.newConsumer(Schema.STRING).topic(topicName).subscriptionName(sharedSubName).subscriptionType(SubscriptionType.Shared).subscriptionMode(SubscriptionMode.Durable).subscribe();
    @Cleanup
    Consumer<String> keySharedConsumer1 = pulsarClient.newConsumer(Schema.STRING).topic(topicName).subscriptionName(keySharedSubName).subscriptionType(SubscriptionType.Key_Shared).subscriptionMode(SubscriptionMode.Durable).subscribe();
    @Cleanup
    Consumer<String> keySharedConsumer2 = pulsarClient.newConsumer(Schema.STRING).topic(topicName).subscriptionName(keySharedSubName).subscriptionType(SubscriptionType.Key_Shared).subscriptionMode(SubscriptionMode.Durable).subscribe();
    ConcurrentOpenHashMap<String, NonPersistentSubscription> subscriptionMap = mockTopic.getSubscriptions();
    assertEquals(subscriptionMap.size(), 4);
    // Check exclusive subscription
    NonPersistentSubscription exclusiveSub = subscriptionMap.get(exclusiveSubName);
    assertNotNull(exclusiveSub);
    exclusiveConsumer.close();
    Awaitility.waitAtMost(10, TimeUnit.SECONDS).pollInterval(1, TimeUnit.SECONDS).until(() -> subscriptionMap.get(exclusiveSubName) == null);
    // Check failover subscription
    NonPersistentSubscription failoverSub = subscriptionMap.get(failoverSubName);
    assertNotNull(failoverSub);
    failoverConsumer1.close();
    failoverSub = subscriptionMap.get(failoverSubName);
    assertNotNull(failoverSub);
    failoverConsumer2.close();
    Awaitility.waitAtMost(10, TimeUnit.SECONDS).pollInterval(1, TimeUnit.SECONDS).until(() -> subscriptionMap.get(failoverSubName) == null);
    // Check shared subscription
    NonPersistentSubscription sharedSub = subscriptionMap.get(sharedSubName);
    assertNotNull(sharedSub);
    sharedConsumer1.close();
    sharedSub = subscriptionMap.get(sharedSubName);
    assertNotNull(sharedSub);
    sharedConsumer2.close();
    Awaitility.waitAtMost(10, TimeUnit.SECONDS).pollInterval(1, TimeUnit.SECONDS).until(() -> subscriptionMap.get(sharedSubName) == null);
    // Check KeyShared subscription
    NonPersistentSubscription keySharedSub = subscriptionMap.get(keySharedSubName);
    assertNotNull(keySharedSub);
    keySharedConsumer1.close();
    keySharedSub = subscriptionMap.get(keySharedSubName);
    assertNotNull(keySharedSub);
    keySharedConsumer2.close();
    Awaitility.waitAtMost(10, TimeUnit.SECONDS).pollInterval(1, TimeUnit.SECONDS).until(() -> subscriptionMap.get(keySharedSubName) == null);
}

