    producer.close();
    // change the repl cluster to peer-cluster r3 from r1
    admin1.namespaces().setNamespaceReplicationClusters(namespace1, Sets.newHashSet("r3"));
    NamespaceBundles bundles = pulsar1.getNamespaceService().getNamespaceBundleFactory().getBundles(NamespaceName.get(namespace1));
