    String topic = BrokerTestUtil.newUniqueName("persistent://public/default/testUnsubscribes");
    @Cleanup
    Consumer<String> c1 = pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionName("sub").subscriptionType(SubscriptionType.Shared).subscribe();
    @Cleanup
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(topic).create();
    for (int i = 0; i < 1000; i++) {
        producer.newMessage().value("msg").deliverAfter(1, TimeUnit.HOURS).send();
    }
    Dispatcher dispatcher = pulsar.getBrokerService().getTopicReference(topic).get().getSubscription("sub").getDispatcher();
    Awaitility.await().untilAsserted(() -> Assert.assertEquals(dispatcher.getNumberOfDelayedMessages(), 1000));
    Map<String, String> cursorProperties = ((PersistentDispatcherMultipleConsumers) dispatcher).getCursor().getCursorProperties();
    List<Long> bucketIds = cursorProperties.entrySet().stream().filter(x -> x.getKey().startsWith(CURSOR_INTERNAL_PROPERTY_PREFIX + "delayed.bucket")).map(x -> Long.valueOf(x.getValue())).toList();
    assertTrue(bucketIds.size() > 0);
    c1.close();
    restartBroker();
    admin.topics().deleteSubscription(topic, "sub");
    for (Long bucketId : bucketIds) {
        try {
            LedgerHandle ledgerHandle = pulsarTestContext.getBookKeeperClient().openLedger(bucketId, BookKeeper.DigestType.CRC32C, new byte[] {});
            Assert.fail("Should fail");
        } catch (BKException.BKNoSuchLedgerExistsException e) {
            // ignore it
        }
    }
}

@Test
public void testBucketDelayedIndexMetrics() throws Exception {
    cleanup();
    setup();
    String topic = BrokerTestUtil.newUniqueName("persistent://public/default/testBucketDelayedIndexMetrics");
    @Cleanup
    Consumer<String> consumer = pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionName("test_sub").subscriptionType(SubscriptionType.Shared).subscribe();
    @Cleanup
    Consumer<String> consumer2 = pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionName("test_sub2").subscriptionType(SubscriptionType.Shared).subscribe();
    @Cleanup
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(topic).create();
    final int N = 101;
    for (int i = 0; i < N; i++) {
        producer.newMessage().value("msg-" + i).deliverAfter(3600 + i, TimeUnit.SECONDS).sendAsync();
    }
    producer.flush();
    Thread.sleep(2000);
    ByteArrayOutputStream output = new ByteArrayOutputStream();
    PrometheusMetricsTestUtil.generate(pulsar, true, true, true, output);
    String metricsStr = output.toString(StandardCharsets.UTF_8);
    Multimap<String, Metric> metricsMap = parseMetrics(metricsStr);
    List<Metric> bucketsMetrics = metricsMap.get("pulsar_delayed_message_index_bucket_total").stream().filter(metric -> metric.tags.get("topic").equals(topic)).toList();
    MutableInt bucketsSum = new MutableInt();
    bucketsMetrics.stream().filter(metric -> metric.tags.containsKey("subscription")).forEach(metric -> {
        assertEquals(3, metric.value);
        bucketsSum.add(metric.value);
    });
    assertEquals(6, bucketsSum.intValue());
    Optional<Metric> bucketsTopicMetric = bucketsMetrics.stream().filter(metric -> !metric.tags.containsKey("subscription")).findFirst();
    assertTrue(bucketsTopicMetric.isPresent());
    assertEquals(bucketsSum.intValue(), bucketsTopicMetric.get().value);
    List<Metric> loadedIndexMetrics = metricsMap.get("pulsar_delayed_message_index_loaded").stream().filter(metric -> metric.tags.get("topic").equals(topic)).toList();
    MutableInt loadedIndexSum = new MutableInt();
    long count = loadedIndexMetrics.stream().filter(metric -> metric.tags.containsKey("subscription")).peek(metric -> {
        assertTrue(metric.value > 0 && metric.value <= N);
        loadedIndexSum.add(metric.value);
    }).count();
    assertEquals(2, count);
    Optional<Metric> loadedIndexTopicMetrics = bucketsMetrics.stream().filter(metric -> !metric.tags.containsKey("subscription")).findFirst();
    assertTrue(loadedIndexTopicMetrics.isPresent());
    assertEquals(loadedIndexSum.intValue(), loadedIndexTopicMetrics.get().value);
    List<Metric> snapshotSizeBytesMetrics = metricsMap.get("pulsar_delayed_message_index_bucket_snapshot_size_bytes").stream().filter(metric -> metric.tags.get("topic").equals(topic)).toList();
    MutableInt snapshotSizeBytesSum = new MutableInt();
    count = snapshotSizeBytesMetrics.stream().filter(metric -> metric.tags.containsKey("subscription")).peek(metric -> {
        assertTrue(metric.value > 0);
        snapshotSizeBytesSum.add(metric.value);
    }).count();
    assertEquals(2, count);
    Optional<Metric> snapshotSizeBytesTopicMetrics = snapshotSizeBytesMetrics.stream().filter(metric -> !metric.tags.containsKey("subscription")).findFirst();
    assertTrue(snapshotSizeBytesTopicMetrics.isPresent());
    assertEquals(snapshotSizeBytesSum.intValue(), snapshotSizeBytesTopicMetrics.get().value);
    List<Metric> opCountMetrics = metricsMap.get("pulsar_delayed_message_index_bucket_op_count").stream().filter(metric -> metric.tags.get("topic").equals(topic)).toList();
    MutableInt opCountMetricsSum = new MutableInt();
    count = opCountMetrics.stream().filter(metric -> metric.tags.get("state").equals("succeed") && metric.tags.get("type").equals("create") && metric.tags.containsKey("subscription")).peek(metric -> {
        assertTrue(metric.value >= 2);
        opCountMetricsSum.add(metric.value);
    }).count();
    assertEquals(2, count);
    Optional<Metric> opCountTopicMetrics = opCountMetrics.stream().filter(metric -> metric.tags.get("state").equals("succeed") && metric.tags.get("type").equals("create") && !metric.tags.containsKey("subscription")).findFirst();
    assertTrue(opCountTopicMetrics.isPresent());
    assertEquals(opCountMetricsSum.intValue(), opCountTopicMetrics.get().value);
    List<Metric> opLatencyMetrics = metricsMap.get("pulsar_delayed_message_index_bucket_op_latency_ms").stream().filter(metric -> metric.tags.get("topic").equals(topic)).toList();
    MutableInt opLatencyMetricsSum = new MutableInt();
    count = opLatencyMetrics.stream().filter(metric -> metric.tags.get("type").equals("create") && metric.tags.containsKey("subscription")).peek(metric -> {
        assertTrue(metric.tags.containsKey("quantile"));
        opLatencyMetricsSum.add(metric.value);
    }).count();
    assertTrue(count >= 2);
    Optional<Metric> opLatencyTopicMetrics = opCountMetrics.stream().filter(metric -> metric.tags.get("type").equals("create") && !metric.tags.containsKey("subscription")).findFirst();
    assertTrue(opLatencyTopicMetrics.isPresent());
    assertEquals(opLatencyMetricsSum.intValue(), opLatencyTopicMetrics.get().value);
    ByteArrayOutputStream namespaceOutput = new ByteArrayOutputStream();
    PrometheusMetricsTestUtil.generate(pulsar, false, true, true, namespaceOutput);
    Multimap<String, Metric> namespaceMetricsMap = parseMetrics(namespaceOutput.toString(StandardCharsets.UTF_8));
    Optional<Metric> namespaceMetric = namespaceMetricsMap.get("pulsar_delayed_message_index_bucket_total").stream().findFirst();
    assertTrue(namespaceMetric.isPresent());
    assertEquals(6, namespaceMetric.get().value);
}

