@Test
public void verifyChecksumStoredInManagedLedger() throws Exception {
    final String topicName = "persistent://prop/use/ns-abc/topic0";
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topicName).create();
    PersistentTopic topic = (PersistentTopic) pulsar.getBrokerService().getTopicReference(topicName).get();
    ManagedLedger ledger = topic.getManagedLedger();
    ManagedCursor cursor = ledger.openCursor("test");
    producer.send("Hello".getBytes());
    List<Entry> entries = cursor.readEntriesOrWait(1);
    assertEquals(entries.size(), 1);
    ByteBuf b = entries.get(0).getDataBuffer();
    assertTrue(Commands.hasChecksum(b));
    int parsedChecksum = Commands.readChecksum(b);
    int computedChecksum = Crc32cIntChecksum.computeChecksum(b);
    assertEquals(parsedChecksum, computedChecksum);
    entries.get(0).release();
    producer.close();
}

@Test
public void verifyChecksumSentToConsumer() throws Exception {
    final String topicName = "persistent://prop/use/ns-abc/topic-1";
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topicName).create();
    RawReader reader = RawReader.create(pulsarClient, topicName, "sub").get();
    producer.send("Hello".getBytes());
    RawMessage msg = reader.readNextAsync().get();
    ByteBuf b = msg.getHeadersAndPayload();
    assertTrue(Commands.hasChecksum(b));
    int parsedChecksum = Commands.readChecksum(b);
    int computedChecksum = Crc32cIntChecksum.computeChecksum(b);
    assertEquals(parsedChecksum, computedChecksum);
    producer.close();
    reader.closeAsync().get();
}

@Test
public void testDelayedDelivery() throws Exception {
    String topic = BrokerTestUtil.newUniqueName("testNegativeAcks");
    @Cleanup
    Consumer<String> failoverConsumer = pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionName("failover-sub").subscriptionType(SubscriptionType.Failover).subscribe();
    @Cleanup
    Consumer<String> sharedConsumer = pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionName("shared-sub").subscriptionType(SubscriptionType.Shared).subscribe();
    @Cleanup
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(topic).create();
    for (int i = 0; i < 10; i++) {
        producer.newMessage().value("msg-" + i).deliverAfter(5, TimeUnit.SECONDS).sendAsync();
    }
    producer.flush();
    // Failover consumer will receive the messages immediately while
    // the shared consumer will get them after the delay
    Message<String> msg = sharedConsumer.receive(100, TimeUnit.MILLISECONDS);
    assertNull(msg);
    var attributes = Attributes.builder().put(OpenTelemetryAttributes.PULSAR_DOMAIN, "persistent").put(OpenTelemetryAttributes.PULSAR_TENANT, "public").put(OpenTelemetryAttributes.PULSAR_NAMESPACE, "public/default").put(OpenTelemetryAttributes.PULSAR_TOPIC, "persistent://public/default/" + topic).build();
    var metrics = pulsarTestContext.getOpenTelemetryMetricReader().collectAllMetrics();
    BrokerOpenTelemetryTestUtil.assertMetricLongSumValue(metrics, OpenTelemetryTopicStats.DELAYED_SUBSCRIPTION_COUNTER, attributes, 10);
    for (int i = 0; i < 10; i++) {
        msg = failoverConsumer.receive(100, TimeUnit.MILLISECONDS);
        assertEquals(msg.getValue(), "msg-" + i);
    }
    Set<String> receivedMsgs = new TreeSet<>();
    for (int i = 0; i < 10; i++) {
        msg = sharedConsumer.receive(10, TimeUnit.SECONDS);
        receivedMsgs.add(msg.getValue());
    }
    assertEquals(receivedMsgs.size(), 10);
    for (int i = 0; i < 10; i++) {
        assertTrue(receivedMsgs.contains("msg-" + i));
    }
}

@Test
public void testInterleavedMessages() throws Exception {
    String topic = BrokerTestUtil.newUniqueName("testInterleavedMessages");
    @Cleanup
    Consumer<String> consumer = pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionName("shared-sub").subscriptionType(SubscriptionType.Shared).subscribe();
    @Cleanup
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(topic).create();
    for (int i = 0; i < 10; i++) {
        // Publish 1 message without delay and 1 with delay
        producer.newMessage().value("immediate-msg-" + i).sendAsync();
        producer.newMessage().value("delayed-msg-" + i).deliverAfter(5, TimeUnit.SECONDS).sendAsync();
    }
    producer.flush();
    // Failover consumer will receive the messages immediately while
    // the shared consumer will get them after the delay
    for (int i = 0; i < 10; i++) {
        Message<String> msg = consumer.receive(100, TimeUnit.MILLISECONDS);
        assertEquals(msg.getValue(), "immediate-msg-" + i);
        consumer.acknowledge(msg);
    }
    // Delayed messages might not come in same exact order
    Set<String> delayedMessages = new TreeSet<>();
    for (int i = 0; i < 10; i++) {
        Message<String> msg = consumer.receive(10, TimeUnit.SECONDS);
        delayedMessages.add(msg.getValue());
        consumer.acknowledge(msg);
    }
    for (int i = 0; i < 10; i++) {
        assertTrue(delayedMessages.contains("delayed-msg-" + i));
    }
}

