@Test
public void testDelayedDeliveryWithMultipleConcurrentReadEntries() throws Exception {
    String topic = BrokerTestUtil.newUniqueName("persistent://public/default/testDelayedDelivery");
    @Cleanup
    Consumer<String> consumer = pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionName("shared-sub").subscriptionType(SubscriptionType.Shared).receiverQueueSize(// Use small prefetching to simulate the multiple read batches
    1).subscribe();
    // Simulate race condition with high frequency of calls to dispatcher.readMoreEntries()
    PersistentDispatcherMultipleConsumers d = (PersistentDispatcherMultipleConsumers) ((PersistentTopic) pulsar.getBrokerService().getTopicReference(topic).get()).getSubscription("shared-sub").getDispatcher();
    Thread t = new Thread(() -> {
        while (true) {
            synchronized (d) {
                d.readMoreEntries();
            }
            try {
                Thread.sleep(1);
            } catch (InterruptedException e) {
                return;
            }
        }
    });
    t.start();
    @Cleanup
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(topic).create();
    final int N = 1000;
    for (int i = 0; i < N; i++) {
        producer.newMessage().value("msg-" + i).deliverAfter(5, TimeUnit.SECONDS).sendAsync();
    }
    producer.flush();
    Message<String> msg = consumer.receive(100, TimeUnit.MILLISECONDS);
    assertNull(msg);
    Set<String> receivedMsgs = new TreeSet<>();
    for (int i = 0; i < N; i++) {
        msg = consumer.receive(10, TimeUnit.SECONDS);
        receivedMsgs.add(msg.getValue());
    }
    assertEquals(receivedMsgs.size(), N);
    for (int i = 0; i < N; i++) {
        assertTrue(receivedMsgs.contains("msg-" + i));
    }
    t.interrupt();
}

@Test
public void testOrderingDispatch() throws PulsarClientException {
    String topic = BrokerTestUtil.newUniqueName("persistent://public/default/testOrderingDispatch");
    @Cleanup
    Consumer<String> consumer = pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionName("shared-sub").subscriptionType(SubscriptionType.Shared).subscribe();
    @Cleanup
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(topic).create();
    final int N = 1000;
    for (int i = 0; i < N; i++) {
        producer.newMessage().value("msg-" + i).deliverAfter(5, TimeUnit.SECONDS).send();
    }
    List<Message<String>> receives = new ArrayList<>(N);
    for (int i = 0; i < N; i++) {
        Message<String> received = consumer.receive();
        receives.add(received);
        consumer.acknowledge(received);
    }
    assertEquals(receives.size(), N);
    for (int i = 0; i < N; i++) {
        if (i < N - 1) {
            assertTrue(receives.get(i).getMessageId().compareTo(receives.get(i + 1).getMessageId()) < 0);
        }
    }
}

@Test(timeOut = 20000)
public void testEnableAndDisableTopicDelayedDelivery() throws Exception {
    String topicName = "persistent://public/default/topic-" + UUID.randomUUID();
    admin.topics().createPartitionedTopic(topicName, 3);
    pulsarClient.newProducer().topic(topicName).create().close();
    assertNull(admin.topics().getDelayedDeliveryPolicy(topicName));
    DelayedDeliveryPolicies delayedDeliveryPolicies = DelayedDeliveryPolicies.builder().tickTime(2000).active(false).maxDeliveryDelayInMillis(5000).build();
    admin.topics().setDelayedDeliveryPolicy(topicName, delayedDeliveryPolicies);
    //wait for update
    for (int i = 0; i < 50; i++) {
        Thread.sleep(100);
        if (admin.topics().getDelayedDeliveryPolicy(topicName) != null) {
            break;
        }
    }
    assertFalse(admin.topics().getDelayedDeliveryPolicy(topicName).isActive());
    assertEquals(2000, admin.topics().getDelayedDeliveryPolicy(topicName).getTickTime());
    assertEquals(5000, admin.topics().getDelayedDeliveryPolicy(topicName).getMaxDeliveryDelayInMillis());
    admin.topics().removeDelayedDeliveryPolicy(topicName);
    //wait for update
    for (int i = 0; i < 50; i++) {
        Thread.sleep(100);
        if (admin.topics().getDelayedDeliveryPolicy(topicName) == null) {
            break;
        }
    }
    assertNull(admin.topics().getDelayedDeliveryPolicy(topicName));
}

@Test(timeOut = 20000)
public void testEnableTopicDelayedDelivery() throws Exception {
    final String topicName = "persistent://public/default/test" + UUID.randomUUID().toString();
    admin.topics().createPartitionedTopic(topicName, 3);
    pulsarClient.newProducer().topic(topicName).create().close();
    assertNull(admin.topics().getDelayedDeliveryPolicy(topicName));
    //1 Set topic policy
    DelayedDeliveryPolicies delayedDeliveryPolicies = DelayedDeliveryPolicies.builder().tickTime(2000).active(true).build();
    admin.topics().setDelayedDeliveryPolicy(topicName, delayedDeliveryPolicies);
    //wait for update
    for (int i = 0; i < 50; i++) {
        Thread.sleep(100);
        if (admin.topics().getDelayedDeliveryPolicy(topicName) != null) {
            break;
        }
    }
    //2 Setup consumer and producer
    @Cleanup
    Consumer<String> consumer = pulsarClient.newConsumer(Schema.STRING).topic(topicName).subscriptionName("test-sub" + System.currentTimeMillis()).subscriptionType(SubscriptionType.Shared).subscribe();
    @Cleanup
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(topicName).create();
    //3 Send delay message
    for (int i = 0; i < 10; i++) {
        producer.newMessage().value("delayed-msg-" + i).deliverAfter(5, TimeUnit.SECONDS).sendAsync();
    }
    producer.flush();
    //4 There will be no message in the first 3 seconds
    assertNull(consumer.receive(3, TimeUnit.SECONDS));
    Set<String> delayedMessages = new HashSet<>();
    for (int i = 0; i < 10; i++) {
        Message<String> msg = consumer.receive(4, TimeUnit.SECONDS);
        delayedMessages.add(msg.getValue());
        consumer.acknowledge(msg);
    }
    for (int i = 0; i < 10; i++) {
        assertTrue(delayedMessages.contains("delayed-msg-" + i));
    }
    //5 Disable delayed delivery
    delayedDeliveryPolicies = DelayedDeliveryPolicies.builder().tickTime(2000).active(false).build();
    admin.topics().setDelayedDeliveryPolicy(topicName, delayedDeliveryPolicies);
    //wait for update
    for (int i = 0; i < 50; i++) {
        Thread.sleep(100);
        if (!admin.topics().getDelayedDeliveryPolicy(topicName).isActive()) {
            break;
        }
    }
    producer.newMessage().value("disabled-msg").deliverAfter(5, TimeUnit.SECONDS).send();
    //6 Delay deliver is disabled, so we can receive message immediately
    Message<String> msg = consumer.receive(1, TimeUnit.SECONDS);
    assertNotNull(msg);
    consumer.acknowledge(msg);
    //7 Set a very long tick time, so that trackDelayedDelivery will fail. we can receive msg immediately.
    delayedDeliveryPolicies = DelayedDeliveryPolicies.builder().tickTime(Integer.MAX_VALUE).active(true).build();
    admin.topics().setDelayedDeliveryPolicy(topicName, delayedDeliveryPolicies);
    //wait for update
    for (int i = 0; i < 50; i++) {
        Thread.sleep(100);
        if (admin.topics().getDelayedDeliveryPolicy(topicName).isActive()) {
            break;
        }
    }
    producer.newMessage().value("long-tick-msg").deliverAfter(5, TimeUnit.SECONDS).send();
    msg = consumer.receive(1, TimeUnit.SECONDS);
    assertNotNull(msg);
    consumer.acknowledge(msg);
    //8 remove topic policy, it will use namespace level policy
    admin.topics().removeDelayedDeliveryPolicy(topicName);
    //wait for update
    for (int i = 0; i < 50; i++) {
        Thread.sleep(100);
        if (admin.topics().getDelayedDeliveryPolicy(topicName) == null) {
            break;
        }
    }
    producer.newMessage().value("long-tick-msg").deliverAfter(2, TimeUnit.SECONDS).send();
    msg = consumer.receive(1, TimeUnit.SECONDS);
    assertNull(msg);
    msg = consumer.receive(3, TimeUnit.SECONDS);
    assertNotNull(msg);
}

