    assertTrue(individuallySentPositions.isEmpty());
    assertEquals(persistentDispatcher.getLastSentPosition(), initialLastSentPosition.toString());
    // isp: [(1:-1, 1:9]] -> [(1:-1, 1:10]] -> []
    // lsp: 1:10 -> 1:10
    // upper bound is less than initial last sent position
    // upper bound and the new entry are less than or equal to initial last sent position
    assertNull(clearPosition.get());
    individuallySentPositions.addOpenClosed(1, -1, 1, 9);
    persistentDispatcher.sendMessagesToConsumers(PersistentDispatcherMultipleConsumers.ReadType.Normal, Arrays.asList(EntryImpl.create(1, 10, createMessage("test", 1))), true);
    assertTrue(individuallySentPositions.isEmpty());
    assertEquals(persistentDispatcher.getLastSentPosition(), initialLastSentPosition.toString());
    // isp: [(1:-1, 1:2], (1:3, 1:4], (1:5, 1:6]] -> [(1:-1, 1:2], (1:3, 1:4], (1:5, 1:6], (1:9, 1:10]] -> []
    // lsp: 1:10 -> 1:10
    // upper bound and the new entry are less than or equal to initial last sent position
    // individually sent positions has multiple ranges
    assertNull(clearPosition.get());
    individuallySentPositions.addOpenClosed(1, -1, 1, 2);
    individuallySentPositions.addOpenClosed(1, 3, 1, 4);
    individuallySentPositions.addOpenClosed(1, 5, 1, 6);
    persistentDispatcher.sendMessagesToConsumers(PersistentDispatcherMultipleConsumers.ReadType.Normal, Arrays.asList(EntryImpl.create(1, 10, createMessage("test", 1))), true);
    assertTrue(individuallySentPositions.isEmpty());
    assertEquals(persistentDispatcher.getLastSentPosition(), initialLastSentPosition.toString());
    // isp: [(1:-1, 1:10]] -> [(1:-1, 1:11]] -> []
    // lsp: 1:10 -> 1:11
    // upper bound is less than or equal to initial last sent position
    // the new entry is next position of initial last sent position
    assertNull(clearPosition.get());
    individuallySentPositions.addOpenClosed(1, -1, 1, 10);
    persistentDispatcher.sendMessagesToConsumers(PersistentDispatcherMultipleConsumers.ReadType.Normal, Arrays.asList(EntryImpl.create(1, 11, createMessage("test", 1))), true);
    assertTrue(individuallySentPositions.isEmpty());
    assertEquals(persistentDispatcher.getLastSentPosition(), PositionFactory.create(1, 11).toString());
    // isp: [(1:-1, 1:9]] -> [(1:-1, 1:9], (1:10, 1:11]] -> []
    // lsp: 1:10 -> 1:11
    // upper bound is less than initial last sent position
    // the new entry is next position of initial last sent position
    assertNull(clearPosition.get());
    individuallySentPositions.addOpenClosed(1, -1, 1, 9);
    persistentDispatcher.sendMessagesToConsumers(PersistentDispatcherMultipleConsumers.ReadType.Normal, Arrays.asList(EntryImpl.create(1, 11, createMessage("test", 1))), true);
    assertTrue(individuallySentPositions.isEmpty());
    assertEquals(persistentDispatcher.getLastSentPosition(), PositionFactory.create(1, 11).toString());
    // isp: [(1:11, 1:15]] -> [(1:10, 1:15]] -> []
    // lsp: 1:10 -> 1:15
    // upper bound is greater than initial last sent position
    // the range doesn't contain next position of initial last sent position
    // the new entry is next position of initial last sent position
    assertNull(clearPosition.get());
    individuallySentPositions.addOpenClosed(1, 11, 1, 15);
    persistentDispatcher.sendMessagesToConsumers(PersistentDispatcherMultipleConsumers.ReadType.Normal, Arrays.asList(EntryImpl.create(1, 11, createMessage("test", 1))), true);
    assertTrue(individuallySentPositions.isEmpty());
    assertEquals(persistentDispatcher.getLastSentPosition(), PositionFactory.create(1, 15).toString());
    // isp: [(1:11, 1:15]] -> [(1:10, 1:16]] -> []
    // lsp: 1:10 -> 1:16
    // upper bound is greater than initial last sent position
    // the range doesn't contain next position of initial last sent position
    // the new entries contain next position of initial last sent position
    // first of the new entries is less than initial last sent position
    assertNull(clearPosition.get());
    individuallySentPositions.addOpenClosed(1, 11, 1, 15);
    persistentDispatcher.sendMessagesToConsumers(PersistentDispatcherMultipleConsumers.ReadType.Normal, Arrays.asList(EntryImpl.create(1, 9, createMessage("test", 1)), EntryImpl.create(1, 11, createMessage("test", 2)), EntryImpl.create(1, 16, createMessage("test", 3))), true);
    assertTrue(individuallySentPositions.isEmpty());
    assertEquals(persistentDispatcher.getLastSentPosition(), PositionFactory.create(1, 16).toString());
    // isp: [(1:11, 1:15]] -> [(1:11, 1:15]] -> [(1:11, 1:15]]
    // lsp: 1:10 -> 1:10
    // upper bound is greater than initial last sent position
    // the range doesn't contain next position of initial last sent position
    // the new entry isn't  next position of initial last sent position
    // the range contains the new entry
    assertNull(clearPosition.get());
    individuallySentPositions.addOpenClosed(1, 11, 1, 15);
    expectedIndividuallySentPositions.addOpenClosed(1, 11, 1, 15);
    persistentDispatcher.sendMessagesToConsumers(PersistentDispatcherMultipleConsumers.ReadType.Normal, Arrays.asList(EntryImpl.create(1, 15, createMessage("test", 1))), true);
    assertEquals(individuallySentPositions.toString(), expectedIndividuallySentPositions.toString());
    assertEquals(persistentDispatcher.getLastSentPosition(), initialLastSentPosition.toString());
    // isp: [(1:11, 1:15]] -> [(1:11, 1:16]] -> [(1:11, 1:16]]
    // lsp: 1:10 -> 1:10
    // upper bound is greater than initial last sent position
    // the range doesn't contain next position of initial last sent position
    // the new entry isn't next position of initial last sent position
    // the range doesn't contain the new entry
    // the new entry is next position of upper bound
    assertNull(clearPosition.get());
    individuallySentPositions.addOpenClosed(1, 11, 1, 15);
    expectedIndividuallySentPositions.addOpenClosed(1, 11, 1, 16);
    persistentDispatcher.sendMessagesToConsumers(PersistentDispatcherMultipleConsumers.ReadType.Normal, Arrays.asList(EntryImpl.create(1, 16, createMessage("test", 1))), true);
    assertEquals(individuallySentPositions.toString(), expectedIndividuallySentPositions.toString());
    assertEquals(persistentDispatcher.getLastSentPosition(), initialLastSentPosition.toString());
    // isp: [(1:11, 1:15]] -> [(1:11, 1:15], (1:16, 1:17]] -> [(1:11, 1:15], (1:16, 1:17]]
    // lsp: 1:10 -> 1:10
    // upper bound is greater than initial last sent position
    // the range doesn't contain next position of initial last sent position
    // the new entry isn't next position of initial last sent position
    // the range doesn't contain the new entry
    // the new entry isn't next position of upper bound
    // the new entry is same ledger
    assertNull(clearPosition.get());
    individuallySentPositions.addOpenClosed(1, 11, 1, 15);
    expectedIndividuallySentPositions.addOpenClosed(1, 11, 1, 15);
    expectedIndividuallySentPositions.addOpenClosed(1, 16, 1, 17);
    persistentDispatcher.sendMessagesToConsumers(PersistentDispatcherMultipleConsumers.ReadType.Normal, Arrays.asList(EntryImpl.create(1, 17, createMessage("test", 1))), true);
    assertEquals(individuallySentPositions.toString(), expectedIndividuallySentPositions.toString());
    assertEquals(persistentDispatcher.getLastSentPosition(), initialLastSentPosition.toString());
    /*
        On multiple contiguous ledgers
         */
    // isp: [(1:11, 1:18]] -> [(1:11, 1:18], (2:-1, 2:0]] -> [(1:11, 1:18], (2:-1, 2:0]]
    // lsp: 1:10 -> 1:10
    // upper bound is greater than initial last sent position
    // the range doesn't contain next position of initial last sent position
    // the new entry isn't next position of initial last sent position
    // the range doesn't contain the new entry
    // the new entry isn't next position of upper bound
    // the new entry isn't same ledger
    assertNull(clearPosition.get());
    individuallySentPositions.addOpenClosed(1, 11, 1, 18);
    expectedIndividuallySentPositions.addOpenClosed(1, 11, 1, 18);
    expectedIndividuallySentPositions.addOpenClosed(2, -1, 2, 0);
    persistentDispatcher.sendMessagesToConsumers(PersistentDispatcherMultipleConsumers.ReadType.Normal, Arrays.asList(EntryImpl.create(2, 0, createMessage("test", 1))), true);
    assertEquals(individuallySentPositions.toString(), expectedIndividuallySentPositions.toString());
    assertEquals(persistentDispatcher.getLastSentPosition(), initialLastSentPosition.toString());
    // isp: [(1:11, 1:19], (2:-1, 2:0]] -> [(1:10, 1:19], (2:-1, 2:0]] -> []
    // lsp: 1:10 -> 2:0
    // upper bound is greater than initial last sent position
    // the range doesn't contain next position of initial last sent position
    // the new entry is next position of initial last sent position
    // the new entry isn't same ledger
    assertNull(clearPosition.get());
    individuallySentPositions.addOpenClosed(1, 11, 1, 19);
    individuallySentPositions.addOpenClosed(2, -1, 2, 0);
    persistentDispatcher.sendMessagesToConsumers(PersistentDispatcherMultipleConsumers.ReadType.Normal, Arrays.asList(EntryImpl.create(1, 11, createMessage("test", 1))), true);
    assertTrue(individuallySentPositions.isEmpty());
    assertEquals(persistentDispatcher.getLastSentPosition(), PositionFactory.create(2, 0).toString());
    // isp: [(1:11, 1:19], (2:-1, 2:19], (3:-1, 3:0]] -> [(1:10, 1:19], (2:-1, 2:19], (3:-1, 3:0]] -> []
    // lsp: 1:10 -> 3:0
    // upper bound is greater than initial last sent position
    // the range doesn't contain next position of initial last sent position
    // the new entry is next position of initial last sent position
    // the new entry isn't same ledger
    assertNull(clearPosition.get());
    individuallySentPositions.addOpenClosed(1, 11, 1, 19);
    individuallySentPositions.addOpenClosed(2, -1, 2, 19);
    individuallySentPositions.addOpenClosed(3, -1, 3, 0);
    persistentDispatcher.sendMessagesToConsumers(PersistentDispatcherMultipleConsumers.ReadType.Normal, Arrays.asList(EntryImpl.create(1, 11, createMessage("test", 1))), true);
    assertTrue(individuallySentPositions.isEmpty());
    assertEquals(persistentDispatcher.getLastSentPosition(), PositionFactory.create(3, 0).toString());
    // isp: [(1:11, 1:19], (2:-1, 2:0]] -> [(1:11, 1:19], (2:-1, 2:1]] -> [(1:11, 1:19], (2:-1, 2:1]]
    // lsp: 1:10 -> 1:10
    // upper bound is greater than initial last sent position
    // the range doesn't contain next position of initial last sent position
    // the new entry isn't next position of initial last sent position
    // the new entry isn't same ledger
    assertNull(clearPosition.get());
    individuallySentPositions.addOpenClosed(1, 11, 1, 19);
    individuallySentPositions.addOpenClosed(2, -1, 2, 0);
    expectedIndividuallySentPositions.addOpenClosed(1, 11, 1, 19);
    expectedIndividuallySentPositions.addOpenClosed(2, -1, 2, 1);
    persistentDispatcher.sendMessagesToConsumers(PersistentDispatcherMultipleConsumers.ReadType.Normal, Arrays.asList(EntryImpl.create(2, 1, createMessage("test", 1))), true);
    assertEquals(individuallySentPositions.toString(), expectedIndividuallySentPositions.toString());
    assertEquals(persistentDispatcher.getLastSentPosition(), initialLastSentPosition.toString());
}

@Test
public void testCanAcknowledgeAndAbortForTransaction() throws Exception {
    List<MutablePair<Position, Integer>> positionsPair = new ArrayList<>();
    positionsPair.add(new MutablePair<>(PositionFactory.create(2, 1), 0));
    positionsPair.add(new MutablePair<>(PositionFactory.create(2, 3), 0));
    positionsPair.add(new MutablePair<>(PositionFactory.create(2, 5), 0));
    doAnswer((invocationOnMock) -> {
        ((AsyncCallbacks.DeleteCallback) invocationOnMock.getArguments()[1]).deleteComplete(invocationOnMock.getArguments()[2]);
        return null;
    }).when(cursorMock).asyncDelete(any(List.class), any(AsyncCallbacks.DeleteCallback.class), any());
    doReturn(CommandSubscribe.SubType.Exclusive).when(consumerMock).subType();
    Awaitility.await().until(() -> {
        try {
            persistentSubscription.addConsumer(consumerMock);
            return true;
        } catch (Exception e) {
            return false;
        }
    });
    // Single ack for txn1
    persistentSubscription.transactionIndividualAcknowledge(txnID1, positionsPair);
    List<Position> positions = new ArrayList<>();
    positions.add(PositionFactory.create(1, 100));
    // Cumulative ack for txn1
    persistentSubscription.transactionCumulativeAcknowledge(txnID1, positions).get();
    positions.clear();
    positions.add(PositionFactory.create(2, 1));
    // Can not single ack message already acked.
    try {
        persistentSubscription.transactionIndividualAcknowledge(txnID2, positionsPair).get();
        fail("Single acknowledge for transaction2 should fail. ");
    } catch (ExecutionException e) {
        assertEquals(e.getCause().getMessage(), "[persistent://prop/use/ns-abc/successTopic][subscriptionName] " + "Transaction:(1,2) try to ack message:2:1 in pending ack status.");
    }
    positions.clear();
    positions.add(PositionFactory.create(2, 50));
    // Can not cumulative ack message for another txn.
    try {
        persistentSubscription.transactionCumulativeAcknowledge(txnID2, positions).get();
        fail("Cumulative acknowledge for transaction2 should fail. ");
    } catch (ExecutionException e) {
        assertTrue(e.getCause() instanceof TransactionConflictException);
        assertEquals(e.getCause().getMessage(), "[persistent://prop/use/ns-abc/successTopic]" + "[subscriptionName] Transaction:(1,2) try to cumulative batch ack position: " + "2:50 within range of current currentPosition: 1:100");
    }
    List<Position> positionList = new ArrayList<>();
    positionList.add(PositionFactory.create(1, 1));
    positionList.add(PositionFactory.create(1, 3));
    positionList.add(PositionFactory.create(1, 5));
    positionList.add(PositionFactory.create(3, 1));
    positionList.add(PositionFactory.create(3, 3));
    positionList.add(PositionFactory.create(3, 5));
    // Acknowledge from normal consumer will succeed ignoring message acked by ongoing transaction.
    persistentSubscription.acknowledgeMessage(positionList, AckType.Individual, Collections.emptyMap());
    //Abort txn.
    persistentSubscription.endTxn(txnID1.getMostSigBits(), txnID2.getLeastSigBits(), TxnAction.ABORT_VALUE, -1);
    positions.clear();
    positions.add(PositionFactory.create(2, 50));
    // Retry above ack, will succeed. As abort has clear pending_ack for those messages.
    persistentSubscription.transactionCumulativeAcknowledge(txnID2, positions);
    positionsPair.clear();
    positionsPair.add(new MutablePair(PositionFactory.create(2, 1), 0));
    persistentSubscription.transactionIndividualAcknowledge(txnID2, positionsPair);
}

@Test
public void testAcknowledgeUpdateCursorLastActive() throws Exception {
    doAnswer((invocationOnMock) -> {
