@Test
public void testChangeSubscriptionType() throws Exception {
    PersistentTopic topic = new PersistentTopic(successTopicName, ledgerMock, brokerService);
    PersistentSubscription sub = new PersistentSubscription(topic, "change-sub-type", cursorMock, false);
    Consumer consumer = new Consumer(sub, SubType.Exclusive, topic.getName(), 1, 0, "Cons1", true, serverCnx, "myrole-1", Collections.emptyMap(), false, new KeySharedMeta().setKeySharedMode(KeySharedMode.AUTO_SPLIT), MessageId.latest, DEFAULT_CONSUMER_EPOCH);
    sub.addConsumer(consumer);
    consumer.close();
    SubType previousSubType = SubType.Exclusive;
    for (SubType subType : List.of(SubType.Shared, SubType.Failover, SubType.Key_Shared, SubType.Exclusive)) {
        Dispatcher previousDispatcher = sub.getDispatcher();
        consumer = new Consumer(sub, subType, topic.getName(), 1, 0, "Cons1", true, serverCnx, "myrole-1", Collections.emptyMap(), false, new KeySharedMeta().setKeySharedMode(KeySharedMode.AUTO_SPLIT), MessageId.latest, DEFAULT_CONSUMER_EPOCH);
        sub.addConsumer(consumer);
        assertTrue(sub.getDispatcher().isConsumerConnected());
        assertFalse(sub.getDispatcher().isClosed());
        assertEquals(sub.getDispatcher().getType(), subType);
        assertFalse(previousDispatcher.isConsumerConnected());
        assertTrue(previousDispatcher.isClosed());
        assertEquals(previousDispatcher.getType(), previousSubType);
        consumer.close();
        previousSubType = subType;
    }
}

