public void testDeleteTopicDeleteOnMetadataStoreFailed() throws Exception {
    doReturn(CompletableFuture.completedFuture(null)).when(ledgerMock).asyncTruncate();
    // create topic
    brokerService.pulsar().getPulsarResources().getNamespaceResources().getPartitionedTopicResources().createPartitionedTopic(TopicName.get(successTopicName), new PartitionedTopicMetadata(2));
