    for (int i = 0; i < 10; i++) {
        producer.send("test");
    }
    EntryFilter mockFilterReject = mock(EntryFilter.class);
    when(mockFilterReject.filterEntry(any(Entry.class), any(FilterContext.class))).thenReturn(EntryFilter.FilterResult.REJECT);
    EntryFilter mockFilterAccept = mock(EntryFilter.class);
    when(mockFilterAccept.filterEntry(any(Entry.class), any(FilterContext.class))).thenReturn(EntryFilter.FilterResult.ACCEPT);
    if (overrideBrokerEntryFilters) {
        setMockFilterToTopic((PersistentTopic) pulsar.getBrokerService().getTopicReference(topic).get(), List.of(mockFilterReject, mockFilterAccept));
    } else {
        setMockFilterToTopic((PersistentTopic) pulsar.getBrokerService().getTopicReference(topic).get(), List.of());
        setMockBrokerFilter(List.of(mockFilterReject, mockFilterAccept));
    }
    Consumer<String> consumer = pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionInitialPosition(Earliest).subscriptionName(subName).subscribe();
    int counter = 0;
    while (true) {
        Message<String> message = consumer.receive(1, TimeUnit.SECONDS);
        if (message != null) {
            counter++;
            consumer.acknowledge(message);
        } else {
            break;
        }
    }
    // All normal messages can be received
    assertEquals(0, counter);
    consumer.close();
    verify(mockFilterReject, times(10)).filterEntry(any(Entry.class), any(FilterContext.class));
    verify(mockFilterAccept, never()).filterEntry(any(Entry.class), any(FilterContext.class));
    if (overrideBrokerEntryFilters) {
        setMockFilterToTopic((PersistentTopic) pulsar.getBrokerService().getTopicReference(topic).get(), List.of(mockFilterAccept, mockFilterReject));
    } else {
        setMockFilterToTopic((PersistentTopic) pulsar.getBrokerService().getTopicReference(topic).get(), List.of());
        setMockBrokerFilter(List.of(mockFilterAccept, mockFilterReject));
    }
    @Cleanup
    Consumer<String> consumer2 = pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionInitialPosition(Earliest).subscriptionName(subName + "-2").subscribe();
    counter = 0;
    while (true) {
        Message<String> message = consumer2.receive(1, TimeUnit.SECONDS);
        if (message != null) {
            counter++;
            consumer2.acknowledge(message);
        } else {
            break;
        }
    }
    assertEquals(0, counter);
    verify(mockFilterReject, times(20)).filterEntry(any(Entry.class), any(FilterContext.class));
    verify(mockFilterAccept, times(10)).filterEntry(any(Entry.class), any(FilterContext.class));
}

