    Thread.sleep(2 * config1.getReplicatedSubscriptionsSnapshotFrequencyMillis());
    consumer2 = client2.newConsumer().topic(topicName).subscriptionName(subName).subscribe();
    final int numReceivedMessages2 = readMessages(consumer2, receivedMessages, -1, allowDuplicates);
    consumer2.close();
    assertEquals(receivedMessages, sentMessages);
    assertTrue(numReceivedMessages1 < numMessages, String.format("numReceivedMessages1 (%d) should be less than %d", numReceivedMessages1, numMessages));
    assertTrue(numReceivedMessages2 < numMessages, String.format("numReceivedMessages2 (%d) should be less than %d", numReceivedMessages2, numMessages));
}

