    assertEquals(topic.getReplicators().values().get(0).getRateLimiter().get().getDispatchRateOnByte(), byteRate);
    @Cleanup
    PulsarClient client2 = PulsarClient.builder().serviceUrl(url2.toString()).build();
    final AtomicInteger totalReceived = new AtomicInteger(0);
    @Cleanup
    Consumer<byte[]> ignored = client2.newConsumer().topic(topicName).subscriptionName("sub2-in-cluster2").messageListener((c1, msg) -> {
