@Test(timeOut = testTimeout)
public void testFailoverInactiveConsumer() throws Exception {
    String key = "testFailoverInactiveConsumer";
    final String topicName = "persistent://prop/use/ns-abc/topic-" + key;
    final String subscriptionName = "my-failover-subscription-" + key;
    final String messagePredicate = "my-message-" + key + "-";
    final int totalMessages = 10;
    // 1. producer connect
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topicName).enableBatching(false).messageRoutingMode(MessageRoutingMode.SinglePartition).create();
    PersistentTopic topicRef = (PersistentTopic) pulsar.getBrokerService().getTopicReference(topicName).get();
    assertNotNull(topicRef);
    assertEquals(topicRef.getProducers().size(), 1);
    // 2. Create consumer
    ConsumerBuilder<byte[]> consumerBuilder = pulsarClient.newConsumer().topic(topicName).subscriptionName(subscriptionName).receiverQueueSize(10).subscriptionType(SubscriptionType.Failover);
    Consumer<byte[]> consumer1 = consumerBuilder.clone().consumerName("Consumer-1").subscribe();
    Consumer<byte[]> consumer2 = consumerBuilder.clone().consumerName("Consumer-2").subscribe();
    // 3. Producer publishes messages
    for (int i = 0; i < totalMessages; i++) {
        String message = messagePredicate + i;
        producer.send(message.getBytes());
        log.info("Producer produced " + message);
    }
    // 4. Receive messages
    int receivedConsumer1 = 0, receivedConsumer2 = 0;
    Message<byte[]> message1;
    Message<byte[]> message2;
    do {
        message1 = consumer1.receive(500, TimeUnit.MILLISECONDS);
        if (message1 != null) {
            log.info("Consumer 1 Received: " + new String(message1.getData()));
            receivedConsumer1 += 1;
        }
    } while (message1 != null);
    do {
        message2 = consumer2.receive(500, TimeUnit.MILLISECONDS);
        if (message2 != null) {
            log.info("Consumer 2 Received: " + new String(message2.getData()));
            receivedConsumer2 += 1;
        }
    } while (message2 != null);
    log.info("Consumer 1 receives = " + receivedConsumer1);
    log.info("Consumer 2 receives = " + receivedConsumer2);
    log.info("Total receives = " + (receivedConsumer2 + receivedConsumer1));
    assertEquals(receivedConsumer2 + receivedConsumer1, totalMessages);
    // Consumer 2 is on Stand By
    assertEquals(receivedConsumer1, 0);
    // 5. Consumer 2 asks for a redelivery but the request is ignored
    log.info("Consumer 2 asks for resend");
    consumer2.redeliverUnacknowledgedMessages();
    Thread.sleep(1000);
    message1 = consumer1.receive(500, TimeUnit.MILLISECONDS);
    message2 = consumer2.receive(500, TimeUnit.MILLISECONDS);
    assertNull(message1);
    assertNotNull(message2);
}

/**
 * make sure new schema is backwards compatible with latest
 */
@Test
public void testBackwardCompatibility() {
    SchemaCompatibilityCheck schemaCompatibilityCheck = getSchemaCheck();
    // adding a field with default is backwards compatible
    Assert.assertTrue(schemaCompatibilityCheck.isCompatible(schemaData1, schemaData2, SchemaCompatibilityStrategy.BACKWARD), "adding a field with default is backwards compatible");
    // adding a field without default is NOT backwards compatible
    Assert.assertFalse(schemaCompatibilityCheck.isCompatible(schemaData1, schemaData3, SchemaCompatibilityStrategy.BACKWARD), "adding a field without default is NOT backwards compatible");
    // Modifying a field name with an alias is backwards compatible
    Assert.assertTrue(schemaCompatibilityCheck.isCompatible(schemaData1, schemaData4, SchemaCompatibilityStrategy.BACKWARD), "Modifying a field name with an alias is backwards compatible");
    // evolving field to a union is backwards compatible
    Assert.assertTrue(schemaCompatibilityCheck.isCompatible(schemaData1, schemaData5, SchemaCompatibilityStrategy.BACKWARD), "evolving field to a union is backwards compatible");
    // removing a field from a union is NOT backwards compatible
    Assert.assertFalse(schemaCompatibilityCheck.isCompatible(schemaData5, schemaData1, SchemaCompatibilityStrategy.BACKWARD), "removing a field from a union is NOT backwards compatible");
    // adding a field to a union is backwards compatible
    Assert.assertTrue(schemaCompatibilityCheck.isCompatible(schemaData5, schemaData6, SchemaCompatibilityStrategy.BACKWARD), "adding a field to a union is backwards compatible");
    // removing a field a union is NOT backwards compatible
    Assert.assertFalse(schemaCompatibilityCheck.isCompatible(schemaData6, schemaData5, SchemaCompatibilityStrategy.BACKWARD), "removing a field a union is NOT backwards compatible");
}

