    assertThat(otelMetrics).anySatisfy(metric -> assertThat(metric).hasName(SchemaRegistryStats.SCHEMA_REGISTRY_REQUEST_DURATION_METRIC_NAME).hasHistogramSatisfying(histogram -> histogram.hasPointsSatisfying(point -> point.hasAttributes(Attributes.of(OpenTelemetryAttributes.PULSAR_NAMESPACE, "tenant/ns", SchemaRegistryStats.REQUEST_TYPE_KEY, "delete", SchemaRegistryStats.RESPONSE_TYPE_KEY, "success")).hasCount(1), point -> point.hasAttributes(Attributes.of(OpenTelemetryAttributes.PULSAR_NAMESPACE, "tenant/ns", SchemaRegistryStats.REQUEST_TYPE_KEY, "put", SchemaRegistryStats.RESPONSE_TYPE_KEY, "success")).hasCount(1), point -> point.hasAttributes(Attributes.of(OpenTelemetryAttributes.PULSAR_NAMESPACE, "tenant/ns", SchemaRegistryStats.REQUEST_TYPE_KEY, "list", SchemaRegistryStats.RESPONSE_TYPE_KEY, "success")).hasCount(1), point -> point.hasAttributes(Attributes.of(OpenTelemetryAttributes.PULSAR_NAMESPACE, "tenant/ns", SchemaRegistryStats.REQUEST_TYPE_KEY, "get", SchemaRegistryStats.RESPONSE_TYPE_KEY, "success")).hasCount(1))));
    ByteArrayOutputStream output = new ByteArrayOutputStream();
    PrometheusMetricsTestUtil.generate(pulsar, false, false, false, output);
    output.flush();
    String metricsStr = output.toString(StandardCharsets.UTF_8);
    Multimap<String, Metric> metrics = parseMetrics(metricsStr);
    Collection<Metric> delMetrics = metrics.get("pulsar_schema_del_ops_failed_total");
    Assert.assertEquals(delMetrics.size(), 0);
    Collection<Metric> getMetrics = metrics.get("pulsar_schema_get_ops_failed_total");
    Assert.assertEquals(getMetrics.size(), 0);
    Collection<Metric> putMetrics = metrics.get("pulsar_schema_put_ops_failed_total");
    Assert.assertEquals(putMetrics.size(), 0);
    Collection<Metric> deleteLatency = metrics.get("pulsar_schema_del_ops_latency_count");
    for (Metric metric : deleteLatency) {
        Assert.assertEquals(metric.tags.get("namespace"), namespace);
        Assert.assertTrue(metric.value > 0);
    }
    Collection<Metric> getLatency = metrics.get("pulsar_schema_get_ops_latency_count");
    for (Metric metric : getLatency) {
        Assert.assertEquals(metric.tags.get("namespace"), namespace);
        Assert.assertTrue(metric.value > 0);
    }
    Collection<Metric> putLatency = metrics.get("pulsar_schema_put_ops_latency_count");
    for (Metric metric : putLatency) {
        Assert.assertEquals(metric.tags.get("namespace"), namespace);
        Assert.assertTrue(metric.value > 0);
    }
}

