@Test
public void testSeekByFunction() throws Exception {
    final String topicName = "persistent://prop/use/ns-abc/test" + UUID.randomUUID();
    int partitionNum = 4;
    int msgNum = 160;
    admin.topics().createPartitionedTopic(topicName, partitionNum);
    creatProducerAndSendMsg(topicName, msgNum);
    org.apache.pulsar.client.api.Consumer<String> consumer = pulsarClient.newConsumer(Schema.STRING).startMessageIdInclusive().topic(topicName).subscriptionName("my-sub").subscribe();
    TopicName partitionedTopic = TopicName.get(topicName);
    Reader<String> reader = pulsarClient.newReader(Schema.STRING).startMessageId(MessageId.earliest).topic(partitionedTopic.getPartition(0).toString()).create();
    List<MessageId> list = new ArrayList<>();
    while (reader.hasMessageAvailable()) {
        list.add(reader.readNext().getMessageId());
    }
    // get middle msg from partition-0
    MessageId middleMsgIdInPartition0 = list.get(list.size() / 2);
    List<MessageId> msgNotIn = list.subList(0, list.size() / 2 - 1);
    // get last msg from partition-1
    MessageId lastMsgInPartition1 = admin.topics().getLastMessageId(partitionedTopic.getPartition(1).toString());
    reader.close();
    reader = pulsarClient.newReader(Schema.STRING).startMessageId(MessageId.earliest).topic(partitionedTopic.getPartition(2).toString()).create();
    // get first msg from partition-2
    MessageId firstMsgInPartition2 = reader.readNext().getMessageId();
    consumer.seek((topic) -> {
        int index = TopicName.get(topic).getPartitionIndex();
        if (index == 0) {
            return middleMsgIdInPartition0;
        } else if (index == 1) {
            return lastMsgInPartition1;
        } else if (index == 2) {
            return firstMsgInPartition2;
        }
        return null;
    });
    Set<MessageId> received = new HashSet<>();
    while (true) {
        Message<String> message = consumer.receive(2, TimeUnit.SECONDS);
        if (message == null) {
            break;
        }
        received.add(message.getMessageId());
    }
    int msgNumFromPartition1 = list.size() / 2;
    int msgNumFromPartition2 = 1;
    int msgNumFromPartition3 = msgNum / partitionNum;
    assertEquals(received.size(), msgNumFromPartition1 + msgNumFromPartition2 + msgNumFromPartition3);
    assertTrue(received.contains(middleMsgIdInPartition0));
    assertTrue(received.contains(lastMsgInPartition1));
    assertTrue(received.contains(firstMsgInPartition2));
    for (MessageId messageId : msgNotIn) {
        assertFalse(received.contains(messageId));
    }
    reader.close();
    consumer.close();
}

@Test
public void testSeekByFunctionAndMultiTopic() throws Exception {
    final String topicName = "persistent://prop/use/ns-abc/test" + UUID.randomUUID();
    final String topicName2 = "persistent://prop/use/ns-abc/test" + UUID.randomUUID();
    int partitionNum = 3;
    int msgNum = 15;
    admin.topics().createPartitionedTopic(topicName, partitionNum);
    admin.topics().createPartitionedTopic(topicName2, partitionNum);
    creatProducerAndSendMsg(topicName, msgNum);
    creatProducerAndSendMsg(topicName2, msgNum);
    TopicName topic = TopicName.get(topicName);
    TopicName topic2 = TopicName.get(topicName2);
    MessageId msgIdInTopic1Partition0 = admin.topics().getLastMessageId(topic.getPartition(0).toString());
    MessageId msgIdInTopic1Partition2 = admin.topics().getLastMessageId(topic.getPartition(2).toString());
    MessageId msgIdInTopic2Partition0 = admin.topics().getLastMessageId(topic2.getPartition(0).toString());
    MessageId msgIdInTopic2Partition2 = admin.topics().getLastMessageId(topic2.getPartition(2).toString());
    org.apache.pulsar.client.api.Consumer<String> consumer = pulsarClient.newConsumer(Schema.STRING).startMessageIdInclusive().topics(Arrays.asList(topicName, topicName2)).subscriptionName("my-sub").subscribe();
    consumer.seek((partitionedTopic) -> {
        if (partitionedTopic.equals(topic.getPartition(0).toString())) {
            return msgIdInTopic1Partition0;
        }
        if (partitionedTopic.equals(topic.getPartition(2).toString())) {
            return msgIdInTopic1Partition2;
        }
        if (partitionedTopic.equals(topic2.getPartition(0).toString())) {
            return msgIdInTopic2Partition0;
        }
        if (partitionedTopic.equals(topic2.getPartition(2).toString())) {
            return msgIdInTopic2Partition2;
        }
        return MessageId.earliest;
    });
    int count = 0;
    while (true) {
        Message message = consumer.receive(2, TimeUnit.SECONDS);
        if (message == null) {
            break;
        }
        count++;
    }
    int msgInTopic1Partition0 = 1;
    int msgInTopic1Partition1 = msgNum / partitionNum;
    int msgInTopic1Partition2 = 1;
    assertEquals(count, (msgInTopic1Partition0 + msgInTopic1Partition1 + msgInTopic1Partition2) * 2);
}

@Test
public void testExceptionBySeekFunction() throws Exception {
    final String topicName = "persistent://prop/use/ns-abc/test" + UUID.randomUUID();
    creatProducerAndSendMsg(topicName, 10);
    org.apache.pulsar.client.api.Consumer consumer = pulsarClient.newConsumer().topic(topicName).subscriptionName("my-sub").subscribe();
    try {
        consumer.seek((Function<String, MessageId>) null);
        fail("should fail");
    } catch (Exception e) {
        assertTrue(e instanceof PulsarClientException);
        assertTrue(e.getMessage().contains("Function must be set"));
    }
    assertNull(consumer.seekAsync((topic) -> null).get());
    try {
        assertNull(consumer.seekAsync((topic) -> new Object()).get());
        fail("should fail");
    } catch (Exception e) {
        assertTrue(e.getCause() instanceof PulsarClientException);
        assertTrue(e.getCause().getMessage().contains("Only support seek by messageId or timestamp"));
    }
}

@Test
public void testDynamicEnableConfigurationMetadataSyncEventTopic() throws Exception {
    // Verify the condition that supports synchronizer: the metadata store is a different one.
    Awaitility.await().untilAsserted(() -> {
        boolean shouldShutdownConfigurationMetadataStore = WhiteboxImpl.getInternalState(pulsar1, "shouldShutdownConfigurationMetadataStore");
        assertTrue(shouldShutdownConfigurationMetadataStore);
    });
    // Verify the synchronizer will be created dynamically.
    admin1.brokers().updateDynamicConfiguration(CONF_NAME_SYNC_EVENT_TOPIC, SYNC_EVENT_TOPIC);
    Awaitility.await().untilAsserted(() -> {
        assertEquals(pulsar1.getConfig().getConfigurationMetadataSyncEventTopic(), SYNC_EVENT_TOPIC);
        PulsarMetadataEventSynchronizer synchronizer = WhiteboxImpl.getInternalState(pulsar1, "configMetadataSynchronizer");
        assertNotNull(synchronizer);
        assertEquals(synchronizer.getState(), PulsarMetadataEventSynchronizer.State.Started);
        assertTrue(synchronizer.isStarted());
    });
    PulsarMetadataEventSynchronizer synchronizerStarted = WhiteboxImpl.getInternalState(pulsar1, "configMetadataSynchronizer");
    Producer<MetadataEvent> producerStarted = WhiteboxImpl.getInternalState(synchronizerStarted, "producer");
    Consumer<MetadataEvent> consumerStarted = WhiteboxImpl.getInternalState(synchronizerStarted, "consumer");
    // Verify the synchronizer will be closed dynamically.
    admin1.brokers().deleteDynamicConfiguration(CONF_NAME_SYNC_EVENT_TOPIC);
    Awaitility.await().untilAsserted(() -> {
        // The synchronizer that was started will be closed.
        assertEquals(synchronizerStarted.getState(), PulsarMetadataEventSynchronizer.State.Closed);
        assertTrue(synchronizerStarted.isClosingOrClosed());
        assertFalse(producerStarted.isConnected());
        assertFalse(consumerStarted.isConnected());
        // The synchronizer in memory will be null.
        assertNull(pulsar1.getConfig().getConfigurationMetadataSyncEventTopic());
        PulsarMetadataEventSynchronizer synchronizer = WhiteboxImpl.getInternalState(pulsar1, "configMetadataSynchronizer");
        assertNull(synchronizer);
    });
}

@Test
public void testConcurrentlyRegisterUnregisterListeners() throws ExecutionException, InterruptedException {
    TopicName topicName = TopicName.get("test");
    class TopicPolicyListenerImpl implements TopicPolicyListener<TopicPolicies> {

        @Override
        public void onUpdate(TopicPolicies data) {
            //no op.
        }
    }
    CompletableFuture<Void> f = CompletableFuture.completedFuture(null).thenRunAsync(() -> {
        for (int i = 0; i < 100; i++) {
            TopicPolicyListener<TopicPolicies> listener = new TopicPolicyListenerImpl();
            systemTopicBasedTopicPoliciesService.registerListener(topicName, listener);
            Assert.assertNotNull(systemTopicBasedTopicPoliciesService.listeners.get(topicName));
            Assert.assertTrue(systemTopicBasedTopicPoliciesService.listeners.get(topicName).size() >= 1);
            systemTopicBasedTopicPoliciesService.unregisterListener(topicName, listener);
        }
    });
    for (int i = 0; i < 100; i++) {
        TopicPolicyListener<TopicPolicies> listener = new TopicPolicyListenerImpl();
        systemTopicBasedTopicPoliciesService.registerListener(topicName, listener);
        Assert.assertNotNull(systemTopicBasedTopicPoliciesService.listeners.get(topicName));
        Assert.assertTrue(systemTopicBasedTopicPoliciesService.listeners.get(topicName).size() >= 1);
        systemTopicBasedTopicPoliciesService.unregisterListener(topicName, listener);
    }
    f.get();
    //Some system topics will be added to the listeners. Just check if it contains topicName.
    Assert.assertFalse(systemTopicBasedTopicPoliciesService.listeners.containsKey(topicName));
}

@Test
public void testGetPolicy() throws ExecutionException, InterruptedException, TopicPoliciesCacheNotInitException {
    // Init topic policies
    TopicPolicies initPolicy = TopicPolicies.builder().maxConsumerPerTopic(10).build();
    systemTopicBasedTopicPoliciesService.updateTopicPoliciesAsync(TOPIC1, initPolicy).get();
    // Wait for all topic policies updated.
