@Test
public void testMarkerDelete() throws Exception {
    final String subName = "testMarkerDelete";
    final String topicName = NAMESPACE1 + "/testMarkerDelete";
    @Cleanup
    Consumer<byte[]> consumer = pulsarClient.newConsumer().topic(topicName).subscriptionName(subName).isAckReceiptEnabled(true).subscriptionType(SubscriptionType.Shared).subscribe();
    Producer<byte[]> producer = pulsarClient.newProducer().sendTimeout(0, TimeUnit.SECONDS).topic(topicName).create();
    Transaction txn1 = getTxn();
    Transaction txn2 = getTxn();
    Transaction txn3 = getTxn();
    Transaction txn4 = getTxn();
    MessageIdImpl msgId1 = (MessageIdImpl) producer.newMessage(txn1).send();
    MessageIdImpl msgId2 = (MessageIdImpl) producer.newMessage(txn2).send();
    assertNull(consumer.receive(1, TimeUnit.SECONDS));
    txn1.commit().get();
    consumer.acknowledgeAsync(consumer.receive()).get();
    assertNull(consumer.receive(1, TimeUnit.SECONDS));
    // maxReadPosition move to msgId1, msgId2 have not be committed
    assertEquals(admin.topics().getInternalStats(topicName).cursors.get(subName).markDeletePosition, PositionFactory.create(msgId1.getLedgerId(), msgId1.getEntryId()).toString());
    MessageIdImpl msgId3 = (MessageIdImpl) producer.newMessage(txn3).send();
    txn2.commit().get();
    consumer.acknowledgeAsync(consumer.receive()).get();
    assertNull(consumer.receive(1, TimeUnit.SECONDS));
    // maxReadPosition move to txn1 marker, so entryId is msgId2.getEntryId() + 1,
    // because send msgId2 before commit txn1
    assertEquals(admin.topics().getInternalStats(topicName).cursors.get(subName).markDeletePosition, PositionFactory.create(msgId2.getLedgerId(), msgId2.getEntryId() + 1).toString());
    MessageIdImpl msgId4 = (MessageIdImpl) producer.newMessage(txn4).send();
    txn3.commit().get();
    consumer.acknowledgeAsync(consumer.receive()).get();
    assertNull(consumer.receive(1, TimeUnit.SECONDS));
    // maxReadPosition move to txn2 marker, because msgId4 have not be committed
    assertEquals(admin.topics().getInternalStats(topicName).cursors.get(subName).markDeletePosition, PositionFactory.create(msgId3.getLedgerId(), msgId3.getEntryId() + 1).toString());
    txn4.abort().get();
    // maxReadPosition move to txn4 abort marker, so entryId is msgId4.getEntryId() + 2
    Awaitility.await().untilAsserted(() -> assertEquals(admin.topics().getInternalStats(topicName).cursors.get(subName).markDeletePosition, PositionFactory.create(msgId4.getLedgerId(), msgId4.getEntryId() + 2).toString()));
}

