@Test
public void testAvgMessagesPerEntry() throws Exception {
    conf.setAllowOverrideEntryFilters(true);
    final String topic = "persistent://public/default/testFilterState";
    String subName = "sub";
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).producerName("producer1").enableBatching(true).topic(topic).batchingMaxMessages(20).batchingMaxPublishDelay(5, TimeUnit.SECONDS).batchingMaxBytes(Integer.MAX_VALUE).create();
    producer.send("first-message");
    List<CompletableFuture<MessageId>> futures = new ArrayList<>();
    for (int i = 0; i < 20; i++) {
        futures.add(producer.sendAsync("message"));
    }
    FutureUtil.waitForAll(futures);
    producer.close();
    Producer<String> producer2 = pulsarClient.newProducer(Schema.STRING).producerName("producer2").enableBatching(false).topic(topic).create();
    producer2.newMessage().value("producer2-message").send();
    producer2.close();
    // mock entry filters
    NarClassLoader narClassLoader = mock(NarClassLoader.class);
    EntryFilter filter = new EntryFilterProducerTest();
    EntryFilterWithClassLoader loader = spyWithClassAndConstructorArgs(EntryFilterWithClassLoader.class, filter, narClassLoader, false);
    Pair<String, List<EntryFilter>> entryFilters = Pair.of("filter", List.of(loader));
    PersistentTopic topicRef = (PersistentTopic) pulsar.getBrokerService().getTopicReference(topic).get();
    Field field1 = topicRef.getClass().getSuperclass().getDeclaredField("entryFilters");
    field1.setAccessible(true);
    field1.set(topicRef, entryFilters);
    Map<String, String> metadataConsumer = new HashMap<>();
    metadataConsumer.put("matchValueAccept", "producer1");
    metadataConsumer.put("matchValueReschedule", "producer2");
    @Cleanup
    Consumer<String> consumer = pulsarClient.newConsumer(Schema.STRING).topic(topic).properties(metadataConsumer).subscriptionName(subName).subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).subscribe();
    int counter = 0;
    while (true) {
        Message<String> message = consumer.receive(10, TimeUnit.SECONDS);
        if (message != null) {
            counter++;
            assertNotEquals(message.getValue(), "producer2-message");
            consumer.acknowledge(message);
        } else {
            break;
        }
    }
    assertEquals(21, counter);
    ConsumerStats consumerStats = admin.topics().getStats(topic).getSubscriptions().get(subName).getConsumers().get(0);
    assertEquals(21, consumerStats.getMsgOutCounter());
    // Math.round(1 * 0.9 + 0.1 * (20 / 1))
    int avgMessagesPerEntry = consumerStats.getAvgMessagesPerEntry();
    assertEquals(3, avgMessagesPerEntry);
}

