        String message = "my-message-" + i;
        producer.send(message.getBytes());
    }
    for (Entry<String, ManagedLedgerImpl> ledger : managedLedgerFactory.getManagedLedgers().entrySet()) {
        ManagedLedgerMBeanImpl stats = (ManagedLedgerMBeanImpl) ledger.getValue().getStats();
        stats.refreshStats(1, TimeUnit.SECONDS);
    }
    List<Metrics> list3 = metrics.generate();
    Assert.assertEquals(list3.get(0).getMetrics().get(addEntryRateKey), 5.0D);
    // Validate OpenTelemetry metrics.
    var ledgers = managedLedgerFactory.getManagedLedgers();
    var topicNameObj = TopicName.get(topicName);
    var mlName = topicNameObj.getPersistenceNamingEncoding();
    assertThat(ledgers).containsKey(mlName);
    var ml = ledgers.get(mlName);
    var attribCommon = Attributes.of(OpenTelemetryAttributes.ML_NAME, mlName, OpenTelemetryAttributes.PULSAR_NAMESPACE, topicNameObj.getNamespace());
    var metricReader = pulsarTestContext.getOpenTelemetryMetricReader();
    Awaitility.await().untilAsserted(() -> {
        var otelMetrics = metricReader.collectAllMetrics();
        assertMetricLongSumValue(otelMetrics, OpenTelemetryManagedLedgerStats.BACKLOG_COUNTER, attribCommon, 15);
        assertMetricLongSumValue(otelMetrics, OpenTelemetryManagedLedgerStats.MARK_DELETE_COUNTER, attribCommon, 0);
    });
    for (int i = 0; i < 10; i++) {
        var msg = consumer.receive(1, TimeUnit.SECONDS);
        consumer.acknowledge(msg);
    }
    Awaitility.await().untilAsserted(() -> {
        var otelMetrics = metricReader.collectAllMetrics();
        assertMetricLongSumValue(otelMetrics, OpenTelemetryManagedLedgerStats.BACKLOG_COUNTER, attribCommon, 5);
        assertMetricLongSumValue(otelMetrics, OpenTelemetryManagedLedgerStats.MARK_DELETE_COUNTER, attribCommon, value -> assertThat(value).isPositive());
    });
    Awaitility.await().untilAsserted(() -> {
        @Cleanup
        var cons = pulsarClient.newConsumer().topic(topicName).subscriptionName(BrokerTestUtil.newUniqueName("sub")).subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).subscribe();
        cons.receive(1, TimeUnit.SECONDS);
        var attribSucceed = Attributes.of(OpenTelemetryAttributes.ML_NAME, mlName, OpenTelemetryAttributes.PULSAR_NAMESPACE, topicNameObj.getNamespace(), OpenTelemetryAttributes.ML_OPERATION_STATUS, "success");
        var attribFailed = Attributes.of(OpenTelemetryAttributes.ML_NAME, mlName, OpenTelemetryAttributes.PULSAR_NAMESPACE, topicNameObj.getNamespace(), OpenTelemetryAttributes.ML_OPERATION_STATUS, "failure");
        var otelMetrics = metricReader.collectAllMetrics();
        assertMetricLongSumValue(otelMetrics, OpenTelemetryManagedLedgerStats.ADD_ENTRY_COUNTER, attribSucceed, 15);
        assertMetricLongSumValue(otelMetrics, OpenTelemetryManagedLedgerStats.ADD_ENTRY_COUNTER, attribFailed, 0);
        assertMetricLongSumValue(otelMetrics, OpenTelemetryManagedLedgerStats.BYTES_OUT_COUNTER, attribCommon, value -> assertThat(value).isPositive());
        assertMetricLongSumValue(otelMetrics, OpenTelemetryManagedLedgerStats.BYTES_OUT_WITH_REPLICAS_COUNTER, attribCommon, value -> assertThat(value).isPositive());
        assertMetricLongSumValue(otelMetrics, OpenTelemetryManagedLedgerStats.READ_ENTRY_COUNTER, attribSucceed, value -> assertThat(value).isPositive());
        assertMetricLongSumValue(otelMetrics, OpenTelemetryManagedLedgerStats.READ_ENTRY_COUNTER, attribFailed, 0);
        assertMetricLongSumValue(otelMetrics, OpenTelemetryManagedLedgerStats.BYTES_IN_COUNTER, attribCommon, value -> assertThat(value).isPositive());
        assertMetricLongSumValue(otelMetrics, OpenTelemetryManagedLedgerStats.READ_ENTRY_CACHE_MISS_COUNTER, attribCommon, value -> assertThat(value).isPositive());
    });
}

