    admin.topics().createNonPartitionedTopic(topicName);
    var producerCount = 5;
    var messagesPerProducer = 2;
    var consumerCount = 3;
    var messageCount = producerCount * messagesPerProducer;
    for (int i = 0; i < producerCount; i++) {
        var producer = registerCloseable(pulsarClient.newProducer().topic(topicName).create());
        for (int j = 0; j < messagesPerProducer; j++) {
            producer.send(String.format("producer-%d-msg-%d", i, j).getBytes());
        }
    }
    var cdl = new CountDownLatch(consumerCount);
    for (int i = 0; i < consumerCount; i++) {
        var consumer = registerCloseable(pulsarClient.newConsumer().topic(topicName).subscriptionName("test").subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).subscriptionType(SubscriptionType.Shared).subscribe());
        consumer.receiveAsync().orTimeout(100, TimeUnit.MILLISECONDS).handle((__, ex) -> {
            cdl.countDown();
            return null;
        });
    }
    cdl.await();
    var attributes = Attributes.builder().put(OpenTelemetryAttributes.PULSAR_DOMAIN, "persistent").put(OpenTelemetryAttributes.PULSAR_TENANT, "prop").put(OpenTelemetryAttributes.PULSAR_NAMESPACE, "prop/ns-abc").put(OpenTelemetryAttributes.PULSAR_TOPIC, topicName).build();
