@Test(dataProvider = "testSubscriptionMetrics")
public void testSubscriptionStats(final String topic, final String subName, boolean enableTopicStats, boolean setFilter) throws Exception {
    @Cleanup
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(topic).enableBatching(false).create();
    @Cleanup
    Consumer<String> consumer = pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionType(SubscriptionType.Exclusive).subscriptionName(subName).subscribe();
    boolean isPersistent = pulsar.getBrokerService().getTopic(topic, false).get().get().isPersistent();
    Dispatcher dispatcher = pulsar.getBrokerService().getTopic(topic, false).get().get().getSubscription(subName).getDispatcher();
    if (setFilter) {
        Field field = EntryFilterSupport.class.getDeclaredField("entryFilters");
        field.setAccessible(true);
        Field hasFilterField = EntryFilterSupport.class.getDeclaredField("hasFilter");
        hasFilterField.setAccessible(true);
        NarClassLoader narClassLoader = mock(NarClassLoader.class);
        EntryFilter filter1 = new EntryFilterTest();
        EntryFilterWithClassLoader loader1 = spyWithClassAndConstructorArgs(EntryFilterWithClassLoader.class, filter1, narClassLoader, false);
        field.set(dispatcher, List.of(loader1));
        hasFilterField.set(dispatcher, true);
    }
    int rejectedCount = 100;
    int acceptCount = 100;
    int scheduleCount = 100;
    for (int i = 0; i < rejectedCount; i++) {
        producer.newMessage().property("REJECT", " ").value(UUID.randomUUID().toString()).send();
    }
    for (int i = 0; i < acceptCount; i++) {
        producer.newMessage().property("ACCEPT", " ").value(UUID.randomUUID().toString()).send();
    }
    for (int i = 0; i < scheduleCount; i++) {
        producer.newMessage().property("RESCHEDULE", " ").value(UUID.randomUUID().toString()).send();
    }
    for (int i = 0; i < acceptCount; i++) {
        Message<String> message = consumer.receive(1, TimeUnit.SECONDS);
        Assert.assertNotNull(message);
        consumer.acknowledge(message);
    }
    ByteArrayOutputStream output = new ByteArrayOutputStream();
    PrometheusMetricsTestUtil.generate(pulsar, enableTopicStats, false, false, output);
    String metricsStr = output.toString();
    Multimap<String, Metric> metrics = parseMetrics(metricsStr);
    Collection<Metric> throughFilterMetrics = metrics.get("pulsar_subscription_filter_processed_msg_count");
    Collection<Metric> acceptedMetrics = metrics.get("pulsar_subscription_filter_accepted_msg_count");
    Collection<Metric> rejectedMetrics = metrics.get("pulsar_subscription_filter_rejected_msg_count");
    Collection<Metric> rescheduledMetrics = metrics.get("pulsar_subscription_filter_rescheduled_msg_count");
    if (enableTopicStats) {
        Assert.assertTrue(throughFilterMetrics.size() > 0);
        Assert.assertTrue(acceptedMetrics.size() > 0);
        Assert.assertTrue(rejectedMetrics.size() > 0);
        Assert.assertTrue(rescheduledMetrics.size() > 0);
        double throughFilter = throughFilterMetrics.stream().filter(m -> m.tags.get("subscription").equals(subName) && m.tags.get("topic").equals(topic)).mapToDouble(m -> m.value).sum();
        double filterAccepted = acceptedMetrics.stream().filter(m -> m.tags.get("subscription").equals(subName) && m.tags.get("topic").equals(topic)).mapToDouble(m -> m.value).sum();
        double filterRejected = rejectedMetrics.stream().filter(m -> m.tags.get("subscription").equals(subName) && m.tags.get("topic").equals(topic)).mapToDouble(m -> m.value).sum();
        double filterRescheduled = rescheduledMetrics.stream().filter(m -> m.tags.get("subscription").equals(subName) && m.tags.get("topic").equals(topic)).mapToDouble(m -> m.value).sum();
        if (setFilter) {
            Assert.assertEquals(filterAccepted, acceptCount);
            Assert.assertEquals(filterRejected, rejectedCount);
            // Only works on the test, if there are some markers,
            // the filterProcessCount will be not equal with rejectedCount + rescheduledCount + acceptCount
            Assert.assertEquals(throughFilter, filterAccepted + filterRejected + filterRescheduled, 0.01 * throughFilter);
        } else {
            Assert.assertEquals(throughFilter, 0D);
            Assert.assertEquals(filterAccepted, 0D);
            Assert.assertEquals(filterRejected, 0D);
            Assert.assertEquals(filterRescheduled, 0D);
        }
    } else {
        Assert.assertEquals(throughFilterMetrics.size(), 0);
        Assert.assertEquals(acceptedMetrics.size(), 0);
        Assert.assertEquals(rejectedMetrics.size(), 0);
        Assert.assertEquals(rescheduledMetrics.size(), 0);
    }
    testSubscriptionStatsAdminApi(topic, subName, setFilter, acceptCount, rejectedCount);
}

