 */
@Test(timeOut = 60000)
public void testBuildConsumerEncounterPendingAckInitFailure() throws Exception {
    // 1. Prepare and make sure the consumer can be built successfully.
    String topic = NAMESPACE1 + "/testUnloadSubscriptionWhenFailedInitPendingAck";
    @Cleanup
    Consumer<byte[]> consumer1 = pulsarClient.newConsumer().subscriptionName("subName1").topic(topic).subscribe();
    // 2. Mock a transactionPendingAckStoreProvider to test building consumer
    // failing at transactionPendingAckStoreProvider::checkInitializedBefore.
    Field transactionPendingAckStoreProviderField = PulsarService.class.getDeclaredField("transactionPendingAckStoreProvider");
    transactionPendingAckStoreProviderField.setAccessible(true);
    TransactionPendingAckStoreProvider pendingAckStoreProvider = (TransactionPendingAckStoreProvider) transactionPendingAckStoreProviderField.get(pulsarServiceList.get(0));
    TransactionPendingAckStoreProvider mockProvider = mock(pendingAckStoreProvider.getClass());
    // 3. Test retryable exception when checkInitializedBefore:
    // The consumer will be built successfully after one time retry.
    when(mockProvider.checkInitializedBefore(any())).// First, the method checkInitializedBefore will fail with a retryable exception.
    thenReturn(FutureUtil.failedFuture(new ManagedLedgerException("mock fail initialize"))).// Then, the method will be executed successfully.
    thenReturn(CompletableFuture.completedFuture(false));
    transactionPendingAckStoreProviderField.set(pulsarServiceList.get(0), mockProvider);
    @Cleanup
    Consumer<byte[]> consumer2 = pulsarClient.newConsumer().subscriptionName("subName2").topic(topic).subscribe();
    // 4. Test retryable exception when newPendingAckStore:
    // The consumer will be built successfully after one time retry.
    when(mockProvider.checkInitializedBefore(any())).thenReturn(CompletableFuture.completedFuture(true));
    when(mockProvider.newPendingAckStore(any())).// First, the method newPendingAckStore will fail with a retryable exception.
    thenReturn(FutureUtil.failedFuture(new ManagedLedgerException("mock fail new store"))).// Then, the method will be executed successfully.
    thenCallRealMethod();
    transactionPendingAckStoreProviderField.set(pulsarServiceList.get(0), mockProvider);
    @Cleanup
    Consumer<byte[]> consumer3 = pulsarClient.newConsumer().subscriptionName("subName3").topic(topic).subscribe();
    // 5. Test no-retryable exception:
    // The consumer building will be failed without retrying.
    when(mockProvider.checkInitializedBefore(any())).// The method checkInitializedBefore will fail with a no-retryable exception without retrying.
    thenReturn(FutureUtil.failedFuture(new ManagedLedgerException.NonRecoverableLedgerException("mock fail"))).thenReturn(CompletableFuture.completedFuture(false));
    @Cleanup
    PulsarClient pulsarClient = PulsarClient.builder().serviceUrl(pulsarServiceList.get(0).getBrokerServiceUrl()).operationTimeout(3, TimeUnit.SECONDS).build();
    try {
        @Cleanup
        Consumer<byte[]> consumer4 = pulsarClient.newConsumer().subscriptionName("subName4").topic(topic).subscribe();
        fail();
    } catch (Exception exception) {
        assertTrue(exception.getMessage().contains("Failed to init transaction pending ack."));
    }
}

@Test
public void individualPendingAckReplayTest() throws Exception {
    int messageCount = 1000;
    String subName = "individual-test";
    @Cleanup
    Producer<byte[]> producer = pulsarClient.newProducer().topic(PENDING_ACK_REPLAY_TOPIC).enableBatching(true).batchingMaxMessages(200).create();
    @Cleanup
    Consumer<byte[]> consumer = pulsarClient.newConsumer().topic(PENDING_ACK_REPLAY_TOPIC).subscriptionName(subName).subscriptionType(SubscriptionType.Shared).enableBatchIndexAcknowledgment(true).subscribe();
    Transaction abortTxn = pulsarClient.newTransaction().withTransactionTimeout(30, TimeUnit.SECONDS).build().get();
    List<MessageId> pendingAckMessageIds = new ArrayList<>();
    List<MessageId> normalAckMessageIds = new ArrayList<>();
    for (int i = 0; i < messageCount; i++) {
        producer.send("Hello Pulsar!".getBytes());
        Message<byte[]> message = consumer.receive();
        if (i % 2 == 0) {
            consumer.acknowledgeAsync(message.getMessageId(), abortTxn).get();
            pendingAckMessageIds.add(message.getMessageId());
        } else {
            normalAckMessageIds.add(message.getMessageId());
        }
    }
    //in order to test pending ack replay
    admin.topics().unload(PENDING_ACK_REPLAY_TOPIC);
    Awaitility.await().until(consumer::isConnected);
    Transaction commitTxn = pulsarClient.newTransaction().withTransactionTimeout(30, TimeUnit.SECONDS).build().get();
    Transaction txn = pulsarClient.newTransaction().withTransactionTimeout(30, TimeUnit.SECONDS).build().get();
    // this messageIds are ack by transaction
    for (int i = 0; i < pendingAckMessageIds.size(); i++) {
        try {
            consumer.acknowledgeAsync(pendingAckMessageIds.get(i), txn).get();
            fail();
        } catch (ExecutionException e) {
            assertTrue(e.getCause() instanceof PulsarClientException.TransactionConflictException);
        }
    }
    // this messageIds are not ack by transaction
    for (int i = 0; i < normalAckMessageIds.size(); i++) {
        consumer.acknowledgeAsync(normalAckMessageIds.get(i), commitTxn).get();
    }
    txn.abort().get();
    // commit this txn, normalAckMessageIds are in pending ack state
    commitTxn.commit().get();
    // abort this txn, pendingAckMessageIds are delete from pending ack state
    abortTxn.abort().get();
    // replay this pending ack
    admin.topics().unload(PENDING_ACK_REPLAY_TOPIC);
    Awaitility.await().until(consumer::isConnected);
    abortTxn = pulsarClient.newTransaction().withTransactionTimeout(30, TimeUnit.SECONDS).build().get();
    commitTxn = pulsarClient.newTransaction().withTransactionTimeout(30, TimeUnit.SECONDS).build().get();
    // normalAckMessageIds are ack and then commit, so ack fail
    for (int i = 0; i < normalAckMessageIds.size(); i++) {
        try {
            consumer.acknowledgeAsync(normalAckMessageIds.get(i), abortTxn).get();
            fail();
        } catch (ExecutionException e) {
            assertTrue(e.getCause() instanceof PulsarClientException.TransactionConflictException);
        }
    }
    // pendingAckMessageIds are all abort, so can ack again
    for (int i = 0; i < pendingAckMessageIds.size(); i++) {
        consumer.acknowledgeAsync(pendingAckMessageIds.get(i), commitTxn).get();
    }
    abortTxn.abort().get();
    commitTxn.commit().get();
    PersistentTopic topic = (PersistentTopic) getPulsarServiceList().get(0).getBrokerService().getTopic(TopicName.get(PENDING_ACK_REPLAY_TOPIC).toString(), false).get().get();
    Field field = PersistentSubscription.class.getDeclaredField("pendingAckHandle");
    field.setAccessible(true);
    PendingAckHandleImpl pendingAckHandle = (PendingAckHandleImpl) field.get(topic.getSubscription(subName));
    field = PendingAckHandleImpl.class.getDeclaredField("pendingAckStoreFuture");
    field.setAccessible(true);
    CompletableFuture<PendingAckStore> pendingAckStoreCompletableFuture = (CompletableFuture<PendingAckStore>) field.get(pendingAckHandle);
    pendingAckStoreCompletableFuture.get();
    field = MLPendingAckStore.class.getDeclaredField("cursor");
    field.setAccessible(true);
    ManagedCursor managedCursor = (ManagedCursor) field.get(pendingAckStoreCompletableFuture.get());
    // in order to check out the pending ack cursor is clear whether or not.
    Awaitility.await().until(() -> (managedCursor.getMarkDeletedPosition()).compareTo(managedCursor.getManagedLedger().getLastConfirmedEntry()) == -1);
}

@Test
public void testPendingAckMetrics() throws Exception {
    final int messageCount = 100;
    String subName = "testMetric" + UUID.randomUUID();
    @Cleanup
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(PENDING_ACK_REPLAY_TOPIC).create();
    @Cleanup
    Consumer<String> consumer = pulsarClient.newConsumer(Schema.STRING).topic(PENDING_ACK_REPLAY_TOPIC).subscriptionName(subName).subscriptionType(SubscriptionType.Exclusive).enableBatchIndexAcknowledgment(true).subscribe();
    for (int a = 0; a < messageCount; a++) {
        producer.send(UUID.randomUUID().toString());
    }
    for (int a = 0; a < messageCount; a++) {
        Message<String> message = consumer.receive(10, TimeUnit.SECONDS);
        if (null == message) {
            break;
        }
        Transaction txn = pulsarClient.newTransaction().withTransactionTimeout(10, TimeUnit.SECONDS).build().get();
        consumer.acknowledgeCumulativeAsync(message.getMessageId(), txn).get();
        if (a % 2 == 0) {
            txn.abort().get();
        } else {
            txn.commit().get();
        }
    }
    @Cleanup
    ByteArrayOutputStream statsOut = new ByteArrayOutputStream();
    PrometheusMetricsTestUtil.generate(pulsarServiceList.get(0), true, false, false, statsOut);
    String metricsStr = statsOut.toString();
    Multimap<String, Metric> metricsMap = parseMetrics(metricsStr);
    Collection<Metric> abortedCount = metricsMap.get("pulsar_txn_tp_aborted_count_total");
    Collection<Metric> committedCount = metricsMap.get("pulsar_txn_tp_committed_count_total");
    Collection<Metric> commitLatency = metricsMap.get("pulsar_txn_tp_commit_latency");
    Assert.assertTrue(commitLatency.size() > 0);
    int count = 0;
    for (Metric metric : commitLatency) {
        if (metric.tags.get("topic").endsWith(PENDING_ACK_REPLAY_TOPIC) && metric.value > 0) {
            count++;
        }
    }
    Assert.assertTrue(count > 0);
    for (Metric metric : abortedCount) {
        if (metric.tags.get("subscription").equals(subName) && metric.tags.get("status").equals("succeed")) {
            assertTrue(metric.tags.get("topic").endsWith(PENDING_ACK_REPLAY_TOPIC));
            assertTrue(metric.value > 0);
        }
    }
    for (Metric metric : committedCount) {
        if (metric.tags.get("subscription").equals(subName) && metric.tags.get("status").equals("succeed")) {
            assertTrue(metric.tags.get("topic").endsWith(PENDING_ACK_REPLAY_TOPIC));
            assertTrue(metric.value > 0);
        }
    }
    var otelMetrics = pulsarTestContexts.get(0).getOpenTelemetryMetricReader().collectAllMetrics();
    var commonAttributes = Attributes.builder().put(OpenTelemetryAttributes.PULSAR_TENANT, "tnx").put(OpenTelemetryAttributes.PULSAR_NAMESPACE, "tnx/ns1").put(OpenTelemetryAttributes.PULSAR_TOPIC, TopicName.get(PENDING_ACK_REPLAY_TOPIC).toString()).put(OpenTelemetryAttributes.PULSAR_SUBSCRIPTION_NAME, subName).build();
    assertMetricLongSumValue(otelMetrics, OpenTelemetryTransactionPendingAckStoreStats.ACK_COUNTER, Attributes.builder().putAll(commonAttributes).put(OpenTelemetryAttributes.PULSAR_TRANSACTION_STATUS, "committed").put(OpenTelemetryAttributes.PULSAR_TRANSACTION_ACK_STORE_OPERATION_STATUS, "success").build(), 50);
    assertMetricLongSumValue(otelMetrics, OpenTelemetryTransactionPendingAckStoreStats.ACK_COUNTER, Attributes.builder().putAll(commonAttributes).put(OpenTelemetryAttributes.PULSAR_TRANSACTION_STATUS, "committed").put(OpenTelemetryAttributes.PULSAR_TRANSACTION_ACK_STORE_OPERATION_STATUS, "failure").build(), 0);
    assertMetricLongSumValue(otelMetrics, OpenTelemetryTransactionPendingAckStoreStats.ACK_COUNTER, Attributes.builder().putAll(commonAttributes).put(OpenTelemetryAttributes.PULSAR_TRANSACTION_STATUS, "aborted").put(OpenTelemetryAttributes.PULSAR_TRANSACTION_ACK_STORE_OPERATION_STATUS, "success").build(), 50);
    assertMetricLongSumValue(otelMetrics, OpenTelemetryTransactionPendingAckStoreStats.ACK_COUNTER, Attributes.builder().putAll(commonAttributes).put(OpenTelemetryAttributes.PULSAR_TRANSACTION_STATUS, "aborted").put(OpenTelemetryAttributes.PULSAR_TRANSACTION_ACK_STORE_OPERATION_STATUS, "failure").build(), 0);
}

