@Test
public void ackCommitTest() throws Exception {
    final String subscriptionName = "ackCommitTest";
    Transaction txn = pulsarClient.newTransaction().withTransactionTimeout(5, TimeUnit.SECONDS).build().get();
    log.info("init transaction {}.", txn);
    @Cleanup
    Producer<byte[]> incomingProducer = pulsarClient.newProducer().topic(ACK_COMMIT_TOPIC).batchingMaxMessages(1).roundRobinRouterBatchingPartitionSwitchFrequency(1).create();
    int incomingMessageCnt = 10;
    for (int i = 0; i < incomingMessageCnt; i++) {
        incomingProducer.newMessage().value("Hello Txn.".getBytes()).sendAsync();
    }
    log.info("prepare incoming messages finished.");
    @Cleanup
    Consumer<byte[]> consumer = pulsarClient.newConsumer().topic(ACK_COMMIT_TOPIC).subscriptionName(subscriptionName).subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).enableBatchIndexAcknowledgment(true).subscriptionType(SubscriptionType.Shared).subscribe();
    Awaitility.await().until(consumer::isConnected);
    for (int i = 0; i < incomingMessageCnt; i++) {
        Message<byte[]> message = consumer.receive();
        log.info("receive messageId: {}", message.getMessageId());
        consumer.acknowledgeAsync(message.getMessageId(), txn);
    }
    // The pending messages count should be the incomingMessageCnt
    Awaitility.await().untilAsserted(() -> Assert.assertEquals(getPendingAckCount(ACK_COMMIT_TOPIC, subscriptionName), incomingMessageCnt));
    consumer.redeliverUnacknowledgedMessages();
    Message<byte[]> message = consumer.receive(2, TimeUnit.SECONDS);
    Assert.assertNull(message);
    // The pending messages count should be the incomingMessageCnt
    Assert.assertEquals(getPendingAckCount(ACK_COMMIT_TOPIC, subscriptionName), incomingMessageCnt);
    txn.commit().get();
    // After commit, the pending messages count should be 0
    Awaitility.await().untilAsserted(() -> Assert.assertEquals(getPendingAckCount(ACK_COMMIT_TOPIC, subscriptionName), 0));
    consumer.redeliverUnacknowledgedMessages();
    for (int i = 0; i < incomingMessageCnt; i++) {
        message = consumer.receive(2, TimeUnit.SECONDS);
        Assert.assertNull(message);
    }
    log.info("finish test ackCommitTest");
}

