@Test(timeOut = 30000)
public void testTransactionAckMessageList() throws Exception {
    String topic = "persistent://" + NAMESPACE1 + "/test";
    String subName = "testSub";
    @Cleanup
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topic).sendTimeout(5, TimeUnit.SECONDS).create();
    @Cleanup
    Consumer<byte[]> consumer = pulsarClient.newConsumer().topic(topic).subscriptionName(subName).subscribe();
    for (int i = 0; i < 5; i++) {
        producer.newMessage().send();
    }
    //verify using aborted transaction to ack message list
    List<MessageId> messages = new ArrayList<>();
    for (int i = 0; i < 4; i++) {
        Message<byte[]> message = consumer.receive();
        messages.add(message.getMessageId());
    }
    Transaction transaction = pulsarClient.newTransaction().withTransactionTimeout(5, TimeUnit.MINUTES).build().get();
    consumer.acknowledgeAsync(messages, transaction);
    transaction.abort().get();
    consumer.close();
    consumer = pulsarClient.newConsumer().topic(topic).subscriptionName(subName).subscribe();
    for (int i = 0; i < 4; i++) {
        Message<byte[]> message = consumer.receive();
        assertTrue(messages.contains(message.getMessageId()));
    }
    //verify using committed transaction to ack message list
    transaction = pulsarClient.newTransaction().withTransactionTimeout(5, TimeUnit.MINUTES).build().get();
    consumer.acknowledgeAsync(messages, transaction);
    transaction.commit().get();
    consumer.close();
    consumer = pulsarClient.newConsumer().topic(topic).subscriptionName(subName).subscribe();
    Message<byte[]> message = consumer.receive(5, TimeUnit.SECONDS);
    Assert.assertNotNull(message);
    Assert.assertFalse(messages.contains(message.getMessageId()));
    message = consumer.receive(5, TimeUnit.SECONDS);
    Assert.assertNull(message);
    consumer.close();
}

