@Test(timeOut = 10_000)
public void testTBSnapshotWriter() throws Exception {
    String namespace = TENANT + "/ns-" + RandomStringUtils.randomAlphabetic(5);
    admin.namespaces().createNamespace(namespace, 16);
    String topic = namespace + "/test-create-snapshot-writer-failed";
    int partitionCount = 20;
    admin.topics().createPartitionedTopic(topic, partitionCount);
    Class<SystemTopicTxnBufferSnapshotService> clazz = SystemTopicTxnBufferSnapshotService.class;
    Field field = clazz.getDeclaredField("refCountedWriterMap");
    field.setAccessible(true);
    // inject a failed writer future
    CompletableFuture<SystemTopicClient.Writer<?>> writerFuture = new CompletableFuture<>();
    for (PulsarService pulsarService : pulsarServiceList) {
        SystemTopicTxnBufferSnapshotService bufferSnapshotService = pulsarService.getTransactionBufferSnapshotServiceFactory().getTxnBufferSnapshotService();
        ConcurrentHashMap<NamespaceName, ReferenceCountedWriter> writerMap1 = ((ConcurrentHashMap<NamespaceName, ReferenceCountedWriter>) field.get(bufferSnapshotService));
        ReferenceCountedWriter failedCountedWriter = new ReferenceCountedWriter(NamespaceName.get(namespace), writerFuture, bufferSnapshotService);
        writerMap1.put(NamespaceName.get(namespace), failedCountedWriter);
        SystemTopicTxnBufferSnapshotService segmentSnapshotService = pulsarService.getTransactionBufferSnapshotServiceFactory().getTxnBufferSnapshotSegmentService();
        ConcurrentHashMap<NamespaceName, ReferenceCountedWriter> writerMap2 = ((ConcurrentHashMap<NamespaceName, ReferenceCountedWriter>) field.get(segmentSnapshotService));
        ReferenceCountedWriter failedCountedWriter2 = new ReferenceCountedWriter(NamespaceName.get(namespace), writerFuture, segmentSnapshotService);
        writerMap2.put(NamespaceName.get(namespace), failedCountedWriter2);
        SystemTopicTxnBufferSnapshotService indexSnapshotService = pulsarService.getTransactionBufferSnapshotServiceFactory().getTxnBufferSnapshotIndexService();
        ConcurrentHashMap<NamespaceName, ReferenceCountedWriter> writerMap3 = ((ConcurrentHashMap<NamespaceName, ReferenceCountedWriter>) field.get(indexSnapshotService));
        ReferenceCountedWriter failedCountedWriter3 = new ReferenceCountedWriter(NamespaceName.get(namespace), writerFuture, indexSnapshotService);
        writerMap3.put(NamespaceName.get(namespace), failedCountedWriter3);
    }
    CompletableFuture<Producer<byte[]>> producerFuture = pulsarClient.newProducer().topic(topic).sendTimeout(0, TimeUnit.SECONDS).createAsync();
    getTopic("persistent://" + topic + "-partition-0");
    Thread.sleep(3000);
    // the producer shouldn't be created, because the transaction buffer snapshot writer future didn't finish.
    assertFalse(producerFuture.isDone());
    // The topic will be closed, because the transaction buffer snapshot writer future is failed,
    // the failed writer future will be removed, the producer will be reconnected and work well.
    writerFuture.completeExceptionally(new PulsarClientException.TopicTerminatedException("failed writer"));
    Producer<byte[]> producer = producerFuture.get();
    for (int i = 0; i < partitionCount * 2; i++) {
        Transaction txn = pulsarClient.newTransaction().withTransactionTimeout(1, TimeUnit.MINUTES).build().get();
        producer.newMessage(txn).value("test".getBytes()).sendAsync();
        txn.commit().get();
    }
    checkSnapshotPublisherCount(namespace, 1);
    producer.close();
    admin.topics().unload(topic);
    checkSnapshotPublisherCount(namespace, 0);
}

@Test
public void testReadCommittedWithReadCompacted() throws Exception {
    final String namespace = "tnx/ns-read-committed-compacted";
    final String topic = "persistent://" + namespace + "/test_transaction_topic";
    admin.namespaces().createNamespace(namespace);
    admin.topics().createNonPartitionedTopic(topic);
    admin.topicPolicies().setCompactionThreshold(topic, 100 * 1024 * 1024);
    @Cleanup
    Consumer<String> consumer = this.pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionName("sub").subscriptionType(SubscriptionType.Exclusive).readCompacted(true).subscribe();
    @Cleanup
    Producer<String> producer = this.pulsarClient.newProducer(Schema.STRING).topic(topic).create();
    producer.newMessage().key("K1").value("V1").send();
    Transaction txn = pulsarClient.newTransaction().withTransactionTimeout(1, TimeUnit.MINUTES).build().get();
    producer.newMessage(txn).key("K2").value("V2").send();
    producer.newMessage(txn).key("K3").value("V3").send();
    List<String> messages = new ArrayList<>();
    while (true) {
        Message<String> message = consumer.receive(5, TimeUnit.SECONDS);
        if (message == null) {
            break;
        }
        messages.add(message.getValue());
    }
    Assert.assertEquals(messages, List.of("V1"));
    txn.commit();
    messages.clear();
    while (true) {
        Message<String> message = consumer.receive(5, TimeUnit.SECONDS);
        if (message == null) {
            break;
        }
        messages.add(message.getValue());
    }
    Assert.assertEquals(messages, List.of("V2", "V3"));
}

@Test
public void testReadCommittedWithCompaction() throws Exception {
    final String namespace = "tnx/ns-read-committed-compaction";
    final String topic = "persistent://" + namespace + "/test_transaction_topic" + UUID.randomUUID();
    admin.namespaces().createNamespace(namespace);
    admin.topics().createNonPartitionedTopic(topic);
    admin.topicPolicies().setCompactionThreshold(topic, 100 * 1024 * 1024);
    @Cleanup
    Producer<String> producer = this.pulsarClient.newProducer(Schema.STRING).topic(topic).create();
    producer.newMessage().key("K1").value("V1").send();
    Transaction txn = pulsarClient.newTransaction().withTransactionTimeout(1, TimeUnit.MINUTES).build().get();
    producer.newMessage(txn).key("K2").value("V2").send();
    producer.newMessage(txn).key("K3").value("V3").send();
    txn.commit().get();
    producer.newMessage().key("K1").value("V4").send();
    Transaction txn2 = pulsarClient.newTransaction().withTransactionTimeout(1, TimeUnit.MINUTES).build().get();
    producer.newMessage(txn2).key("K2").value("V5").send();
    producer.newMessage(txn2).key("K3").value("V6").send();
    txn2.commit().get();
    admin.topics().triggerCompaction(topic);
    Awaitility.await().untilAsserted(() -> {
        assertEquals(admin.topics().compactionStatus(topic).status, LongRunningProcessStatus.Status.SUCCESS);
    });
    @Cleanup
    Consumer<String> consumer = this.pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionName("sub").subscriptionType(SubscriptionType.Exclusive).subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).readCompacted(true).subscribe();
    List<String> result = new ArrayList<>();
    while (true) {
        Message<String> receive = consumer.receive(2, TimeUnit.SECONDS);
        if (receive == null) {
            break;
        }
        result.add(receive.getValue());
    }
    Assert.assertEquals(result, List.of("V4", "V5", "V6"));
}

@Test
public void testDelayedDeliveryExceedsMaxDelay() throws Exception {
    final long maxDeliveryDelayInMillis = 5000;
    final String namespace = "tnx/testDelayedDeliveryExceedsMaxDelay";
    final String topic = "persistent://" + namespace + "/test_transaction_topic" + UUID.randomUUID();
    admin.namespaces().createNamespace(namespace);
    admin.topics().createNonPartitionedTopic(topic);
    admin.topicPolicies().setDelayedDeliveryPolicy(topic, DelayedDeliveryPolicies.builder().active(true).tickTime(100L).maxDeliveryDelayInMillis(maxDeliveryDelayInMillis).build());
    @Cleanup
    Producer<byte[]> producer = this.pulsarClient.newProducer().topic(topic).sendTimeout(5, TimeUnit.SECONDS).addEncryptionKey("my-app-key").defaultCryptoKeyReader("file:./src/test/resources/certificate/public-key.client-rsa.pem").create();
    try {
        Transaction txn = pulsarClient.newTransaction().withTransactionTimeout(5, TimeUnit.SECONDS).build().get();
        producer.newMessage(txn).value(UUID.randomUUID().toString().getBytes(StandardCharsets.UTF_8)).deliverAfter(6, TimeUnit.SECONDS).send();
        txn.commit();
        fail("Should have thrown NotAllowedException due to exceeding maxDeliveryDelayInMillis");
    } catch (PulsarClientException.NotAllowedException ex) {
        assertEquals(ex.getMessage(), "Exceeds max allowed delivery delay of " + maxDeliveryDelayInMillis + " milliseconds");
    }
}

@Test
public void testPersistentTopicGetLastDispatchablePositionWithTxn() throws Exception {
    String topic = "persistent://" + NAMESPACE1 + "/testPersistentTopicGetLastDispatchablePositionWithTxn";
    @Cleanup
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(topic).enableBatching(false).create();
    BrokerService brokerService = pulsarTestContexts.get(0).getBrokerService();
    PersistentTopic persistentTopic = (PersistentTopic) brokerService.getTopicReference(topic).get();
    // send a normal message
    String body = UUID.randomUUID().toString();
    MessageIdImpl msgId = (MessageIdImpl) producer.send(body);
    // send 3 txn messages
    Transaction txn = pulsarClient.newTransaction().build().get();
    producer.newMessage(txn).value(UUID.randomUUID().toString()).send();
    producer.newMessage(txn).value(UUID.randomUUID().toString()).send();
    producer.newMessage(txn).value(UUID.randomUUID().toString()).send();
    // get last dispatchable position
    Position lastDispatchablePosition = persistentTopic.getLastDispatchablePosition().get();
    // the last dispatchable position should be the message id of the normal message
    assertEquals(lastDispatchablePosition, PositionFactory.create(msgId.getLedgerId(), msgId.getEntryId()));
    // abort the txn
    txn.abort().get(5, TimeUnit.SECONDS);
    // get last dispatchable position
    lastDispatchablePosition = persistentTopic.getLastDispatchablePosition().get();
    // the last dispatchable position should be the message id of the normal message
    assertEquals(lastDispatchablePosition, PositionFactory.create(msgId.getLedgerId(), msgId.getEntryId()));
    @Cleanup
    Reader<String> reader = pulsarClient.newReader(Schema.STRING).topic(topic).startMessageId(MessageId.earliest).create();
    Transaction txn1 = pulsarClient.newTransaction().build().get();
    producer.newMessage(txn1).value(UUID.randomUUID().toString()).send();
    producer.newMessage(txn1).value(UUID.randomUUID().toString()).send();
    producer.newMessage(txn1).value(UUID.randomUUID().toString()).send();
    List<Message<String>> messages = new ArrayList<>();
    while (reader.hasMessageAvailable()) {
        messages.add(reader.readNext());
    }
    assertEquals(messages.size(), 1);
    assertEquals(messages.get(0).getValue(), body);
    txn1.abort().get(5, TimeUnit.SECONDS);
    @Cleanup
    Reader<String> reader1 = pulsarClient.newReader(Schema.STRING).topic(topic).startMessageId(MessageId.earliest).create();
    List<Message<String>> messages1 = new ArrayList<>();
    while (reader1.hasMessageAvailable()) {
        messages1.add(reader1.readNext());
    }
    assertEquals(messages1.size(), 1);
    assertEquals(messages1.get(0).getValue(), body);
}

@Test
@SneakyThrows
public void testHandle() {
    String restriction = "Reach the max tenants [5] restriction";
    String internal = "internal exception";
    String illegal = "illegal argument exception ";
    ExceptionHandler handler = new ExceptionHandler();
    HttpServletResponse response = Mockito.mock(HttpServletResponse.class);
    handler.handle(response, new InterceptException(PRECONDITION_FAILED_412, restriction));
    Mockito.verify(response).sendError(PRECONDITION_FAILED_412, restriction);
    handler.handle(response, new InterceptException(INTERNAL_SERVER_ERROR_500, internal));
    Mockito.verify(response).sendError(INTERNAL_SERVER_ERROR_500, internal);
    handler.handle(response, new IllegalArgumentException(illegal));
    Mockito.verify(response).sendError(INTERNAL_SERVER_ERROR_500, illegal);
    Response response2 = Mockito.mock(Response.class);
    HttpChannel httpChannel = Mockito.mock(HttpChannel.class);
    Mockito.when(response2.getHttpChannel()).thenReturn(httpChannel);
    handler.handle(response2, new InterceptException(PRECONDITION_FAILED_412, restriction));
    Mockito.verify(httpChannel).sendResponse(Mockito.any(), Mockito.any(), Mockito.anyBoolean());
}

@Test
public void testInChunkedReturnFalse() throws NoSuchMethodException, InvocationTargetException, IllegalAccessException {
    MaxRequestSizeFilter maxRequestSizeFilter = new MaxRequestSizeFilter(MAX_SIZE);
    Method isChunked = maxRequestSizeFilter.getClass().getDeclaredMethod("isChunked", ServletRequest.class);
    isChunked.setAccessible(true);
    // request is not httpServlet Request
    ServletRequest mockHttpServletRequest = Mockito.mock(ServletRequest.class);
    Boolean result = (Boolean) isChunked.invoke(maxRequestSizeFilter, mockHttpServletRequest);
    Assert.assertFalse(result);
    // request not include encoding
    HttpServletRequest spyHttpServletRequest = Mockito.spy(HttpServletRequest.class);
    Mockito.doReturn(null).when(spyHttpServletRequest).getHeader("Transfer-Encoding");
    Boolean result2 = (Boolean) isChunked.invoke(maxRequestSizeFilter, spyHttpServletRequest);
    Assert.assertFalse(result2);
    //request Transfer-Encoding is not chunked
    HttpServletRequest spyHttpServletRequest3 = Mockito.spy(HttpServletRequest.class);
    Mockito.doReturn("whatever").when(spyHttpServletRequest3).getHeader("Transfer-Encoding");
    Boolean result3 = (Boolean) isChunked.invoke(maxRequestSizeFilter, spyHttpServletRequest);
    Assert.assertFalse(result3);
}

