@Test(dataProvider = "tlsEnabled")
public void testClientIPIsPickedFromHAProxyProtocolAndLogged(boolean tlsEnabled) throws Exception {
    String metricsUrl = (tlsEnabled ? pulsar.getWebServiceAddressTls() : pulsar.getWebServiceAddress()) + "/metrics/";
    performLoggingTest(consoleCaptor -> {
        // Send a GET request to the metrics URL
        ContentResponse response = httpClient.newRequest(metricsUrl).// Jetty client will add HA Proxy protocol header with the given IP to the request
        tag(new V2.Tag(V2.Tag.Command.PROXY, null, V2.Tag.Protocol.STREAM, // source IP and port
        "99.22.33.44", 1234, // destination IP and port
        "5.4.3.1", 4321, null)).send();
        // Validate the response
        assertTrue(response.getContentAsString().contains("process_cpu_seconds_total"));
        // Validate that the client IP and destination IP passed in HA Proxy protocol is logged
        assertTrue(consoleCaptor.getStandardOutput().stream().anyMatch(line -> line.contains("RequestLog") && line.contains("[R:99.22.33.44:1234 via ") && line.contains(" dst 5.4.3.1:4321]")));
    });
}

@Test
public void testWebExecutorMetrics() throws Exception {
    setupEnv(true, false, false, false, -1, false);
    var otelMetrics = pulsarTestContext.getOpenTelemetryMetricReader().collectAllMetrics();
    assertMetricLongSumValue(otelMetrics, WebExecutorThreadPoolStats.LIMIT_COUNTER, LimitType.MAX.attributes, value -> assertThat(value).isPositive());
    assertMetricLongSumValue(otelMetrics, WebExecutorThreadPoolStats.LIMIT_COUNTER, LimitType.MIN.attributes, value -> assertThat(value).isPositive());
    assertMetricLongSumValue(otelMetrics, WebExecutorThreadPoolStats.USAGE_COUNTER, UsageType.ACTIVE.attributes, value -> assertThat(value).isNotNegative());
    assertMetricLongSumValue(otelMetrics, WebExecutorThreadPoolStats.USAGE_COUNTER, UsageType.CURRENT.attributes, value -> assertThat(value).isPositive());
    assertMetricLongSumValue(otelMetrics, WebExecutorThreadPoolStats.USAGE_COUNTER, UsageType.IDLE.attributes, value -> assertThat(value).isNotNegative());
    ByteArrayOutputStream statsOut = new ByteArrayOutputStream();
    PrometheusMetricsTestUtil.generate(pulsar, false, false, false, statsOut);
    String metricsStr = statsOut.toString();
    Multimap<String, Metric> metrics = parseMetrics(metricsStr);
    Collection<Metric> maxThreads = metrics.get("pulsar_web_executor_max_threads");
    Collection<Metric> minThreads = metrics.get("pulsar_web_executor_min_threads");
    Collection<Metric> activeThreads = metrics.get("pulsar_web_executor_active_threads");
    Collection<Metric> idleThreads = metrics.get("pulsar_web_executor_idle_threads");
    Collection<Metric> currentThreads = metrics.get("pulsar_web_executor_current_threads");
    for (Metric metric : maxThreads) {
        Assert.assertNotNull(metric.tags.get("cluster"));
        Assert.assertTrue(metric.value > 0);
    }
    for (Metric metric : minThreads) {
        Assert.assertNotNull(metric.tags.get("cluster"));
        Assert.assertTrue(metric.value > 0);
    }
    for (Metric metric : activeThreads) {
        Assert.assertNotNull(metric.tags.get("cluster"));
        Assert.assertTrue(metric.value >= 0);
    }
    for (Metric metric : idleThreads) {
        Assert.assertNotNull(metric.tags.get("cluster"));
        Assert.assertTrue(metric.value >= 0);
    }
    for (Metric metric : currentThreads) {
        Assert.assertNotNull(metric.tags.get("cluster"));
        Assert.assertTrue(metric.value > 0);
    }
}

