@Test
public void testRateLimiting() throws Exception {
    setupEnv(false, false, false, false, 10.0, false);
    // setupEnv makes a HTTP call to create the cluster.
    var metrics = pulsarTestContext.getOpenTelemetryMetricReader().collectAllMetrics();
    assertMetricLongSumValue(metrics, RateLimitingFilter.RATE_LIMIT_REQUEST_COUNT_METRIC_NAME, Result.ACCEPTED.attributes, 1);
    assertThat(metrics).noneSatisfy(metricData -> assertThat(metricData).hasName(RateLimitingFilter.RATE_LIMIT_REQUEST_COUNT_METRIC_NAME).hasLongSumSatisfying(sum -> sum.hasPointsSatisfying(point -> point.hasAttributes(Result.REJECTED.attributes))));
    // Make requests without exceeding the max rate
    for (int i = 0; i < 5; i++) {
        makeHttpRequest(false, false);
        Thread.sleep(200);
    }
    metrics = pulsarTestContext.getOpenTelemetryMetricReader().collectAllMetrics();
    assertMetricLongSumValue(metrics, RateLimitingFilter.RATE_LIMIT_REQUEST_COUNT_METRIC_NAME, Result.ACCEPTED.attributes, 6);
    assertThat(metrics).noneSatisfy(metricData -> assertThat(metricData).hasName(RateLimitingFilter.RATE_LIMIT_REQUEST_COUNT_METRIC_NAME).hasLongSumSatisfying(sum -> sum.hasPointsSatisfying(point -> point.hasAttributes(Result.REJECTED.attributes))));
    try {
        for (int i = 0; i < 500; i++) {
            makeHttpRequest(false, false);
        }
        fail("Some request should have failed");
    } catch (IOException e) {
        assertTrue(e.getMessage().contains("429"));
    }
    metrics = pulsarTestContext.getOpenTelemetryMetricReader().collectAllMetrics();
    assertMetricLongSumValue(metrics, RateLimitingFilter.RATE_LIMIT_REQUEST_COUNT_METRIC_NAME, Result.ACCEPTED.attributes, value -> assertThat(value).isGreaterThan(6));
    assertMetricLongSumValue(metrics, RateLimitingFilter.RATE_LIMIT_REQUEST_COUNT_METRIC_NAME, Result.REJECTED.attributes, value -> assertThat(value).isPositive());
}

