@Test
public void testMaxRequestSize() throws Exception {
    setupEnv(true, false, false, false, -1, false);
    String url = pulsar.getWebServiceAddress() + "/admin/v2/tenants/my-tenant" + System.currentTimeMillis();
    @Cleanup
    AsyncHttpClient client = new DefaultAsyncHttpClient();
    BoundRequestBuilder builder = client.preparePut(url).setHeader("Accept", "application/json").setHeader("Content-Type", "application/json");
    // HTTP server is configured to reject everything > 10K
    TenantInfo info1 = TenantInfo.builder().adminRoles(Collections.singleton(StringUtils.repeat("*", 20 * 1024))).build();
    builder.setBody(ObjectMapperFactory.getMapper().writer().writeValueAsBytes(info1));
    Response res = builder.execute().get();
    // This should have failed
    assertEquals(res.getStatusCode(), 400);
    // Create local cluster
    String localCluster = "test";
    pulsar.getPulsarResources().getClusterResources().createCluster(localCluster, ClusterDataImpl.builder().build());
    TenantInfo info2 = TenantInfo.builder().adminRoles(Collections.singleton(StringUtils.repeat("*", 1 * 1024))).allowedClusters(Sets.newHashSet(localCluster)).build();
    builder.setBody(ObjectMapperFactory.getMapper().writer().writeValueAsBytes(info2));
    Response res2 = builder.execute().get();
    assertEquals(res2.getStatusCode(), 204);
    // Simple GET without content size should go through
    Response res3 = client.prepareGet(url).setHeader("Accept", "application/json").setHeader("Content-Type", "application/json").execute().get();
    assertEquals(res3.getStatusCode(), 200);
}

