    replacePulsarClient(PulsarClient.builder().serviceUrl(pulsar.getBrokerServiceUrl()).authentication(authentication));
    // (1) Create subscription name
    Consumer<byte[]> consumer = pulsarClient.newConsumer().topic(topicName).subscriptionName(subscriptionName).subscribe();
