            cdlTopicLoadSemaphoreVerification.await();
        }
        return ret;
    }).doCallRealMethod().when(topicLoadRequestSemaphoreSpy).tryAcquire();
    topicLoadRequestSemaphoreField.set(pulsar2.getBrokerService(), new AtomicReference<>(topicLoadRequestSemaphoreSpy));
    assertThat(pulsarTestContext.getOpenTelemetryMetricReader().collectAllMetrics()).noneSatisfy(metric -> assertThat(metric).hasName(LOOKUP_REQUEST_DURATION_METRIC_NAME));
