    assertThat(metricReader.collectAllMetrics()).anySatisfy(metric -> assertThat(metric).hasName(BrokerService.TOPIC_LOOKUP_USAGE_METRIC_NAME).hasLongSumSatisfying(sum -> sum.hasPointsSatisfying(point -> point.hasValue(1))));
    cdlLookupSemaphoreVerification.countDown();
    cdlAfterTopicLoadSemaphoreAcquire.await();
    assertThat(pulsarTestContext2.getOpenTelemetryMetricReader().collectAllMetrics()).anySatisfy(metric -> assertThat(metric).hasName(BrokerService.TOPIC_LOAD_USAGE_METRIC_NAME).hasLongSumSatisfying(sum -> sum.hasPointsSatisfying(point -> point.hasValue(1))));
    cdlTopicLoadSemaphoreVerification.countDown();
    // load namespace-bundle by calling Broker2
    @Cleanup
    var consumer = consumerFuture.get();
    @Cleanup
    var producer = pulsarClient.newProducer().topic("persistent://my-property/my-ns/my-topic1").create();
    for (int i = 0; i < 10; i++) {
        String message = "my-message-" + i;
        producer.send(message.getBytes());
    }
    Message<byte[]> msg = null;
    Set<String> messageSet = new HashSet<>();
    for (int i = 0; i < 10; i++) {
        msg = consumer.receive(5, TimeUnit.SECONDS);
        String receivedMessage = new String(msg.getData());
        log.debug("Received message: [{}]", receivedMessage);
        String expectedMessage = "my-message-" + i;
        testMessageOrderAndDuplicates(messageSet, receivedMessage, expectedMessage);
    }
    var metrics = metricReader.collectAllMetrics();
    assertThat(metrics).anySatisfy(metric -> assertThat(metric).hasName(LOOKUP_REQUEST_DURATION_METRIC_NAME).hasHistogramSatisfying(histogram -> histogram.hasPointsSatisfying(point -> point.hasAttributes(NamespaceService.PULSAR_LOOKUP_RESPONSE_REDIRECT_ATTRIBUTES).hasCount(1), point -> point.hasAttributes(NamespaceService.PULSAR_LOOKUP_RESPONSE_BROKER_ATTRIBUTES).hasCount(1))));
    // Acknowledge the consumption of all messages at once
    consumer.acknowledgeCumulative(msg);
}

