public void testDeadLetterTopic(boolean produceLargeMessages) throws Exception {
    final String topic = "persistent://my-property/my-ns/dead-letter-topic";
    final int maxRedeliveryCount = 2;
    final int sendMessages = 100;
    Consumer<byte[]> consumer = pulsarClient.newConsumer(Schema.BYTES).topic(topic).subscriptionName("my-subscription").subscriptionType(SubscriptionType.Shared).ackTimeout(1, TimeUnit.SECONDS).deadLetterPolicy(DeadLetterPolicy.builder().maxRedeliverCount(maxRedeliveryCount).build()).receiverQueueSize(100).subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).subscribe();
    @Cleanup
