    newPulsarClient = newPulsarClient(lookupUrl.toString(), 0);
    Consumer<byte[]> deadLetterConsumer = newPulsarClient.newConsumer(Schema.BYTES).topic("persistent://my-property/my-ns/dead-letter-topic-my-subscription-DLQ").subscriptionName("my-subscription").subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).subscribe();
    Producer<byte[]> producer = pulsarClient.newProducer(Schema.BYTES).topic(topic).enableChunking(produceLargeMessages).enableBatching(!produceLargeMessages).create();
    Map<Integer, String> messageContent = new HashMap<>();
    for (int i = 0; i < sendMessages; i++) {
        String data;
        if (!produceLargeMessages) {
            data = String.format("Hello Pulsar [%d]", i);
        } else {
            data = createMessagePayload(1024 * 10);
        }
        producer.newMessage().key(String.valueOf(i)).value(data.getBytes()).send();
        messageContent.put(i, data);
    }
    producer.close();
    int totalReceived = 0;
    do {
        Message<byte[]> message = consumer.receive(5, TimeUnit.SECONDS);
        assertNotNull(message, "The consumer should be able to receive messages.");
        log.info("consumer received message : {}", message.getMessageId());
        totalReceived++;
    } while (totalReceived < sendMessages * (maxRedeliveryCount + 1));
    int totalInDeadLetter = 0;
