@Test(timeOut = 30000)
public void testDuplicatedMessageSendToDeadLetterTopic() throws Exception {
    final String topic = "persistent://my-property/my-ns/dead-letter-topic-DuplicatedMessage";
    final int maxRedeliveryCount = 1;
    final int messageCount = 10;
    final int consumerCount = 3;
    //1 start 3 parallel consumers
    List<Consumer<String>> consumers = new ArrayList<>();
    final AtomicInteger totalReceived = new AtomicInteger(0);
    @Cleanup("shutdownNow")
    ExecutorService executor = Executors.newFixedThreadPool(consumerCount);
    for (int i = 0; i < consumerCount; i++) {
        executor.execute(() -> {
            try {
                Consumer<String> consumer = pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionName("my-subscription-DuplicatedMessage").subscriptionType(SubscriptionType.Shared).ackTimeout(1001, TimeUnit.MILLISECONDS).deadLetterPolicy(DeadLetterPolicy.builder().maxRedeliverCount(maxRedeliveryCount).deadLetterTopic(topic + "-DLQ").build()).negativeAckRedeliveryDelay(1001, TimeUnit.MILLISECONDS).receiverQueueSize(100).subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).messageListener((MessageListener<String>) (consumer1, msg) -> {
                    totalReceived.getAndIncrement();
                    //never ack
                }).subscribe();
                consumers.add(consumer);
            } catch (PulsarClientException e) {
                fail();
            }
        });
    }
    //2 send messages
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(topic).create();
    for (int i = 0; i < messageCount; i++) {
        producer.send(String.format("Message [%d]", i));
    }
    //3 start a DLQ consumer
    Consumer<String> deadLetterConsumer = pulsarClient.newConsumer(Schema.STRING).topic(topic + "-DLQ").subscriptionName("my-subscription-DuplicatedMessage-DLQ").subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).subscribe();
    int totalInDeadLetter = 0;
    while (true) {
        Message<String> message = deadLetterConsumer.receive(10, TimeUnit.SECONDS);
        if (message == null) {
            break;
        }
        deadLetterConsumer.acknowledge(message);
        totalInDeadLetter++;
    }
    //4 The number of messages that consumers can consume should be equal to messageCount * (maxRedeliveryCount + 1)
    assertEquals(totalReceived.get(), messageCount * (maxRedeliveryCount + 1));
    //5 The message in DLQ should be equal to messageCount
    assertEquals(totalInDeadLetter, messageCount);
    //6 clean up
    producer.close();
    deadLetterConsumer.close();
    for (Consumer<String> consumer : consumers) {
        consumer.close();
    }
}

