@Test
public void testStickyKeyRangesRestartConsumers() throws Exception {
    final String topic = TopicName.get("persistent", "public", "default", "testStickyKeyRangesRestartConsumers" + UUID.randomUUID()).toString();
    final String subscriptionName = "my-sub";
    final int numMessages = 100;
    // start 2 consumers
    Set<String> sentMessages = new ConcurrentSkipListSet<>();
    CountDownLatch count1 = new CountDownLatch(2);
    // consumer 2 usually receive the fix messages
    CountDownLatch count2 = new CountDownLatch(13);
    CountDownLatch count3 = new CountDownLatch(numMessages);
    @Cleanup
    Consumer<String> consumer1 = pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionName(subscriptionName).subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).subscriptionType(SubscriptionType.Key_Shared).keySharedPolicy(KeySharedPolicy.stickyHashRange().ranges(Range.of(0, 65536 / 2))).messageListener((consumer, msg) -> {
        consumer.acknowledgeAsync(msg).whenComplete((m, e) -> {
            if (e != null) {
                log.error("error", e);
            } else {
                sentMessages.remove(msg.getKey());
                count1.countDown();
                count3.countDown();
            }
        });
    }).subscribe();
    @Cleanup
    Consumer<String> consumer2 = pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionName(subscriptionName).subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).subscriptionType(SubscriptionType.Key_Shared).keySharedPolicy(KeySharedPolicy.stickyHashRange().ranges(Range.of(65536 / 2 + 1, 65535))).messageListener((consumer, msg) -> {
        consumer.acknowledgeAsync(msg).whenComplete((m, e) -> {
            if (e != null) {
                log.error("error", e);
            } else {
                sentMessages.remove(msg.getKey());
                count2.countDown();
                count3.countDown();
            }
        });
    }).subscribe();
    Future producerFuture = pulsar.getExecutor().submit(() -> {
        try {
            try (Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(topic).enableBatching(false).create()) {
                for (int i = 0; i < numMessages; i++) {
                    String key = "test" + i;
                    sentMessages.add(key);
                    producer.newMessage().key(key).value("test" + i).send();
                    Thread.sleep(100);
                }
            }
        } catch (Throwable t) {
            log.error("error", t);
        }
    });
    // wait for some messages to be received by both of the consumers
    count1.await();
    count2.await();
    consumer1.close();
    consumer2.close();
    // this sleep is to trigger a race condition that happens
    // when there are some messages that cannot be dispatched while consuming
    Thread.sleep(3000);
    // start consuming again...
    @Cleanup
    Consumer consumer3 = pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionName(subscriptionName).subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).subscriptionType(SubscriptionType.Key_Shared).keySharedPolicy(KeySharedPolicy.stickyHashRange().ranges(Range.of(0, 65536 / 2))).messageListener((consumer, msg) -> {
        consumer.acknowledgeAsync(msg).whenComplete((m, e) -> {
            if (e != null) {
                log.error("error", e);
            } else {
                sentMessages.remove(msg.getKey());
                count3.countDown();
            }
        });
    }).subscribe();
    @Cleanup
    Consumer consumer4 = pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionName(subscriptionName).subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).subscriptionType(SubscriptionType.Key_Shared).keySharedPolicy(KeySharedPolicy.stickyHashRange().ranges(Range.of(65536 / 2 + 1, 65535))).messageListener((consumer, msg) -> {
        consumer.acknowledgeAsync(msg).whenComplete((m, e) -> {
            if (e != null) {
                log.error("error", e);
            } else {
                sentMessages.remove(msg.getKey());
                count3.countDown();
            }
        });
    }).subscribe();
    // wait for all the messages to be delivered
    count3.await();
    assertTrue(sentMessages.isEmpty(), "didn't receive " + sentMessages);
    producerFuture.get();
}

@Test
public void testContinueDispatchMessagesWhenMessageDelayed() throws Exception {
    int delayedMessages = 40;
    int messages = 40;
    int sum = 0;
    final String topic = "persistent://public/default/key_shared-" + UUID.randomUUID();
    final String subName = "my-sub";
    @Cleanup
    Consumer<Integer> consumer1 = pulsarClient.newConsumer(Schema.INT32).topic(topic).subscriptionName(subName).receiverQueueSize(10).subscriptionType(SubscriptionType.Key_Shared).subscribe();
    @Cleanup
    Producer<Integer> producer = pulsarClient.newProducer(Schema.INT32).topic(topic).create();
    for (int i = 0; i < delayedMessages; i++) {
        MessageId messageId = producer.newMessage().key(String.valueOf(random.nextInt(NUMBER_OF_KEYS))).value(100 + i).deliverAfter(10, TimeUnit.SECONDS).send();
        log.info("Published delayed message :{}", messageId);
    }
    for (int i = 0; i < messages; i++) {
        MessageId messageId = producer.newMessage().key(String.valueOf(random.nextInt(NUMBER_OF_KEYS))).value(i).send();
        log.info("Published message :{}", messageId);
    }
    @Cleanup
    Consumer<Integer> consumer2 = pulsarClient.newConsumer(Schema.INT32).topic(topic).subscriptionName(subName).receiverQueueSize(30).subscriptionType(SubscriptionType.Key_Shared).subscribe();
    for (int i = 0; i < delayedMessages + messages; i++) {
        Message<Integer> msg = consumer1.receive(30, TimeUnit.SECONDS);
        if (msg != null) {
            log.info("c1 message: {}, {}", msg.getValue(), msg.getMessageId());
            consumer1.acknowledge(msg);
        } else {
            break;
        }
        sum++;
    }
    log.info("Got {} messages...", sum);
    int remaining = delayedMessages + messages - sum;
    for (int i = 0; i < remaining; i++) {
        Message<Integer> msg = consumer2.receive(30, TimeUnit.SECONDS);
        if (msg != null) {
            log.info("c2 message: {}, {}", msg.getValue(), msg.getMessageId());
            consumer2.acknowledge(msg);
        } else {
            break;
        }
        sum++;
    }
    log.info("Got {} other messages...", sum);
    Assert.assertEquals(sum, delayedMessages + messages);
}

@Test
public void testNoRepeatedReadAndDiscard() throws Exception {
    int delayedMessages = 100;
    final String topic = BrokerTestUtil.newUniqueName("persistent://public/default/tp");
    final String subName = "my-sub";
    admin.topics().createNonPartitionedTopic(topic);
    AtomicInteger replyReadCounter = injectReplayReadCounter(topic, subName);
    // Send messages.
    @Cleanup
    Producer<Integer> producer = pulsarClient.newProducer(Schema.INT32).topic(topic).enableBatching(false).create();
    for (int i = 0; i < delayedMessages; i++) {
        MessageId messageId = producer.newMessage().key(String.valueOf(random.nextInt(NUMBER_OF_KEYS))).value(100 + i).send();
        log.info("Published message :{}", messageId);
    }
    producer.close();
    // Make ack holes.
    Consumer<Integer> consumer1 = pulsarClient.newConsumer(Schema.INT32).topic(topic).subscriptionName(subName).receiverQueueSize(10).subscriptionType(SubscriptionType.Key_Shared).subscribe();
    Consumer<Integer> consumer2 = pulsarClient.newConsumer(Schema.INT32).topic(topic).subscriptionName(subName).receiverQueueSize(10).subscriptionType(SubscriptionType.Key_Shared).subscribe();
    List<Message> msgList1 = new ArrayList<>();
    List<Message> msgList2 = new ArrayList<>();
    for (int i = 0; i < 10; i++) {
        Message msg1 = consumer1.receive(1, TimeUnit.SECONDS);
        if (msg1 != null) {
            msgList1.add(msg1);
        }
        Message msg2 = consumer2.receive(1, TimeUnit.SECONDS);
        if (msg2 != null) {
            msgList2.add(msg2);
        }
    }
    Consumer<Integer> redeliverConsumer = null;
    if (!msgList1.isEmpty()) {
        msgList1.forEach(msg -> consumer1.acknowledgeAsync(msg));
        redeliverConsumer = consumer2;
    } else {
        msgList2.forEach(msg -> consumer2.acknowledgeAsync(msg));
        redeliverConsumer = consumer1;
    }
    // consumer3 will be added to the "recentJoinedConsumers".
    Consumer<Integer> consumer3 = pulsarClient.newConsumer(Schema.INT32).topic(topic).subscriptionName(subName).receiverQueueSize(1000).subscriptionType(SubscriptionType.Key_Shared).subscribe();
    redeliverConsumer.close();
    // Verify: no repeated Read-and-discard.
    Thread.sleep(5 * 1000);
    int maxReplayCount = delayedMessages * 2;
    log.info("Reply read count: {}", replyReadCounter.get());
    assertTrue(replyReadCounter.get() < maxReplayCount);
    // cleanup.
    consumer1.close();
    consumer2.close();
    consumer3.close();
    admin.topics().delete(topic, false);
}

/**
 * This test is in order to guarantee the feature added by https://github.com/apache/pulsar/pull/7105.
 * 1. Start 3 consumers:
 *   - consumer1 will be closed and trigger a messages redeliver.
 *   - consumer2 will not ack any messages to make the new consumer joined late will be stuck due
 *     to the mechanism "recentlyJoinedConsumers".
 *   - consumer3 will always receive and ack messages.
 * 2. Add consumer4 after consumer1 was close, and consumer4 will be stuck due to the mechanism
 *    "recentlyJoinedConsumers".
 * 3. Verify:
 *   - (Main purpose) consumer3 can still receive messages util the cursor.readerPosition is larger than LAC.
 *   - no repeated Read-and-discard.
 *   - at last, all messages will be received.
 */
// the test will be finished in 60s.
@Test(timeOut = 180 * 1000, dataProvider = "allowKeySharedOutOfOrder")
public void testRecentJoinedPosWillNotStuckOtherConsumer(boolean allowKeySharedOutOfOrder) throws Exception {
    final int messagesSentPerTime = 100;
    final Set<Integer> totalReceivedMessages = new TreeSet<>();
    final String topic = BrokerTestUtil.newUniqueName("persistent://public/default/tp");
    final String subName = "my-sub";
    admin.topics().createNonPartitionedTopic(topic);
    AtomicInteger replyReadCounter = injectReplayReadCounter(topic, subName);
    // Send messages.
    @Cleanup
    Producer<Integer> producer = pulsarClient.newProducer(Schema.INT32).topic(topic).enableBatching(false).create();
    for (int i = 0; i < messagesSentPerTime; i++) {
        MessageId messageId = producer.newMessage().key(String.valueOf(random.nextInt(NUMBER_OF_KEYS))).value(100 + i).send();
        log.info("Published message :{}", messageId);
    }
    KeySharedPolicy keySharedPolicy = KeySharedPolicy.autoSplitHashRange().setAllowOutOfOrderDelivery(allowKeySharedOutOfOrder);
    // 1. Start 3 consumers and make ack holes.
    //   - one consumer will be closed and trigger a messages redeliver.
    //   - one consumer will not ack any messages to make the new consumer joined late will be stuck due to the
    //     mechanism "recentlyJoinedConsumers".
    //   - one consumer will always receive and ack messages.
    Consumer<Integer> consumer1 = pulsarClient.newConsumer(Schema.INT32).topic(topic).subscriptionName(subName).receiverQueueSize(10).subscriptionType(SubscriptionType.Key_Shared).keySharedPolicy(keySharedPolicy).subscribe();
    Consumer<Integer> consumer2 = pulsarClient.newConsumer(Schema.INT32).topic(topic).subscriptionName(subName).receiverQueueSize(10).subscriptionType(SubscriptionType.Key_Shared).keySharedPolicy(keySharedPolicy).subscribe();
    Consumer<Integer> consumer3 = pulsarClient.newConsumer(Schema.INT32).topic(topic).subscriptionName(subName).receiverQueueSize(10).subscriptionType(SubscriptionType.Key_Shared).keySharedPolicy(keySharedPolicy).subscribe();
    List<Message> msgList1 = new ArrayList<>();
    List<Message> msgList2 = new ArrayList<>();
    List<Message> msgList3 = new ArrayList<>();
    for (int i = 0; i < 10; i++) {
        Message<Integer> msg1 = consumer1.receive(1, TimeUnit.SECONDS);
        if (msg1 != null) {
            totalReceivedMessages.add(msg1.getValue());
            msgList1.add(msg1);
        }
        Message<Integer> msg2 = consumer2.receive(1, TimeUnit.SECONDS);
        if (msg2 != null) {
            totalReceivedMessages.add(msg2.getValue());
            msgList2.add(msg2);
        }
        Message<Integer> msg3 = consumer3.receive(1, TimeUnit.SECONDS);
        if (msg2 != null) {
            totalReceivedMessages.add(msg3.getValue());
            msgList3.add(msg3);
        }
    }
    Consumer<Integer> consumerWillBeClose = null;
    Consumer<Integer> consumerAlwaysAck = null;
    Consumer<Integer> consumerStuck = null;
    if (!msgList1.isEmpty()) {
        msgList1.forEach(msg -> consumer1.acknowledgeAsync(msg));
        consumerAlwaysAck = consumer1;
        consumerWillBeClose = consumer2;
        consumerStuck = consumer3;
    } else if (!msgList2.isEmpty()) {
        msgList2.forEach(msg -> consumer2.acknowledgeAsync(msg));
        consumerAlwaysAck = consumer2;
        consumerWillBeClose = consumer3;
        consumerStuck = consumer1;
    } else {
        msgList3.forEach(msg -> consumer3.acknowledgeAsync(msg));
        consumerAlwaysAck = consumer3;
        consumerWillBeClose = consumer1;
        consumerStuck = consumer2;
    }
    // 2. Add consumer4 after "consumerWillBeClose" was close, and consumer4 will be stuck due to the mechanism
    //    "recentlyJoinedConsumers".
    Consumer<Integer> consumer4 = pulsarClient.newConsumer(Schema.INT32).topic(topic).subscriptionName(subName).receiverQueueSize(1000).subscriptionType(SubscriptionType.Key_Shared).keySharedPolicy(keySharedPolicy).subscribe();
    consumerWillBeClose.close();
    Thread.sleep(2000);
    for (int i = messagesSentPerTime; i < messagesSentPerTime * 2; i++) {
        MessageId messageId = producer.newMessage().key(String.valueOf(random.nextInt(NUMBER_OF_KEYS))).value(100 + i).send();
        log.info("Published message :{}", messageId);
    }
    // Send messages again.
    // Verify: "consumerAlwaysAck" can receive messages util the cursor.readerPosition is larger than LAC.
    while (true) {
        Message<Integer> msg = consumerAlwaysAck.receive(2, TimeUnit.SECONDS);
        if (msg == null) {
            break;
        }
        totalReceivedMessages.add(msg.getValue());
        consumerAlwaysAck.acknowledge(msg);
    }
    PersistentTopic persistentTopic = (PersistentTopic) pulsar.getBrokerService().getTopic(topic, false).join().get();
    ManagedLedgerImpl managedLedger = (ManagedLedgerImpl) persistentTopic.getManagedLedger();
    ManagedCursorImpl cursor = (ManagedCursorImpl) managedLedger.openCursor(subName);
    log.info("cursor_readPosition {}, LAC {}", cursor.getReadPosition(), managedLedger.getLastConfirmedEntry());
    assertTrue((cursor.getReadPosition()).compareTo(managedLedger.getLastConfirmedEntry()) > 0);
    // Make all consumers to start to read and acknowledge messages.
    // Verify: no repeated Read-and-discard.
    Thread.sleep(5 * 1000);
    int maxReplayCount = messagesSentPerTime * 2;
    log.info("Reply read count: {}", replyReadCounter.get());
    assertTrue(replyReadCounter.get() < maxReplayCount);
    // Verify: at last, all messages will be received.
    ReceivedMessages<Integer> receivedMessages = ackAllMessages(consumerAlwaysAck, consumerStuck, consumer4);
    totalReceivedMessages.addAll(receivedMessages.messagesReceived.stream().map(p -> p.getRight()).collect(Collectors.toList()));
    assertEquals(totalReceivedMessages.size(), messagesSentPerTime * 2);
    // cleanup.
    consumer1.close();
    consumer2.close();
    consumer3.close();
    consumer4.close();
    producer.close();
    admin.topics().delete(topic, false);
}

@Test(dataProvider = "batchingAndMemoryLimit")
public void testRejectMessages(boolean batching, int memoryLimit) throws Exception {
    String topic = newTopicName();
    ClientBuilder clientBuilder = PulsarClient.builder().serviceUrl(pulsar.getBrokerServiceUrl()).memoryLimit(memoryLimit, SizeUnit.KILO_BYTES);
    @Cleanup
    PulsarTestClient client = PulsarTestClient.create(clientBuilder);
    @Cleanup
    ProducerImpl<byte[]> producer = (ProducerImpl<byte[]>) client.newProducer().topic(topic).enableBatching(batching).batchingMaxMessages(1).batchingMaxPublishDelay(1, TimeUnit.HOURS).batchingMaxBytes(Integer.MAX_VALUE).blockIfQueueFull(false).sendTimeout(5, TimeUnit.SECONDS).create();
    // make sure all message pending at pendingMessages queue
    // connection with broker can not be established, so handleSendReceipt will not be invoked while sending message
    client.dropOpSendMessages();
    final int n = 101;
    for (int i = 0; i < n; i++) {
        producer.sendAsync(new byte[1024]);
    }
    Awaitility.await().atMost(Duration.ofSeconds(5)).until(() -> producer.getPendingQueueSize() == n);
    if (batching) {
        // BatchMessageContainerImpl allocated buffer size is 1024, so we need add n(batches)*1024
        assertEquals(client.getMemoryLimitController().currentUsage(), n * 1024 + n * 1024);
    } else {
        assertEquals(client.getMemoryLimitController().currentUsage(), n * 1024);
    }
    try {
        producer.send(new byte[1024]);
        fail("should have failed");
    } catch (MemoryBufferIsFullError e) {
        // Expected
    }
    client.allowReconnecting();
    Awaitility.await().atMost(Duration.ofSeconds(30)).until(() -> producer.getPendingQueueSize() == 0);
    assertEquals(client.getMemoryLimitController().currentUsage(), 0);
    // We should now be able to send again
    producer.send(new byte[1024]);
}

