/**
 * verifies: message-rate change gets reflected immediately into topic at runtime
 *
 * @throws Exception
 */
@SuppressWarnings("deprecation")
@Test
public void testMessageRateDynamicallyChange() throws Exception {
    log.info("-- Starting {} test --", methodName);
    final String namespace = "my-property/throttling_ns";
    final String topicName = "persistent://" + namespace + "/throttlingBlock";
    admin.namespaces().createNamespace(namespace, Sets.newHashSet("test"));
    // create producer and topic
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topicName).create();
    PersistentTopic topic = (PersistentTopic) pulsar.getBrokerService().getOrCreateTopic(topicName).get();
    // (1) verify message-rate is -1 initially
    Assert.assertFalse(topic.getDispatchRateLimiter().isPresent());
    // (2) change to 100
    int messageRate = 100;
    DispatchRate dispatchRate = DispatchRate.builder().dispatchThrottlingRateInMsg(messageRate).dispatchThrottlingRateInByte(-1).ratePeriodInSecond(360).build();
    admin.namespaces().setDispatchRate(namespace, dispatchRate);
    boolean isDispatchRateUpdate = false;
    int retry = 5;
    for (int i = 0; i < retry; i++) {
        if (topic.getDispatchRateLimiter().isPresent()) {
            isDispatchRateUpdate = true;
            break;
        } else {
            if (i != retry - 1) {
                Thread.sleep(100);
            }
        }
    }
    Assert.assertTrue(isDispatchRateUpdate);
    Assert.assertEquals(admin.namespaces().getDispatchRate(namespace), dispatchRate);
    Policies policies = admin.namespaces().getPolicies(namespace);
    Map<String, DispatchRate> dispatchRateMap = new HashMap<>();
    dispatchRateMap.put("test", dispatchRate);
    Assert.assertEquals(policies.clusterDispatchRate, dispatchRateMap);
    Assert.assertEquals(policies.topicDispatchRate, dispatchRateMap);
    // (3) change to 500
    messageRate = 500;
    dispatchRate = DispatchRate.builder().dispatchThrottlingRateInMsg(-1).dispatchThrottlingRateInByte(messageRate).ratePeriodInSecond(360).build();
    admin.namespaces().setDispatchRate(namespace, dispatchRate);
    isDispatchRateUpdate = false;
    for (int i = 0; i < retry; i++) {
        if (topic.getDispatchRateLimiter().get().getDispatchRateOnByte() == messageRate) {
            isDispatchRateUpdate = true;
            break;
        } else {
            if (i != retry - 1) {
                Thread.sleep(100);
            }
        }
    }
    Assert.assertTrue(isDispatchRateUpdate);
    Assert.assertEquals(admin.namespaces().getDispatchRate(namespace), dispatchRate);
    policies = admin.namespaces().getPolicies(namespace);
    dispatchRateMap.put("test", dispatchRate);
    Assert.assertEquals(policies.clusterDispatchRate, dispatchRateMap);
    Assert.assertEquals(policies.topicDispatchRate, dispatchRateMap);
    producer.close();
}

/**
 * verify: consumer should not receive all messages due to message-rate throttling
 *
 * @param subscription
 * @throws Exception
 */
@Test(dataProvider = "subscriptionAndDispatchRateType", timeOut = 5000)
public void testMessageRateLimitingNotReceiveAllMessages(SubscriptionType subscription, DispatchRateType dispatchRateType) throws Exception {
    log.info("-- Starting {} test --", methodName);
    final String namespace = "my-property/throttling_ns";
    final String topicName = "persistent://" + namespace + "/throttlingBlock";
    final int messageRate = 100;
    DispatchRate dispatchRate = null;
    if (DispatchRateType.messageRate.equals(dispatchRateType)) {
        dispatchRate = DispatchRate.builder().dispatchThrottlingRateInMsg(messageRate).dispatchThrottlingRateInByte(-1).ratePeriodInSecond(360).build();
    } else {
        dispatchRate = DispatchRate.builder().dispatchThrottlingRateInMsg(-1).dispatchThrottlingRateInByte(messageRate).ratePeriodInSecond(360).build();
    }
    admin.namespaces().createNamespace(namespace, Sets.newHashSet("test"));
    admin.namespaces().setDispatchRate(namespace, dispatchRate);
    // create producer and topic
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topicName).create();
    PersistentTopic topic = (PersistentTopic) pulsar.getBrokerService().getOrCreateTopic(topicName).get();
    Awaitility.await().ignoreExceptions().until(() -> topic.getDispatchRateLimiter().get().getDispatchRateOnMsg() > 0 || topic.getDispatchRateLimiter().get().getDispatchRateOnByte() > 0);
    Assert.assertEquals(admin.namespaces().getDispatchRate(namespace), dispatchRate);
    int numMessages = 500;
    final AtomicInteger totalReceived = new AtomicInteger(0);
    Consumer<byte[]> consumer = pulsarClient.newConsumer().topic(topicName).subscriptionName("my-subscriber-name").subscriptionType(subscription).messageListener((c1, msg) -> {
