@Test
public void testNonDurableSubscription() throws Exception {
    String topicName = "persistent://my-property/my-ns/nonDurable-topic1";
    // 1 setup producer、consumer
    @Cleanup
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(topicName).create();
    @Cleanup
    Consumer<String> consumer = pulsarClient.newConsumer(Schema.STRING).topic(topicName).readCompacted(true).subscriptionMode(SubscriptionMode.NonDurable).subscriptionType(SubscriptionType.Exclusive).subscriptionName("my-nonDurable-subscriber").subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).subscribe();
    // 2 send message
    int messageNum = 10;
    for (int i = 0; i < messageNum; i++) {
        producer.send("message" + i);
    }
    // 3 receive the first 5 messages
    for (int i = 0; i < 5; i++) {
        Message<String> message = consumer.receive();
        assertNotNull(message);
        Assert.assertEquals(message.getValue(), "message" + i);
        consumer.acknowledge(message);
    }
    // 4 trigger reconnect
    ((ConsumerImpl) consumer).getClientCnx().close();
