/**
 * Verifies that broker should failed to publish message if producer publishes messages more than rate limit
 */
@Test
public void testProducerRateLimit() throws Exception {
    int defaultNonPersistentMessageRate = conf.getMaxConcurrentNonPersistentMessagePerConnection();
    try {
        final String topic = "non-persistent://my-property/my-ns/unacked-topic";
        // restart broker with lower publish rate limit
        conf.setMaxConcurrentNonPersistentMessagePerConnection(1);
        stopBroker();
        startBroker();
        // produce message concurrently
        @Cleanup("shutdownNow")
        ExecutorService executor = Executors.newFixedThreadPool(5);
        AtomicBoolean failed = new AtomicBoolean(false);
        @Cleanup
        Consumer<byte[]> consumer = pulsarClient.newConsumer().topic(topic).subscriptionName("subscriber-1").subscribe();
        var producerName = BrokerTestUtil.newUniqueName("testProducerRateLimit");
        @Cleanup
        Producer<byte[]> producer = pulsarClient.newProducer().topic(topic).producerName(producerName).create();
        byte[] msgData = "testData".getBytes();
        final int totalProduceMessages = 10;
        CountDownLatch latch = new CountDownLatch(totalProduceMessages);
        for (int i = 0; i < totalProduceMessages; i++) {
            executor.submit(() -> {
                try {
                    producer.send(msgData);
                } catch (Exception e) {
                    log.error("Failed to send message", e);
                    failed.set(true);
                }
                latch.countDown();
            });
        }
        latch.await();
        Message<?> msg = null;
        Set<String> messageSet = new HashSet<>();
        for (int i = 0; i < totalProduceMessages; i++) {
            msg = consumer.receive(500, TimeUnit.MILLISECONDS);
            if (msg != null) {
                messageSet.add(new String(msg.getData()));
            } else {
                break;
            }
        }
        // publish should not be failed
        assertFalse(failed.get());
        // but as message should be dropped at broker: broker should not receive the message
        assertNotEquals(messageSet.size(), totalProduceMessages);
        // Verify the corresponding metric is updated
        var attributes = Attributes.builder().put(OpenTelemetryAttributes.PULSAR_PRODUCER_NAME, producerName).put(OpenTelemetryAttributes.PULSAR_PRODUCER_ID, 0).put(OpenTelemetryAttributes.PULSAR_PRODUCER_ACCESS_MODE, "shared").put(OpenTelemetryAttributes.PULSAR_DOMAIN, "non-persistent").put(OpenTelemetryAttributes.PULSAR_TENANT, "my-property").put(OpenTelemetryAttributes.PULSAR_NAMESPACE, "my-property/my-ns").put(OpenTelemetryAttributes.PULSAR_TOPIC, topic).build();
        var metrics = pulsarTestContext.getOpenTelemetryMetricReader().collectAllMetrics();
        assertMetricLongSumValue(metrics, OpenTelemetryProducerStats.MESSAGE_DROP_COUNTER, attributes, value -> assertThat(value).isPositive());
    } finally {
        conf.setMaxConcurrentNonPersistentMessagePerConnection(defaultNonPersistentMessageRate);
    }
}

