@Test(timeOut = 100000)
public void testPauseAndResume() throws Exception {
    log.info("-- Starting {} test --", methodName);
    // number of permits broker has when consumer initially subscribes
    int receiverQueueSize = 20;
    AtomicReference<CountDownLatch> latch = new AtomicReference<>(new CountDownLatch(receiverQueueSize));
    AtomicInteger received = new AtomicInteger();
    Consumer<byte[]> consumer = pulsarClient.newConsumer().receiverQueueSize(receiverQueueSize).topic("persistent://my-property/my-ns/my-topic-pr").subscriptionName("my-subscriber-name").messageListener((c1, msg) -> {
        Assert.assertNotNull(msg, "Message cannot be null");
        String receivedMessage = new String(msg.getData());
        log.debug("Received message [{}] in the listener", receivedMessage);
        c1.acknowledgeAsync(msg);
        received.incrementAndGet();
        latch.get().countDown();
    }).subscribe();
    Producer<byte[]> producer = pulsarClient.newProducer().topic("persistent://my-property/my-ns/my-topic-pr").create();
    consumer.pause();
    for (int i = 0; i < receiverQueueSize * 2; i++) producer.send(("my-message-" + i).getBytes());
    log.info("Waiting for message listener to ack " + receiverQueueSize + " messages");
    assertTrue(latch.get().await(receiverQueueSize, TimeUnit.SECONDS), "Timed out waiting for message listener acks");
    log.info("Giving message listener an opportunity to receive messages while paused");
    Awaitility.await().untilAsserted(() -> assertEquals(received.intValue(), receiverQueueSize, "Consumer received messages while paused"));
    latch.set(new CountDownLatch(receiverQueueSize));
    consumer.resume();
    log.info("Waiting for message listener to ack all messages");
    assertTrue(latch.get().await(receiverQueueSize, TimeUnit.SECONDS), "Timed out waiting for message listener acks");
    consumer.close();
    producer.close();
    log.info("-- Exiting {} test --", methodName);
}

