public void testBlockUnackedConsumerRedeliverySpecificMessagesCloseConsumerWhileProduce() {
    log.info("-- Starting {} test --", methodName);
    int unAckedMessages = pulsar.getConfiguration().getMaxUnackedMessagesPerConsumer();
    try {
        final int unAckedMessagesBufferSize = 10;
        final int receiverQueueSize = 20;
        final int totalProducedMsgs = 50;
        pulsar.getConfiguration().setMaxUnackedMessagesPerConsumer(unAckedMessagesBufferSize);
        // Only subscribe consumer
        ConsumerImpl<byte[]> consumer = (ConsumerImpl<byte[]>) pulsarClient.newConsumer().topic("persistent://my-property/my-ns/unacked-topic").subscriptionName("subscriber-1").receiverQueueSize(receiverQueueSize).subscriptionType(SubscriptionType.Shared).subscribe();
        consumer.close();
        Producer<byte[]> producer = pulsarClient.newProducer().topic("persistent://my-property/my-ns/unacked-topic").create();
        // (1) Produced Messages
        for (int i = 0; i < totalProducedMsgs; i++) {
            String message = "my-message-" + i;
            producer.send(message.getBytes());
        }
        producer.flush();
        // (1.a) start consumer again
        consumer = (ConsumerImpl<byte[]>) pulsarClient.newConsumer().topic("persistent://my-property/my-ns/unacked-topic").subscriptionName("subscriber-1").receiverQueueSize(receiverQueueSize).subscriptionType(SubscriptionType.Shared).subscribe();
        // (2) try to consume messages: but will be able to consume number of messages = unAckedMessagesBufferSize
        Message<byte[]> msg;
        List<Message<byte[]>> messages1 = new ArrayList<>();
        for (int i = 0; i < totalProducedMsgs; i++) {
            msg = consumer.receive(RECEIVE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
            if (msg != null) {
                messages1.add(msg);
                log.info("Received message: " + new String(msg.getData()));
            } else {
                break;
            }
        }
        // client should not receive all produced messages and should be blocked due to unack-messages
        Set<MessageIdImpl> redeliveryMessages = messages1.stream().map(m -> (MessageIdImpl) m.getMessageId()).collect(Collectors.toSet());
        // (3) redeliver all consumed messages
        consumer.redeliverUnacknowledgedMessages(Sets.newHashSet(redeliveryMessages));
        Thread.sleep(1000);
        Set<MessageIdImpl> messages2 = new HashSet<>();
        for (int i = 0; i < totalProducedMsgs; i++) {
            msg = consumer.receive(RECEIVE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
            if (msg != null) {
                messages2.add((MessageIdImpl) msg.getMessageId());
                log.info("Received message: " + new String(msg.getData()));
            } else {
                break;
            }
        }
        assertEquals(messages1.size(), messages2.size());
        // (4) Verify: redelivered all previous unacked-consumed messages
        messages2.removeAll(redeliveryMessages);
        assertEquals(messages2.size(), 0);
        producer.close();
        consumer.close();
        log.info("-- Exiting {} test --", methodName);
    } catch (Exception e) {
        fail();
    } finally {
        pulsar.getConfiguration().setMaxUnackedMessagesPerConsumer(unAckedMessages);
    }
}

@Test(timeOut = 100000)
public void testPriorityConsumer() throws Exception {
    log.info("-- Starting {} test --", methodName);
    Consumer<byte[]> consumer1 = pulsarClient.newConsumer().topic("persistent://my-property/my-ns/my-topic2").subscriptionName("my-subscriber-name").subscriptionType(SubscriptionType.Shared).receiverQueueSize(5).priorityLevel(1).subscribe();
    @Cleanup
    PulsarClient // Creates new client connection
    newPulsarClient = newPulsarClient(lookupUrl.toString(), 0);
    Consumer<byte[]> consumer2 = newPulsarClient.newConsumer().topic("persistent://my-property/my-ns/my-topic2").subscriptionName("my-subscriber-name").subscriptionType(SubscriptionType.Shared).receiverQueueSize(5).priorityLevel(1).subscribe();
    @Cleanup
    PulsarClient // Creates new client connection
    newPulsarClient1 = newPulsarClient(lookupUrl.toString(), 0);
    Consumer<byte[]> consumer3 = newPulsarClient1.newConsumer().topic("persistent://my-property/my-ns/my-topic2").subscriptionName("my-subscriber-name").subscriptionType(SubscriptionType.Shared).receiverQueueSize(5).priorityLevel(1).subscribe();
    @Cleanup
    PulsarClient // Creates new client connection
    newPulsarClient2 = newPulsarClient(lookupUrl.toString(), 0);
    Consumer<byte[]> consumer4 = newPulsarClient2.newConsumer().topic("persistent://my-property/my-ns/my-topic2").subscriptionName("my-subscriber-name").subscriptionType(SubscriptionType.Shared).receiverQueueSize(5).priorityLevel(2).subscribe();
    Producer<byte[]> producer = pulsarClient.newProducer().topic("persistent://my-property/my-ns/my-topic2").create();
    List<Future<MessageId>> futures = new ArrayList<>();
    // Asynchronously produce messages
    for (int i = 0; i < 15; i++) {
        final String message = "my-message-" + i;
        Future<MessageId> future = producer.sendAsync(message.getBytes());
        futures.add(future);
    }
    log.info("Waiting for async publish to complete");
    for (Future<MessageId> future : futures) {
        future.get();
    }
    for (int i = 0; i < 20; i++) {
        consumer1.receive(RECEIVE_TIMEOUT_SHORT_MILLIS, TimeUnit.MILLISECONDS);
        consumer2.receive(RECEIVE_TIMEOUT_SHORT_MILLIS, TimeUnit.MILLISECONDS);
    }
    /**
     * a. consumer1 and consumer2 now has more permits (as received and sent more permits) b. try to produce more
     * messages: which will again distribute among consumer1 and consumer2 and should not dispatch to consumer4
     */
    for (int i = 0; i < 5; i++) {
        final String message = "my-message-" + i;
        Future<MessageId> future = producer.sendAsync(message.getBytes());
        futures.add(future);
    }
    Assert.assertNull(consumer4.receive(RECEIVE_TIMEOUT_SHORT_MILLIS, TimeUnit.MILLISECONDS));
    // Asynchronously acknowledge upto and including the last message
    producer.close();
    consumer1.close();
    consumer2.close();
    consumer3.close();
    consumer4.close();
    log.info("-- Exiting {} test --", methodName);
}

/**
 * <pre>
 * Verifies Dispatcher dispatches messages properly with shared-subscription consumers with combination of blocked
 * and unblocked consumers.
 *
 * 1. Dispatcher will have 5 consumers : c1, c2, c3, c4, c5.
 *      Out of which : c1,c2,c4,c5 will be blocked due to MaxUnackedMessages limit.
 * 2. So, dispatcher should moves round-robin and make sure it delivers unblocked consumer : c3
 * </pre>
 *
 * @throws Exception
 */
@Test(timeOut = 30000)
public void testSharedSamePriorityConsumer() throws Exception {
    log.info("-- Starting {} test --", methodName);
    final int queueSize = 5;
    int maxUnAckMsgs = pulsar.getConfiguration().getMaxConcurrentLookupRequest();
    pulsar.getConfiguration().setMaxUnackedMessagesPerConsumer(queueSize);
    Producer<byte[]> producer = pulsarClient.newProducer().topic("persistent://my-property/my-ns/my-topic2").enableBatching(false).messageRoutingMode(MessageRoutingMode.SinglePartition).create();
    @Cleanup
    PulsarClient // Creates new client connection
    newPulsarClient = newPulsarClient(lookupUrl.toString(), 0);
    Consumer<byte[]> c1 = newPulsarClient.newConsumer().topic("persistent://my-property/my-ns/my-topic2").subscriptionName("my-subscriber-name").subscriptionType(SubscriptionType.Shared).receiverQueueSize(queueSize).acknowledgmentGroupTime(0, TimeUnit.SECONDS).subscribe();
    @Cleanup
    PulsarClient // Creates new client connection
    newPulsarClient1 = newPulsarClient(lookupUrl.toString(), 0);
    Consumer<byte[]> c2 = newPulsarClient1.newConsumer().topic("persistent://my-property/my-ns/my-topic2").subscriptionName("my-subscriber-name").subscriptionType(SubscriptionType.Shared).receiverQueueSize(queueSize).acknowledgmentGroupTime(0, TimeUnit.SECONDS).subscribe();
    List<Future<MessageId>> futures = new ArrayList<>();
    // Asynchronously produce messages
    final int totalPublishMessages = 500;
    for (int i = 0; i < totalPublishMessages; i++) {
        final String message = "my-message-" + i;
        Future<MessageId> future = producer.sendAsync(message.getBytes());
        futures.add(future);
    }
    log.info("Waiting for async publish to complete");
    for (Future<MessageId> future : futures) {
        future.get();
    }
    List<Message<byte[]>> messages = new ArrayList<>();
    // let consumer1 and consumer2 consume messages up to the queue will be full
    for (int i = 0; i < totalPublishMessages; i++) {
        Message<byte[]> msg = c1.receive(RECEIVE_TIMEOUT_MEDIUM_MILLIS, TimeUnit.MILLISECONDS);
        if (msg != null) {
            messages.add(msg);
        } else {
            break;
        }
    }
    for (int i = 0; i < totalPublishMessages; i++) {
        Message<byte[]> msg = c2.receive(RECEIVE_TIMEOUT_MEDIUM_MILLIS, TimeUnit.MILLISECONDS);
        if (msg != null) {
            messages.add(msg);
        } else {
            break;
        }
    }
    Assert.assertEquals(queueSize * 2, messages.size());
    // create new consumers with the same priority
    @Cleanup
    PulsarClient // Creates new client connection
    newPulsarClient2 = newPulsarClient(lookupUrl.toString(), 0);
    Consumer<byte[]> c3 = newPulsarClient2.newConsumer().topic("persistent://my-property/my-ns/my-topic2").subscriptionName("my-subscriber-name").subscriptionType(SubscriptionType.Shared).receiverQueueSize(queueSize).acknowledgmentGroupTime(0, TimeUnit.SECONDS).subscribe();
    @Cleanup
    PulsarClient // Creates new client connection
    newPulsarClient3 = newPulsarClient(lookupUrl.toString(), 0);
    Consumer<byte[]> c4 = newPulsarClient3.newConsumer().topic("persistent://my-property/my-ns/my-topic2").subscriptionName("my-subscriber-name").subscriptionType(SubscriptionType.Shared).receiverQueueSize(queueSize).acknowledgmentGroupTime(0, TimeUnit.SECONDS).subscribe();
    @Cleanup
    PulsarClient // Creates new client connection
    newPulsarClient4 = newPulsarClient(lookupUrl.toString(), 0);
    Consumer<byte[]> c5 = newPulsarClient4.newConsumer().topic("persistent://my-property/my-ns/my-topic2").subscriptionName("my-subscriber-name").subscriptionType(SubscriptionType.Shared).receiverQueueSize(queueSize).acknowledgmentGroupTime(0, TimeUnit.SECONDS).subscribe();
    // c1 and c2 are blocked: so, let c3, c4 and c5 consume rest of the messages
    for (int i = 0; i < totalPublishMessages; i++) {
        Message<byte[]> msg = c4.receive(RECEIVE_TIMEOUT_MEDIUM_MILLIS, TimeUnit.MILLISECONDS);
        if (msg != null) {
            messages.add(msg);
        } else {
            break;
        }
    }
    for (int i = 0; i < totalPublishMessages; i++) {
        Message<byte[]> msg = c5.receive(RECEIVE_TIMEOUT_MEDIUM_MILLIS, TimeUnit.MILLISECONDS);
        if (msg != null) {
            messages.add(msg);
        } else {
            break;
        }
    }
    for (int i = 0; i < totalPublishMessages; i++) {
        Message<byte[]> msg = c3.receive(RECEIVE_TIMEOUT_MEDIUM_MILLIS, TimeUnit.MILLISECONDS);
        if (msg != null) {
            messages.add(msg);
            c3.acknowledge(msg);
        } else {
            break;
        }
    }
    // total messages must be consumed by all consumers
    Assert.assertEquals(messages.size(), totalPublishMessages);
    // Asynchronously acknowledge upto and including the last message
    producer.close();
    c1.close();
    c2.close();
    c3.close();
    c4.close();
    c5.close();
    pulsar.getConfiguration().setMaxUnackedMessagesPerConsumer(maxUnAckMsgs);
    log.info("-- Exiting {} test --", methodName);
}

@Test(timeOut = 100000, dataProvider = "ackReceiptEnabled", groups = "quarantine")
public void testRedeliveryFailOverConsumer(boolean ackReceiptEnabled) throws Exception {
    log.info("-- Starting {} test --", methodName);
    final int receiverQueueSize = 10;
    // Only subscribe consumer
    ConsumerImpl<byte[]> consumer = (ConsumerImpl<byte[]>) pulsarClient.newConsumer().topic("persistent://my-property/my-ns/unacked-topic").subscriptionName("subscriber-1").receiverQueueSize(receiverQueueSize).subscriptionType(SubscriptionType.Failover).isAckReceiptEnabled(ackReceiptEnabled).acknowledgmentGroupTime(0, TimeUnit.SECONDS).subscribe();
    Producer<byte[]> producer = pulsarClient.newProducer().topic("persistent://my-property/my-ns/unacked-topic").create();
    // (1) send all message at once
    int consumeMsgInParts = 4;
    for (int i = 0; i < receiverQueueSize * 2; i++) {
        String message = "my-message-" + i;
        producer.send(message.getBytes());
    }
    producer.flush();
    // (1.a) consume first consumeMsgInParts msgs and trigger redeliver
    Message<byte[]> msg;
    List<Message<byte[]>> messages1 = new ArrayList<>();
    for (int i = 0; i < consumeMsgInParts; i++) {
        //There is some detailed info about this case.
        //https://github.com/apache/pulsar/pull/15088#issuecomment-1113521990
        msg = consumer.receive();
        if (msg != null) {
            messages1.add(msg);
            consumer.acknowledge(msg);
            log.info("Received message: " + new String(msg.getData()));
        } else {
            break;
        }
    }
    assertEquals(messages1.size(), consumeMsgInParts);
    consumer.redeliverUnacknowledgedMessages();
    Thread.sleep(1000L);
    // (1.b) consume second consumeMsgInParts msgs and trigger redeliver
    messages1.clear();
    for (int i = 0; i < consumeMsgInParts; i++) {
        msg = consumer.receive();
        if (msg != null) {
            messages1.add(msg);
            consumer.acknowledge(msg);
            log.info("Received message: " + new String(msg.getData()));
        } else {
            break;
        }
    }
    assertEquals(messages1.size(), consumeMsgInParts);
    consumer.redeliverUnacknowledgedMessages();
    Thread.sleep(1000L);
    int remainingMsgs = (2 * receiverQueueSize) - (2 * consumeMsgInParts);
    messages1.clear();
    for (int i = 0; i < remainingMsgs; i++) {
        msg = consumer.receive();
        if (msg != null) {
            messages1.add(msg);
            consumer.acknowledge(msg);
            log.info("Received message: " + new String(msg.getData()));
        } else {
            break;
        }
    }
    assertEquals(messages1.size(), remainingMsgs);
    producer.close();
    consumer.close();
    log.info("-- Exiting {} test --", methodName);
}

@Test(timeOut = 10000)
