@Test(timeOut = 100000)
public void testECDSAEncryption() throws Exception {
    log.info("-- Starting {} test --", methodName);
    String topicName = "persistent://my-property/my-ns/myecdsa-topic1-" + System.currentTimeMillis();
    class EncKeyReader implements CryptoKeyReader {

        final EncryptionKeyInfo keyInfo = new EncryptionKeyInfo();

        @Override
        public EncryptionKeyInfo getPublicKey(String keyName, Map<String, String> keyMeta) {
            String CERT_FILE_PATH = "./src/test/resources/certificate/public-key." + keyName;
            if (Files.isReadable(Paths.get(CERT_FILE_PATH))) {
                try {
                    keyInfo.setKey(Files.readAllBytes(Paths.get(CERT_FILE_PATH)));
                    return keyInfo;
                } catch (IOException e) {
                    Assert.fail("Failed to read certificate from " + CERT_FILE_PATH);
                }
            } else {
                Assert.fail("Certificate file " + CERT_FILE_PATH + " is not present or not readable.");
            }
            return null;
        }

        @Override
        public EncryptionKeyInfo getPrivateKey(String keyName, Map<String, String> keyMeta) {
            String CERT_FILE_PATH = "./src/test/resources/certificate/private-key." + keyName;
            if (Files.isReadable(Paths.get(CERT_FILE_PATH))) {
                try {
                    keyInfo.setKey(Files.readAllBytes(Paths.get(CERT_FILE_PATH)));
                    return keyInfo;
                } catch (IOException e) {
                    Assert.fail("Failed to read certificate from " + CERT_FILE_PATH);
                }
            } else {
                Assert.fail("Certificate file " + CERT_FILE_PATH + " is not present or not readable.");
            }
            return null;
        }
    }
    final int totalMsg = 10;
    Set<String> messageSet = new HashSet<>();
    Consumer<byte[]> cryptoConsumer = pulsarClient.newConsumer().topic(topicName).subscriptionName("my-subscriber-name").cryptoKeyReader(new EncKeyReader()).subscribe();
    Consumer<byte[]> normalConsumer = pulsarClient.newConsumer().topic(topicName).subscriptionName("my-subscriber-name-normal").subscribe();
    Producer<byte[]> cryptoProducer = pulsarClient.newProducer().topic(topicName).addEncryptionKey("client-ecdsa.pem").cryptoKeyReader(new EncKeyReader()).create();
    for (int i = 0; i < totalMsg; i++) {
        String message = "my-message-" + i;
        cryptoProducer.send(message.getBytes());
    }
    Message<byte[]> msg;
    msg = normalConsumer.receive(RECEIVE_TIMEOUT_MEDIUM_MILLIS, TimeUnit.MILLISECONDS);
    // should not able to read message using normal message.
    assertNull(msg);
    for (int i = 0; i < totalMsg; i++) {
        msg = cryptoConsumer.receive(RECEIVE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
        String receivedMessage = new String(msg.getData());
        log.debug("Received message: [{}]", receivedMessage);
        String expectedMessage = "my-message-" + i;
        testMessageOrderAndDuplicates(messageSet, receivedMessage, expectedMessage);
    }
    // Acknowledge the consumption of all messages at once
    cryptoConsumer.acknowledgeCumulative(msg);
    cryptoConsumer.close();
    log.info("-- Exiting {} test --", methodName);
}

