    sub.close(true, Optional.empty()).get();
    // Make sure that the rate limiter is closed
    Assert.assertEquals(dispatchRateLimiter.getDispatchRateOnMsg(), -1);
    Assert.assertEquals(dispatchRateLimiter.getDispatchRateOnByte(), -1);
