@Test
public void testDefaultCryptoKeyReader() throws Exception {
    final String topic = "persistent://my-property/my-ns/test-reader-default-crypto-key-reader" + System.currentTimeMillis();
    final String ecdsaPublicKeyFile = "file:./src/test/resources/certificate/public-key.client-ecdsa.pem";
    final String ecdsaPrivateKeyFile = "file:./src/test/resources/certificate/private-key.client-ecdsa.pem";
    final String ecdsaPublicKeyData = "data:application/x-pem-file;base64,";
    final String ecdsaPrivateKeyData = "data:application/x-pem-file;base64,";
    final String rsaPublicKeyFile = "file:./src/test/resources/certificate/public-key.client-rsa.pem";
    final String rsaPrivateKeyFile = "file:./src/test/resources/certificate/private-key.client-rsa.pem";
    final String rsaPublicKeyData = "data:application/x-pem-file;base64,";
    final String rsaPrivateKeyData = "data:application/x-pem-file;base64,";
    final int numMsg = 10;
    Map<String, String> privateKeyFileMap = new HashMap<>();
    privateKeyFileMap.put("client-ecdsa.pem", ecdsaPrivateKeyFile);
    privateKeyFileMap.put("client-rsa.pem", rsaPrivateKeyFile);
    Map<String, String> privateKeyDataMap = new HashMap<>();
    privateKeyDataMap.put("client-ecdsa.pem", ecdsaPrivateKeyData);
    privateKeyDataMap.put("client-rsa.pem", rsaPrivateKeyData);
    Reader<byte[]> reader1 = pulsarClient.newReader().topic(topic).startMessageId(MessageId.latest).defaultCryptoKeyReader(ecdsaPrivateKeyFile).create();
    Reader<byte[]> reader2 = pulsarClient.newReader().topic(topic).startMessageId(MessageId.latest).defaultCryptoKeyReader(ecdsaPrivateKeyData).create();
    Reader<byte[]> reader3 = pulsarClient.newReader().topic(topic).startMessageId(MessageId.latest).defaultCryptoKeyReader(privateKeyFileMap).create();
    Reader<byte[]> reader4 = pulsarClient.newReader().topic(topic).startMessageId(MessageId.latest).defaultCryptoKeyReader(privateKeyDataMap).create();
    Producer<byte[]> producer1 = pulsarClient.newProducer().topic(topic).addEncryptionKey("client-ecdsa.pem").defaultCryptoKeyReader(ecdsaPublicKeyFile).create();
    Producer<byte[]> producer2 = pulsarClient.newProducer().topic(topic).addEncryptionKey("client-ecdsa.pem").defaultCryptoKeyReader(ecdsaPublicKeyData).create();
    for (int i = 0; i < numMsg; i++) {
        producer1.send(("my-message-" + i).getBytes());
    }
    for (int i = numMsg; i < numMsg * 2; i++) {
        producer2.send(("my-message-" + i).getBytes());
    }
    producer1.close();
    producer2.close();
    for (Reader<byte[]> reader : (List<Reader<byte[]>>) Lists.newArrayList(reader1, reader2)) {
        for (int i = 0; i < numMsg * 2; i++) {
            MessageImpl<byte[]> msg = (MessageImpl<byte[]>) reader.readNext(5, TimeUnit.SECONDS);
            // verify that encrypted message contains encryption-context
            msg.getEncryptionCtx().orElseThrow(() -> new IllegalStateException("encryption-ctx not present for encrypted message"));
            assertEquals(new String(msg.getData()), "my-message-" + i);
        }
    }
    reader1.close();
    reader2.close();
    Producer<byte[]> producer3 = pulsarClient.newProducer().topic(topic).addEncryptionKey("client-rsa.pem").defaultCryptoKeyReader(rsaPublicKeyFile).create();
    Producer<byte[]> producer4 = pulsarClient.newProducer().topic(topic).addEncryptionKey("client-rsa.pem").defaultCryptoKeyReader(rsaPublicKeyData).create();
    for (int i = numMsg * 2; i < numMsg * 3; i++) {
        producer3.send(("my-message-" + i).getBytes());
    }
    for (int i = numMsg * 3; i < numMsg * 4; i++) {
        producer4.send(("my-message-" + i).getBytes());
    }
    producer3.close();
    producer4.close();
    for (Reader<byte[]> reader : (List<Reader<byte[]>>) Lists.newArrayList(reader3, reader4)) {
        for (int i = 0; i < numMsg * 4; i++) {
            MessageImpl<byte[]> msg = (MessageImpl<byte[]>) reader.readNext(5, TimeUnit.SECONDS);
            // verify that encrypted message contains encryption-context
            msg.getEncryptionCtx().orElseThrow(() -> new IllegalStateException("encryption-ctx not present for encrypted message"));
            assertEquals(new String(msg.getData()), "my-message-" + i);
        }
    }
    reader3.close();
    reader4.close();
}

@Test
public void testSimpleReaderReachEndOfTopic() throws Exception {
    Reader<byte[]> reader = pulsarClient.newReader().topic("persistent://my-property/my-ns/testSimpleReaderReachEndOfTopic").startMessageId(MessageId.earliest).create();
    Producer<byte[]> producer = pulsarClient.newProducer().topic("persistent://my-property/my-ns/testSimpleReaderReachEndOfTopic").create();
    // no data write, should return false
    assertFalse(reader.hasMessageAvailable());
    // produce message 0 -- 99
    for (int i = 0; i < 100; i++) {
        String message = "my-message-" + i;
        producer.send(message.getBytes());
    }
    MessageImpl<byte[]> msg = null;
    Set<String> messageSet = new HashSet<>();
    int index = 0;
    // read message till end.
    while (reader.hasMessageAvailable()) {
        msg = (MessageImpl<byte[]>) reader.readNext(1, TimeUnit.SECONDS);
        String receivedMessage = new String(msg.getData());
        log.debug("Received message: [{}]", receivedMessage);
        String expectedMessage = "my-message-" + (index++);
        testMessageOrderAndDuplicates(messageSet, receivedMessage, expectedMessage);
    }
    assertEquals(index, 100);
    // readNext should return null, after reach the end of topic.
    assertNull(reader.readNext(1, TimeUnit.SECONDS));
    // produce message again.
    for (int i = 100; i < 200; i++) {
        String message = "my-message-" + i;
        producer.send(message.getBytes());
    }
    // read message till end again.
    while (reader.hasMessageAvailable()) {
        msg = (MessageImpl<byte[]>) reader.readNext(1, TimeUnit.SECONDS);
        String receivedMessage = new String(msg.getData());
        log.debug("Received message: [{}]", receivedMessage);
        String expectedMessage = "my-message-" + (index++);
        testMessageOrderAndDuplicates(messageSet, receivedMessage, expectedMessage);
    }
    assertEquals(index, 200);
    // readNext should return null, after reach the end of topic.
    assertNull(reader.readNext(1, TimeUnit.SECONDS));
    reader.close();
    producer.close();
}

