        while (msg != null) {
            index++;
            msg = reader.readNext(100, TimeUnit.MILLISECONDS);
        }
        assertEquals(index, 101);
    }
    assertFalse(reader.hasMessageAvailable());
    reader.close();
    producer.close();
}

