        String expectedMessage = "my-message-" + (msgNum++);
        Assert.assertNotEquals(receivedMessage, expectedMessage, "Received encrypted message " + receivedMessage + " should not match the expected message " + expectedMessage);
        consumer.acknowledgeCumulative(msg);
    } catch (Exception e) {
        Assert.fail("Failed to receive message even aftet ConsumerCryptoFailureAction.CONSUME is set.");
    }
    // 5. Set keyreader and failure action
    consumer.close();
    consumer = pulsarClient.newConsumer(Schema.STRING).topic("persistent://my-property/use/my-ns/myenc-topic1").subscriptionName("my-subscriber-name").subscriptionType(SubscriptionType.Exclusive).cryptoKeyReader(new EncKeyReader()).cryptoFailureAction(ConsumerCryptoFailureAction.FAIL).subscribe();
    for (int i = msgNum; i < totalMsg - 1; i++) {
        msg = consumer.receive(5, TimeUnit.SECONDS);
        String receivedMessage = msg.getValue();
        log.debug("Received message: [{}]", receivedMessage);
        String expectedMessage = "my-message-" + i;
        testMessageOrderAndDuplicates(messageSet, receivedMessage, expectedMessage);
    }
    // Acknowledge the consumption of all messages at once
    consumer.acknowledgeCumulative(msg);
    consumer.close();
    // 6. Set consumer config to discard if decryption fails
    consumer.close();
    consumer = pulsarClient.newConsumer(Schema.STRING).topic("persistent://my-property/use/my-ns/myenc-topic1").subscriptionName("my-subscriber-name").subscriptionType(SubscriptionType.Exclusive).cryptoFailureAction(ConsumerCryptoFailureAction.DISCARD).subscribe();
    // Receive should proceed and discard encrypted messages
    msg = consumer.receive(5, TimeUnit.SECONDS);
    Assert.assertNull(msg, "Message received even after ConsumerCryptoFailureAction.DISCARD is set.");
    log.info("-- Exiting {} test --", methodName);
}

