@Test(timeOut = 30000, dataProvider = "combinations")
public void testConsumerDedup(boolean batchingEnabled, int receiverQueueSize) throws Exception {
    String topic = BrokerTestUtil.newUniqueName("persistent://my-property/my-ns/my-topic");
    @Cleanup
    Consumer<String> consumer = pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionName("test").// Use high ack delay to simulate a message being tracked as dup
    acknowledgmentGroupTime(1, TimeUnit.HOURS).receiverQueueSize(receiverQueueSize).subscribe();
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(topic).enableBatching(batchingEnabled).batchingMaxMessages(10).batchingMaxPublishDelay(1, TimeUnit.HOURS).create();
    for (int i = 0; i < 30; i++) {
        producer.sendAsync("hello-" + i);
    }
    producer.flush();
    // Consumer receives and acks all the messages, though the acks
    // are still cached in client lib
    for (int i = 0; i < 30; i++) {
        Message<String> msg = consumer.receive();
        assertEquals(msg.getValue(), "hello-" + i);
        consumer.acknowledge(msg);
    }
    // Trigger redelivery by unloading the topic.
    admin.topics().unload(topic);
    // Consumer dedup logic will detect the dups and not bubble them up to the application
    // (With zero-queue we cannot use receive with timeout)
    if (receiverQueueSize > 0) {
        Message<String> msg = consumer.receive(100, TimeUnit.MILLISECONDS);
        assertNull(msg);
    }
    // The flow permits in consumer shouldn't have been messed up by the deduping
    // and we should be able to get new messages through
    for (int i = 0; i < 30; i++) {
        producer.sendAsync("new-message-" + i);
    }
    producer.flush();
    for (int i = 0; i < 30; i++) {
        Message<String> msg = consumer.receive();
        assertEquals(msg.getValue(), "new-message-" + i);
        consumer.acknowledge(msg);
    }
}

@Test
public void testConsumerMemoryLimit() throws Exception {
    String topic = newTopicName();
    ClientBuilder clientBuilder = PulsarClient.builder().serviceUrl(pulsar.getBrokerServiceUrl()).memoryLimit(10, SizeUnit.KILO_BYTES);
    @Cleanup
    PulsarTestClient client = PulsarTestClient.create(clientBuilder);
    @Cleanup
    ProducerImpl<byte[]> producer = (ProducerImpl<byte[]>) client.newProducer().topic(topic).enableBatching(false).blockIfQueueFull(false).create();
    @Cleanup
    ConsumerImpl<byte[]> c1 = (ConsumerImpl<byte[]>) client.newConsumer().subscriptionName("sub").topic(topic).autoScaledReceiverQueueSizeEnabled(true).subscribe();
    @Cleanup
    ConsumerImpl<byte[]> c2 = (ConsumerImpl<byte[]>) client.newConsumer().subscriptionName("sub2").topic(topic).autoScaledReceiverQueueSizeEnabled(true).subscribe();
    c2.updateAutoScaleReceiverQueueHint();
    int n = 5;
    for (int i = 0; i < n; i++) {
        producer.send(new byte[3000]);
    }
    Awaitility.await().until(c1.scaleReceiverQueueHint::get);
    c1.setCurrentReceiverQueueSize(10);
    Awaitility.await().until(() -> c1.incomingMessages.size() == n);
    log.info("memory usage:{}", client.getMemoryLimitController().currentUsagePercent());
    //1. check memory limit reached,
    Assert.assertTrue(client.getMemoryLimitController().currentUsagePercent() > 1);
    //2. check c2 can't expand receiver queue.
    Assert.assertEquals(c2.getCurrentReceiverQueueSize(), 1);
    for (int i = 0; i < n; i++) {
        Awaitility.await().until(() -> c2.incomingMessages.size() == 1);
        Assert.assertNotNull(c2.receive());
    }
    Assert.assertTrue(c2.scaleReceiverQueueHint.get());
    //this should trigger c2 receiver queue size expansion.
    c2.receiveAsync();
    //make sure expectMoreIncomingMessages is called.
    Awaitility.await().until(() -> !c2.pendingReceives.isEmpty());
    Assert.assertEquals(c2.getCurrentReceiverQueueSize(), 1);
    //3. producer can't send message;
    Assert.expectThrows(PulsarClientException.MemoryBufferIsFullError.class, () -> producer.send(new byte[10]));
    //4. ConsumerBase#reduceCurrentReceiverQueueSize is called already. Queue size reduced to 5.
    log.info("RQS:{}", c1.getCurrentReceiverQueueSize());
    Assert.assertEquals(c1.getCurrentReceiverQueueSize(), 5);
    for (int i = 0; i < n; i++) {
        c1.receive();
    }
}

