    String topicName = "persistent://my-property/my-ns/testSendChunkMessageWithSameSequenceID";
    String producerName = "test-producer";
    @Cleanup
    Consumer<String> consumer = pulsarClient.newConsumer(Schema.STRING).subscriptionName("test-sub").topic(topicName).subscribe();
    @Cleanup
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).producerName(producerName).topic(topicName).enableChunking(true).enableBatching(false).create();
    // payload size in KB
    int messageSize = 6000;
    String message = "a".repeat(messageSize * 1000);
    producer.newMessage().value(message).sequenceId(10).send();
    Message<String> msg = consumer.receive(10, TimeUnit.SECONDS);
    assertNotNull(msg);
    assertTrue(msg.getMessageId() instanceof ChunkMessageIdImpl);
    assertEquals(msg.getValue(), message);
    producer.newMessage().value(message).sequenceId(10).send();
    msg = consumer.receive(3, TimeUnit.SECONDS);
    assertNull(msg);
}

