    }
    Reader<byte[]> reader = pulsarClient.newReader().topic(topicName).startMessageIdInclusive().startMessageId(msgIds.get(1)).create();
    Message<byte[]> readMsg = reader.readNext(5, TimeUnit.SECONDS);
    assertEquals(msgIds.get(1), readMsg.getMessageId());
    consumer1.close();
    consumer2.close();
    producer.close();
    log.info("-- Exiting {} test --", methodName);
}

