@Test
public void testBlockIfQueueFullWhenChunking() throws Exception {
    this.conf.setMaxMessageSize(50);
    @Cleanup
    final Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic("my-property/my-ns/test-chunk-size").enableChunking(true).enableBatching(false).blockIfQueueFull(true).maxPendingMessages(3).create();
    // Test sending large message (totalChunks > maxPendingMessages) should not cause deadlock
    // We need to use a separate thread to send the message instead of using the sendAsync, because the deadlock
    // might happen before publishing messages to the broker.
    CompletableFuture<Void> sendMsg = CompletableFuture.runAsync(() -> {
        try {
            producer.send(createMessagePayload(200));
        } catch (PulsarClientException e) {
            throw new RuntimeException(e);
        }
    });
    try {
        sendMsg.get(5, TimeUnit.SECONDS);
    } catch (TimeoutException e) {
        Assert.fail("Deadlock detected when sending large message.");
    }
    // Test sending multiple large messages (For every message, totalChunks < maxPendingMessages) concurrently
    // should not cause the deadlock.
    List<CompletableFuture<Void>> sendMsgFutures = new ArrayList<>();
    for (int i = 0; i < 3; i++) {
        sendMsgFutures.add(CompletableFuture.runAsync(() -> {
            try {
                producer.send(createMessagePayload(100));
            } catch (PulsarClientException e) {
                throw new RuntimeException(e);
            }
        }));
    }
    try {
        FutureUtil.waitForAll(sendMsgFutures).get(5, TimeUnit.SECONDS);
    } catch (TimeoutException e) {
        Assert.fail("Deadlock detected when sending multiple large messages concurrently.");
    }
}

@Test(timeOut = 10000, dataProviderClass = EnumValuesDataProvider.class, dataProvider = "values")
public void producerSendAsync(TopicType topicType) throws PulsarClientException, PulsarAdminException {
    // Given
    String key = "producerSendAsync-" + topicType;
    final String topicName = "persistent://prop/cluster/namespace/topic-" + key;
    final String subscriptionName = "my-subscription-" + key;
    final String messagePrefix = "my-message-" + key + "-";
    final int numberOfMessages = 30;
    if (topicType == TopicType.PARTITIONED) {
        int numberOfPartitions = 3;
        admin.topics().createPartitionedTopic(topicName, numberOfPartitions);
    }
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topicName).enableBatching(false).messageRoutingMode(MessageRoutingMode.SinglePartition).create();
    Consumer<byte[]> consumer = pulsarClient.newConsumer().topic(topicName).subscriptionName(subscriptionName).subscribe();
    // When
    // Messages are published asynchronously
    List<Future<MessageId>> futures = new ArrayList<>();
    for (int i = 0; i < numberOfMessages; i++) {
        String message = messagePrefix + i;
        futures.add(producer.sendAsync(message.getBytes()));
    }
    // Then
    // expect that the Message Ids of subsequently sent messages are in ascending order
    Set<MessageId> messageIds = new HashSet<>();
    MessageIdImpl previousMessageId = null;
    for (Future<MessageId> f : futures) {
        try {
            MessageIdImpl currentMessageId = (MessageIdImpl) f.get();
            if (previousMessageId != null) {
                assertTrue(currentMessageId.compareTo(previousMessageId) > 0, "Message Ids should be in ascending order");
            }
            messageIds.add(currentMessageId);
            previousMessageId = currentMessageId;
        } catch (Exception e) {
            fail("Failed to publish message", e);
        }
    }
    // And
    // expect that there's a message id for each sent out message
    // and that all messages have been received by the consumer
    log.info("Message IDs = {}", messageIds);
    assertEquals(messageIds.size(), numberOfMessages, "Not all messages published successfully");
    for (int i = 0; i < numberOfMessages; i++) {
        Message<byte[]> message = consumer.receive();
        assertEquals(new String(message.getData()), messagePrefix + i);
        MessageId messageId = message.getMessageId();
        assertTrue(messageIds.remove(messageId), "Failed to receive message");
    }
    log.info("Remaining message IDs = {}", messageIds);
    assertEquals(messageIds.size(), 0, "Not all messages received successfully");
    consumer.unsubscribe();
}

