@Test(dataProvider = "batchingAndCompression")
public void testParseMessages(boolean batchEnabled, CompressionType compressionType) throws Exception {
    final String topic = "persistent://my-tenant/my-ns/message-parse-test-" + batchEnabled + "-" + compressionType;
    final TopicName topicName = TopicName.get(topic);
    final int n = 10;
    @Cleanup
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).compressionType(compressionType).enableBatching(batchEnabled).batchingMaxPublishDelay(10, TimeUnit.SECONDS).topic(topic).create();
    ManagedCursor cursor = ((PersistentTopic) pulsar.getBrokerService().getTopicReference(topic).get()).getManagedLedger().newNonDurableCursor(PositionFactory.EARLIEST);
    if (batchEnabled) {
        for (int i = 0; i < n - 1; i++) {
            producer.sendAsync("hello-" + i);
        }
        producer.send("hello-" + (n - 1));
    } else {
        for (int i = 0; i < n; i++) {
            producer.send("Pulsar-" + i);
        }
    }
    if (batchEnabled) {
        Entry entry = cursor.readEntriesOrWait(1).get(0);
        List<RawMessage> messages = new ArrayList<>();
        ByteBuf headsAndPayload = entry.getDataBuffer();
        try {
            MessageParser.parseMessage(topicName, entry.getLedgerId(), entry.getEntryId(), headsAndPayload, messages::add, Commands.DEFAULT_MAX_MESSAGE_SIZE);
        } finally {
            entry.release();
        }
        assertEquals(messages.size(), 10);
        for (int i = 0; i < n; i++) {
            assertEquals(messages.get(i).getData(), Unpooled.wrappedBuffer(("hello-" + i).getBytes()));
        }
        messages.forEach(msg -> {
            msg.getSchemaVersion();
            msg.release();
        });
        Awaitility.await().atMost(3, TimeUnit.SECONDS).untilAsserted(() -> {
            assertEquals(headsAndPayload.refCnt(), 0);
        });
    } else {
        // Read through raw data
        assertEquals(cursor.getNumberOfEntriesInBacklog(false), n);
        List<Entry> entries = cursor.readEntriesOrWait(n);
        assertEquals(entries.size(), n);
        List<ByteBuf> headsAndPayloadList = new ArrayList<>();
        List<RawMessage> messages = new ArrayList<>();
        for (Entry entry : entries) {
            ByteBuf headsAndPayload = entry.getDataBuffer();
            headsAndPayloadList.add(headsAndPayload);
            MessageParser.parseMessage(topicName, entry.getLedgerId(), entry.getEntryId(), entry.getDataBuffer(), messages::add, Commands.DEFAULT_MAX_MESSAGE_SIZE);
            entry.release();
        }
        assertEquals(messages.size(), 10);
        messages.forEach(msg -> {
            msg.getSchemaVersion();
            msg.release();
        });
        for (ByteBuf byteBuf : headsAndPayloadList) {
            Awaitility.await().atMost(3, TimeUnit.SECONDS).untilAsserted(() -> {
                assertEquals(byteBuf.refCnt(), 0);
            });
        }
    }
}

/**
 * Verifies publish rate limiting by setting rate-limiting on number of published messages.
 *
 * @throws Exception
 */
@Test
public void testSimplePublishMessageThrottling() throws Exception {
    log.info("-- Starting {} test --", methodName);
    final String namespace = "my-property/throttling_publish";
    final String topicName = "persistent://" + namespace + "/throttlingMessageBlock";
    admin.namespaces().createNamespace(namespace, Sets.newHashSet("test"));
    PublishRate publishMsgRate = new PublishRate();
    publishMsgRate.publishThrottlingRateInMsg = 10;
    // create producer and topic
    ProducerImpl<byte[]> producer = (ProducerImpl<byte[]>) pulsarClient.newProducer().topic(topicName).maxPendingMessages(30000).create();
    PersistentTopic topic = (PersistentTopic) pulsar.getBrokerService().getTopicIfExists(topicName).get().get();
    // enable throttling
    admin.namespaces().setPublishRate(namespace, publishMsgRate);
    Producer prod = topic.getProducers().values().iterator().next();
    // reset counter
    prod.updateRates();
    int total = 200;
    for (int i = 0; i < total; i++) {
        producer.send(new byte[80]);
    }
    // calculate rates and due to throttling rate should be < total per-second
    prod.updateRates();
    double rateIn = prod.getStats().msgRateIn;
    assertTrue(rateIn < total);
    // disable throttling
    publishMsgRate.publishThrottlingRateInMsg = -1;
    admin.namespaces().setPublishRate(namespace, publishMsgRate);
    // reset counter
    prod.updateRates();
    for (int i = 0; i < total; i++) {
        producer.send(new byte[80]);
    }
    prod.updateRates();
    rateIn = prod.getStats().msgRateIn;
    assertTrue(rateIn > total);
    producer.close();
}

