@Test(dataProvider = "enableBatch")
public void testRedeliveryAddEpoch(boolean enableBatch) throws Exception {
    final String topic = "testRedeliveryAddEpoch";
    final String subName = "my-sub";
    @Cleanup
    ConsumerImpl<String> consumer = ((ConsumerImpl<String>) pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionName(subName).subscriptionType(SubscriptionType.Failover).subscribe());
