@Test
public void testReaderWithTimeLong() throws Exception {
    String ns = "my-property/my-ns";
    String topic = "persistent://" + ns + "/testReadFromPartition" + UUID.randomUUID();
    admin.topics().createPartitionedTopic(topic, 3);
    RetentionPolicies retention = new RetentionPolicies(-1, -1);
    admin.namespaces().setRetention(ns, retention);
    ProducerBuilder<byte[]> produceBuilder = pulsarClient.newProducer();
    produceBuilder.topic(topic);
    produceBuilder.enableBatching(false);
    Producer<byte[]> producer = produceBuilder.create();
    int totalMsg = 10;
    // (1) Publish 10 messages with publish-time 5 HOUR back
    // 5 hours old
    long oldMsgPublishTime = System.currentTimeMillis() - TimeUnit.HOURS.toMillis(5);
    for (int i = 0; i < totalMsg; i++) {
        TypedMessageBuilderImpl<byte[]> msg = (TypedMessageBuilderImpl<byte[]>) producer.newMessage().value(("old" + i).getBytes());
        msg.getMetadataBuilder().setPublishTime(oldMsgPublishTime).setSequenceId(i).setProducerName(producer.getProducerName()).setReplicatedFrom("us-west1");
        msg.send();
    }
    // (2) Publish 10 messages with publish-time 1 HOUR back
    // 1 hour old
    long newMsgPublishTime = System.currentTimeMillis() - TimeUnit.HOURS.toMillis(1);
    MessageId firstMsgId = null;
    for (int i = 0; i < totalMsg; i++) {
        TypedMessageBuilderImpl<byte[]> msg = (TypedMessageBuilderImpl<byte[]>) producer.newMessage().value(("new" + i).getBytes());
        msg.getMetadataBuilder().setPublishTime(newMsgPublishTime).setProducerName(producer.getProducerName()).setReplicatedFrom("us-west1");
        MessageId msgId = msg.send();
        if (firstMsgId == null) {
            firstMsgId = msgId;
        }
    }
    // (3) Create reader and set position 1 hour back so, it should only read messages which are 2 hours old which
    // published on step 2
    Reader<byte[]> reader = pulsarClient.newReader().topic(topic).startMessageFromRollbackDuration(2, TimeUnit.HOURS).create();
    List<MessageId> receivedMessageIds = new ArrayList<>();
    while (reader.hasMessageAvailable()) {
        Message<byte[]> msg = reader.readNext(1, TimeUnit.SECONDS);
        if (msg == null) {
            break;
        }
        receivedMessageIds.add(msg.getMessageId());
    }
    assertEquals(receivedMessageIds.size(), totalMsg);
    restartBroker();
    assertFalse(reader.hasMessageAvailable());
    reader.close();
    producer.close();
}

