@Test(dataProvider = "variationsBackoff")
public void testNegativeAcksWithBackoff(boolean batching, boolean usePartitions, SubscriptionType subscriptionType, int minNackTimeMs, int maxNackTimeMs) throws Exception {
    log.info("Test negative acks with back off batching={} partitions={} subType={} minNackTimeMs={}, " + "maxNackTimeMs={}", batching, usePartitions, subscriptionType, minNackTimeMs, maxNackTimeMs);
    String topic = BrokerTestUtil.newUniqueName("testNegativeAcksWithBackoff");
    MultiplierRedeliveryBackoff backoff = MultiplierRedeliveryBackoff.builder().minDelayMs(minNackTimeMs).maxDelayMs(maxNackTimeMs).build();
    @Cleanup
    Consumer<String> consumer = pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionName("sub1").acknowledgmentGroupTime(0, TimeUnit.SECONDS).subscriptionType(subscriptionType).negativeAckRedeliveryBackoff(backoff).subscribe();
    @Cleanup
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(topic).enableBatching(batching).create();
    Set<String> sentMessages = new HashSet<>();
    final int N = 10;
    for (int i = 0; i < N; i++) {
        String value = "test-" + i;
        producer.sendAsync(value);
        sentMessages.add(value);
    }
    producer.flush();
    final int redeliverCount = 5;
    long firstReceivedAt = System.currentTimeMillis();
    long expectedTotalRedeliveryDelay = 0;
    for (int i = 0; i < redeliverCount; i++) {
        for (int j = 0; j < N; j++) {
            Message<String> msg = consumer.receive();
            log.info("Received message {}", msg.getValue());
            consumer.negativeAcknowledge(msg);
        }
        expectedTotalRedeliveryDelay += backoff.next(i);
    }
    Set<String> receivedMessages = new HashSet<>();
    // All the messages should be received again
    for (int i = 0; i < N; i++) {
        Message<String> msg = consumer.receive();
        receivedMessages.add(msg.getValue());
        consumer.acknowledge(msg);
    }
    long receivedAfterRedeliveryAt = System.currentTimeMillis();
    log.info("Total redelivery delay: {} ms", receivedAfterRedeliveryAt - firstReceivedAt);
    assertEquals(receivedMessages, sentMessages);
    if (SubscriptionType.Shared == subscriptionType) {
        log.info("Total expected redelivery delay {} ms", expectedTotalRedeliveryDelay);
        assertTrue(receivedAfterRedeliveryAt - firstReceivedAt >= expectedTotalRedeliveryDelay);
    }
    // There should be no more messages
    assertNull(consumer.receive(100, TimeUnit.MILLISECONDS));
    consumer.close();
    producer.close();
}

