    consumer.negativeAcknowledge(batchMessageId3);
    assertEquals(negativeAcksTracker.getNackedMessagesCount().orElse(-1).intValue(), 1);
    assertEquals(unAckedMessageTracker.size(), 0);
    negativeAcksTracker.close();
}

