    pulsar.getConfiguration().setDefaultRetentionSizeInMB(0);
    @Cleanup
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topicName).sendTimeout(1, TimeUnit.SECONDS).enableBatching(false).create();
    @Cleanup
    Consumer<byte[]> consumer = pulsarClient.newConsumer().topic(topicName).subscriptionName("my-sub").subscribe();
    // Act: prepare a full ledger data and ack them.
    for (int i = 0; i < messagesCount; i++) {
        producer.newMessage().sendAsync();
    }
    for (int i = 0; i < messagesCount; i++) {
        Message<byte[]> message = consumer.receive();
        assertNotNull(message);
