@Test
public void testFailAndRetry() throws Exception {
    @Cleanup("shutdownNow")
    ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
    CompletableFuture<Boolean> callback = new CompletableFuture<>();
    AtomicInteger atomicInteger = new AtomicInteger(0);
    Backoff backoff = new BackoffBuilder().setInitialTime(100, TimeUnit.MILLISECONDS).setMax(2000, TimeUnit.MILLISECONDS).setMandatoryStop(5000, TimeUnit.MILLISECONDS).create();
    RetryUtil.retryAsynchronously(() -> {
        CompletableFuture<Boolean> future = new CompletableFuture<>();
        atomicInteger.incrementAndGet();
        if (atomicInteger.get() < 5) {
            future.completeExceptionally(new RuntimeException("fail"));
        } else {
            future.complete(true);
        }
        return future;
    }, backoff, executor, callback);
    assertTrue(callback.get());
    assertEquals(atomicInteger.get(), 5);
}

