/**
 * Verifies Broker publish rate limiting enabled by broker conf.
 * Broker publish throttle enabled / topic publish throttle disabled
 * @throws Exception
 */
@Test
public void testBrokerPublishMessageThrottlingInit() throws Exception {
    log.info("-- Starting {} test --", methodName);
    final String namespace = "my-property/throttling_publish_init";
    final String topicName = "persistent://" + namespace + "/brokerThrottlingMessageBlock";
    admin.namespaces().createNamespace(namespace, Sets.newHashSet("test"));
    // create producer and topic
    ProducerImpl<byte[]> producer = (ProducerImpl<byte[]>) pulsarClient.newProducer().topic(topicName).enableBatching(false).maxPendingMessages(30000).create();
    PersistentTopic topic = (PersistentTopic) pulsar.getBrokerService().getTopicIfExists(topicName).get().get();
    log.info("Get broker configuration: brokerTick {},  MaxMessageRate {}, MaxByteRate {}", pulsar.getConfiguration().getBrokerPublisherThrottlingTickTimeMillis(), pulsar.getConfiguration().getBrokerPublisherThrottlingMaxMessageRate(), pulsar.getConfiguration().getBrokerPublisherThrottlingMaxByteRate());
    Producer prod = topic.getProducers().values().iterator().next();
    // reset counter
    prod.updateRates();
    int total = 100;
    for (int i = 0; i < total; i++) {
        producer.send(new byte[80]);
    }
    // calculate rates and due to throttling rate should be < total per-second
    prod.updateRates();
    double rateIn = prod.getStats().msgRateIn;
    log.info("1-st rate in: {}, total: {} ", rateIn, total);
    assertTrue(rateIn < total);
    // disable throttling
    admin.brokers().updateDynamicConfiguration("brokerPublisherThrottlingMaxMessageRate", Integer.toString(0));
    // reset counter
    prod.updateRates();
    for (int i = 0; i < total; i++) {
        producer.send(new byte[80]);
    }
    prod.updateRates();
    rateIn = prod.getStats().msgRateIn;
    log.info("2-nd rate in: {}, total: {} ", rateIn, total);
    assertTrue(rateIn > total);
    producer.close();
}

