@Test
public void testSendTxnAckMessageToDLQ() throws Exception {
    String topic = NAMESPACE1 + "/testSendTxnAckMessageToDLQ";
    String subName = "test";
    String value = "test";
    @Cleanup
    ProducerImpl<byte[]> producer = (ProducerImpl<byte[]>) pulsarClient.newProducer().topic(topic).enableBatching(false).sendTimeout(1, TimeUnit.SECONDS).create();
    @Cleanup
    Consumer<byte[]> consumer = pulsarClient.newConsumer().topic(topic).subscriptionType(SubscriptionType.Shared).// consumer can't receive the same message three times
    deadLetterPolicy(DeadLetterPolicy.builder().maxRedeliverCount(1).build()).subscriptionName(subName).subscribe();
    @Cleanup
    Consumer<byte[]> deadLetterConsumer = pulsarClient.newConsumer().topic(String.format("%s-%s" + RetryMessageUtil.DLQ_GROUP_TOPIC_SUFFIX, topic, subName)).subscriptionType(SubscriptionType.Shared).deadLetterPolicy(DeadLetterPolicy.builder().maxRedeliverCount(1).build()).subscriptionName("test").subscribe();
    producer.send(value.getBytes());
    Transaction transaction = pulsarClient.newTransaction().withTransactionTimeout(1, TimeUnit.MINUTES).build().get();
    // consumer receive the message the first time, redeliverCount = 0
    consumer.acknowledgeAsync(consumer.receive(waitTimeForCanReceiveMsgInSec, TimeUnit.SECONDS).getMessageId(), transaction).get();
    transaction.abort().get();
    transaction = pulsarClient.newTransaction().withTransactionTimeout(5, TimeUnit.MINUTES).build().get();
    // consumer receive the message the second time, redeliverCount = 1, also can be received
    consumer.acknowledgeAsync(consumer.receive(waitTimeForCanReceiveMsgInSec, TimeUnit.SECONDS).getMessageId(), transaction).get();
    transaction.abort().get();
    // consumer receive the message the third time, redeliverCount = 2,
    // the message will be sent to DLQ, can't receive
    assertNull(consumer.receive(waitTimeForCannotReceiveMsgInSec, TimeUnit.SECONDS));
    assertEquals(((ConsumerImpl<?>) consumer).getAvailablePermits(), 3);
    assertEquals(value, new String(deadLetterConsumer.receive(waitTimeForCanReceiveMsgInSec, TimeUnit.SECONDS).getValue()));
    // cleanup.
    consumer.close();
    deadLetterConsumer.close();
    producer.close();
    admin.topics().delete(String.format("%s-%s" + RetryMessageUtil.DLQ_GROUP_TOPIC_SUFFIX, topic, subName), true);
    admin.topics().delete(topic, true);
}

