@Test(dataProvider = "variationsRedeliveryTracker")
public void testExclusiveSingleAckedNormalTopic(boolean isRedeliveryTracker) throws Exception {
    String key = "testExclusiveSingleAckedNormalTopic";
    final String topicName = "persistent://prop/ns-abc/topic-" + key;
    final String subscriptionName = "my-ex-subscription-" + key;
    final String messagePredicate = "my-message-" + key + "-";
    final int totalMessages = 10;
    // 1. producer connect
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topicName).enableBatching(false).messageRoutingMode(MessageRoutingMode.SinglePartition).create();
    // 2. Create consumer
    Consumer<byte[]> consumer = null;
    if (isRedeliveryTracker) {
        consumer = pulsarClient.newConsumer().topic(topicName).subscriptionName(subscriptionName).receiverQueueSize(7).ackTimeout(ackTimeOutMillis, TimeUnit.MILLISECONDS).ackTimeoutRedeliveryBackoff(MultiplierRedeliveryBackoff.builder().minDelayMs(1000).maxDelayMs(20000).build()).subscribe();
    } else {
        consumer = pulsarClient.newConsumer().topic(topicName).subscriptionName(subscriptionName).receiverQueueSize(7).ackTimeout(ackTimeOutMillis, TimeUnit.MILLISECONDS).subscribe();
    }
    // 3. producer publish messages
    for (int i = 0; i < totalMessages / 2; i++) {
        String message = messagePredicate + i;
        log.info("Producer produced: " + message);
        producer.send(message.getBytes());
    }
    // 4. Receiver receives the message
    Message<byte[]> message = consumer.receive();
    while (message != null) {
        log.info("Consumer received : " + new String(message.getData()));
        message = consumer.receive(500, TimeUnit.MILLISECONDS);
    }
    long size = ((ConsumerImpl<?>) consumer).getUnAckedMessageTracker().size();
    log.info(key + " Unacked Message Tracker size is " + size);
    assertEquals(size, totalMessages / 2);
    // Blocking call, redeliver should kick in
    message = consumer.receive();
    log.info("Consumer received : " + new String(message.getData()));
    HashSet<String> hSet = new HashSet<>();
    for (int i = totalMessages / 2; i < totalMessages; i++) {
        String messageString = messagePredicate + i;
        producer.send(messageString.getBytes());
    }
    do {
        hSet.add(new String(message.getData()));
        consumer.acknowledge(message);
        log.info("Consumer acknowledged : " + new String(message.getData()));
        message = consumer.receive(500, TimeUnit.MILLISECONDS);
    } while (message != null);
    size = ((ConsumerImpl<?>) consumer).getUnAckedMessageTracker().size();
    log.info(key + " Unacked Message Tracker size is " + size);
    assertEquals(size, 0);
    assertEquals(hSet.size(), totalMessages);
}

