@Test(dataProvider = "variationsBackoff")
public void testCheckUnAcknowledgedMessageRedeliveryTimer(long ackTimeOutMillis, long minDelayMs, long maxDelayMs, int multiplier) throws PulsarClientException, InterruptedException {
    String key = "testCheckUnAcknowledgedMessageRedeliveryTimer";
    final String topicName = "persistent://prop/ns-abc/topic-" + key;
    final String subscriptionName = "my-ex-subscription-" + key;
    final String messagePredicate = "my-message-" + key + "-";
    final int totalMessages = 3;
    // 1. producer connect
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topicName).enableBatching(false).messageRoutingMode(MessageRoutingMode.SinglePartition).create();
    // 2. Create consumer
    ConsumerImpl<byte[]> consumer = (ConsumerImpl<byte[]>) pulsarClient.newConsumer().topic(topicName).subscriptionName(subscriptionName).receiverQueueSize(7).subscriptionType(SubscriptionType.Shared).ackTimeout(ackTimeOutMillis, TimeUnit.MILLISECONDS).ackTimeoutRedeliveryBackoff(MultiplierRedeliveryBackoff.builder().minDelayMs(minDelayMs).maxDelayMs(maxDelayMs).multiplier(multiplier).build()).subscribe();
    // 3. producer publish messages
    for (int i = 0; i < totalMessages; i++) {
        String message = messagePredicate + i;
        log.info("Producer produced: " + message);
        producer.send(message.getBytes());
    }
    for (int i = 0; i < totalMessages; i++) {
        Message<byte[]> msg = consumer.receive();
        if (i != totalMessages - 1) {
            consumer.acknowledge(msg);
        }
    }
    for (int i = 0; i < 5; i++) {
        int redeliveryCount = i + 1;
        int redeliveryTime = (int) Math.min(minDelayMs * (int) Math.pow(multiplier, i), maxDelayMs);
        assertEquals(consumer.getUnAckedMessageTracker().size(), 1);
        long startTime = System.currentTimeMillis();
        Message<byte[]> msg = consumer.receive();
        assertTrue(System.currentTimeMillis() - startTime >= ackTimeOutMillis + redeliveryTime);
        assertEquals(msg.getRedeliveryCount(), redeliveryCount);
        assertEquals(consumer.getUnAckedMessageTracker().size(), 1);
    }
}

@Test
public void testSingleMessageBatch() throws Exception {
    String topicName = "prop/ns-abc/topic-estSingleMessageBatch";
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(topicName).enableBatching(true).batchingMaxPublishDelay(10, TimeUnit.SECONDS).create();
    Consumer<String> consumer = pulsarClient.newConsumer(Schema.STRING).topic(topicName).subscriptionName("subscription").ackTimeout(1, TimeUnit.HOURS).subscribe();
    // Force the creation of a batch with a single message
    producer.sendAsync("hello");
    producer.flush();
    Message<String> message = consumer.receive();
    assertFalse(((ConsumerImpl<?>) consumer).getUnAckedMessageTracker().isEmpty());
    consumer.acknowledge(message);
    assertTrue(((ConsumerImpl<?>) consumer).getUnAckedMessageTracker().isEmpty());
    // Test ackTimeoutRedeliveryBackoff
    consumer.close();
    consumer = pulsarClient.newConsumer(Schema.STRING).topic(topicName).subscriptionName("subscription").ackTimeout(1, TimeUnit.HOURS).ackTimeoutRedeliveryBackoff(MultiplierRedeliveryBackoff.builder().minDelayMs(1000).maxDelayMs(60000).build()).subscribe();
    // Force the creation of a batch with a single message
    producer.sendAsync("hello");
    producer.flush();
    message = consumer.receive();
    assertFalse(((ConsumerImpl<?>) consumer).getUnAckedMessageTracker().isEmpty());
    consumer.acknowledge(message);
    assertTrue(((ConsumerImpl<?>) consumer).getUnAckedMessageTracker().isEmpty());
}

