@Test
public void testConsumerMetrics() throws Exception {
    String topic = newTopicName();
    PulsarClient client = PulsarClient.builder().serviceUrl(pulsar.getBrokerServiceUrl()).openTelemetry(otel).build();
    @Cleanup
    Producer<String> producer = client.newProducer(Schema.STRING).topic(topic).create();
    Consumer<String> consumer = client.newConsumer(Schema.STRING).topic(topic).subscriptionName("my-sub").ackTimeout(1, TimeUnit.SECONDS).subscriptionType(SubscriptionType.Shared).subscribe();
    for (int i = 0; i < 10; i++) {
        producer.send("Hello");
    }
    Thread.sleep(1000);
    Attributes nsAttrs = Attributes.builder().put("pulsar.tenant", "my-property").put("pulsar.namespace", "my-property/my-ns").put("pulsar.subscription", "my-sub").build();
    var metrics = collectMetrics();
    assertCounterValue(metrics, "pulsar.client.connection.opened", 1, Attributes.empty());
    assertHistoCountValue(metrics, "pulsar.client.lookup.duration", 2, Attributes.builder().put("pulsar.lookup.transport-type", "binary").put("pulsar.lookup.type", "topic").put("pulsar.response.status", "success").build());
    assertHistoCountValue(metrics, "pulsar.client.lookup.duration", 2, Attributes.builder().put("pulsar.lookup.transport-type", "binary").put("pulsar.lookup.type", "metadata").put("pulsar.response.status", "success").build());
    assertCounterValue(metrics, "pulsar.client.consumer.receive_queue.count", 10, nsAttrs);
    assertCounterValue(metrics, "pulsar.client.consumer.receive_queue.size", "hello".length() * 10, nsAttrs);
    assertCounterValue(metrics, "pulsar.client.consumer.opened", 1, nsAttrs);
    Message<String> msg1 = consumer.receive();
    consumer.acknowledge(msg1);
    Message<String> msg2 = consumer.receive();
    consumer.negativeAcknowledge(msg2);
    /* Message<String> msg3 = */
    consumer.receive();
    metrics = collectMetrics();
    assertCounterValue(metrics, "pulsar.client.consumer.receive_queue.count", 7, nsAttrs);
    assertCounterValue(metrics, "pulsar.client.consumer.receive_queue.size", "hello".length() * 7, nsAttrs);
    assertCounterValue(metrics, "pulsar.client.consumer.message.received.count", 3, nsAttrs);
    assertCounterValue(metrics, "pulsar.client.consumer.message.received.size", "hello".length() * 3, nsAttrs);
    // Let msg3 to reach ack-timeout
    Thread.sleep(3000);
    metrics = collectMetrics();
    assertCounterValue(metrics, "pulsar.client.consumer.receive_queue.count", 8, nsAttrs);
    assertCounterValue(metrics, "pulsar.client.consumer.receive_queue.size", "hello".length() * 8, nsAttrs);
    assertCounterValue(metrics, "pulsar.client.consumer.message.ack", 1, nsAttrs);
    assertCounterValue(metrics, "pulsar.client.consumer.message.nack", 1, nsAttrs);
    assertCounterValue(metrics, "pulsar.client.consumer.message.ack.timeout", 1, nsAttrs);
    client.close();
    metrics = collectMetrics();
    assertCounterValue(metrics, "pulsar.client.consumer.closed", 1, nsAttrs);
    assertCounterValue(metrics, "pulsar.client.connection.closed", 1, Attributes.empty());
}

@Test(dataProvider = "config")
public void testDefaultProcessor(int numPartitions, boolean enableBatching, int batchingMaxMessages) throws Exception {
    final String topic = "testDefaultProcessor-" + numPartitions + "-" + enableBatching + "-" + batchingMaxMessages;
    final int numMessages = 10;
    final String messagePrefix = "msg-";
    if (numPartitions > 1) {
        admin.topics().createPartitionedTopic(topic, numPartitions);
    }
    @Cleanup
    final Producer<String> producer = pulsarClient.newProducer(Schema.STRING).topic(topic).enableBatching(enableBatching).batchingMaxMessages(batchingMaxMessages).batchingMaxPublishDelay(100, TimeUnit.MILLISECONDS).messageRouter(new MessageRouter() {

        int i = 0;

        @Override
        public int choosePartition(Message<?> msg, TopicMetadata metadata) {
            return i++ % metadata.numPartitions();
        }
    }).create();
    for (int i = 0; i < numMessages; i++) {
        final String value = messagePrefix + i;
        producer.sendAsync(value).whenComplete((id, e) -> {
            if (e == null) {
                log.info("Send {} to {} {}", value, topic, id);
            } else {
                log.error("Failed to send {}: {}", value, e.getMessage());
            }
        });
    }
    final DefaultProcessorWithRefCnt processor = new DefaultProcessorWithRefCnt();
    @Cleanup
    final Consumer<String> consumer = pulsarClient.newConsumer(Schema.STRING).topic(topic).subscriptionName("sub").subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).messagePayloadProcessor(processor).subscribe();
    final List<String> values = new ArrayList<>();
    for (int i = 0; i < numMessages; i++) {
        final Message<String> message = consumer.receive(1, TimeUnit.SECONDS);
        Assert.assertNotNull(message);
        values.add(message.getValue());
        consumer.acknowledge(message.getMessageId());
    }
    if (numPartitions > 1) {
        // messages are out of order across multiple partitions
        Collections.sort(values);
    }
    for (int i = 0; i < numMessages; i++) {
        Assert.assertEquals(values.get(i), messagePrefix + i);
    }
    // Each buffer's refCnt is 2 because after retrieving the refCnt, there will be two release for the ByteBuf:
    // 1. ConsumerImpl#processPayloadByProcessor
    // 2. PulsarDecoder#channelRead
    if (enableBatching) {
        int numBatches = numMessages / batchingMaxMessages;
        numBatches += (numMessages % batchingMaxMessages == 0) ? 0 : 1;
        Assert.assertEquals(processor.getTotalRefCnt(), 2 * numBatches);
    } else {
        Assert.assertEquals(processor.getTotalRefCnt(), 2 * numMessages);
    }
}

@Test
public void testCustomBatchFormat() {
    final List<List<String>> inputs = new ArrayList<>();
    inputs.add(Collections.emptyList());
    inputs.add(Collections.singletonList("java"));
    inputs.add(Arrays.asList("hello", "world", "java"));
    for (List<String> input : inputs) {
        final ByteBuf buf = CustomBatchFormat.serialize(input);
        final CustomBatchFormat.Metadata metadata = CustomBatchFormat.readMetadata(buf);
        final List<String> parsedTokens = new ArrayList<>();
        for (int i = 0; i < metadata.getNumMessages(); i++) {
            parsedTokens.add(Schema.STRING.decode(CustomBatchFormat.readMessage(buf)));
        }
        Assert.assertEquals(parsedTokens, input);
        Assert.assertEquals(parsedTokens.size(), input.size());
        Assert.assertEquals(buf.refCnt(), 1);
        buf.release();
    }
}

