/**
 * Why should we check the recursion number of "findStartPointLoop", see: #17976
 */
@Test
public void testRecursionNumberOfFindStartPointLoop() {
    AtomicLong bingoMarker = new AtomicLong();
    long start = 0;
    long end = 100;
    long targetMessageId = 1;
    // Mock cache.
    AsyncLoadingCache<Long, MessageIdData> cache = Caffeine.newBuilder().buildAsync(mockCacheLoader(start, end, targetMessageId, bingoMarker));
    AtomicInteger invokeCounterOfCacheGet = new AtomicInteger();
    AsyncLoadingCache<Long, MessageIdData> cacheWithCounter = spy(cache);
    doAnswer(invocation -> {
        invokeCounterOfCacheGet.incrementAndGet();
        return cache.get((Long) invocation.getArguments()[0]);
    }).when(cacheWithCounter).get(anyLong());
    // Because when "findStartPointLoop(...)" is executed, will trigger "cache.get()" three times, including
    // "cache.get(start)", "cache.get(mid)" and "cache.get(end)". Therefore, we can calculate the count of
    // executed "findStartPointLoop".
    Supplier<Integer> loopCounter = () -> invokeCounterOfCacheGet.get() / 3;
    // Do test.
    Position targetPosition = PositionFactory.create(DEFAULT_LEDGER_ID, targetMessageId);
    CompletableFuture<Long> promise = new CompletableFuture<>();
    CompactedTopicImpl.findStartPointLoop(targetPosition, start, end, promise, cacheWithCounter);
    // Do verify.
    promise.join();
    assertEquals(loopCounter.get().intValue(), 2);
}

@Test
public void testEntryLookup() throws Exception {
    @Cleanup
    BookKeeper bk = pulsar.getBookKeeperClientFactory().create(this.conf, null, null, Optional.empty(), null).get();
    Triple<Long, List<Pair<MessageIdData, Long>>, List<Pair<MessageIdData, Long>>> compactedLedgerData = buildCompactedLedger(bk, 500);
    List<Pair<MessageIdData, Long>> positions = compactedLedgerData.getMiddle();
    List<Pair<MessageIdData, Long>> idsInGaps = compactedLedgerData.getRight();
    LedgerHandle lh = bk.openLedger(compactedLedgerData.getLeft(), Compactor.COMPACTED_TOPIC_LEDGER_DIGEST_TYPE, Compactor.COMPACTED_TOPIC_LEDGER_PASSWORD);
    long lastEntryId = lh.getLastAddConfirmed();
    AsyncLoadingCache<Long, MessageIdData> cache = CompactedTopicImpl.createCache(lh, 50);
    MessageIdData firstPositionId = positions.get(0).getLeft();
    Pair<MessageIdData, Long> lastPosition = positions.get(positions.size() - 1);
    // check ids before and after ids in compacted ledger
    Assert.assertEquals(CompactedTopicImpl.findStartPoint(PositionFactory.create(0, 0), lastEntryId, cache).get(), Long.valueOf(0));
    Assert.assertEquals(CompactedTopicImpl.findStartPoint(PositionFactory.create(Long.MAX_VALUE, 0), lastEntryId, cache).get(), Long.valueOf(CompactedTopicImpl.NEWER_THAN_COMPACTED));
    // entry 0 is never in compacted ledger due to how we generate dummy
    Assert.assertEquals(CompactedTopicImpl.findStartPoint(PositionFactory.create(firstPositionId.getLedgerId(), 0), lastEntryId, cache).get(), Long.valueOf(0));
    // check next id after last id in compacted ledger
    Assert.assertEquals(CompactedTopicImpl.findStartPoint(PositionFactory.create(lastPosition.getLeft().getLedgerId(), lastPosition.getLeft().getEntryId() + 1), lastEntryId, cache).get(), Long.valueOf(CompactedTopicImpl.NEWER_THAN_COMPACTED));
    // shuffle to make cache work hard
    Collections.shuffle(positions, r);
    Collections.shuffle(idsInGaps, r);
    // Check ids we know are in compacted ledger
    for (Pair<MessageIdData, Long> p : positions) {
        Position pos = PositionFactory.create(p.getLeft().getLedgerId(), p.getLeft().getEntryId());
        Long got = CompactedTopicImpl.findStartPoint(pos, lastEntryId, cache).get();
        Assert.assertEquals(got, p.getRight());
    }
    // Check ids we know are in the gaps of the compacted ledger
    for (Pair<MessageIdData, Long> gap : idsInGaps) {
        Position pos = PositionFactory.create(gap.getLeft().getLedgerId(), gap.getLeft().getEntryId());
        Assert.assertEquals(CompactedTopicImpl.findStartPoint(pos, lastEntryId, cache).get(), gap.getRight());
    }
}

@Test
public void testCleanupOldCompactedTopicLedger() throws Exception {
    @Cleanup
    BookKeeper bk = pulsar.getBookKeeperClientFactory().create(this.conf, null, null, Optional.empty(), null).get();
    LedgerHandle oldCompactedLedger = bk.createLedger(1, 1, Compactor.COMPACTED_TOPIC_LEDGER_DIGEST_TYPE, Compactor.COMPACTED_TOPIC_LEDGER_PASSWORD);
    oldCompactedLedger.close();
    LedgerHandle newCompactedLedger = bk.createLedger(1, 1, Compactor.COMPACTED_TOPIC_LEDGER_DIGEST_TYPE, Compactor.COMPACTED_TOPIC_LEDGER_PASSWORD);
    newCompactedLedger.close();
    // set the compacted topic ledger
    CompactedTopicImpl compactedTopic = new CompactedTopicImpl(bk);
    compactedTopic.newCompactedLedger(PositionFactory.create(1, 2), oldCompactedLedger.getId()).get();
    // ensure both ledgers still exist, can be opened
    bk.openLedger(oldCompactedLedger.getId(), Compactor.COMPACTED_TOPIC_LEDGER_DIGEST_TYPE, Compactor.COMPACTED_TOPIC_LEDGER_PASSWORD).close();
    bk.openLedger(newCompactedLedger.getId(), Compactor.COMPACTED_TOPIC_LEDGER_DIGEST_TYPE, Compactor.COMPACTED_TOPIC_LEDGER_PASSWORD).close();
    // update the compacted topic ledger
    Position newHorizon = PositionFactory.create(1, 3);
    compactedTopic.newCompactedLedger(newHorizon, newCompactedLedger.getId()).get();
    // Make sure the old compacted ledger still exist after the new compacted ledger created.
    bk.openLedger(oldCompactedLedger.getId(), Compactor.COMPACTED_TOPIC_LEDGER_DIGEST_TYPE, Compactor.COMPACTED_TOPIC_LEDGER_PASSWORD).close();
    Assert.assertTrue(compactedTopic.getCompactedTopicContext().isPresent());
    Assert.assertEquals(compactedTopic.getCompactedTopicContext().get().getLedger().getId(), newCompactedLedger.getId());
    Assert.assertTrue(compactedTopic.getCompactionHorizon().isPresent());
    Assert.assertEquals(compactedTopic.getCompactionHorizon().get(), newHorizon);
    compactedTopic.deleteCompactedLedger(oldCompactedLedger.getId()).join();
    // old ledger should be deleted, new still there
    try {
        bk.openLedger(oldCompactedLedger.getId(), Compactor.COMPACTED_TOPIC_LEDGER_DIGEST_TYPE, Compactor.COMPACTED_TOPIC_LEDGER_PASSWORD).close();
        Assert.fail("Should have failed to open old ledger");
    } catch (BKException.BKNoSuchLedgerExistsException | BKException.BKNoSuchLedgerExistsOnMetadataServerException e) {
        // correct, expected behaviour
    }
    bk.openLedger(newCompactedLedger.getId(), Compactor.COMPACTED_TOPIC_LEDGER_DIGEST_TYPE, Compactor.COMPACTED_TOPIC_LEDGER_PASSWORD).close();
}

