    Mockito.doReturn(CompletableFuture.completedFuture(Collections.emptyList())).when(service).readCompactedEntries(Mockito.any(), Mockito.intThat(argument -> argument > 0));
    Mockito.doReturn(CompletableFuture.completedFuture(lastCompactedPosition)).when(service).getLastCompactedPosition();
