@Test
public void testEmptyPayloadDeletesWhenEncrypted() throws Exception {
    String topic = "persistent://my-property/use/my-ns/my-topic1";
    // subscribe before sending anything, so that we get all messages
    pulsarClient.newConsumer().topic(topic).subscriptionName("sub1").readCompacted(true).subscribe().close();
    try (Producer<byte[]> producerNormal = pulsarClient.newProducer().topic(topic).enableBatching(false).addEncryptionKey("client-ecdsa.pem").cryptoKeyReader(new EncKeyReader()).create();
        Producer<byte[]> producerBatch = pulsarClient.newProducer().topic(topic).maxPendingMessages(3).enableBatching(true).addEncryptionKey("client-ecdsa.pem").cryptoKeyReader(new EncKeyReader()).batchingMaxMessages(3).batchingMaxPublishDelay(1, TimeUnit.HOURS).create()) {
        // key0 persists through it all
        producerNormal.newMessage().key("key0").value("my-message-0".getBytes()).send();
        // key1 is added but then deleted
        producerNormal.newMessage().key("key1").value("my-message-1".getBytes()).send();
        producerNormal.newMessage().key("key1").send();
        // key2 is added but deleted in same batch
        producerBatch.newMessage().key("key2").value("my-message-2".getBytes()).sendAsync();
        producerBatch.newMessage().key("key3").value("my-message-3".getBytes()).sendAsync();
        producerBatch.newMessage().key("key2").send();
        // key4 is added, deleted, then resurrected
        producerNormal.newMessage().key("key4").value("my-message-4".getBytes()).send();
    }
    // compact the topic
    compact(topic, new EncKeyReader());
    try (Consumer<byte[]> consumer = pulsarClient.newConsumer().topic(topic).cryptoKeyReader(new EncKeyReader()).subscriptionName("sub1").readCompacted(true).subscribe()) {
        Message<byte[]> message1 = consumer.receive();
        Assert.assertEquals(message1.getKey(), "key0");
        Assert.assertEquals(new String(message1.getData()), "my-message-0");
        if (getCompactor() instanceof StrategicTwoPhaseCompactor) {
            Message<byte[]> message3 = consumer.receive();
            Assert.assertEquals(message3.getKey(), "key3");
            Assert.assertEquals(new String(message3.getData()), "my-message-3");
            Message<byte[]> message5 = consumer.receive();
            Assert.assertEquals(message5.getKey(), "key4");
            Assert.assertEquals(new String(message5.getData()), "my-message-4");
        } else {
            // see all messages from batch
            Message<byte[]> message2 = consumer.receive();
            Assert.assertEquals(message2.getKey(), "key2");
            Assert.assertEquals(new String(message2.getData()), "my-message-2");
            Message<byte[]> message3 = consumer.receive();
            Assert.assertEquals(message3.getKey(), "key3");
            Assert.assertEquals(new String(message3.getData()), "my-message-3");
            Message<byte[]> message4 = consumer.receive();
            Assert.assertEquals(message4.getKey(), "key2");
            Assert.assertEquals(new String(message4.getData()), "");
            Message<byte[]> message5 = consumer.receive();
            Assert.assertEquals(message5.getKey(), "key4");
            Assert.assertEquals(new String(message5.getData()), "my-message-4");
        }
    }
}

