@Test
public void testAcknowledgeWithReconnection() throws Exception {
    final String topicName = "persistent://my-property/use/my-ns/testAcknowledge" + UUID.randomUUID();
    final String subName = "my-sub";
    @Cleanup
    PulsarClient client = newPulsarClient(lookupUrl.toString(), 100);
    Producer<String> producer = pulsarClient.newProducer(Schema.STRING).enableBatching(false).topic(topicName).create();
    List<String> expected = new ArrayList<>();
    for (int i = 0; i < 10; i++) {
        producer.newMessage().key(String.valueOf(i)).value(String.valueOf(i)).send();
        expected.add(String.valueOf(i));
    }
    producer.flush();
    admin.topics().triggerCompaction(topicName);
    Awaitility.await().untilAsserted(() -> {
        assertEquals(admin.topics().compactionStatus(topicName).status, LongRunningProcessStatus.Status.SUCCESS);
    });
    // trim the topic
    admin.topics().unload(topicName);
    Awaitility.await().untilAsserted(() -> {
        PersistentTopicInternalStats internalStats = admin.topics().getInternalStats(topicName, false);
        assertEquals(internalStats.numberOfEntries, 0);
    });
    ConsumerImpl<String> consumer = (ConsumerImpl<String>) client.newConsumer(Schema.STRING).topic(topicName).readCompacted(true).receiverQueueSize(1).subscriptionName(subName).subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).isAckReceiptEnabled(true).subscribe();
    List<String> results = new ArrayList<>();
    for (int i = 0; i < 5; i++) {
        Message<String> message = consumer.receive(3, TimeUnit.SECONDS);
        if (message == null) {
            break;
        }
        results.add(message.getValue());
        consumer.acknowledge(message);
    }
    Awaitility.await().untilAsserted(() -> assertEquals(admin.topics().getStats(topicName, true).getSubscriptions().get(subName).getMsgBacklog(), 5));
    // Make consumer reconnect to broker
    admin.topics().unload(topicName);
    // Wait for consumer to reconnect and clear incomingMessages
    consumer.pause();
    Awaitility.await().untilAsserted(() -> {
        Assert.assertEquals(consumer.numMessagesInQueue(), 0);
    });
    consumer.resume();
    for (int i = 0; i < 5; i++) {
        Message<String> message = consumer.receive(3, TimeUnit.SECONDS);
        if (message == null) {
            break;
        }
        results.add(message.getValue());
        consumer.acknowledge(message);
    }
    Awaitility.await().untilAsserted(() -> assertEquals(admin.topics().getStats(topicName, true).getSubscriptions().get(subName).getMsgBacklog(), 0));
    Assert.assertEquals(results, expected);
    Message<String> message = consumer.receive(3, TimeUnit.SECONDS);
    Assert.assertNull(message);
    // Make consumer reconnect to broker
    admin.topics().unload(topicName);
    producer.newMessage().key("K").value("V").send();
    Message<String> message2 = consumer.receive(3, TimeUnit.SECONDS);
    Assert.assertEquals(message2.getValue(), "V");
    consumer.acknowledge(message2);
    Awaitility.await().untilAsserted(() -> {
        PersistentTopicInternalStats internalStats = admin.topics().getInternalStats(topicName);
        Assert.assertEquals(internalStats.lastConfirmedEntry, internalStats.cursors.get(subName).markDeletePosition);
    });
    consumer.close();
    producer.close();
}

