@Test
public void testCompactedWithConcurrentSend() throws Exception {
    String topic = "persistent://my-property/use/my-ns/testCompactedWithConcurrentSend";
    @Cleanup
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topic).enableBatching(false).messageRoutingMode(MessageRoutingMode.SinglePartition).create();
    var future = CompletableFuture.runAsync(() -> {
        for (int i = 0; i < 100; i++) {
            try {
                producer.newMessage().key(String.valueOf(i)).value(String.valueOf(i).getBytes()).send();
            } catch (PulsarClientException e) {
                throw new RuntimeException(e);
            }
        }
    });
    PersistentTopic persistentTopic = (PersistentTopic) pulsar.getBrokerService().getTopicReference(topic).get();
    PulsarTopicCompactionService topicCompactionService = (PulsarTopicCompactionService) persistentTopic.getTopicCompactionService();
    Awaitility.await().untilAsserted(() -> {
        long compactedLedgerId = compact(topic);
        Thread.sleep(300);
        Optional<CompactedTopicContext> compactedTopicContext = topicCompactionService.getCompactedTopic().getCompactedTopicContext();
        Assert.assertTrue(compactedTopicContext.isPresent());
        Assert.assertEquals(compactedTopicContext.get().ledger.getId(), compactedLedgerId);
    });
    Position lastCompactedPosition = topicCompactionService.getLastCompactedPosition().get();
    Entry lastCompactedEntry = topicCompactionService.readLastCompactedEntry().get();
    Assert.assertTrue(PositionFactory.create(lastCompactedPosition.getLedgerId(), lastCompactedPosition.getEntryId()).compareTo(lastCompactedEntry.getLedgerId(), lastCompactedEntry.getEntryId()) >= 0);
    future.join();
}

/**
 * Test broker-tool generate docs
 *
 * @throws Exception
 */
@Test
public void testGenerateDocs() throws Exception {
    PrintStream oldStream = System.out;
    try {
        ByteArrayOutputStream baoStream = new ByteArrayOutputStream();
        System.setOut(new PrintStream(baoStream));
        Class argumentsClass = Class.forName("org.apache.pulsar.compaction.CompactorTool$Arguments");
        Constructor constructor = argumentsClass.getDeclaredConstructor();
        constructor.setAccessible(true);
        Object obj = constructor.newInstance();
        CmdGenerateDocs cmd = new CmdGenerateDocs("pulsar");
        cmd.addCommand("compact-topic", obj);
        cmd.run(null);
        String message = baoStream.toString();
        Field[] fields = argumentsClass.getDeclaredFields();
        for (Field field : fields) {
            boolean fieldHasAnno = field.isAnnotationPresent(Option.class);
            if (fieldHasAnno) {
                Option fieldAnno = field.getAnnotation(Option.class);
                String[] names = fieldAnno.names();
                String nameStr = Arrays.asList(names).toString();
                nameStr = nameStr.substring(1, nameStr.length() - 1);
                assertTrue(message.indexOf(nameStr) > 0);
            }
        }
    } finally {
        System.setOut(oldStream);
    }
}

