@Test(timeOut = 20000)
public void testSameBatchCompactToSameBatch() throws Exception {
    final String topic = "persistent://my-property/use/my-ns/testSameBatchCompactToSameBatch" + UUID.randomUUID();
    // Use odd number to make sure the last message is flush by `reader.hasNext() == false`.
    final int messages = 11;
    // 1.create producer and publish message to the topic.
    ProducerBuilder<Integer> builder = pulsarClient.newProducer(Schema.INT32).compressionType(MSG_COMPRESSION_TYPE).topic(topic);
    builder.batchingMaxMessages(2).batchingMaxPublishDelay(10, TimeUnit.MILLISECONDS);
    Producer<Integer> producer = builder.create();
    List<CompletableFuture<MessageId>> futures = new ArrayList<>(messages);
    for (int i = 0; i < messages; i++) {
        futures.add(producer.newMessage().key(String.valueOf(i)).value(i).sendAsync());
    }
    FutureUtil.waitForAll(futures).get();
    // 2.compact the topic.
    StrategicTwoPhaseCompactor compactor = new StrategicTwoPhaseCompactor(conf, pulsarClient, bk, compactionScheduler);
    compactor.compact(topic, strategy).get();
    // consumer with readCompacted enabled only get compacted entries
    try (Consumer<Integer> consumer = pulsarClient.newConsumer(Schema.INT32).topic(topic).subscriptionName("sub1").readCompacted(true).subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).subscribe()) {
        int received = 0;
        while (true) {
            Message<Integer> m = consumer.receive(2, TimeUnit.SECONDS);
            if (m == null) {
                break;
            }
            MessageIdAdv messageId = (MessageIdAdv) m.getMessageId();
            if (received < messages - 1) {
                assertEquals(messageId.getBatchSize(), 2);
            } else {
                assertEquals(messageId.getBatchSize(), 0);
            }
            received++;
        }
        assertEquals(received, messages);
    }
}

@Test
public void test() throws Exception {
    String topic = "persistent://prop-xyz/ns1/my-topic";
    PulsarTopicCompactionService service = new PulsarTopicCompactionService(topic, bk, () -> compactor);
    @Cleanup
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topic).enableBatching(false).messageRoutingMode(MessageRoutingMode.SinglePartition).create();
    producer.newMessage().key("c").value("C_0".getBytes()).send();
    conf.setBrokerEntryMetadataInterceptors(org.assertj.core.util.Sets.newTreeSet("org.apache.pulsar.common.intercept.AppendIndexMetadataInterceptor"));
    restartBroker();
    long startTime = System.currentTimeMillis();
    producer.newMessage().key("a").value("A_1".getBytes()).send();
    producer.newMessage().key("b").value("B_1".getBytes()).send();
    producer.newMessage().key("a").value("A_2".getBytes()).send();
    producer.newMessage().key("b").value("B_2".getBytes()).send();
    producer.newMessage().key("b").value("B_3".getBytes()).send();
    producer.flush();
    service.compact().join();
    CompactedTopicImpl compactedTopic = service.getCompactedTopic();
    Long compactedLedger = admin.topics().getInternalStats(topic).cursors.get(COMPACTION_SUBSCRIPTION).properties.get(COMPACTED_TOPIC_LEDGER_PROPERTY);
    String markDeletePosition = admin.topics().getInternalStats(topic).cursors.get(COMPACTION_SUBSCRIPTION).markDeletePosition;
    String[] split = markDeletePosition.split(":");
    compactedTopic.newCompactedLedger(PositionFactory.create(Long.valueOf(split[0]), Long.valueOf(split[1])), compactedLedger).join();
    Position lastCompactedPosition = service.getLastCompactedPosition().join();
    assertEquals(admin.topics().getInternalStats(topic).lastConfirmedEntry, lastCompactedPosition.toString());
    List<Entry> entries = service.readCompactedEntries(PositionFactory.EARLIEST, 4).join();
    assertEquals(entries.size(), 3);
    entries.stream().map(e -> {
        try {
            return MessageImpl.deserialize(e.getDataBuffer());
        } catch (IOException ex) {
            throw new RuntimeException(ex);
        }
    }).forEach(message -> {
        String data = new String(message.getData());
        if (Objects.equals(message.getKey(), "a")) {
            assertEquals(data, "A_2");
        } else if (Objects.equals(message.getKey(), "b")) {
            assertEquals(data, "B_3");
        } else if (Objects.equals(message.getKey(), "c")) {
            assertEquals(data, "C_0");
        } else {
            fail();
        }
    });
    List<Entry> entries2 = service.readCompactedEntries(PositionFactory.EARLIEST, 1).join();
    assertEquals(entries2.size(), 1);
    Entry entry = service.findEntryByEntryIndex(0).join();
    BrokerEntryMetadata brokerEntryMetadata = Commands.peekBrokerEntryMetadataIfExist(entry.getDataBuffer());
    assertNotNull(brokerEntryMetadata);
    assertEquals(brokerEntryMetadata.getIndex(), 2);
    MessageMetadata metadata = Commands.parseMessageMetadata(entry.getDataBuffer());
    assertEquals(metadata.getPartitionKey(), "a");
    entry.release();
    entry = service.findEntryByEntryIndex(3).join();
    brokerEntryMetadata = Commands.peekBrokerEntryMetadataIfExist(entry.getDataBuffer());
    assertNotNull(brokerEntryMetadata);
    assertEquals(brokerEntryMetadata.getIndex(), 4);
    metadata = Commands.parseMessageMetadata(entry.getDataBuffer());
    assertEquals(metadata.getPartitionKey(), "b");
    entry.release();
    entry = service.findEntryByPublishTime(startTime).join();
    brokerEntryMetadata = Commands.peekBrokerEntryMetadataIfExist(entry.getDataBuffer());
    assertNotNull(brokerEntryMetadata);
    assertEquals(brokerEntryMetadata.getIndex(), 2);
    metadata = Commands.parseMessageMetadata(entry.getDataBuffer());
    assertEquals(metadata.getPartitionKey(), "a");
    entry.release();
}

