@Test
public void testSetAlwaysInCompatibleStrategyOnTopicLevelAndCheckAlwaysInCompatible() throws PulsarClientException, PulsarServerException, PulsarAdminException {
    String topicName = TopicName.get(TopicDomain.persistent.value(), PUBLIC_TENANT, namespace, "testSetAlwaysInCompatibleStrategyOnTopicLevelAndCheckAlwaysInCompatible").toString();
    pulsar.getAdminClient().topics().createNonPartitionedTopic(topicName);
    pulsar.getAdminClient().topicPolicies().setSchemaCompatibilityStrategy(topicName, SchemaCompatibilityStrategy.ALWAYS_INCOMPATIBLE);
    Awaitility.await().untilAsserted(() -> assertEquals(pulsar.getAdminClient().topicPolicies().getSchemaCompatibilityStrategy(topicName, true), SchemaCompatibilityStrategy.ALWAYS_INCOMPATIBLE));
    pulsarClient.newProducer(Schema.AVRO(SchemaDefinition.<Schemas.PersonOne>builder().withAlwaysAllowNull(true).withPojo(Schemas.PersonOne.class).build())).topic(topicName).create();
    ProducerBuilder<Schemas.PersonThree> producerBuilder = pulsarClient.newProducer(Schema.AVRO(SchemaDefinition.<Schemas.PersonThree>builder().withAlwaysAllowNull(true).withPojo(Schemas.PersonThree.class).build())).topic(topicName);
    Throwable t = expectThrows(PulsarClientException.IncompatibleSchemaException.class, producerBuilder::create);
    assertTrue(t.getMessage().contains("org.apache.avro.SchemaValidationException: Unable to read schema"));
}

@Test
public void testSetAlwaysCompatibleOnNamespaceLevelAndCheckAlwaysInCompatible() throws PulsarClientException, PulsarServerException, PulsarAdminException {
    admin.namespaces().setSchemaCompatibilityStrategy(namespaceName, SchemaCompatibilityStrategy.ALWAYS_COMPATIBLE);
    String topicName = TopicName.get(TopicDomain.persistent.value(), PUBLIC_TENANT, namespace, "testSetAlwaysCompatibleOnNamespaceLevelAndCheckAlwaysInCompatible").toString();
    pulsar.getAdminClient().topics().createNonPartitionedTopic(topicName);
