@Test
public void testUpdateSchemaCompatibilityStrategyRepeatedly() throws PulsarClientException, PulsarServerException, PulsarAdminException {
    assertEquals(conf.getSchemaCompatibilityStrategy(), SchemaCompatibilityStrategy.FULL);
    String topicName = TopicName.get(TopicDomain.persistent.value(), PUBLIC_TENANT, namespace, "testUpdateSchemaCompatibilityStrategyRepeatedly").toString();
    pulsar.getAdminClient().topics().createNonPartitionedTopic(topicName);
    Awaitility.await().untilAsserted(() -> assertEquals(admin.topicPolicies().getSchemaCompatibilityStrategy(topicName, true), SchemaCompatibilityStrategy.FULL));
    Awaitility.await().untilAsserted(() -> assertNull(admin.namespaces().getSchemaAutoUpdateCompatibilityStrategy(namespaceName)));
    Awaitility.await().untilAsserted(() -> assertEquals(admin.namespaces().getSchemaCompatibilityStrategy(namespaceName), SchemaCompatibilityStrategy.UNDEFINED));
    pulsarClient.newProducer(Schema.AVRO(SchemaDefinition.<Schemas.PersonOne>builder().withAlwaysAllowNull(true).withPojo(Schemas.PersonOne.class).build())).topic(topicName).create();
    // Set SchemaCompatibilityStrategy.ALWAYS_INCOMPATIBLE to schema_auto_update_compatibility_strategy on
    // namespace level.
    admin.namespaces().setSchemaAutoUpdateCompatibilityStrategy(namespaceName, SchemaAutoUpdateCompatibilityStrategy.AutoUpdateDisabled);
    Awaitility.await().untilAsserted(() -> assertEquals(admin.namespaces().getSchemaAutoUpdateCompatibilityStrategy(namespaceName), SchemaAutoUpdateCompatibilityStrategy.AutoUpdateDisabled));
    Awaitility.await().untilAsserted(() -> assertEquals(admin.namespaces().getSchemaCompatibilityStrategy(namespaceName), SchemaCompatibilityStrategy.UNDEFINED));
    Awaitility.await().untilAsserted(() -> assertEquals(admin.topicPolicies().getSchemaCompatibilityStrategy(topicName, true), SchemaCompatibilityStrategy.ALWAYS_INCOMPATIBLE));
    ProducerBuilder<Schemas.PersonThree> producerBuilder = pulsarClient.newProducer(Schema.AVRO(SchemaDefinition.<Schemas.PersonThree>builder().withAlwaysAllowNull(true).withPojo(Schemas.PersonThree.class).build())).topic(topicName);
    Throwable t = expectThrows(PulsarClientException.IncompatibleSchemaException.class, producerBuilder::create);
    assertTrue(t.getMessage().contains("org.apache.avro.SchemaValidationException: Unable to read schema"));
    // Set SchemaCompatibilityStrategy.ALWAYS_COMPATIBLE to schema_compatibility_strategy on namespace level.
    admin.namespaces().setSchemaCompatibilityStrategy(namespaceName, SchemaCompatibilityStrategy.ALWAYS_COMPATIBLE);
    Awaitility.await().untilAsserted(() -> assertEquals(admin.namespaces().getSchemaAutoUpdateCompatibilityStrategy(namespaceName), SchemaAutoUpdateCompatibilityStrategy.AutoUpdateDisabled));
    Awaitility.await().untilAsserted(() -> assertEquals(admin.namespaces().getSchemaCompatibilityStrategy(namespaceName), SchemaCompatibilityStrategy.ALWAYS_COMPATIBLE));
    Awaitility.await().untilAsserted(() -> assertEquals(admin.topicPolicies().getSchemaCompatibilityStrategy(topicName, true), SchemaCompatibilityStrategy.ALWAYS_COMPATIBLE));
    pulsarClient.newProducer(Schema.AVRO(SchemaDefinition.<Schemas.PersonOne>builder().withAlwaysAllowNull(true).withPojo(Schemas.PersonOne.class).build())).topic(topicName).create();
    // Set SchemaCompatibilityStrategy.ALWAYS_INCOMPATIBLE on topic level.
    admin.topicPolicies().setSchemaCompatibilityStrategy(topicName, SchemaCompatibilityStrategy.ALWAYS_INCOMPATIBLE);
    Awaitility.await().untilAsserted(() -> assertEquals(admin.topicPolicies().getSchemaCompatibilityStrategy(topicName, true), SchemaCompatibilityStrategy.ALWAYS_INCOMPATIBLE));
    producerBuilder = pulsarClient.newProducer(Schema.AVRO(SchemaDefinition.<Schemas.PersonThree>builder().withAlwaysAllowNull(true).withPojo(Schemas.PersonThree.class).build())).topic(topicName);
    t = expectThrows(PulsarClientException.IncompatibleSchemaException.class, producerBuilder::create);
    assertTrue(t.getMessage().contains("org.apache.avro.SchemaValidationException: Unable to read schema"));
    // Remove schema compatibility strategy on topic level.
    admin.topicPolicies().removeSchemaCompatibilityStrategy(topicName);
    Awaitility.await().untilAsserted(() -> assertEquals(admin.topicPolicies().getSchemaCompatibilityStrategy(topicName, true), SchemaCompatibilityStrategy.ALWAYS_COMPATIBLE));
    pulsarClient.newProducer(Schema.AVRO(SchemaDefinition.<Schemas.PersonOne>builder().withAlwaysAllowNull(true).withPojo(Schemas.PersonOne.class).build())).topic(topicName).create();
    // Remove schema_compatibility_strategy on namespace level.
    admin.namespaces().setSchemaCompatibilityStrategy(namespaceName, SchemaCompatibilityStrategy.UNDEFINED);
    Awaitility.await().untilAsserted(() -> assertEquals(admin.namespaces().getSchemaCompatibilityStrategy(namespaceName), SchemaCompatibilityStrategy.UNDEFINED));
    Awaitility.await().untilAsserted(() -> assertEquals(admin.topicPolicies().getSchemaCompatibilityStrategy(topicName, true), SchemaCompatibilityStrategy.ALWAYS_INCOMPATIBLE));
    producerBuilder = pulsarClient.newProducer(Schema.AVRO(SchemaDefinition.<Schemas.PersonThree>builder().withAlwaysAllowNull(true).withPojo(Schemas.PersonThree.class).build())).topic(topicName);
    t = expectThrows(PulsarClientException.IncompatibleSchemaException.class, producerBuilder::create);
    assertTrue(t.getMessage().contains("org.apache.avro.SchemaValidationException: Unable to read schema"));
}

