@Test
public void testAlwaysCompatible() throws Exception {
    admin.namespaces().setSchemaCompatibilityStrategy(namespaceName, SchemaCompatibilityStrategy.ALWAYS_COMPATIBLE);
    final String topicName = TopicName.get(TopicDomain.persistent.value(), PUBLIC_TENANT, namespace, "testAlwaysCompatible" + UUID.randomUUID().toString()).toString();
    Schema<?>[] schemas = new Schema[] { Schema.AVRO(Schemas.PersonOne.class), Schema.AVRO(Schemas.PersonFour.class), Schema.JSON(Schemas.PersonOne.class), Schema.JSON(Schemas.PersonFour.class), Schema.INT8, Schema.INT16, Schema.INT32, Schema.INT64, Schema.DATE, Schema.BOOL, Schema.DOUBLE, Schema.STRING, Schema.BYTES, Schema.FLOAT, Schema.INSTANT, Schema.BYTEBUFFER, Schema.TIME, Schema.TIMESTAMP, Schema.LOCAL_DATE, Schema.LOCAL_DATE_TIME, Schema.LOCAL_TIME };
    for (Schema<?> schema : schemas) {
        Producer<?> p = pulsarClient.newProducer(schema).topic(topicName).create();
        p.close();
    }
    for (Schema<?> schema : schemas) {
        Consumer<?> c = pulsarClient.newConsumer(schema).topic(topicName).subscriptionName(UUID.randomUUID().toString()).subscribe();
        c.close();
    }
    List<SchemaInfo> schemasOfTopic = admin.schemas().getAllSchemas(topicName);
    // bytes[] schema and bytebuffer schema does not upload schema info to the schema registry
    assertEquals(schemasOfTopic.size(), schemas.length - 2);
    // Try to upload the schema again.
    for (Schema<?> schema : schemas) {
        Producer<?> p = pulsarClient.newProducer(schema).topic(topicName).create();
        p.close();
    }
    assertEquals(schemasOfTopic.size(), schemas.length - 2);
}

