public void test() throws Exception {
    Consumer<GenericRecord> consumer = pulsarClient.newConsumer(Schema.AUTO_CONSUME()).topic(PARTITIONED_TOPIC).subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).subscriptionName("test").subscribe();
    consumer.close();
    @Cleanup
    Producer<Schemas.PersonFour> producer = pulsarClient.newProducer(Schema.JSON(Schemas.PersonFour.class)).topic(PARTITIONED_TOPIC).enableBatching(false).roundRobinRouterBatchingPartitionSwitchFrequency(1).create();
