    consumer = pulsarClient.newConsumer(Schema.AUTO_CONSUME()).topic(TopicName.get(PARTITIONED_TOPIC).getPartition(1).toString()).subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).subscriptionName("test").subscribe();
