@Test
public void testMultiTopicSetSchemaProvider() throws Exception {
    final String tenant = PUBLIC_TENANT;
    final String namespace = "test-namespace-" + randomName(16);
    final String topicOne = "test-multi-version-schema-one";
    final String topicTwo = "test-multi-version-schema-two";
    final String fqtnOne = TopicName.get(TopicDomain.persistent.value(), tenant, namespace, topicOne).toString();
    final String fqtnTwo = TopicName.get(TopicDomain.persistent.value(), tenant, namespace, topicTwo).toString();
    admin.namespaces().createNamespace(tenant + "/" + namespace, Sets.newHashSet(CLUSTER_NAME));
    admin.topics().createPartitionedTopic(fqtnOne, 3);
    admin.topics().createPartitionedTopic(fqtnTwo, 3);
    admin.schemas().createSchema(fqtnOne, Schema.AVRO(SchemaDefinition.<Schemas.PersonOne>builder().withAlwaysAllowNull(false).withSupportSchemaVersioning(true).withPojo(Schemas.PersonOne.class).build()).getSchemaInfo());
    admin.schemas().createSchema(fqtnOne, Schema.AVRO(SchemaDefinition.<Schemas.PersonTwo>builder().withAlwaysAllowNull(false).withSupportSchemaVersioning(true).withPojo(Schemas.PersonTwo.class).build()).getSchemaInfo());
    Schema<Schemas.PersonTwo> personTwoSchema = Schema.AVRO(SchemaDefinition.<Schemas.PersonTwo>builder().withAlwaysAllowNull(false).withSupportSchemaVersioning(true).withPojo(Schemas.PersonTwo.class).build());
    admin.schemas().createSchema(fqtnTwo, personTwoSchema.getSchemaInfo());
    Producer<Schemas.PersonTwo> producer = pulsarClient.newProducer(Schema.AVRO(SchemaDefinition.<Schemas.PersonTwo>builder().withAlwaysAllowNull(false).withSupportSchemaVersioning(true).withPojo(Schemas.PersonTwo.class).build())).topic(fqtnOne).create();
    Schemas.PersonTwo personTwo = new Schemas.PersonTwo();
    personTwo.setId(1);
    personTwo.setName("Tom");
    Consumer<Schemas.PersonTwo> consumer = pulsarClient.newConsumer(Schema.AVRO(SchemaDefinition.<Schemas.PersonTwo>builder().withAlwaysAllowNull(false).withSupportSchemaVersioning(true).withPojo(Schemas.PersonTwo.class).build())).subscriptionName("test").topic(fqtnOne, fqtnTwo).subscribe();
    Consumer<GenericRecord> consumer2 = pulsarClient.newConsumer(Schema.AUTO_CONSUME()).subscriptionName("test2").topic(fqtnOne, fqtnTwo).subscribe();
    producer.send(personTwo);
    Message<Schemas.PersonTwo> message = consumer.receive();
    Schemas.PersonTwo personConsume = message.getValue();
    assertEquals(personConsume.getName(), "Tom");
    assertEquals(personConsume.getId(), 1);
    Schema<?> schema = message.getReaderSchema().get();
    log.info("the-schema {}", schema);
    assertEquals(personTwoSchema.getSchemaInfo(), schema.getSchemaInfo());
    org.apache.avro.Schema nativeSchema = (org.apache.avro.Schema) schema.getNativeSchema().get();
    log.info("nativeSchema-schema {}", nativeSchema);
    assertNotNull(nativeSchema);
    // verify that with AUTO_CONSUME we can access the original schema
    // and the Native AVRO schema
    Message<?> message2 = consumer2.receive();
    Schema<?> schema2 = message2.getReaderSchema().get();
    log.info("the-schema {}", schema2);
    assertEquals(personTwoSchema.getSchemaInfo(), schema2.getSchemaInfo());
    org.apache.avro.Schema nativeSchema2 = (org.apache.avro.Schema) schema.getNativeSchema().get();
    log.info("nativeSchema-schema {}", nativeSchema2);
    assertNotNull(nativeSchema2);
    producer.close();
    consumer.close();
}

