    admin.topics().delete(topic1, true);
    assertEquals(this.getPulsar().getSchemaRegistryService().trimDeletedSchemaAndGetList(TopicName.get(topic1).getSchemaName()).get().size(), 0);
    admin.topics().deletePartitionedTopic(topic2, true);
    assertEquals(this.getPulsar().getSchemaRegistryService().trimDeletedSchemaAndGetList(TopicName.get(topic2).getSchemaName()).get().size(), 0);
}

