    List<CompletableFuture<SchemaRegistry.SchemaAndMetadata>> schemaFutures2 = this.getPulsar().getSchemaRegistryService().getAllSchemas(TopicName.get(topicTwo).getSchemaName()).get();
    FutureUtil.waitForAll(schemaFutures2).get();
