@Test
public void testCreateSchemaInParallel() throws Exception {
    final String namespace = "test-namespace-" + randomName(16);
    String ns = PUBLIC_TENANT + "/" + namespace;
    admin.namespaces().createNamespace(ns, Sets.newHashSet(CLUSTER_NAME));
    final String topic = getTopicName(ns, "testCreateSchemaInParallel");
    @Cleanup("shutdownNow")
    ExecutorService executor = Executors.newFixedThreadPool(16);
    List<CompletableFuture<Producer<Schemas.PersonOne>>> producers = new ArrayList<>(16);
    CountDownLatch latch = new CountDownLatch(16);
    for (int i = 0; i < 16; i++) {
        executor.execute(() -> {
            producers.add(pulsarClient.newProducer(Schema.AVRO(Schemas.PersonOne.class)).topic(topic).createAsync());
            latch.countDown();
        });
    }
    latch.await();
    FutureUtil.waitForAll(producers).join();
    assertEquals(admin.schemas().getAllSchemas(topic).size(), 1);
    producers.clear();
    List<CompletableFuture<Producer<Schemas.PersonThree>>> producers2 = new ArrayList<>(16);
    CountDownLatch latch2 = new CountDownLatch(16);
    for (int i = 0; i < 16; i++) {
        executor.execute(() -> {
            producers2.add(pulsarClient.newProducer(Schema.AVRO(Schemas.PersonThree.class)).topic(topic).createAsync());
            latch2.countDown();
        });
    }
    latch2.await();
    FutureUtil.waitForAll(producers2).join();
    assertEquals(admin.schemas().getAllSchemas(topic).size(), 2);
    producers.forEach(p -> {
        try {
            p.join().close();
        } catch (Exception ignore) {
        }
    });
    producers2.forEach(p -> {
        try {
            p.join().close();
        } catch (Exception ignore) {
        }
    });
    producers.clear();
    producers2.clear();
}

/**
 * This test validates that consumer/producers should recover on topic whose
 * schema ledgers are not able to open due to non-recoverable error.
 *
 * @throws Exception
 */
@Test
public void testDeletedSchemaLedgerRecovery() throws Exception {
    final String tenant = PUBLIC_TENANT;
    final String namespace = "test-namespace-" + randomName(16);
    final String topicOne = "test-multi-version-schema-one";
    final String subName = "test";
    final String topicName = TopicName.get(TopicDomain.persistent.value(), tenant, namespace, topicOne).toString();
    admin.namespaces().createNamespace(tenant + "/" + namespace, Sets.newHashSet(CLUSTER_NAME));
    // (1) create schema
    Producer<Schemas.PersonTwo> producer = pulsarClient.newProducer(Schema.AVRO(SchemaDefinition.<Schemas.PersonTwo>builder().withAlwaysAllowNull(false).withSupportSchemaVersioning(true).withPojo(Schemas.PersonTwo.class).build())).topic(topicName).create();
    Schemas.PersonTwo personTwo = new Schemas.PersonTwo();
    personTwo.setId(1);
    personTwo.setName("Tom");
    Consumer<Schemas.PersonTwo> consumer = pulsarClient.newConsumer(Schema.AVRO(SchemaDefinition.<Schemas.PersonTwo>builder().withAlwaysAllowNull(false).withSupportSchemaVersioning(true).withPojo(Schemas.PersonTwo.class).build())).subscriptionName(subName).topic(topicName).subscribe();
    producer.send(personTwo);
    producer.close();
    consumer.close();
    // (2) Delete schema ledger
    MetadataCache<SchemaStorageFormat.SchemaLocator> locatorEntryCache = pulsar.getLocalMetadataStore().getMetadataCache(new MetadataSerde<SchemaStorageFormat.SchemaLocator>() {

        @Override
        public byte[] serialize(String path, SchemaStorageFormat.SchemaLocator value) {
            return value.toByteArray();
        }

        @Override
        public SchemaStorageFormat.SchemaLocator deserialize(String path, byte[] content, Stat stat) throws IOException {
            return SchemaStorageFormat.SchemaLocator.parseFrom(content);
        }
    });
    String path = "/schemas/public/" + namespace + "/test-multi-version-schema-one";
    SchemaLocator schema = locatorEntryCache.get(path).get().get();
    schema = locatorEntryCache.get(path).get().get();
    long ledgerId = schema.getInfo().getPosition().getLedgerId();
    pulsar.getBookKeeperClient().deleteLedger(ledgerId);
    // (3) Topic should recover from deleted schema and should allow to create consumer and producer
    consumer = pulsarClient.newConsumer(Schema.AVRO(SchemaDefinition.<Schemas.PersonTwo>builder().withAlwaysAllowNull(false).withSupportSchemaVersioning(true).withPojo(Schemas.PersonTwo.class).build())).subscriptionName(subName).topic(topicName).subscribe();
    producer = pulsarClient.newProducer(Schema.AVRO(SchemaDefinition.<Schemas.PersonTwo>builder().withAlwaysAllowNull(false).withSupportSchemaVersioning(true).withPojo(Schemas.PersonTwo.class).build())).topic(topicName).create();
    assertNotNull(consumer);
    assertNotNull(producer);
    consumer.close();
    producer.close();
}

