@Test
public void testItems() {
    ConcurrentBitmapSortedLongPairSet set = new ConcurrentBitmapSortedLongPairSet();
    Set<ConcurrentLongPairSet.LongPair> items = set.items(10, ConcurrentLongPairSet.LongPair::new);
    assertEquals(items.size(), 0);
    for (int i = 0; i < 100; i++) {
        set.add(1, i);
        set.add(2, i);
        set.add(5, i);
    }
    for (int i = 0; i < 100; i++) {
        set.add(1, i + 1000);
        set.add(2, i + 1000);
        set.add(5, i + 1000);
    }
    for (int i = 0; i < 100; i++) {
        set.add(1, i + 500);
        set.add(2, i + 500);
        set.add(5, i + 500);
    }
    assertEquals(set.size(), 900);
    assertFalse(set.isEmpty());
    items = set.items(10, ConcurrentLongPairSet.LongPair::new);
    assertEquals(items.size(), 10);
    ConcurrentLongPairSet.LongPair last = null;
    for (ConcurrentLongPairSet.LongPair item : items) {
        if (last != null) {
            assertTrue(item.compareTo(last) > 0);
        }
        last = item;
    }
    items = set.items(900, ConcurrentLongPairSet.LongPair::new);
    assertEquals(items.size(), 900);
    last = null;
    for (ConcurrentLongPairSet.LongPair item : items) {
        if (last != null) {
            assertTrue(item.compareTo(last) > 0);
        }
        last = item;
    }
    items = set.items(1000, ConcurrentLongPairSet.LongPair::new);
    assertEquals(items.size(), 900);
}

@Test
public void concurrentInsertions() throws Throwable {
    ConcurrentBitmapSortedLongPairSet set = new ConcurrentBitmapSortedLongPairSet();
    @Cleanup("shutdownNow")
    ExecutorService executor = Executors.newCachedThreadPool();
    final int nThreads = 8;
    final int N = 1000;
    List<Future<?>> futures = new ArrayList<>();
    for (int i = 0; i < nThreads; i++) {
        final int threadIdx = i;
        futures.add(executor.submit(() -> {
            int start = N * (threadIdx + 1);
            for (int j = 0; j < N; j++) {
                int key = start + j;
                // Ensure keys are unique
                set.add(key, key);
            }
        }));
    }
    for (Future<?> future : futures) {
        future.get();
    }
    assertEquals(set.size(), N * nThreads);
}

@Test
public void testGenerateNextLogIndexLag() {
    LogIndexLagBackoff logIndexLagBackoff = new LogIndexLagBackoff(1, 10, 1);
    Assert.assertEquals(logIndexLagBackoff.next(0), 1);
    Assert.assertEquals(logIndexLagBackoff.next(6), 6);
    Assert.assertEquals(logIndexLagBackoff.next(77), 10);
    logIndexLagBackoff = new LogIndexLagBackoff(1, 10, 2);
    Assert.assertEquals(logIndexLagBackoff.next(3), 9);
    try {
        new LogIndexLagBackoff(-1, 2, 3);
    } catch (IllegalArgumentException e) {
        Assert.assertEquals(e.getMessage(), "min lag must be > 0");
    }
    try {
        new LogIndexLagBackoff(2, 1, 3);
    } catch (IllegalArgumentException e) {
        Assert.assertEquals(e.getMessage(), "maxLag should be >= minLag");
    }
    try {
        new LogIndexLagBackoff(1, 1, 0.2);
    } catch (IllegalArgumentException e) {
        Assert.assertEquals(e.getMessage(), "exponent must be > 0");
    }
}

