            assertTrue(consumeSocket1.getReceivedMessagesCount() >= 10 || consumeSocket2.getReceivedMessagesCount() >= 10);
            assertTrue(readSocket.getReceivedMessagesCount() >= 10);
        });
        // if the subscription type is exclusive (default), either of the
        // consumer
        // sessions has already been closed
        assertTrue(consumerFuture1.get().isOpen());
