    Producer<byte[]> producer1 = pulsarClient.newProducer().topic(topic1).batchingMaxMessages(1).create();
    @Cleanup
    Producer<byte[]> producer2 = pulsarClient.newProducer().topic(topic2).batchingMaxMessages(1).create();
    try {
        consumerClient1.start();
        consumerClient2.start();
        ClientUpgradeRequest consumerRequest1 = new ClientUpgradeRequest();
        ClientUpgradeRequest consumerRequest2 = new ClientUpgradeRequest();
        Future<Session> consumerFuture1 = consumerClient1.connect(consumeSocket1, URI.create(consumerUri1), consumerRequest1);
        Future<Session> consumerFuture2 = consumerClient2.connect(consumeSocket2, URI.create(consumerUri2), consumerRequest2);
        assertTrue(consumerFuture1.get().isOpen());
        assertTrue(consumerFuture2.get().isOpen());
        assertEquals(consumeSocket1.getReceivedMessagesCount(), 0);
        assertEquals(consumeSocket2.getReceivedMessagesCount(), 0);
        for (int i = 1; i <= messages; i++) {
            producer1.sendAsync(String.valueOf(i).getBytes(StandardCharsets.UTF_8));
            producer2.sendAsync(String.valueOf(i).getBytes(StandardCharsets.UTF_8));
        }
        producer1.flush();
        producer2.flush();
        consumeSocket1.sendPermits(2 * messages);
        Awaitility.await().untilAsserted(() -> assertEquals(consumeSocket1.getReceivedMessagesCount(), 2 * messages));
        Awaitility.await().untilAsserted(() -> assertEquals(admin.topics().getStats(topic1).getSubscriptions().get(subscription1).getMsgBacklog(), 0));
        Awaitility.await().untilAsserted(() -> assertEquals(admin.topics().getStats(topic2).getSubscriptions().get(subscription1).getMsgBacklog(), 0));
        consumeSocket2.sendPermits(2 * messages);
        Awaitility.await().untilAsserted(() -> assertEquals(consumeSocket2.getReceivedMessagesCount(), 2 * messages));
    } finally {
        stopWebSocketClient(consumerClient1, consumerClient2);
    }
}

@Test(timeOut = 30000)
public void socketTest() throws GeneralSecurityException {
    String consumerUri = "wss://localhost:" + proxyServer.getListenPortHTTPS().get() + "/ws/consumer/persistent/my-property/use/my-ns/my-topic/my-sub";
    String producerUri = "wss://localhost:" + proxyServer.getListenPortHTTPS().get() + "/ws/producer/persistent/my-property/use/my-ns/my-topic/";
    URI consumeUri = URI.create(consumerUri);
    URI produceUri = URI.create(producerUri);
    SslContextFactory sslContextFactory = new SslContextFactory();
    sslContextFactory.setSslContext(SecurityUtility.createSslContext(false, SecurityUtility.loadCertificatesFromPemFile(CA_CERT_FILE_PATH), null));
    WebSocketClient consumeClient = new WebSocketClient(sslContextFactory);
    SimpleConsumerSocket consumeSocket = new SimpleConsumerSocket();
    WebSocketClient produceClient = new WebSocketClient(sslContextFactory);
    try {
        consumeClient.start();
        ClientUpgradeRequest consumeRequest = new ClientUpgradeRequest();
        Future<Session> consumerFuture = consumeClient.connect(consumeSocket, consumeUri, consumeRequest);
        log.info("Connecting to : {}", consumeUri);
        Assert.assertTrue(consumerFuture.get().isOpen());
        SimpleProducerSocket produceSocket = new SimpleProducerSocket();
        ClientUpgradeRequest produceRequest = new ClientUpgradeRequest();
        produceClient.start();
        Future<Session> producerFuture = produceClient.connect(produceSocket, produceUri, produceRequest);
        Assert.assertTrue(producerFuture.get().isOpen());
        Awaitility.await().untilAsserted(() -> {
            Assert.assertTrue(produceSocket.getBuffer().size() > 0);
            Assert.assertEquals(produceSocket.getBuffer(), consumeSocket.getBuffer());
        });
        consumeSocket.awaitClose(1, TimeUnit.SECONDS);
        produceSocket.awaitClose(1, TimeUnit.SECONDS);
    } catch (Throwable t) {
        log.error(t.getMessage());
        Assert.fail(t.getMessage());
    } finally {
        try {
            consumeClient.stop();
            produceClient.stop();
            log.info("proxy clients are stopped successfully");
        } catch (Exception e) {
            log.error("failed to close clients ", e);
        }
    }
}

