@Test
public void testNoDeadlockWithRackawarePolicy() throws Exception {
    ClientConfiguration bkClientConf = new ClientConfiguration();
    bkClientConf.setProperty(BookieRackAffinityMapping.METADATA_STORE_INSTANCE, store);
    BookieRackAffinityMapping mapping = new BookieRackAffinityMapping();
    mapping.setBookieAddressResolver(BookieSocketAddress.LEGACY_BOOKIEID_RESOLVER);
    mapping.setConf(bkClientConf);
    @Cleanup("stop")
    HashedWheelTimer timer = new HashedWheelTimer(new ThreadFactoryBuilder().setNameFormat("TestTimer-%d").build(), bkClientConf.getTimeoutTimerTickDurationMs(), TimeUnit.MILLISECONDS, bkClientConf.getTimeoutTimerNumTicks());
    RackawareEnsemblePlacementPolicy repp = new RackawareEnsemblePlacementPolicy();
    repp.initialize(bkClientConf, Optional.of(mapping), timer, DISABLE_ALL, NullStatsLogger.INSTANCE, BookieSocketAddress.LEGACY_BOOKIEID_RESOLVER);
    repp.withDefaultRack(NetworkTopology.DEFAULT_REGION_AND_RACK);
    mapping.registerRackChangeListener(repp);
    @Cleanup("shutdownNow")
    ExecutorService executor1 = Executors.newSingleThreadExecutor();
    @Cleanup("shutdownNow")
    ExecutorService executor2 = Executors.newSingleThreadExecutor();
    CountDownLatch count = new CountDownLatch(2);
    executor1.submit(() -> {
        try {
            Method handleUpdates = BookieRackAffinityMapping.class.getDeclaredMethod("handleUpdates", Notification.class);
            handleUpdates.setAccessible(true);
            Notification n = new Notification(NotificationType.Modified, BookieRackAffinityMapping.BOOKIE_INFO_ROOT_PATH);
            long start = System.currentTimeMillis();
            while (System.currentTimeMillis() - start < 2_000) {
                handleUpdates.invoke(mapping, n);
            }
            count.countDown();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    });
    executor2.submit(() -> {
        Set<BookieId> writableBookies = new HashSet<>();
        writableBookies.add(BOOKIE1.toBookieId());
        long start = System.currentTimeMillis();
        while (System.currentTimeMillis() - start < 2_000) {
            repp.onClusterChanged(writableBookies, Collections.emptySet());
            repp.onClusterChanged(Collections.emptySet(), Collections.emptySet());
        }
        count.countDown();
    });
    assertTrue(count.await(3, TimeUnit.SECONDS));
}

