@Test
public void testTokenSettingPrefix() throws Exception {
    AuthenticationProviderToken provider = new AuthenticationProviderToken();
    KeyPair keyPair = Keys.keyPairFor(SignatureAlgorithm.RS256);
    String publicKeyStr = AuthTokenUtils.encodeKeyBase64(keyPair.getPublic());
    Properties properties = new Properties();
    // Use public key for validation
    properties.setProperty(AuthenticationProviderToken.CONF_TOKEN_PUBLIC_KEY, publicKeyStr);
    ServiceConfiguration conf = new ServiceConfiguration();
    conf.setProperties(properties);
    ServiceConfiguration mockConf = mock(ServiceConfiguration.class);
    String prefix = "test";
    Mockito.when(mockConf.getProperty(anyString())).thenAnswer(invocationOnMock -> conf.getProperty(((String) invocationOnMock.getArgument(0)).substring(prefix.length())));
    Mockito.when(mockConf.getProperty(AuthenticationProviderToken.CONF_TOKEN_SETTING_PREFIX)).thenReturn(prefix);
    provider.initialize(mockConf);
    // Each property is fetched only once. Prevent multiple fetches.
    Mockito.verify(mockConf, Mockito.times(1)).getProperty(AuthenticationProviderToken.CONF_TOKEN_SETTING_PREFIX);
    Mockito.verify(mockConf, Mockito.times(1)).getProperty(prefix + AuthenticationProviderToken.CONF_TOKEN_SECRET_KEY);
    Mockito.verify(mockConf, Mockito.times(1)).getProperty(prefix + AuthenticationProviderToken.CONF_TOKEN_PUBLIC_KEY);
    Mockito.verify(mockConf, Mockito.times(1)).getProperty(prefix + AuthenticationProviderToken.CONF_TOKEN_AUTH_CLAIM);
    Mockito.verify(mockConf, Mockito.times(1)).getProperty(prefix + AuthenticationProviderToken.CONF_TOKEN_PUBLIC_ALG);
    Mockito.verify(mockConf, Mockito.times(1)).getProperty(prefix + AuthenticationProviderToken.CONF_TOKEN_AUDIENCE_CLAIM);
    Mockito.verify(mockConf, Mockito.times(1)).getProperty(prefix + AuthenticationProviderToken.CONF_TOKEN_AUDIENCE);
}

