@Test
public void testSchemeFilter() {
    ServiceConfiguration config = newEmptyConfiguration();
    config.setBrokerServicePort(Optional.of(6650));
    config.setBrokerServicePortTls(Optional.of(6651));
    config.setBindAddresses("extra:pulsar://0.0.0.0:6652,extra:http://0.0.0.0:8080");
    List<BindAddress> addresses;
    addresses = BindAddressValidator.validateBindAddresses(config, null);
    assertEquals(Arrays.asList(new BindAddress(null, URI.create("pulsar://0.0.0.0:6650")), new BindAddress(null, URI.create("pulsar+ssl://0.0.0.0:6651")), new BindAddress("extra", URI.create("pulsar://0.0.0.0:6652")), new BindAddress("extra", URI.create("http://0.0.0.0:8080"))), addresses);
    addresses = BindAddressValidator.validateBindAddresses(config, Arrays.asList("pulsar", "pulsar+ssl"));
    assertEquals(Arrays.asList(new BindAddress(null, URI.create("pulsar://0.0.0.0:6650")), new BindAddress(null, URI.create("pulsar+ssl://0.0.0.0:6651")), new BindAddress("extra", URI.create("pulsar://0.0.0.0:6652"))), addresses);
    addresses = BindAddressValidator.validateBindAddresses(config, Collections.singletonList("http"));
    assertEquals(Collections.singletonList(new BindAddress("extra", URI.create("http://0.0.0.0:8080"))), addresses);
}

