@Test
public void testDoIndividualBatchAckAsync() throws Exception {
    ConsumerConfigurationData<?> conf = new ConsumerConfigurationData<>();
    AcknowledgmentsGroupingTracker tracker = new PersistentAcknowledgmentsGroupingTracker(consumer, conf, eventLoopGroup);
    MessageId messageId1 = new BatchMessageIdImpl(5, 1, 0, 3, 10, null);
    BitSet bitSet = new BitSet(20);
    for (int i = 0; i < 20; i++) {
        bitSet.set(i, true);
    }
    MessageId messageId2 = new BatchMessageIdImpl(3, 2, 0, 5, 20, bitSet);
    Method doIndividualBatchAckAsync = PersistentAcknowledgmentsGroupingTracker.class.getDeclaredMethod("doIndividualBatchAckAsync", MessageIdAdv.class);
    doIndividualBatchAckAsync.setAccessible(true);
    doIndividualBatchAckAsync.invoke(tracker, messageId1);
    doIndividualBatchAckAsync.invoke(tracker, messageId2);
    Field pendingIndividualBatchIndexAcks = PersistentAcknowledgmentsGroupingTracker.class.getDeclaredField("pendingIndividualBatchIndexAcks");
    pendingIndividualBatchIndexAcks.setAccessible(true);
    ConcurrentHashMap<MessageIdAdv, ConcurrentBitSetRecyclable> batchIndexAcks = (ConcurrentHashMap<MessageIdAdv, ConcurrentBitSetRecyclable>) pendingIndividualBatchIndexAcks.get(tracker);
    MessageIdImpl position1 = new MessageIdImpl(5, 1, 0);
    MessageIdImpl position2 = new MessageIdImpl(3, 2, 0);
    assertTrue(batchIndexAcks.containsKey(position1));
    assertNotNull(batchIndexAcks.get(position1));
    assertEquals(batchIndexAcks.get(position1).cardinality(), 9);
    assertTrue(batchIndexAcks.containsKey(position2));
    assertNotNull(batchIndexAcks.get(position2));
    assertEquals(batchIndexAcks.get(position2).cardinality(), 19);
    tracker.close();
}

/**
 * This test validates if {@link AuthenticationTls} is serializable to prevent future non-serializable changes and also
 * validates that streamProvider can be serializable and user can use AuthenticationTls in serialiazable task.
 *
 * @throws Exception
 */
@Test
public void testSerializableAuthentication() throws Exception {
    SerializableSupplier tlsCertSupplier = new SerializableSupplier("cert");
    SerializableSupplier tlsKeySupplier = new SerializableSupplier("key");
    SerializableSupplier tlsTrustSupplier = new SerializableSupplier("trust");
    AuthenticationTls tls = new AuthenticationTls(tlsCertSupplier, tlsKeySupplier, tlsTrustSupplier);
    // serialize
    ByteArrayOutputStream outStream = new ByteArrayOutputStream();
    ObjectOutputStream out = new ObjectOutputStream(outStream);
    out.writeObject(tls);
    out.flush();
    byte[] outputBytes = outStream.toByteArray();
    out.close();
    // deserialize
    ByteArrayInputStream bis = new ByteArrayInputStream(outputBytes);
    ObjectInput in = new ObjectInputStream(bis);
    AuthenticationTls ts = (AuthenticationTls) in.readObject();
    in.close();
    // read the object and validate the fields
    byte[] cert = new byte[tlsCertSupplier.getData().length];
    byte[] key = new byte[tlsKeySupplier.getData().length];
    byte[] trust = new byte[tlsTrustSupplier.getData().length];
    ts.getCertStreamProvider().get().read(cert);
    ts.getKeyStreamProvider().get().read(key);
    ts.getTrustStoreStreamProvider().get().read(trust);
    assertEquals(cert, tlsCertSupplier.getData());
    assertEquals(key, tlsKeySupplier.getData());
    assertEquals(trust, tlsTrustSupplier.getData());
}

