@Test
public void testTimestampWithJsonDef() {
    AvroSchema<TimestampPojo> schemaWithPojo = AvroSchema.of(SchemaDefinition.<TimestampPojo>builder().withPojo(TimestampPojo.class).withJSR310ConversionEnabled(false).build());
    TimestampPojo timestampPojo = new TimestampPojo(Instant.parse("2022-06-10T12:38:59.039084Z"));
