@Test
public void testAddAndRemove() {
    PulsarClientImpl client = mock(PulsarClientImpl.class);
    ConnectionPool connectionPool = mock(ConnectionPool.class);
    when(client.instrumentProvider()).thenReturn(InstrumentProvider.NOOP);
    when(client.getCnxPool()).thenReturn(connectionPool);
    Timer timer = new HashedWheelTimer(new DefaultThreadFactory("pulsar-timer", Thread.currentThread().isDaemon()), 1, TimeUnit.MILLISECONDS);
    when(client.timer()).thenReturn(timer);
    ConsumerBase<byte[]> consumer = mock(ConsumerBase.class);
    doNothing().when(consumer).onAckTimeoutSend(any());
    doNothing().when(consumer).redeliverUnacknowledgedMessages(any());
    ConsumerConfigurationData<?> conf = new ConsumerConfigurationData<>();
    conf.setAckTimeoutMillis(1000000);
    conf.setTickDurationMillis(100000);
    UnAckedMessageTracker tracker = new UnAckedMessageTracker(client, consumer, conf);
    tracker.close();
    assertTrue(tracker.isEmpty());
    assertEquals(tracker.size(), 0);
    MessageIdImpl mid = new MessageIdImpl(1L, 1L, -1);
    assertTrue(tracker.add(mid));
    assertFalse(tracker.add(mid));
    assertEquals(tracker.size(), 1);
    HashSet<MessageId> headPartition = tracker.timePartitions.removeFirst();
    headPartition.clear();
    tracker.timePartitions.addLast(headPartition);
    assertFalse(tracker.add(mid));
    assertEquals(tracker.size(), 1);
    assertTrue(tracker.remove(mid));
    assertTrue(tracker.isEmpty());
    assertEquals(tracker.size(), 0);
    timer.stop();
}

@Test
public void testTrackChunkedMessageId() {
    PulsarClientImpl client = mock(PulsarClientImpl.class);
    ConnectionPool connectionPool = mock(ConnectionPool.class);
    when(client.instrumentProvider()).thenReturn(InstrumentProvider.NOOP);
    when(client.getCnxPool()).thenReturn(connectionPool);
    Timer timer = new HashedWheelTimer(new DefaultThreadFactory("pulsar-timer", Thread.currentThread().isDaemon()), 1, TimeUnit.MILLISECONDS);
    when(client.timer()).thenReturn(timer);
    ConsumerBase<byte[]> consumer = mock(ConsumerBase.class);
    doNothing().when(consumer).onAckTimeoutSend(any());
    doNothing().when(consumer).redeliverUnacknowledgedMessages(any());
    ConsumerConfigurationData<?> conf = new ConsumerConfigurationData<>();
    conf.setAckTimeoutMillis(1000);
    conf.setTickDurationMillis(1000);
    UnAckedMessageTracker tracker = new UnAckedMessageTracker(client, consumer, conf);
    assertTrue(tracker.isEmpty());
    assertEquals(tracker.size(), 0);
    // Build chunked message ID
    MessageIdImpl[] chunkMsgIds = new MessageIdImpl[5];
    for (int i = 0; i < 5; i++) {
        chunkMsgIds[i] = new MessageIdImpl(1L, i, -1);
    }
    ChunkMessageIdImpl chunkedMessageId = new ChunkMessageIdImpl(chunkMsgIds[0], chunkMsgIds[chunkMsgIds.length - 1]);
    consumer.unAckedChunkedMessageIdSequenceMap = ConcurrentOpenHashMap.<MessageIdAdv, MessageIdImpl[]>newBuilder().build();
    consumer.unAckedChunkedMessageIdSequenceMap.put(chunkedMessageId, chunkMsgIds);
    // Redeliver chunked message
    tracker.add(chunkedMessageId);
    Awaitility.await().pollInterval(Duration.ofMillis(200)).atMost(Duration.ofSeconds(3)).untilAsserted(() -> assertEquals(tracker.size(), 0));
    // Assert that all chunk message ID are removed from unAckedChunkedMessageIdSequenceMap
    assertEquals(consumer.unAckedChunkedMessageIdSequenceMap.size(), 0);
    timer.stop();
}

@Test
public void testCeilDiv() {
    Assert.assertEquals(MathUtils.ceilDiv(0, 1024), 0);
    Assert.assertEquals(MathUtils.ceilDiv(1, 1024), 1);
    Assert.assertEquals(MathUtils.ceilDiv(1023, 1024), 1);
    Assert.assertEquals(MathUtils.ceilDiv(1024, 1024), 1);
    Assert.assertEquals(MathUtils.ceilDiv(1025, 1024), 2);
    Assert.assertEquals(MathUtils.ceilDiv(0, Integer.MAX_VALUE), 0);
    Assert.assertEquals(MathUtils.ceilDiv(1, Integer.MAX_VALUE), 1);
    Assert.assertEquals(MathUtils.ceilDiv(Integer.MAX_VALUE - 1, Integer.MAX_VALUE), 1);
    Assert.assertEquals(MathUtils.ceilDiv(Integer.MAX_VALUE, Integer.MAX_VALUE), 1);
}

@Test
public void testCache() {
    AtomicLong currentTime = new AtomicLong(0);
    Clock clock = mock(Clock.class);
    when(clock.millis()).then(invocation -> currentTime.longValue());
    AtomicInteger currentValue = new AtomicInteger(0);
    Supplier<Integer> cache = new ObjectCache<>(() -> currentValue.getAndIncrement(), 10, TimeUnit.MILLISECONDS, clock);
    cache.get();
    assertEquals(cache.get().intValue(), 0);
    assertEquals(cache.get().intValue(), 0);
    currentTime.set(1);
    // Still the value has not expired
    assertEquals(cache.get().intValue(), 0);
    currentTime.set(10);
    assertEquals(cache.get().intValue(), 1);
    currentTime.set(15);
    assertEquals(cache.get().intValue(), 1);
    currentTime.set(22);
    assertEquals(cache.get().intValue(), 2);
}

