}

@Test
public void test() throws Exception {
    final Path newClientConf = Files.createTempFile("client", ".conf");
    final byte[] content = ("webServiceUrl=http://localhost:8081/\n" + "brokerServiceUrl=pulsar://localhost:6651/\n").getBytes(StandardCharsets.UTF_8);
    Files.write(newClientConf, content);
    assertTrue(runCommand(new String[] { "create", "myclient", "--file", newClientConf.toFile().getAbsolutePath() }));
    assertTrue(output.isEmpty());
    cleanOutput();
    assertNull(pulsarShell.getConfigStore().getLastUsed());
    assertTrue(runCommand(new String[] { "use", "myclient" }));
    assertTrue(output.isEmpty());
    cleanOutput();
    assertEquals(pulsarShell.getConfigStore().getLastUsed(), pulsarShell.getConfigStore().getConfig("myclient"));
    verify(pulsarShell).reload(any());
    assertTrue(runCommand(new String[] { "list" }));
    assertEquals(output, "default\nmyclient (*)\n");
    cleanOutput();
    assertFalse(runCommand(new String[] { "delete", "myclient" }));
    assertEquals(output, "'myclient' is currently used and it can't be deleted.\n");
    cleanOutput();
    assertTrue(runCommand(new String[] { "update", "myclient", "--file", newClientConf.toFile().getAbsolutePath() }));
    assertTrue(output.isEmpty());
    verify(pulsarShell, times(2)).reload(any());
    assertTrue(runCommand(new String[] { "clone", "myclient", "--name", "myclient-copied" }));
    assertTrue(output.isEmpty());
    verify(pulsarShell, times(2)).reload(any());
    assertTrue(runCommand(new String[] { "view", "myclient-copied" }));
    assertEquals(output, "webServiceUrl=http://localhost:8081/\nbrokerServiceUrl" + "=pulsar://localhost:6651/\n\n");
    cleanOutput();
}

@Test
public void testSetGetProperty() throws Exception {
    final Path newClientConf = Files.createTempFile("client", ".conf");
    final byte[] content = ("webServiceUrl=http://localhost:8081/\n" + "brokerServiceUrl=pulsar://localhost:6651/\n").getBytes(StandardCharsets.UTF_8);
    Files.write(newClientConf, content);
    assertTrue(runCommand(new String[] { "create", "myclient", "--file", newClientConf.toFile().getAbsolutePath() }));
    assertTrue(output.isEmpty());
    cleanOutput();
    assertTrue(runCommand(new String[] { "use", "myclient" }));
    assertTrue(output.isEmpty());
    cleanOutput();
    assertTrue(runCommand(new String[] { "get-property", "-p", "webServiceUrl", "myclient" }));
    assertEquals(output, "http://localhost:8081/\n");
    cleanOutput();
    assertTrue(runCommand(new String[] { "set-property", "-p", "newConf", "-v", "myValue", "myclient" }));
    verify(pulsarShell, times(2)).reload(any());
    cleanOutput();
    assertTrue(runCommand(new String[] { "get-property", "-p", "newConf", "myclient" }));
    assertEquals(output, "myValue\n");
    cleanOutput();
    assertTrue(runCommand(new String[] { "view", "myclient" }));
    assertEquals(output, "webServiceUrl=http://localhost:8081/\nbrokerServiceUrl" + "=pulsar://localhost:6651/\nnewConf=myValue\n\n");
    cleanOutput();
    assertTrue(runCommand(new String[] { "set-property", "-p", "newConf", "-v", "myValue2", "myclient" }));
    verify(pulsarShell, times(3)).reload(any());
    cleanOutput();
    assertTrue(runCommand(new String[] { "get-property", "-p", "newConf", "myclient" }));
    assertEquals(output, "myValue2\n");
    cleanOutput();
    assertTrue(runCommand(new String[] { "view", "myclient" }));
    assertEquals(output, "webServiceUrl=http://localhost:8081/\nbrokerServiceUrl" + "=pulsar://localhost:6651/\nnewConf=myValue2\n\n");
    cleanOutput();
    assertTrue(runCommand(new String[] { "set-property", "-p", "newConf", "-v", "", "myclient" }));
    verify(pulsarShell, times(4)).reload(any());
    cleanOutput();
    assertTrue(runCommand(new String[] { "view", "myclient" }));
    assertEquals(output, "webServiceUrl=http://localhost:8081/\nbrokerServiceUrl" + "=pulsar://localhost:6651/\nnewConf=\n\n");
    cleanOutput();
    assertTrue(runCommand(new String[] { "get-property", "-p", "newConf", "myclient" }));
    assertTrue(output.isEmpty());
    cleanOutput();
}

