@Test
public void clusters() throws Exception {
    PulsarAdmin admin = Mockito.mock(PulsarAdmin.class);
    Clusters mockClusters = mock(Clusters.class);
    when(admin.clusters()).thenReturn(mockClusters);
    CmdClusters clusters = new CmdClusters(() -> admin);
    clusters.run(split("list"));
    verify(mockClusters).getClusters();
    clusters.run(split("get use"));
    verify(mockClusters).getCluster("use");
    clusters.run(split("create use --url http://my-service.url:8080"));
    verify(mockClusters).createCluster("use", ClusterData.builder().serviceUrl("http://my-service.url:8080").build());
    clusters.run(split("update use --url http://my-service.url:8080"));
    verify(mockClusters).updateCluster("use", ClusterData.builder().serviceUrl("http://my-service.url:8080").build());
    clusters.run(split("delete use"));
    verify(mockClusters).deleteCluster("use");
    clusters.run(split("list-failure-domains use"));
    verify(mockClusters).getFailureDomains("use");
    clusters.run(split("get-failure-domain use --domain-name domain"));
    verify(mockClusters).getFailureDomain("use", "domain");
    clusters.run(split("create-failure-domain use --domain-name domain --broker-list b1"));
    FailureDomain domain = FailureDomain.builder().brokers(Collections.singleton("b1")).build();
    verify(mockClusters).createFailureDomain("use", "domain", domain);
    clusters.run(split("update-failure-domain use --domain-name domain --broker-list b1"));
    verify(mockClusters).updateFailureDomain("use", "domain", domain);
    clusters.run(split("delete-failure-domain use --domain-name domain"));
    verify(mockClusters).deleteFailureDomain("use", "domain");
    // Re-create CmdClusters to avoid a issue.
    // See https://github.com/cbeust/jcommander/issues/271
    clusters = new CmdClusters(() -> admin);
    clusters.run(split("create my-cluster --url http://my-service.url:8080 --url-secure https://my-service.url:4443"));
    verify(mockClusters).createCluster("my-cluster", ClusterData.builder().serviceUrl("http://my-service.url:8080").serviceUrlTls("https://my-service.url:4443").build());
    clusters.run(split("update my-cluster --url http://my-service.url:8080 --url-secure https://my-service.url:4443"));
    verify(mockClusters).updateCluster("my-cluster", ClusterData.builder().serviceUrl("http://my-service.url:8080").serviceUrlTls("https://my-service.url:4443").build());
    clusters.run(split("delete my-cluster"));
    verify(mockClusters).deleteCluster("my-cluster");
    clusters.run(split("update-peer-clusters my-cluster --peer-clusters c1,c2"));
    verify(mockClusters).updatePeerClusterNames("my-cluster", Sets.newLinkedHashSet(Lists.newArrayList("c1", "c2")));
    clusters.run(split("get-peer-clusters my-cluster"));
    verify(mockClusters).getPeerClusterNames("my-cluster");
    // test create cluster without --url
    clusters = new CmdClusters(() -> admin);
    clusters.run(split("create my-secure-cluster --url-secure https://my-service.url:4443"));
    verify(mockClusters).createCluster("my-secure-cluster", ClusterData.builder().serviceUrlTls("https://my-service.url:4443").build());
    clusters.run(split("update my-secure-cluster --url-secure https://my-service.url:4443"));
    verify(mockClusters).updateCluster("my-secure-cluster", ClusterData.builder().serviceUrlTls("https://my-service.url:4443").build());
    clusters.run(split("delete my-secure-cluster"));
    verify(mockClusters).deleteCluster("my-secure-cluster");
    // test create cluster with tls
    clusters = new CmdClusters(() -> admin);
    clusters.run(split("create my-tls-cluster --url-secure https://my-service.url:4443 --tls-enable " + "--tls-enable-keystore --tls-trust-store-type JKS --tls-trust-store /var/private/tls/client.truststore.jks " + "--tls-trust-store-pwd clientpw --tls-key-store-type KEYSTORE_TYPE --tls-key-store /var/private/tls/client.keystore.jks " + "--tls-key-store-pwd KEYSTORE_STORE_PWD"));
    ClusterData.Builder data = ClusterData.builder().serviceUrlTls("https://my-service.url:4443").brokerClientTlsEnabled(true).brokerClientTlsEnabledWithKeyStore(true).brokerClientTlsTrustStoreType("JKS").brokerClientTlsTrustStore("/var/private/tls/client.truststore.jks").brokerClientTlsTrustStorePassword("clientpw").brokerClientTlsKeyStoreType("KEYSTORE_TYPE").brokerClientTlsKeyStore("/var/private/tls/client.keystore.jks").brokerClientTlsKeyStorePassword("KEYSTORE_STORE_PWD");
    verify(mockClusters).createCluster("my-tls-cluster", data.build());
    clusters.run(split("update my-tls-cluster --url-secure https://my-service.url:4443 --tls-enable " + "--tls-trust-certs-filepath /path/to/ca.cert.pem --tls-key-filepath KEY_FILEPATH --tls-certs-filepath CERTS_FILEPATH"));
    data.brokerClientTlsEnabledWithKeyStore(false).brokerClientTlsTrustStore(null).brokerClientTlsTrustStorePassword(null).brokerClientTlsKeyStoreType("JKS").brokerClientTlsKeyStore(null).brokerClientTlsKeyStorePassword(null).brokerClientTrustCertsFilePath("/path/to/ca.cert.pem").brokerClientKeyFilePath("KEY_FILEPATH").brokerClientCertificateFilePath("CERTS_FILEPATH");
    verify(mockClusters).updateCluster("my-tls-cluster", data.build());
}

