@Test
public void namespacesSetOffloadPolicies() throws Exception {
    PulsarAdmin admin = Mockito.mock(PulsarAdmin.class);
    Namespaces mockNamespaces = mock(Namespaces.class);
    when(admin.namespaces()).thenReturn(mockNamespaces);
    Lookup mockLookup = mock(Lookup.class);
    when(admin.lookups()).thenReturn(mockLookup);
    // filesystem offload
    CmdNamespaces namespaces = new CmdNamespaces(() -> admin);
    namespaces.run(split("set-offload-policies myprop/clust/ns2 -d filesystem -oat 100M -oats 1h -oae 1h -orp bookkeeper-first"));
    verify(mockNamespaces).setOffloadPolicies("myprop/clust/ns2", OffloadPoliciesImpl.create("filesystem", null, null, null, null, null, null, null, 64 * 1024 * 1024, 1024 * 1024, 100 * 1024 * 1024L, 3600L, 3600 * 1000L, OffloadedReadPriority.BOOKKEEPER_FIRST));
    // S3 offload
    CmdNamespaces namespaces2 = new CmdNamespaces(() -> admin);
    namespaces2.run(split("set-offload-policies myprop/clust/ns1 -r test-region -d aws-s3 -b test-bucket -e http://test.endpoint -mbs 32M -rbs 5M -oat 10M -oats 100 -oae 10s -orp tiered-storage-first"));
    verify(mockNamespaces).setOffloadPolicies("myprop/clust/ns1", OffloadPoliciesImpl.create("aws-s3", "test-region", "test-bucket", "http://test.endpoint", null, null, null, null, 32 * 1024 * 1024, 5 * 1024 * 1024, 10 * 1024 * 1024L, 100L, 10000L, OffloadedReadPriority.TIERED_STORAGE_FIRST));
}

