@Test
public void testRemoval() {
    LongPairSet set = new ConcurrentSortedLongPairSet(16);
    set.add(0, 0);
    set.add(1, 1);
    set.add(3, 3);
    set.add(6, 6);
    set.add(7, 7);
    List<LongPair> values = new ArrayList<>(set.items());
    values.sort(null);
    assertEquals(values, Lists.newArrayList(new LongPair(0, 0), new LongPair(1, 1), new LongPair(3, 3), new LongPair(6, 6), new LongPair(7, 7)));
    set.forEach((first, second) -> {
        if (first < 5) {
            set.remove(first, second);
        }
    });
    assertEquals(set.size(), values.size() - 3);
    values = new ArrayList<>(set.items());
    values.sort(null);
    assertEquals(values, Lists.newArrayList(new LongPair(6, 6), new LongPair(7, 7)));
}

@Test
public void testIfRemoval() {
    LongPairSet set = new ConcurrentSortedLongPairSet(16, 1, 1);
    set.add(0, 0);
    set.add(1, 1);
    set.add(3, 3);
    set.add(6, 6);
    set.add(7, 7);
    List<LongPair> values = new ArrayList<>(set.items());
    values.sort(null);
    assertEquals(values, Lists.newArrayList(new LongPair(0, 0), new LongPair(1, 1), new LongPair(3, 3), new LongPair(6, 6), new LongPair(7, 7)));
    int removeItems = set.removeIf((first, second) -> first < 5);
    assertEquals(3, removeItems);
    assertEquals(set.size(), values.size() - 3);
    values = new ArrayList<>(set.items());
    values.sort(null);
    assertEquals(values, Lists.newArrayList(new LongPair(6, 6), new LongPair(7, 7)));
    set = new ConcurrentSortedLongPairSet(128, 2, true);
    set.add(2, 2);
    set.add(1, 3);
    set.add(3, 1);
    set.add(2, 1);
    set.add(3, 2);
    set.add(1, 2);
    set.add(1, 1);
    removeItems = set.removeIf((ledgerId, entryId) -> {
        return ComparisonChain.start().compare(ledgerId, 1).compare(entryId, 3).result() <= 0;
    });
    assertEquals(removeItems, 3);
}

