    assertEquals(queue.size(), 2);
    assertEquals(queue.toString(), "[3, 4]");
    queue.offer(6);
    queue.offer(7);
    assertTrue(queue.remove(6));
    assertEquals(queue.size(), 3);
    assertEquals(queue.toString(), "[3, 4, 7]");
    queue.offer(8);
    assertTrue(queue.remove(8));
    assertEquals(queue.size(), 3);
    assertEquals(queue.toString(), "[3, 4, 7]");
