    assertTrue(queue.remove(8));
    assertEquals(queue.size(), 2);
    assertEquals(queue.toString(), "[3, 7]");
    assertTrue(queue.remove(7));
    assertEquals(queue.size(), 1);
    assertEquals(queue.toString(), "[3]");
