@Test
public void processUpdateTest() throws PulsarClientException {
    SchedulerManager schedulerManager = mock(SchedulerManager.class);
    WorkerConfig workerConfig = new WorkerConfig();
    workerConfig.setWorkerId("worker-1");
    FunctionMetaDataManager functionMetaDataManager = spy(new FunctionMetaDataManager(workerConfig, schedulerManager, mockPulsarClient(), ErrorNotifier.getDefaultImpl()));
    Function.FunctionMetaData m1 = Function.FunctionMetaData.newBuilder().setVersion(1).setFunctionDetails(Function.FunctionDetails.newBuilder().setName("func-1").setNamespace("namespace-1").setTenant("tenant-1")).build();
    Assert.assertTrue(functionMetaDataManager.processUpdate(m1));
    verify(functionMetaDataManager, times(1)).setFunctionMetaData(any(Function.FunctionMetaData.class));
    verify(schedulerManager, times(0)).schedule();
    Assert.assertEquals(m1, functionMetaDataManager.functionMetaDataMap.get("tenant-1").get("namespace-1").get("func-1"));
    Assert.assertEquals(1, functionMetaDataManager.functionMetaDataMap.get("tenant-1").get("namespace-1").size());
    // outdated request
    try {
        functionMetaDataManager.processUpdate(m1);
        Assert.assertTrue(false);
    } catch (IllegalArgumentException e) {
        Assert.assertEquals(e.getMessage(), "Update request ignored because it is out of date. Please try again.");
    }
    verify(functionMetaDataManager, times(1)).setFunctionMetaData(any(Function.FunctionMetaData.class));
    verify(schedulerManager, times(0)).schedule();
    Assert.assertEquals(m1, functionMetaDataManager.functionMetaDataMap.get("tenant-1").get("namespace-1").get("func-1"));
    Assert.assertEquals(1, functionMetaDataManager.functionMetaDataMap.get("tenant-1").get("namespace-1").size());
    // udpate with new version
    m1 = m1.toBuilder().setVersion(2).build();
    Assert.assertTrue(functionMetaDataManager.processUpdate(m1));
    verify(functionMetaDataManager, times(2)).setFunctionMetaData(any(Function.FunctionMetaData.class));
    verify(schedulerManager, times(0)).schedule();
    Assert.assertEquals(m1, functionMetaDataManager.functionMetaDataMap.get("tenant-1").get("namespace-1").get("func-1"));
    Assert.assertEquals(1, functionMetaDataManager.functionMetaDataMap.get("tenant-1").get("namespace-1").size());
}

