    try {
        resource.updateSource(sourceConfig.getTenant(), sourceConfig.getNamespace(), sourceConfig.getName(), null, mockedFormData, null, sourceConfig, null, null);
        fail("Update without changes should fail");
    } catch (RestException e) {
