@Test
public void testRebalance() {
    Function.FunctionMetaData function1 = Function.FunctionMetaData.newBuilder().setFunctionDetails(Function.FunctionDetails.newBuilder().setName("func-1").setNamespace("namespace-1").setTenant("tenant-1").setParallelism(1)).setVersion(0).build();
    List<Function.Assignment> assignments = new LinkedList<>();
    for (int i = 0; i < 10; i++) {
        Function.Assignment assignment1 = Function.Assignment.newBuilder().setWorkerId("worker-1").setInstance(Function.Instance.newBuilder().setFunctionMetaData(function1).setInstanceId(i).build()).build();
        assignments.add(assignment1);
    }
    Set<String> workers = new HashSet<>();
    for (int i = 0; i < 3; i++) {
        workers.add("worker-" + i);
    }
    RoundRobinScheduler roundRobinScheduler = new RoundRobinScheduler();
    List<Function.Assignment> newAssignments = roundRobinScheduler.rebalance(assignments, workers);
    Map<String, Integer> workerAssignments = new HashMap<>();
    for (Function.Assignment assignment : newAssignments) {
        Integer count = workerAssignments.get((assignment.getWorkerId()));
        if (count == null) {
            count = 0;
        }
        count++;
        workerAssignments.put(assignment.getWorkerId(), count);
    }
    Assert.assertEquals(workerAssignments.size(), 2);
    for (Map.Entry<String, Integer> entry : workerAssignments.entrySet()) {
        Assert.assertEquals(entry.getValue().intValue(), 3);
    }
}

@Test
public void testSchedule() throws Exception {
    List<Function.FunctionMetaData> functionMetaDataList = new LinkedList<>();
    long version = 5;
    Function.FunctionMetaData function1 = Function.FunctionMetaData.newBuilder().setFunctionDetails(Function.FunctionDetails.newBuilder().setName("func-1").setNamespace("namespace-1").setTenant("tenant-1").setParallelism(1)).setVersion(version).build();
    functionMetaDataList.add(function1);
    doReturn(functionMetaDataList).when(functionMetaDataManager).getAllFunctionMetaData();
    ThreadRuntimeFactory factory = mock(ThreadRuntimeFactory.class);
