@Test
public void testIndexDelete() throws Exception {
    String index = "myindex-" + UUID.randomUUID();
    try (ElasticSearchClient client = new ElasticSearchClient(new ElasticSearchConfig().setElasticSearchUrl("http://" + container.getHttpHostAddress()).setIndexName(index), mock(SinkContext.class))) {
