@Test
public void testBulkRetry() throws Exception {
    try (ElasticToxiproxiContainer toxiproxy = new ElasticToxiproxiContainer(container, network)) {
        toxiproxy.start();
        final String index = "indexbulktest-" + UUID.randomUUID();
        ElasticSearchConfig config = new ElasticSearchConfig().setElasticSearchUrl("http://" + toxiproxy.getHttpHostAddress()).setIndexName(index).setBulkEnabled(true).setMaxRetries(1000).setBulkActions(2).setRetryBackoffInMs(100).// disabled, we want to have full control over flush() method
        setBulkFlushIntervalInMs(-1);
        try (ElasticSearchClient client = new ElasticSearchClient(config, mock(SinkContext.class))) {
            try {
                assertTrue(client.createIndexIfNeeded(index));
                MockRecord<GenericObject> mockRecord = new MockRecord<>();
                client.bulkIndex(mockRecord, Pair.of("1", "{\"a\":1}"));
                client.bulkIndex(mockRecord, Pair.of("2", "{\"a\":2}"));
                assertEquals(mockRecord.getAcked(), 2);
                assertEquals(mockRecord.getFailed(), 0);
                assertEquals(client.getRestClient().totalHits(index), 2);
                log.info("starting the toxic");
                toxiproxy.getProxy().setConnectionCut(false);
                toxiproxy.getProxy().toxics().latency("elasticpause", ToxicDirection.DOWNSTREAM, 15000);
                toxiproxy.removeToxicAfterDelay("elasticpause", 15000);
                client.bulkIndex(mockRecord, Pair.of("3", "{\"a\":3}"));
                assertEquals(mockRecord.getAcked(), 2);
                assertEquals(mockRecord.getFailed(), 0);
                assertEquals(client.getRestClient().totalHits(index), 2);
                client.flush();
                assertEquals(mockRecord.getAcked(), 3);
                assertEquals(mockRecord.getFailed(), 0);
                assertEquals(client.getRestClient().totalHits(index), 3);
            } finally {
                client.getRestClient().deleteIndex(index);
            }
        }
    }
}

@Test
public void testBulkBlocking() throws Exception {
    try (ElasticToxiproxiContainer toxiproxy = new ElasticToxiproxiContainer(container, network)) {
        toxiproxy.start();
        final String index = "indexblocking-" + UUID.randomUUID();
        ElasticSearchConfig config = new ElasticSearchConfig().setElasticSearchUrl("http://" + toxiproxy.getHttpHostAddress()).setIndexName(index).setBulkEnabled(true).setMaxRetries(1000).setBulkActions(2).setBulkConcurrentRequests(2).setRetryBackoffInMs(100).setBulkFlushIntervalInMs(10000);
        try (ElasticSearchClient client = new ElasticSearchClient(config, mock(SinkContext.class))) {
            assertTrue(client.createIndexIfNeeded(index));
            try {
                MockRecord<GenericObject> mockRecord = new MockRecord<>();
                for (int i = 1; i <= 5; i++) {
                    client.bulkIndex(mockRecord, Pair.of(Integer.toString(i), "{\"a\":" + i + "}"));
                }
                Awaitility.await().untilAsserted(() -> {
                    assertThat("acked record", mockRecord.getAcked(), greaterThanOrEqualTo(4));
                    assertEquals(mockRecord.getFailed(), 0);
                    assertThat("totalHits", client.getRestClient().totalHits(index), greaterThanOrEqualTo(4L));
                });
                client.flush();
                Awaitility.await().untilAsserted(() -> {
                    assertEquals(mockRecord.getFailed(), 0);
                    assertEquals(mockRecord.getAcked(), 5);
                    assertEquals(client.getRestClient().totalHits(index), 5);
                });
                log.info("starting the toxic");
                toxiproxy.getProxy().setConnectionCut(false);
                toxiproxy.getProxy().toxics().latency("elasticpause", ToxicDirection.DOWNSTREAM, 30000);
                toxiproxy.removeToxicAfterDelay("elasticpause", 30000);
                long start = System.currentTimeMillis();
                // 11th bulkIndex is blocking because we have 2 pending requests, and the 3rd request is blocked.
                for (int i = 6; i <= 15; i++) {
                    client.bulkIndex(mockRecord, Pair.of(Integer.toString(i), "{\"a\":" + i + "}"));
                    log.info("{} index {}", System.currentTimeMillis(), i);
                }
                long elapsed = System.currentTimeMillis() - start;
                log.info("elapsed = {}", elapsed);
                // bulkIndex was blocking while elasticsearch was down or busy
                assertTrue(elapsed > 29000);
                Awaitility.await().untilAsserted(() -> {
                    assertEquals(mockRecord.getAcked(), 15);
                    assertEquals(mockRecord.getFailed(), 0);
                });
            } finally {
                client.getRestClient().deleteIndex(index);
            }
        }
    }
}

@Test
public void testBulkIndexAndDelete() throws Exception {
    final String index = "indexbulktest-" + UUID.randomUUID();
    ElasticSearchConfig config = new ElasticSearchConfig().setElasticSearchUrl("http://" + container.getHttpHostAddress()).setIndexName(index).setBulkEnabled(true).setBulkActions(10).setBulkFlushIntervalInMs(-1L);
    try (ElasticSearchClient client = new ElasticSearchClient(config, mock(SinkContext.class))) {
        assertTrue(client.createIndexIfNeeded(index));
        MockRecord<GenericObject> mockRecord = new MockRecord<>();
        for (int i = 0; i < 5; i++) {
            client.bulkIndex(mockRecord, Pair.of("key" + i, "{\"a\":" + i + "}"));
            client.bulkDelete(mockRecord, "key" + i);
        }
        assertEquals(mockRecord.getAcked(), 10);
        assertEquals(mockRecord.getFailed(), 0);
        assertEquals(client.getRestClient().totalHits(index), 0);
        // no effect
        client.flush();
        assertEquals(mockRecord.getAcked(), 10);
    }
}

@Test
public void testIndexKeepNulls() throws Exception {
    final String index = "indexnulls";
    ElasticSearchConfig config = new ElasticSearchConfig().setElasticSearchUrl("http://" + container.getHttpHostAddress()).setIndexName(index);
    try (ElasticSearchClient client = new ElasticSearchClient(config, mock(SinkContext.class))) {
        MockRecord<GenericObject> mockRecord = new MockRecord<>();
        client.indexDocument(mockRecord, Pair.of("key0", "{\"a\":1,\"b\":null}"));
        final Map<String, Object> sourceAsMap;
        if (elasticImageName.equals(ELASTICSEARCH_8)) {
            final ElasticSearchJavaRestClient restClient = (ElasticSearchJavaRestClient) client.getRestClient();
            sourceAsMap = restClient.search(index, "*:*").hits().hits().get(0).source();
        } else {
            final OpenSearchHighLevelRestClient restClient = (OpenSearchHighLevelRestClient) client.getRestClient();
            sourceAsMap = restClient.search(index, "*:*").getHits().getHits()[0].getSourceAsMap();
        }
        assertEquals(sourceAsMap.get("a"), 1);
        assertTrue(sourceAsMap.containsKey("b"));
        assertNull(sourceAsMap.get("b"));
    }
}

