public void testOpenAndWrite() throws Exception {
    message = mock(MessageImpl.class);
    GenericSchema<GenericRecord> genericAvroSchema;
    // prepare a cpu Record
    Cpu cpu = new Cpu();
    cpu.setMeasurement("cpu");
