        urLedgerMgr.disableLedgerReplication();
        fail("Must throw exception, since AutoRecovery is already disabled");
    } catch (UnavailableException e) {
        assertTrue("AutoRecovery is not disabled previously!", e.getCause().getCause() instanceof MetadataStoreException.BadVersionException);
    }
    urLedgerMgr.enableLedgerReplication();
    try {
        urLedgerMgr.enableLedgerReplication();
        fail("Must throw exception, since AutoRecovery is already enabled");
    } catch (UnavailableException e) {
        assertTrue("AutoRecovery is not enabled previously!", e.getCause().getCause() instanceof MetadataStoreException.NotFoundException);
    }
}

