    BookieId replicaToKill = lh.getLedgerMetadata().getAllEnsembles().get(0L).get(2);
    LOG.info("Killing last bookie, {}, in ensemble {}", replicaToKill, lh.getLedgerMetadata().getAllEnsembles().get(0L));
    killBookie(replicaToKill);
    startNewBookie();
    // ensure auditor runs
    getAuditor(10, TimeUnit.SECONDS).submitAuditTask().get();
    assertTrue("Should be marked as underreplicated", latch.await(5, TimeUnit.SECONDS));
    latch = new CountDownLatch(1);
    // should be marked as replicated
    Stat s = watchUrLedgerNode(urZNode, latch);
    if (s != null) {
        assertTrue("Should be marked as replicated", latch.await(15, TimeUnit.SECONDS));
    }
    replicaToKill = lh.getLedgerMetadata().getAllEnsembles().get(0L).get(1);
    LOG.info("Killing second bookie, {}, in ensemble {}", replicaToKill, lh.getLedgerMetadata().getAllEnsembles().get(0L));
    killBookie(replicaToKill);
    // ensure auditor runs
    getAuditor(10, TimeUnit.SECONDS).submitAuditTask().get();
    assertTrue("Should be marked as underreplicated", latch.await(5, TimeUnit.SECONDS));
    latch = new CountDownLatch(1);
    // should be marked as replicated
    s = watchUrLedgerNode(urZNode, latch);
    startNewBookie();
    // ensure auditor runs
    getAuditor(10, TimeUnit.SECONDS).submitAuditTask().get();
    if (s != null) {
        assertTrue("Should be marked as replicated", latch.await(20, TimeUnit.SECONDS));
    }
    // should be able to open ledger without issue
    bkc.openLedger(lh.getId(), DigestType.CRC32, PASSWD);
}

