@Test
public void testAutoRecoveryAlongWithBookieServers() throws Exception {
    LedgerHandle lh = bkc.createLedger(3, 3, BookKeeper.DigestType.CRC32, "testpasswd".getBytes());
    byte[] testData = "testBuiltAutoRecovery".getBytes();
    for (int i = 0; i < 10; i++) {
