@Test
public void testReplicationStats() throws Exception {
    BiConsumer<Boolean, ReplicationWorker> checkReplicationStats = (first, rw) -> {
        try {
            final Method rereplicate = rw.getClass().getDeclaredMethod("rereplicate");
            rereplicate.setAccessible(true);
            final Object result = rereplicate.invoke(rw);
            final Field statsLoggerField = rw.getClass().getDeclaredField("statsLogger");
            statsLoggerField.setAccessible(true);
            final TestStatsLogger statsLogger = (TestStatsLogger) statsLoggerField.get(rw);
            final Counter numDeferLedgerLockReleaseOfFailedLedgerCounter = statsLogger.getCounter(ReplicationStats.NUM_DEFER_LEDGER_LOCK_RELEASE_OF_FAILED_LEDGER);
            final Counter numLedgersReplicatedCounter = statsLogger.getCounter(ReplicationStats.NUM_FULL_OR_PARTIAL_LEDGERS_REPLICATED);
            final Counter numNotAdheringPlacementLedgersCounter = statsLogger.getCounter(ReplicationStats.NUM_NOT_ADHERING_PLACEMENT_LEDGERS_REPLICATED);
            assertEquals("NUM_DEFER_LEDGER_LOCK_RELEASE_OF_FAILED_LEDGER", 1, numDeferLedgerLockReleaseOfFailedLedgerCounter.get().longValue());
            if (first) {
                assertFalse((boolean) result);
                assertEquals("NUM_FULL_OR_PARTIAL_LEDGERS_REPLICATED", 0, numLedgersReplicatedCounter.get().longValue());
                assertEquals("NUM_NOT_ADHERING_PLACEMENT_LEDGERS_REPLICATED", 0, numNotAdheringPlacementLedgersCounter.get().longValue());
            } else {
                assertTrue((boolean) result);
                assertEquals("NUM_FULL_OR_PARTIAL_LEDGERS_REPLICATED", 1, numLedgersReplicatedCounter.get().longValue());
                assertEquals("NUM_NOT_ADHERING_PLACEMENT_LEDGERS_REPLICATED", 1, numNotAdheringPlacementLedgersCounter.get().longValue());
            }
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    };
    testRepairedNotAdheringPlacementPolicyLedgerFragments(RackawareEnsemblePlacementPolicy.class, checkReplicationStats);
}

