public void testNetworkDelayWithBkZkManager() throws Throwable {
    final String zksConnectionString = zks.getConnectionString();
    final String ledgersRoot = "/test/ledgers-" + UUID.randomUUID();
    // prepare registration manager
    @Cleanup
