    CompletableFuture<Stat> f2 = store.put(key1 + "/b", new byte[0], Optional.of(1L));
    // Should succeed
    CompletableFuture<Stat> f3 = store.put(key1 + "/c", new byte[0], Optional.of(-1L));
    // Should fail
    CompletableFuture<Void> f4 = store.delete(key1 + "/d", Optional.empty());
    assertTrue(f1.join().getVersion() >= 0L);
    assertTrue(f1.join().isFirstVersion());
    try {
        f2.join();
    } catch (CompletionException ce) {
        assertEquals(ce.getCause().getClass(), BadVersionException.class);
    }
    assertTrue(f3.join().getVersion() >= 0L);
    assertTrue(f3.join().isFirstVersion());
    try {
        f4.join();
    } catch (CompletionException ce) {
        assertEquals(ce.getCause().getClass(), NotFoundException.class);
    }
}

