        store.getChildren("/a").get();
        fail();
    } catch (Exception e) {
        assertTrue(e.getCause() instanceof MetadataStoreException.AlreadyClosedException);
    }
    try {
        store.exists("/a").get();
        fail();
    } catch (Exception e) {
        assertTrue(e.getCause() instanceof MetadataStoreException.AlreadyClosedException);
    }
}

