    PackageMetadata metadata = PackageMetadata.builder().description("test package metadata serialize and deserialize flow").createTime(System.currentTimeMillis()).contact("test@apache.org").modificationTime(System.currentTimeMillis() + 1000).properties(properties).build();
    byte[] metadataSerialized = PackageMetadataUtil.toBytes(metadata);
    try {
        PackageMetadata deSerializedMetadata = PackageMetadataUtil.fromBytes(metadataSerialized);
        Assert.assertEquals(metadata, deSerializedMetadata);
