/**
 * <pre>
 * It verifies e2e tls + Authentication + Authorization (client -> proxy -> broker>
 *
 * 1. client connects to proxy over tls and pass auth-data
 * 2. proxy authenticate client and retrieve client-role
 *    and send it to broker as originalPrincipal over tls
 * 3. client creates producer/consumer via proxy
 * 4. broker authorize producer/consumer create request using originalPrincipal
 *
 * </pre>
 *
 * @throws Exception
 */
@SuppressWarnings("deprecation")
@Test
public void testTlsSyncProducerAndConsumer() throws Exception {
    log.info("-- Starting {} test --", methodName);
    final String proxyServiceUrl = proxyService.getServiceUrlTls();
    Map<String, String> authParams = Maps.newHashMap();
    authParams.put("tlsCertFile", TLS_CLIENT_CERT_FILE_PATH);
    authParams.put("tlsKeyFile", TLS_CLIENT_KEY_FILE_PATH);
    Authentication authTls = new AuthenticationTls();
    authTls.configure(authParams);
    // create a client which connects to proxy over tls and pass authData
    @Cleanup
    PulsarClient proxyClient = createPulsarClient(authTls, proxyServiceUrl);
    admin.clusters().createCluster(configClusterName, ClusterData.builder().serviceUrl(brokerUrl.toString()).serviceUrlTls(brokerUrlTls.toString()).brokerServiceUrl(pulsar.getBrokerServiceUrl()).brokerServiceUrlTls(pulsar.getBrokerServiceUrlTls()).build());
    admin.tenants().createTenant("my-property", new TenantInfoImpl(Sets.newHashSet("appid1", "appid2"), Sets.newHashSet("test")));
    admin.namespaces().createNamespace("my-property/my-ns", Sets.newHashSet("test"));
    Consumer<byte[]> consumer = proxyClient.newConsumer().topic("persistent://my-property/my-ns/my-topic1").subscriptionName("my-subscriber-name").subscribe();
    Producer<byte[]> producer = proxyClient.newProducer(Schema.BYTES).topic("persistent://my-property/my-ns/my-topic1").create();
    final int msgs = 10;
    for (int i = 0; i < msgs; i++) {
        String message = "my-message-" + i;
        producer.send(message.getBytes());
    }
    Message<byte[]> msg = null;
    Set<String> messageSet = new HashSet<>();
    int count = 0;
    for (int i = 0; i < 10; i++) {
        msg = consumer.receive(5, TimeUnit.SECONDS);
        String receivedMessage = new String(msg.getData());
        log.debug("Received message: [{}]", receivedMessage);
        String expectedMessage = "my-message-" + i;
        testMessageOrderAndDuplicates(messageSet, receivedMessage, expectedMessage);
        count++;
    }
    // Acknowledge the consumption of all messages at once
    Assert.assertEquals(msgs, count);
    consumer.acknowledgeCumulative(msg);
    consumer.close();
    log.info("-- Exiting {} test --", methodName);
}

@Test
void testAuthentication() throws Exception {
    log.info("-- Starting {} test --", methodName);
    // Step 1: Create Admin Client
    updateAdminClient();
    // create a client which connects to proxy and pass authData
    String namespaceName = "my-property/my-ns";
    String topicName = "persistent://my-property/my-ns/my-topic1";
    String subscriptionName = "my-subscriber-name";
    // expires after 60 seconds
    String clientAuthParams = "entityType:client,expiryTime:" + (System.currentTimeMillis() + 60 * 1000);
    // expires after 60 seconds
    String proxyAuthParams = "entityType:proxy,expiryTime:" + (System.currentTimeMillis() + 60 * 1000);
    admin.namespaces().grantPermissionOnNamespace(namespaceName, "proxy", Sets.newHashSet(AuthAction.consume, AuthAction.produce));
    admin.namespaces().grantPermissionOnNamespace(namespaceName, "client", Sets.newHashSet(AuthAction.consume, AuthAction.produce));
    // Step 2: Try to use proxy Client as a normal Client - expect exception
    ProxyConfiguration proxyConfig = new ProxyConfiguration();
    proxyConfig.setAuthenticationEnabled(true);
    proxyConfig.setServicePort(Optional.of(0));
    proxyConfig.setBrokerProxyAllowedTargetPorts("*");
    proxyConfig.setWebServicePort(Optional.of(0));
    proxyConfig.setBrokerServiceURL(pulsar.getBrokerServiceUrl());
    proxyConfig.setClusterName(CLUSTER_NAME);
    proxyConfig.setBrokerClientAuthenticationPlugin(BasicAuthentication.class.getName());
    proxyConfig.setBrokerClientAuthenticationParameters(proxyAuthParams);
    Set<String> providers = new HashSet<>();
    providers.add(BasicAuthenticationProvider.class.getName());
    proxyConfig.setAuthenticationProviders(providers);
    proxyConfig.setForwardAuthorizationCredentials(true);
    AuthenticationService authenticationService = new AuthenticationService(PulsarConfigurationLoader.convertFrom(proxyConfig));
    @Cleanup
    ProxyService proxyService = new ProxyService(proxyConfig, authenticationService);
    proxyService.start();
    final String proxyServiceUrl = proxyService.getServiceUrl();
    // Step 3: Pass correct client params and use multiple connections
    @Cleanup
    PulsarClient proxyClient = createPulsarClient(proxyServiceUrl, clientAuthParams, 3);
    proxyClient.newProducer(Schema.BYTES).topic(topicName).create();
    proxyClient.newProducer(Schema.BYTES).topic(topicName).create();
    proxyClient.newProducer(Schema.BYTES).topic(topicName).create();
    // Step 4: Ensure that all client contexts share the same auth provider
    Assert.assertTrue(proxyService.getClientCnxs().size() >= 3, "expect at least 3 clients");
    proxyService.getClientCnxs().stream().forEach((cnx) -> {
        Assert.assertSame(cnx.authenticationProvider, proxyService.getAuthenticationService().getAuthenticationProvider("BasicAuthentication"));
    });
}

@Test
public void testConfigFileDefaults() throws Exception {
    try (FileInputStream stream = new FileInputStream("../conf/proxy.conf")) {
        final ProxyConfiguration javaConfig = PulsarConfigurationLoader.create(new Properties(), ProxyConfiguration.class);
        final ProxyConfiguration fileConfig = PulsarConfigurationLoader.create(stream, ProxyConfiguration.class);
        List<String> toSkip = Arrays.asList("properties", "class");
        for (PropertyDescriptor pd : Introspector.getBeanInfo(ProxyConfiguration.class).getPropertyDescriptors()) {
            if (pd.getReadMethod() == null || toSkip.contains(pd.getName())) {
                continue;
            }
            final String key = pd.getName();
            final Object javaValue = pd.getReadMethod().invoke(javaConfig);
            final Object fileValue = pd.getReadMethod().invoke(fileConfig);
            assertEquals(fileValue, javaValue, "property '" + key + "' conf/proxy.conf default value doesn't match java default value\nConf: " + fileValue + "\nJava: " + javaValue);
        }
    }
}

