@Test
public void testKeySharedStickyWithStuckConnection() throws Exception {
    @Cleanup
    PulsarClient client = PulsarClient.builder().serviceUrl(proxyService.getServiceUrl()).// keep alive is set to 2 seconds to detect the dead connection on the client side
    // the main focus of the test is to verify that the broker and proxy doesn't get stuck forever
    // when there's a hanging connection from the proxy to the broker and that it doesn't cause issues
    // such as hash range conflicts
    keepAliveInterval(2, TimeUnit.SECONDS).build();
    String topicName = BrokerTestUtil.newUniqueName("persistent://sample/test/local/test-topic");
    @Cleanup
    Consumer<byte[]> consumer = client.newConsumer().topic(topicName).subscriptionName("test-subscription").subscriptionType(SubscriptionType.Key_Shared).keySharedPolicy(KeySharedPolicy.stickyHashRange().ranges(Range.of(0, 65535))).receiverQueueSize(2).isAckReceiptEnabled(true).subscribe();
    Set<String> messages = new HashSet<>();
    try (Producer<byte[]> producer = client.newProducer().topic(topicName).accessMode(ProducerAccessMode.Shared).enableBatching(false).create()) {
        for (int i = 0; i < 10; i++) {
            String message = "test" + i;
            producer.newMessage().value(message.getBytes()).key("A").send();
            messages.add(message);
        }
    }
    int counter = 0;
    while (true) {
        counter++;
        Message<byte[]> msg = consumer.receive(15, TimeUnit.SECONDS);
        if (msg == null) {
            break;
        }
        String msgString = new String(msg.getData());
        log.info("Received message {}", msgString);
        try {
            consumer.acknowledge(msg);
        } catch (PulsarClientException e) {
            log.error("Failed to ack message {}", msgString, e);
        }
        messages.remove(msgString);
        log.info("Remaining messages {}", messages.size());
        if (messages.size() == 0) {
            break;
        }
        if (counter == 2) {
            log.info("Pausing connection between proxy and broker and making further connections from proxy " + "directly to broker");
            useBrokerSocatProxy = false;
            socatContainer.getDockerClient().pauseContainerCmd(socatContainer.getContainerId()).exec();
        }
    }
    Assert.assertEquals(messages.size(), 0);
    Assert.assertEquals(consumer.receive(1, TimeUnit.MILLISECONDS), null);
}

