    String args = String.format(argString, testConsumeTopic, testProduceTopic, pulsar.getBrokerServiceUrl(), testSub, new URL(pulsar.getWebServiceAddress()), authenticationPlugin, authenticationParameters);
    Producer<byte[]> produceToConsumeTopic = pulsarClient.newProducer(Schema.BYTES).producerName("perf-transaction-producer").sendTimeout(0, TimeUnit.SECONDS).topic(testConsumeTopic).create();
    pulsarClient.newConsumer(Schema.BYTES).consumerName("perf-transaction-consumeVerify").topic(testConsumeTopic).subscriptionType(SubscriptionType.Shared).subscriptionName(testSub + "pre").subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).subscribe();
    CountDownLatch countDownLatch = new CountDownLatch(50);
    for (int i = 0; i < 50; i++) {
        produceToConsumeTopic.newMessage().value(("testConsume " + i).getBytes()).sendAsync().thenRun(countDownLatch::countDown);
    }
    countDownLatch.await();
    Thread thread = new Thread(() -> {
        try {
            new PerformanceTransaction().run(args.split(" "));
        } catch (Exception e) {
            e.printStackTrace();
        }
    });
    thread.start();
    thread.join();
    Consumer<byte[]> consumeFromConsumeTopic = pulsarClient.newConsumer(Schema.BYTES).consumerName("perf-transaction-consumeVerify").topic(testConsumeTopic).subscriptionType(SubscriptionType.Shared).subscriptionName(testSub).subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).subscribe();
