@Test(dataProvider = "variedBufferedWriteConfigProvider")
public void testMainProcess(boolean writeWithBatch, boolean readWithBatch) throws Exception {
    HashedWheelTimer transactionTimer = new HashedWheelTimer(new DefaultThreadFactory("transaction-timer"), 1, TimeUnit.MILLISECONDS);
    TxnLogBufferedWriterConfig bufferedWriterConfigForWrite = new TxnLogBufferedWriterConfig();
    bufferedWriterConfigForWrite.setBatchedWriteMaxDelayInMillis(1000 * 3600);
    bufferedWriterConfigForWrite.setBatchedWriteMaxRecords(3);
    bufferedWriterConfigForWrite.setBatchEnabled(writeWithBatch);
    TransactionCoordinatorID transactionCoordinatorID = TransactionCoordinatorID.get(0);
    MLTransactionLogImpl mlTransactionLogForWrite = new MLTransactionLogImpl(TransactionCoordinatorID.get(0), factory, new ManagedLedgerConfig(), bufferedWriterConfigForWrite, transactionTimer, DISABLED_BUFFERED_WRITER_METRICS);
    mlTransactionLogForWrite.initialize().get(3, TimeUnit.SECONDS);
    Map<Integer, List<CompletableFuture<Position>>> expectedMapping = new HashMap<>();
    /**
     * 1. Start 20 transactions, these will eventually be committed.
     *    1-1. new transactions.
     *    1-2. add partition.
     *    1-3. add subscribe.
     * 2. Start 30 transactions, these transactions will never commit, to validate the delete-logic.
     */
    // Add logs: start transaction.
    for (int i = 1; i <= 20; i++) {
        TransactionMetadataEntry transactionLog = new TransactionMetadataEntry();
        transactionLog.setTxnidMostBits(i);
        transactionLog.setTxnidLeastBits(i);
        transactionLog.setMaxLocalTxnId(i);
        transactionLog.setStartTime(i);
        transactionLog.setTimeoutMs(i);
        transactionLog.setMetadataOp(TransactionMetadataEntry.TransactionMetadataOp.NEW);
        CompletableFuture<Position> future = mlTransactionLogForWrite.append(transactionLog);
        expectedMapping.computeIfAbsent(i, k -> new ArrayList<>());
        expectedMapping.get(i).add(future);
    }
    // Add logs: add partition.
    for (int i = 1; i <= 20; i++) {
        TransactionMetadataEntry transactionLog = new TransactionMetadataEntry();
        transactionLog.setTxnidLeastBits(i);
        transactionLog.setMaxLocalTxnId(i);
        transactionLog.setMetadataOp(TransactionMetadataEntry.TransactionMetadataOp.ADD_PARTITION);
        transactionLog.addAllPartitions(Arrays.asList(String.valueOf(i)));
        CompletableFuture<Position> future = mlTransactionLogForWrite.append(transactionLog);
        expectedMapping.computeIfAbsent(i, k -> new ArrayList<>());
        expectedMapping.get(i).add(future);
    }
    // Add logs: add subscription.
    for (int i = 1; i <= 20; i++) {
        TransactionMetadataEntry transactionLog = new TransactionMetadataEntry();
        transactionLog.setTxnidLeastBits(i);
        transactionLog.setMaxLocalTxnId(i);
        transactionLog.setMetadataOp(TransactionMetadataEntry.TransactionMetadataOp.ADD_SUBSCRIPTION);
        Subscription subscription = new Subscription();
        subscription.setSubscription(String.valueOf(i));
        subscription.setTopic(String.valueOf(i));
        transactionLog.addAllSubscriptions(Arrays.asList(subscription));
        CompletableFuture<Position> future = mlTransactionLogForWrite.append(transactionLog);
        expectedMapping.computeIfAbsent(i, k -> new ArrayList<>());
        expectedMapping.get(i).add(future);
    }
    // Add logs: new transactions. These transactions will never commit, to validate the logic of transaction log.
    for (int i = 21; i <= 50; i++) {
        TransactionMetadataEntry transactionLog = new TransactionMetadataEntry();
        transactionLog.setTxnidMostBits(i);
        transactionLog.setTxnidLeastBits(i);
        transactionLog.setMaxLocalTxnId(i);
        transactionLog.setStartTime(i);
        transactionLog.setTimeoutMs(i);
        transactionLog.setMetadataOp(TransactionMetadataEntry.TransactionMetadataOp.NEW);
        CompletableFuture<Position> future = mlTransactionLogForWrite.append(transactionLog);
        expectedMapping.computeIfAbsent(i, k -> new ArrayList<>());
        expectedMapping.get(i).add(future);
    }
    // Waiting all future completed.
    FutureUtil.waitForAll(expectedMapping.values().stream().flatMap(l -> l.stream()).collect(Collectors.toList())).get(2, TimeUnit.SECONDS);
    /**
     * Create a new transaction meta store and execute recover to verify that the txn-mapping built by Recover is as
     * expected. This validates the read and write correct.
     */
    // Create another transaction log for recover.
    TxnLogBufferedWriterConfig bufferedWriterConfigForRecover = new TxnLogBufferedWriterConfig();
    bufferedWriterConfigForRecover.setBatchedWriteMaxDelayInMillis(1000 * 3600);
    bufferedWriterConfigForRecover.setBatchedWriteMaxRecords(3);
    bufferedWriterConfigForRecover.setBatchEnabled(readWithBatch);
    MLTransactionLogImpl mlTransactionLogForRecover = new MLTransactionLogImpl(TransactionCoordinatorID.get(0), factory, new ManagedLedgerConfig(), bufferedWriterConfigForRecover, transactionTimer, DISABLED_BUFFERED_WRITER_METRICS);
    mlTransactionLogForRecover.initialize().get(3, TimeUnit.SECONDS);
    // Recover and verify the txnID and position mappings.
    TransactionTimeoutTracker timeoutTracker = mock(TransactionTimeoutTracker.class);
    MLTransactionSequenceIdGenerator sequenceIdGenerator = mock(MLTransactionSequenceIdGenerator.class);
    TransactionRecoverTracker recoverTracker = mock(TransactionRecoverTracker.class);
    MLTransactionMetadataStore transactionMetadataStoreForRecover = new MLTransactionMetadataStore(transactionCoordinatorID, mlTransactionLogForRecover, timeoutTracker, sequenceIdGenerator, Integer.MAX_VALUE);
    transactionMetadataStoreForRecover.init(recoverTracker).get(2000, TimeUnit.SECONDS);
    Assert.assertEquals(transactionMetadataStoreForRecover.txnMetaMap.size(), expectedMapping.size());
    Iterator<Integer> txnIdSet = expectedMapping.keySet().iterator();
    while (txnIdSet.hasNext()) {
        int txnId = txnIdSet.next();
        List<CompletableFuture<Position>> expectedPositions = expectedMapping.get(txnId);
        List<Position> actualPositions = transactionMetadataStoreForRecover.txnMetaMap.get(Long.valueOf(txnId)).getRight();
        Assert.assertEquals(actualPositions.size(), expectedPositions.size());
        for (int i = 0; i < expectedPositions.size(); i++) {
            Position expectedPosition = expectedPositions.get(i).get(1, TimeUnit.SECONDS);
            Position actualPosition = actualPositions.get(i);
            Assert.assertEquals(actualPosition, expectedPosition);
        }
    }
    /**
     * 1. Commit transactions that create at step-1.
     * 2. Start another 20 transactions, these transactions will never commit, to validate the delete-logic.
     */
    // Add logs: committing.
    for (int i = 1; i <= 20; i++) {
        TransactionMetadataEntry transactionLog = new TransactionMetadataEntry();
        transactionLog.setTxnidLeastBits(i);
        transactionLog.setMaxLocalTxnId(i);
        transactionLog.setExpectedStatus(TxnStatus.OPEN);
        transactionLog.setNewStatus(TxnStatus.COMMITTING);
        transactionLog.setMetadataOp(TransactionMetadataEntry.TransactionMetadataOp.UPDATE);
        CompletableFuture<Position> future = mlTransactionLogForWrite.append(transactionLog);
        expectedMapping.computeIfAbsent(i, k -> new ArrayList<>());
        expectedMapping.get(i).add(future);
    }
    // Add logs: committed.
    for (int i = 1; i <= 20; i++) {
        TransactionMetadataEntry transactionLog = new TransactionMetadataEntry();
        transactionLog.setTxnidLeastBits(i);
        transactionLog.setMaxLocalTxnId(i);
        transactionLog.setExpectedStatus(TxnStatus.COMMITTING);
        transactionLog.setNewStatus(TxnStatus.COMMITTED);
        transactionLog.setMetadataOp(TransactionMetadataEntry.TransactionMetadataOp.UPDATE);
        CompletableFuture<Position> future = mlTransactionLogForWrite.append(transactionLog);
        expectedMapping.computeIfAbsent(i, k -> new ArrayList<>());
        expectedMapping.get(i).add(future);
    }
    // Add logs: new transaction.
    for (int i = 51; i <= 70; i++) {
        TransactionMetadataEntry transactionLog = new TransactionMetadataEntry();
        transactionLog.setTxnidMostBits(i);
        transactionLog.setTxnidLeastBits(i);
        transactionLog.setMaxLocalTxnId(i);
        transactionLog.setStartTime(i);
        transactionLog.setTimeoutMs(i);
        transactionLog.setMetadataOp(TransactionMetadataEntry.TransactionMetadataOp.NEW);
        CompletableFuture<Position> future = mlTransactionLogForWrite.append(transactionLog);
        expectedMapping.computeIfAbsent(i, k -> new ArrayList<>());
        expectedMapping.get(i).add(future);
    }
    // Waiting all callback.
    FutureUtil.waitForAll(expectedMapping.values().stream().flatMap(l -> l.stream()).collect(Collectors.toList())).get(2, TimeUnit.SECONDS);
    // rewind the cursor
    ManagedCursorImpl managedCursorForRecover = (ManagedCursorImpl) transactionMetadataStoreForRecover.getManagedLedger().getCursors().iterator().next();
    /**
     * Rewind the cursor for next-step. *
     */
    managedCursorForRecover.rewind();
    /**
     * Create another transaction meta store and execute recover, assert that the cursor-mark-deleted-position and
     * the cursor-batch-indexes is expected.
     */
    // Create another transaction log for recover.
    MLTransactionLogImpl mlTransactionLogForDelete = new MLTransactionLogImpl(TransactionCoordinatorID.get(0), factory, new ManagedLedgerConfig(), bufferedWriterConfigForRecover, transactionTimer, DISABLED_BUFFERED_WRITER_METRICS);
    mlTransactionLogForDelete.initialize().get(3, TimeUnit.SECONDS);
    MLTransactionMetadataStore transactionMetadataStoreForDelete = new MLTransactionMetadataStore(transactionCoordinatorID, mlTransactionLogForDelete, timeoutTracker, sequenceIdGenerator, Integer.MAX_VALUE);
    transactionMetadataStoreForDelete.init(recoverTracker).get(2000, TimeUnit.SECONDS);
    ManagedCursorImpl managedCursor = (ManagedCursorImpl) mlTransactionLogForDelete.getManagedLedger().getCursors().iterator().next();
    // Calculate expected deleted positions.
    List<Position> expectedDeletedPositions = new ArrayList<>();
    for (int i = 1; i <= 20; i++) {
        expectedDeletedPositions.addAll(expectedMapping.remove(i).stream().map(f -> f.join()).collect(Collectors.toList()));
    }
    expectedDeletedPositions = expectedDeletedPositions.stream().sorted((o1, o2) -> {
        if (o1 instanceof TxnBatchedPositionImpl) {
            TxnBatchedPositionImpl t1 = (TxnBatchedPositionImpl) o1;
            TxnBatchedPositionImpl t2 = (TxnBatchedPositionImpl) o2;
            return ComparisonChain.start().compare(o1.getLedgerId(), o2.getLedgerId()).compare(o1.getEntryId(), o2.getEntryId()).compare(t1.getBatchIndex(), t2.getBatchIndex()).result();
        } else {
            return ComparisonChain.start().compare(o1.getLedgerId(), o2.getLedgerId()).compare(o1.getEntryId(), o2.getEntryId()).result();
        }
    }).collect(Collectors.toList());
    Position markDeletedPosition = null;
    LinkedHashMap<Position, BitSetRecyclable> batchIndexes = null;
    if (expectedDeletedPositions.get(0) instanceof TxnBatchedPositionImpl) {
        Pair<Position, LinkedHashMap<Position, BitSetRecyclable>> pair = calculateBatchIndexes(expectedDeletedPositions.stream().map(p -> (TxnBatchedPositionImpl) p).collect(Collectors.toList()));
        markDeletedPosition = pair.getLeft();
        batchIndexes = pair.getRight();
    } else {
        markDeletedPosition = calculateMarkDeletedPosition(expectedDeletedPositions);
    }
    final Position markDeletedPosition_final = markDeletedPosition;
    // Assert mark deleted position correct.
    Awaitility.await().atMost(2, TimeUnit.SECONDS).until(() -> {
        Position actualMarkDeletedPosition = managedCursor.getMarkDeletedPosition();
        return markDeletedPosition_final.getLedgerId() == actualMarkDeletedPosition.getLedgerId() && markDeletedPosition_final.getEntryId() == actualMarkDeletedPosition.getEntryId();
    });
    // Assert batchIndexes correct.
    if (batchIndexes != null) {
        // calculate last deleted position.
        Map.Entry<Position, BitSetRecyclable> lastOne = batchIndexes.entrySet().stream().reduce((a, b) -> b).get();
        // Wait last one has been deleted from cursor.
        Awaitility.await().atMost(2, TimeUnit.SECONDS).until(() -> {
            long[] ls = managedCursor.getBatchPositionAckSet(lastOne.getKey());
            return Arrays.equals(lastOne.getValue().toLongArray(), ls);
        });
        // Verify batch indexes.
        for (Map.Entry<Position, BitSetRecyclable> entry : batchIndexes.entrySet()) {
            Position p = entry.getKey();
            long[] actualAckSet = managedCursor.getBatchPositionAckSet(p);
            Assert.assertEquals(actualAckSet, entry.getValue().toLongArray());
            entry.getValue().recycle();
        }
    }
    /**
     * cleanup. *
     */
    mlTransactionLogForWrite.closeAsync().get(2, TimeUnit.SECONDS);
    mlTransactionLogForRecover.closeAsync().get(2, TimeUnit.SECONDS);
    mlTransactionLogForDelete.closeAsync().get(2, TimeUnit.SECONDS);
    transactionMetadataStoreForRecover.closeAsync().get(2, TimeUnit.SECONDS);
    transactionMetadataStoreForDelete.closeAsync().get(2, TimeUnit.SECONDS);
    transactionTimer.stop();
}

@Test(dataProvider = "batchSizeAndBatchIndexArgsArray")
public void testSetAckSetByIndex(int batchSize, int batchIndex) {
    // test 1/64
    TxnBatchedPositionImpl txnBatchedPosition = new TxnBatchedPositionImpl(1, 1, batchSize, batchIndex);
    txnBatchedPosition.setAckSetByIndex();
    long[] ls = txnBatchedPosition.getAckSet();
    BitSetRecyclable bitSetRecyclable = BitSetRecyclable.valueOf(ls);
    for (int i = 0; i < batchSize; i++) {
        if (i == batchIndex) {
            Assert.assertFalse(bitSetRecyclable.get(i));
        } else {
            Assert.assertTrue(bitSetRecyclable.get(i));
        }
    }
    bitSetRecyclable.recycle();
}

/**
 * Why is this test needed ？
 * {@link org.apache.bookkeeper.mledger.impl.ManagedCursorImpl} maintains batchIndexes, use {@link Position} or
 * {@link TxnBatchedPositionImpl} as the key. However, different maps may use "param-key.equals(key-in-map)" to
 * determine the contains, or use "key-in-map.equals(param-key)" or use "param-key.compareTo(key-in-map)" or use
 * "key-in-map.compareTo(param-key)" to determine the {@link Map#containsKey(Object)}, the these approaches may
 * return different results.
 * Note: In {@link java.util.concurrent.ConcurrentSkipListMap}, it use the {@link Comparable#compareTo(Object)} to
 *    determine whether the keys are the same. In {@link java.util.HashMap}, it use the
 *    {@link Object#hashCode()} & {@link  Object#equals(Object)} to determine whether the keys are the same.
 */
@Test(dataProvider = "testHashcodeAndEqualsData")
public void testKeyInMap(long ledgerId, long entryId, int batchSize, int batchIndex) {
    // build data.
    Random random = new Random();
    int v = random.nextInt();
    Position position = PositionFactory.create(ledgerId, entryId);
    TxnBatchedPositionImpl txnBatchedPosition = new TxnBatchedPositionImpl(position, batchSize, batchIndex);
    // ConcurrentSkipListMap.
    ConcurrentSkipListMap<Position, Integer> map1 = new ConcurrentSkipListMap<>();
    map1.put(position, v);
    Assert.assertTrue(map1.containsKey(txnBatchedPosition));
    ConcurrentSkipListMap<Position, Integer> map2 = new ConcurrentSkipListMap<>();
    map2.put(txnBatchedPosition, v);
    Assert.assertTrue(map2.containsKey(position));
    // HashMap.
    HashMap<Position, Integer> map3 = new HashMap<>();
    map3.put(position, v);
    Assert.assertTrue(map3.containsKey(txnBatchedPosition));
    HashMap<Position, Integer> map4 = new HashMap<>();
    map4.put(txnBatchedPosition, v);
    Assert.assertTrue(map4.containsKey(position));
    // ConcurrentHashMap.
    ConcurrentHashMap<Position, Integer> map5 = new ConcurrentHashMap<>();
    map5.put(position, v);
    Assert.assertTrue(map5.containsKey(txnBatchedPosition));
    ConcurrentHashMap<Position, Integer> map6 = new ConcurrentHashMap<>();
    map6.put(txnBatchedPosition, v);
    Assert.assertTrue(map6.containsKey(position));
    // LinkedHashMap.
    LinkedHashMap<Position, Integer> map7 = new LinkedHashMap<>();
    map7.put(position, v);
    Assert.assertTrue(map7.containsKey(txnBatchedPosition));
    LinkedHashMap<Position, Integer> map8 = new LinkedHashMap<>();
    map8.put(txnBatchedPosition, v);
    Assert.assertTrue(map8.containsKey(position));
}

/**
 * Why is this test needed ？
 * Make sure that when compare to the "markDeletePosition", it looks like {@link Position}
 * Note: In {@link java.util.concurrent.ConcurrentSkipListMap}, it use the {@link Comparable#compareTo(Object)} to
 *    determine whether the keys are the same. In {@link java.util.HashMap}, it use the
 *    {@link Object#hashCode()} & {@link  Object#equals(Object)} to determine whether the keys are the same.
 */
@Test
public void testCompareTo() {
    Position position = PositionFactory.create(1, 1);
    TxnBatchedPositionImpl txnBatchedPosition = new TxnBatchedPositionImpl(position, 2, 0);
    Assert.assertEquals(position.compareTo(txnBatchedPosition), 0);
    Assert.assertEquals(txnBatchedPosition.compareTo(position), 0);
}

/**
 * Tests all operations from write to callback, including these step:
 *   1. Write many data.
 *   2. Verify callback correct.
 *   3. Read from bookie, verify all data correct.
 *   4. Verify byte buffer that generated by DataSerializer has been released after process finish.
 *   5. Cleanup.
 * Overridden cases: see {@link #mainProcessCasesProvider}.
 *
 * TODO: Additional validation is required:
 *   1. Recycle is handled correctly.
 *   2. ByteBuf generated by data merge before Bookie writes is released correctly, including prefix-ByteBuf and
 *      composite-ByteBuf.
 *   3. Even if executed "bkc.failAfter", also need to verify the data which has already written to bookie.
 */
@Test(dataProvider = "mainProcessCasesProvider", timeOut = 1000 * 10)
public void testMainProcess(int batchedWriteMaxRecords, int batchedWriteMaxSize, int batchedWriteMaxDelayInMillis, boolean batchEnabled, final int writeCmdExecuteCount, int eachDataBytesLen, BookieErrorType bookieErrorType, boolean closeBufferedWriter) throws Exception {
    // Assert args.
    if (BookieErrorType.SOMETIMES_ERROR == bookieErrorType || closeBufferedWriter) {
        if (writeCmdExecuteCount < batchedWriteMaxRecords * 2) {
            throw new IllegalArgumentException("if bookieErrorType is BookieErrorType.SOMETIMES_ERROR or" + " closeBufferedWriter is ture, param-writeCmdExecuteCount max large than" + " param-batchedWriteMaxRecords * 2");
        }
    }
    // Calculate the exactly batch-enabled for assert.
    boolean exactlyBatched = batchEnabled;
    if (batchedWriteMaxSize <= eachDataBytesLen || batchedWriteMaxRecords <= 1) {
        exactlyBatched = false;
    }
    /**
     * Create components for tests.
     *  - managedLedger
     *  - managedCursor
     *  - orderedExecutor
     *  - orderedExecutor
     *  - scheduledExecutorService
     *  - dataSerializer
     */
    ManagedLedger managedLedger = factory.open("txn_test_ledger");
    ManagedCursor managedCursor = managedLedger.openCursor("txn_test_cursor");
    if (BookieErrorType.ALWAYS_ERROR == bookieErrorType) {
        managedLedger = Mockito.spy(managedLedger);
        managedCursor = Mockito.spy(managedCursor);
        failureManagedLedger(managedLedger);
    } else if (BookieErrorType.SOMETIMES_ERROR == bookieErrorType) {
        bkc.failAfter(1, BKException.Code.NotEnoughBookiesException);
        metadataStore.setAlwaysFail(new MetadataStoreException.BadVersionException(""));
    }
    HashedWheelTimer transactionTimer = new HashedWheelTimer(new DefaultThreadFactory("transaction-timer"), 1, TimeUnit.MILLISECONDS);
    JsonDataSerializer dataSerializer = new JsonDataSerializer(eachDataBytesLen);
    /**
     * Execute test task.
     *   1. Write many times.
     *   2. Store the param-context and param-position of callback function for verify.
     */
    // Create TxLogBufferedWriter.
    TxnLogBufferedWriter txnLogBufferedWriter = new TxnLogBufferedWriter<Integer>(managedLedger, ((ManagedLedgerImpl) managedLedger).getExecutor(), transactionTimer, dataSerializer, batchedWriteMaxRecords, batchedWriteMaxSize, batchedWriteMaxDelayInMillis, batchEnabled, DISABLED_BUFFERED_WRITER_METRICS);
    // Store the param-context, param-position, param-exception of callback function and complete-count for verify.
    List<Integer> contextArrayOfCallback = Collections.synchronizedList(new ArrayList<>());
    Map<Integer, ManagedLedgerException> exceptionArrayOfCallback = new ConcurrentHashMap<>();
    Map<Position, List<Position>> positionsOfCallback = Collections.synchronizedMap(new LinkedHashMap<>());
    AtomicBoolean anyFlushCompleted = new AtomicBoolean();
    TxnLogBufferedWriter.AddDataCallback callback = new TxnLogBufferedWriter.AddDataCallback() {

        @Override
        public void addComplete(Position position, Object ctx) {
            anyFlushCompleted.set(true);
            if (contextArrayOfCallback.contains(Integer.valueOf(String.valueOf(ctx)))) {
                return;
            }
            contextArrayOfCallback.add((int) ctx);
            Position lightPosition = PositionFactory.create(position.getLedgerId(), position.getEntryId());
            positionsOfCallback.computeIfAbsent(lightPosition, p -> Collections.synchronizedList(new ArrayList<>()));
            positionsOfCallback.get(lightPosition).add(position);
        }

        @Override
        public void addFailed(ManagedLedgerException exception, Object ctx) {
            if (contextArrayOfCallback.contains(Integer.valueOf(String.valueOf(ctx)))) {
                return;
            }
            contextArrayOfCallback.add((int) ctx);
            exceptionArrayOfCallback.put((int) ctx, exception);
        }
    };
    // Write many times.
    int bufferedWriteCloseAtIndex = writeCmdExecuteCount / 2 + new Random().nextInt(writeCmdExecuteCount / 4 + 1) - 1;
    for (int i = 0; i < writeCmdExecuteCount; i++) {
        txnLogBufferedWriter.asyncAddData(i, callback, i);
        // Ensure flush at least once before close buffered writer.
        if (closeBufferedWriter && i == 0) {
            // TODO Clean up this method in next PR, make more easier to read.
        }
        if (closeBufferedWriter && bufferedWriteCloseAtIndex == i) {
            // Wait for any complete callback, avoid unstable.
            Awaitility.await().until(() -> anyFlushCompleted.get());
            txnLogBufferedWriter.close();
        }
    }
    /**
     * Assert callback correct.
     *   1. callback count.
     *   2. callback param-context.
     *   2. if {@param bookieError} is true. verify the ex count.
     *   3. if {@param bookieError} is false. verify the param-position count.
     *   4. if enabled batch-feature, will verify the attributes (batchSize, batchIndex) of callback param-position.
     * Note: {@link TxnLogBufferedWriter#close()} will make callback that fail by state check execute earlier, so if
     *   {@param closeBufferedWriter} is true, we should sort callback-context-array. Other callback-param should
     *   not sort.
     */
    // Assert callback count.
    Awaitility.await().until(() -> contextArrayOfCallback.size() == writeCmdExecuteCount);
    // Assert callback param-context, verify that all callbacks are executed in strict order.
    // If exception occurs, the failure callback be executed earlier. So sorted contextArrayOfCallback.
    if (closeBufferedWriter || bookieErrorType == BookieErrorType.SOMETIMES_ERROR) {
        Collections.sort(contextArrayOfCallback);
    }
    assertEquals(contextArrayOfCallback.size(), writeCmdExecuteCount);
    for (int ctxIndex = 0, successIndex = 0; ctxIndex < writeCmdExecuteCount; ctxIndex++) {
        // When calling `txnLogBufferedWriter.close`, all tasks in the queue will fail immediately, this makes the
        // callback of failure task earlier.
        if (exceptionArrayOfCallback.containsKey(ctxIndex)) {
            continue;
        }
        assertEquals(contextArrayOfCallback.get(successIndex).intValue(), ctxIndex);
        successIndex++;
    }
    // if {@param bookieError} is true. verify the ex count.
    // if {@param bookieError} is false. verify the param-position count.
    int exceptionCallbackCount = exceptionArrayOfCallback.size();
    int positionCallbackCount = (int) positionsOfCallback.values().stream().flatMap(l -> l.stream()).count();
    if (BookieErrorType.SOMETIMES_ERROR == bookieErrorType || closeBufferedWriter) {
        assertEquals(exceptionCallbackCount + positionCallbackCount, writeCmdExecuteCount);
    } else if (BookieErrorType.NO_ERROR == bookieErrorType) {
        assertEquals(positionCallbackCount, writeCmdExecuteCount);
    } else {
        assertEquals(exceptionCallbackCount, writeCmdExecuteCount);
    }
    // if enabled batch-feature, will verify the attributes (batchSize, batchIndex) of callback param-position.
    if (exactlyBatched && BookieErrorType.ALWAYS_ERROR != bookieErrorType) {
        Iterator<List<Position>> callbackPositionIterator = positionsOfCallback.values().iterator();
        List<String> exactlyFlushedDataArray = dataSerializer.getGeneratedJsonArray();
        for (int batchedEntryIndex = 0; batchedEntryIndex < exactlyFlushedDataArray.size() - exceptionCallbackCount; batchedEntryIndex++) {
            String json = exactlyFlushedDataArray.get(batchedEntryIndex);
            List<Integer> batchedData = JsonDataSerializer.deserializeMergedData(json);
            List<Position> innerPositions = callbackPositionIterator.next();
            for (int i = 0; i < batchedData.size(); i++) {
                TxnBatchedPositionImpl innerPosition = (TxnBatchedPositionImpl) innerPositions.get(i);
                assertEquals(innerPosition.getBatchSize(), batchedData.size());
                assertEquals(innerPosition.getBatchIndex(), i);
            }
        }
    }
    /**
     * Read entries from Bookie, Assert all data and position correct.
     *   1. Assert the data of the read matches the data write.
     *   2. Assert the position of the read matches the position of the callback.
     *   3. Assert callback count equals entry count.
     * Note: after call {@link PulsarMockBookKeeper#failAfter}, the managed ledger could not execute read entries
     *       anymore, so when {@param bookieErrorType} equals {@link BookieErrorType.SOMETIMES_ERROR}, ski verify.
     * Note2: Verify that all entry was written in strict order.
     */
    if (BookieErrorType.NO_ERROR == bookieErrorType) {
        Iterator<Position> callbackPositionIterator = positionsOfCallback.keySet().iterator();
        List<String> dataArrayWrite = dataSerializer.getGeneratedJsonArray();
        int entryCounter = 0;
        while (managedCursor.hasMoreEntries()) {
            List<Entry> entries = managedCursor.readEntries(1);
            if (entries == null || entries.isEmpty()) {
                continue;
            }
            for (int m = 0; m < entries.size(); m++) {
                // Get data read.
                Entry entry = entries.get(m);
                // Assert the position of the read matches the position of the callback.
                Position callbackPosition = callbackPositionIterator.next();
                assertEquals(entry.getLedgerId(), callbackPosition.getLedgerId());
                assertEquals(entry.getEntryId(), callbackPosition.getEntryId());
                if (exactlyBatched) {
                    // Get expected entry data from cache of DataSerializer.
                    String expectEntryData = dataArrayWrite.get(entryCounter);
                    ByteBuf entryByteBuf = entry.getDataBuffer();
                    entryByteBuf.skipBytes(4);
                    byte[] entryContentBytes = new byte[entryByteBuf.readableBytes()];
                    entryByteBuf.readBytes(entryContentBytes);
                    String actEntryData = new String(entryContentBytes, Charset.defaultCharset());
                    // Assert the data of the read matches the data write.
                    assertEquals(actEntryData, expectEntryData);
                } else {
                    int entryValue = entry.getDataBuffer().readInt();
                    // Assert the data of the read matches the data write.
                    assertEquals(entryValue, entryCounter);
                }
                entry.release();
                entryCounter++;
            }
        }
        // Assert callback count equals entry count.
        assertEquals(entryCounter, positionsOfCallback.size());
    }
    /**
     * cleanup. *
     */
    txnLogBufferedWriter.close().get();
    // If we already call {@link PulsarMockBookKeeper#failAfter}, the managed ledger could not close anymore.
    if (BookieErrorType.SOMETIMES_ERROR != bookieErrorType) {
        managedLedger.close();
    }
    transactionTimer.stop();
    /**
     * Assert all Byte Buf generated by DataSerializer has been released.
     *   1. Because ManagedLedger holds write cache, some data is not actually released until ManagedLedger is
     *      closed.
     *   2. If we already call {@link PulsarMockBookKeeper#failAfter(int, int)}, the managed ledger could not close
     *      anymore, so when {@param bookieErrorType} equals {@link BookieErrorType.SOMETIMES_ERROR}, skip verify.
     */
    if (BookieErrorType.SOMETIMES_ERROR != bookieErrorType) {
        dataSerializer.assertAllByteBufHasBeenReleased();
    }
    dataSerializer.cleanup();
}

/**
 * Adjustable thresholds: trigger BookKeeper-write when reaching any one of the following conditions
 *     Max size (bytes)
 *     Max records count
 *     Max delay time
 * Tests these three thresholds.
 */
@Test
public void testFlushThresholds() throws Exception {
    // Create components.
    ManagedLedger managedLedger = Mockito.mock(ManagedLedger.class);
    Mockito.when(managedLedger.getName()).thenReturn(mlName);
    OrderedExecutor orderedExecutor = OrderedExecutor.newBuilder().numThreads(5).name("txn-topic-threads").build();
    Executor topicExecutor = orderedExecutor.chooseThread(managedLedger.getName());
    HashedWheelTimer transactionTimer = new HashedWheelTimer(new DefaultThreadFactory("transaction-timer"), 1, TimeUnit.MILLISECONDS);
    SumStrDataSerializer dataSerializer = new SumStrDataSerializer();
    // Cache the data flush to Bookie for Asserts.
    List<Integer> dataArrayFlushedToBookie = Collections.synchronizedList(new ArrayList<>());
    Mockito.doAnswer(new Answer() {

        @Override
        public Object answer(InvocationOnMock invocation) throws Throwable {
            ByteBuf byteBuf = (ByteBuf) invocation.getArguments()[0];
            byteBuf.skipBytes(4);
            dataArrayFlushedToBookie.add(byteBuf.readInt());
            AsyncCallbacks.AddEntryCallback callback = (AsyncCallbacks.AddEntryCallback) invocation.getArguments()[1];
            callback.addComplete(PositionFactory.create(1, 1), byteBuf, invocation.getArguments()[2]);
            return null;
        }
    }).when(managedLedger).asyncAddEntry(Mockito.any(ByteBuf.class), Mockito.any(), Mockito.any());
    // Test threshold: writeMaxDelayInMillis (use timer).
    TxnLogBufferedWriter txnLogBufferedWriter1 = new TxnLogBufferedWriter<>(managedLedger, topicExecutor, transactionTimer, dataSerializer, 32, 1024 * 4, 100, true, DISABLED_BUFFERED_WRITER_METRICS);
    TxnLogBufferedWriter.AddDataCallback callback = Mockito.mock(TxnLogBufferedWriter.AddDataCallback.class);
    txnLogBufferedWriter1.asyncAddData(100, callback, 100);
    Thread.sleep(90);
    // Verify does not refresh ahead of time.
    assertEquals(dataArrayFlushedToBookie.size(), 0);
    Awaitility.await().atMost(2, TimeUnit.SECONDS).until(() -> dataArrayFlushedToBookie.size() == 1);
    assertEquals(dataArrayFlushedToBookie.get(0).intValue(), 100);
    txnLogBufferedWriter1.close().get();
    // Test threshold: batchedWriteMaxRecords.
    TxnLogBufferedWriter txnLogBufferedWriter2 = new TxnLogBufferedWriter<>(managedLedger, topicExecutor, transactionTimer, dataSerializer, 32, 1024 * 4, 10000, true, DISABLED_BUFFERED_WRITER_METRICS);
    for (int i = 0; i < 32; i++) {
        txnLogBufferedWriter2.asyncAddData(1, callback, 1);
    }
    Awaitility.await().atMost(2, TimeUnit.SECONDS).until(() -> dataArrayFlushedToBookie.size() == 2);
    assertEquals(dataArrayFlushedToBookie.get(1).intValue(), 32);
    txnLogBufferedWriter2.close();
    // Test threshold: batchedWriteMaxSize.
    TxnLogBufferedWriter txnLogBufferedWriter3 = new TxnLogBufferedWriter<>(managedLedger, topicExecutor, transactionTimer, dataSerializer, 1024, 64 * 4, 10000, true, DISABLED_BUFFERED_WRITER_METRICS);
    for (int i = 0; i < 64; i++) {
        txnLogBufferedWriter3.asyncAddData(1, callback, 1);
    }
    Awaitility.await().atMost(2, TimeUnit.SECONDS).until(() -> dataArrayFlushedToBookie.size() == 3);
    assertEquals(dataArrayFlushedToBookie.get(2).intValue(), 64);
    txnLogBufferedWriter3.close();
    // Assert all resources released
    dataSerializer.assertAllByteBufHasBeenReleased();
    // clean up.
    dataSerializer.cleanup();
    transactionTimer.stop();
    orderedExecutor.shutdown();
}

/**
 * The use of {@link ScheduledExecutorService#scheduleAtFixedRate(Runnable, long, long, TimeUnit)} for timed
 * tasks in the original implementation caused this problem:
 *   When the writer thread processes slowly, the scheduleAtFixedRate task will continue to append tasks to the
 *   ledger thread, this burdens the ledger thread and leads to an avalanche.
 * This method is used to verify the fix for the above problem. see: https://github.com/apache/pulsar/pull/16679.
 */
@Test
public void testPendingScheduleTriggerTaskCount() throws Exception {
    // Create components.
    ArrayBlockingQueue<Runnable> workQueue = new ArrayBlockingQueue<>(65536 * 2);
    ThreadPoolExecutor threadPoolExecutor = new ThreadPoolExecutor(1, 1, 5, TimeUnit.SECONDS, workQueue);
    HashedWheelTimer transactionTimer = new HashedWheelTimer(new DefaultThreadFactory("transaction-timer"), 1, TimeUnit.MILLISECONDS);
    SumStrDataSerializer dataSerializer = new SumStrDataSerializer();
    // Mock managed ledger and write counter.
    MockedManagedLedger mockedManagedLedger = mockManagedLedgerWithWriteCounter(mlName);
    // Start tests.
    TxnLogBufferedWriter txnLogBufferedWriter = new TxnLogBufferedWriter<>(mockedManagedLedger.managedLedger, threadPoolExecutor, transactionTimer, dataSerializer, 2, 1024 * 4, 1, true, DISABLED_BUFFERED_WRITER_METRICS);
    TxnLogBufferedWriter.AddDataCallback callback = Mockito.mock(TxnLogBufferedWriter.AddDataCallback.class);
    // Append heavier tasks to the Ledger thread.
    AtomicInteger heavierTaskCounter = new AtomicInteger();
    Thread heavierTask = new Thread(() -> {
        while (true) {
            threadPoolExecutor.execute(() -> {
                try {
                    heavierTaskCounter.incrementAndGet();
                    Thread.sleep(19);
                } catch (InterruptedException e) {
                }
                heavierTaskCounter.decrementAndGet();
            });
            try {
                Thread.sleep(20);
            } catch (InterruptedException e) {
                break;
            }
        }
    });
    // Append normal tasks to ledger thread.
    AtomicInteger addAsyncDataTaskCounter = new AtomicInteger();
    AtomicInteger normalFlushCounter = new AtomicInteger();
    Thread normalWriteTask = new Thread(() -> {
        while (true) {
            for (int i = 0; i < 2; i++) {
                addAsyncDataTaskCounter.incrementAndGet();
                txnLogBufferedWriter.asyncAddData(1, callback, 1);
            }
            normalFlushCounter.incrementAndGet();
            try {
                Thread.sleep(10);
            } catch (InterruptedException e) {
                break;
            }
        }
    });
    heavierTask.start();
    normalWriteTask.start();
    // Running 100 millis.
    Thread.sleep(100);
    heavierTask.interrupt();
    normalWriteTask.interrupt();
    /**
     * Calculates the expected maximum number of remaining tasks.
     * 1. add the task async add.
     * 2. add the task flush by records count limit.
     * 3. sub the task already complete.
     * 4. add the heavier task count.
     */
    int maxCountOfRemainingTasks = 0;
    maxCountOfRemainingTasks += normalFlushCounter.get();
    maxCountOfRemainingTasks += addAsyncDataTaskCounter.get();
    maxCountOfRemainingTasks -= mockedManagedLedger.writeCounter.get() * 3;
    maxCountOfRemainingTasks += heavierTaskCounter.get();
    // In addition to the above tasks, is the timing tasks.
    // Assert the timing task count. The above calculation is not accurate, so leave a margin.
    assertTrue(workQueue.size() - maxCountOfRemainingTasks < 10);
    // clean up.
    txnLogBufferedWriter.close().get();
    dataSerializer.cleanup();
    threadPoolExecutor.shutdown();
    transactionTimer.stop();
    threadPoolExecutor.shutdown();
}

