    log.info("Test geo-replication produce and consume for topic {}.", topic);
    @Cleanup
    PulsarClient client1 = PulsarClient.builder().serviceUrl(getGeoCluster().getClusters()[0].getPlainTextServiceUrl()).build();
    @Cleanup
