    @Cleanup
    Consumer<byte[]> c = client2.newConsumer().topic(topic).subscriptionName("geo-sub").subscribe();
    log.info("Successfully create consumer in cluster {} for topic {}.", cluster2, topic);
    for (int i = 0; i < 10; i++) {
