        try (final Consumer<byte[]> consumer = client.newConsumer().topic(topicName).subscriptionName("non-durable-consumer").subscriptionMode(SubscriptionMode.NonDurable).subscriptionInitialPosition(SubscriptionInitialPosition.Earliest).subscribe()) {
            for (int i = 0; i < numMessages; i++) {
                Message<byte[]> msg = consumer.receive();
                assertEquals(new String(msg.getValue(), UTF_8), "message-" + i);
            }
        }
    }
}

