@Test
public void testRedeliveryOfFailedMessages() throws Exception {
    @Cleanup
    PulsarClient pulsarClient = PulsarClient.builder().serviceUrl(pulsarContainer.getPlainTextPulsarBrokerUrl()).build();
    final String encryptionKeyName = "client-rsa.pem";
    final String encryptionKeyVersion = "1.0";
    Map<String, String> metadata = new HashMap<>();
    metadata.put("version", encryptionKeyVersion);
    class EncKeyReader implements CryptoKeyReader {

        EncryptionKeyInfo keyInfo = new EncryptionKeyInfo();

        @Override
        public EncryptionKeyInfo getPublicKey(String keyName, Map<String, String> keyMeta) {
            String CERT_FILE_PATH = "./src/test/resources/certificate/public-key." + keyName;
            if (Files.isReadable(Paths.get(CERT_FILE_PATH))) {
                try {
                    keyInfo.setKey(Files.readAllBytes(Paths.get(CERT_FILE_PATH)));
                    keyInfo.setMetadata(metadata);
                    return keyInfo;
                } catch (IOException e) {
                    Assert.fail("Failed to read certificate from " + CERT_FILE_PATH);
                }
            } else {
                Assert.fail("Certificate file " + CERT_FILE_PATH + " is not present or not readable.");
            }
            return null;
        }

        @Override
        public EncryptionKeyInfo getPrivateKey(String keyName, Map<String, String> keyMeta) {
            String CERT_FILE_PATH = "./src/test/resources/certificate/private-key." + keyName;
            if (Files.isReadable(Paths.get(CERT_FILE_PATH))) {
                try {
                    keyInfo.setKey(Files.readAllBytes(Paths.get(CERT_FILE_PATH)));
                    keyInfo.setMetadata(metadata);
                    return keyInfo;
                } catch (IOException e) {
                    Assert.fail("Failed to read certificate from " + CERT_FILE_PATH);
                }
            } else {
                Assert.fail("Certificate file " + CERT_FILE_PATH + " is not present or not readable.");
            }
            return null;
        }
    }
    class InvalidKeyReader implements CryptoKeyReader {

        EncryptionKeyInfo keyInfo = new EncryptionKeyInfo();

        @Override
        public EncryptionKeyInfo getPublicKey(String keyName, Map<String, String> keyMeta) {
            return null;
        }

        @Override
        public EncryptionKeyInfo getPrivateKey(String keyName, Map<String, String> metadata) {
            return null;
        }
    }
    /*
         * Redelivery functionality guarantees that customer will get a chance to process the message again.
         * In case of shared subscription eventually every client will get a chance to process the message, till one of them acks it.
         *
         * For client with Encryption enabled where in cases like a new production rollout or a buggy client configuration, we might have a mismatch of consumers
         * - few which can decrypt, few which can't (due to errors or cryptoReader not configured).
         *
         * In that case eventually all messages should be acked as long as there is a single consumer who can decrypt the message.
         *
         * Consumer 1 - Can decrypt message
         * Consumer 2 - Has invalid Reader configured.
         * Consumer 3 - Has no reader configured.
         *
         */
    String topicName = "persistent://my-property/my-ns/myrsa-topic2";
    Producer<byte[]> producer = pulsarClient.newProducer().topic(topicName).addEncryptionKey(encryptionKeyName).compressionType(CompressionType.LZ4).cryptoKeyReader(new EncKeyReader()).create();
    @Cleanup
    PulsarClient // Creates new client connection
    newPulsarClient = newPulsarClient(lookupUrl.toString(), 0);
    Consumer<byte[]> consumer1 = newPulsarClient.newConsumer().topicsPattern(topicName).subscriptionName("my-subscriber-name").cryptoKeyReader(new EncKeyReader()).subscriptionType(SubscriptionType.Shared).ackTimeout(1, TimeUnit.SECONDS).subscribe();
    @Cleanup
    PulsarClient // Creates new client connection
    newPulsarClient1 = newPulsarClient(lookupUrl.toString(), 0);
    Consumer<byte[]> consumer2 = newPulsarClient1.newConsumer().topicsPattern(topicName).subscriptionName("my-subscriber-name").cryptoKeyReader(new InvalidKeyReader()).subscriptionType(SubscriptionType.Shared).ackTimeout(1, TimeUnit.SECONDS).subscribe();
    @Cleanup
    PulsarClient // Creates new client connection
    newPulsarClient2 = newPulsarClient(lookupUrl.toString(), 0);
    Consumer<byte[]> consumer3 = newPulsarClient2.newConsumer().topicsPattern(topicName).subscriptionName("my-subscriber-name").subscriptionType(SubscriptionType.Shared).ackTimeout(1, TimeUnit.SECONDS).subscribe();
    int numberOfMessages = 100;
    String message = "my-message";
    // Since messages are in random order
    Set<String> messages = new HashSet<>();
    for (int i = 0; i < numberOfMessages; i++) {
        producer.send((message + i).getBytes());
    }
    // Consuming from consumer 2 and 3
    // no message should be returned since they can't decrypt the message
    Message<byte[]> m = consumer2.receive(3, TimeUnit.SECONDS);
    assertNull(m);
    m = consumer3.receive(3, TimeUnit.SECONDS);
    assertNull(m);
    for (int i = 0; i < numberOfMessages; i++) {
        // All messages would be received by consumer 1
        m = consumer1.receive();
        messages.add(new String(m.getData()));
        consumer1.acknowledge(m);
    }
    // Consuming from consumer 2 and 3 again just to be sure
    // no message should be returned since they can't decrypt the message
    m = consumer2.receive(3, TimeUnit.SECONDS);
    assertNull(m);
    m = consumer3.receive(3, TimeUnit.SECONDS);
    assertNull(m);
    // checking if all messages were received
    for (int i = 0; i < numberOfMessages; i++) {
        assertTrue(messages.contains((message + i)));
    }
    consumer1.close();
    consumer2.close();
    consumer3.close();
}

@Test
public void testEncryptionFailure() throws Exception {
    class EncKeyReader implements CryptoKeyReader {

        EncryptionKeyInfo keyInfo = new EncryptionKeyInfo();

        @Override
        public EncryptionKeyInfo getPublicKey(String keyName, Map<String, String> keyMeta) {
            String CERT_FILE_PATH = "./src/test/resources/certificate/public-key." + keyName;
            if (Files.isReadable(Paths.get(CERT_FILE_PATH))) {
                try {
                    keyInfo.setKey(Files.readAllBytes(Paths.get(CERT_FILE_PATH)));
                    return keyInfo;
                } catch (IOException e) {
                    log.error("Failed to read certificate from {}", CERT_FILE_PATH);
                }
            }
            return null;
        }

        @Override
        public EncryptionKeyInfo getPrivateKey(String keyName, Map<String, String> keyMeta) {
            String CERT_FILE_PATH = "./src/test/resources/certificate/private-key." + keyName;
            if (Files.isReadable(Paths.get(CERT_FILE_PATH))) {
                try {
                    keyInfo.setKey(Files.readAllBytes(Paths.get(CERT_FILE_PATH)));
                    return keyInfo;
                } catch (IOException e) {
                    log.error("Failed to read certificate from {}", CERT_FILE_PATH);
                }
            }
            return null;
        }
    }
    final int totalMsg = 10;
    MessageImpl<byte[]> msg = null;
    Set<String> messageSet = new HashSet<>();
    Consumer<byte[]> consumer = pulsarClient.newConsumer().topic("persistent://my-property/use/myenc-ns/myenc-topic1").subscriptionName("my-subscriber-name").acknowledgmentGroupTime(0, TimeUnit.SECONDS).subscribe();
    // 1. Invalid key name
    try {
        pulsarClient.newProducer().topic("persistent://my-property/use/myenc-ns/myenc-topic1").addEncryptionKey("client-non-existant-rsa.pem").cryptoKeyReader(new EncKeyReader()).create();
        Assert.fail("Producer creation should not suceed if failing to read key");
    } catch (Exception e) {
        // ok
    }
    // 2. Producer with valid key name
    Producer<byte[]> producer = pulsarClient.newProducer().topic("persistent://my-property/use/myenc-ns/myenc-topic1").addEncryptionKey("client-rsa.pem").cryptoKeyReader(new EncKeyReader()).enableBatching(false).messageRoutingMode(MessageRoutingMode.SinglePartition).create();
    for (int i = 0; i < totalMsg; i++) {
        String message = "my-message-" + i;
        producer.send(message.getBytes());
    }
    // 3. KeyReder is not set by consumer
    // Receive should fail since key reader is not setup
    msg = (MessageImpl<byte[]>) consumer.receive(5, TimeUnit.SECONDS);
    assertNull(msg, "Receive should have failed with no keyreader");
    // 4. Set consumer config to consume even if decryption fails
    consumer.close();
    consumer = pulsarClient.newConsumer().topic("persistent://my-property/use/myenc-ns/myenc-topic1").subscriptionName("my-subscriber-name").cryptoFailureAction(ConsumerCryptoFailureAction.CONSUME).acknowledgmentGroupTime(0, TimeUnit.SECONDS).subscribe();
    int msgNum = 0;
    try {
        // Receive should proceed and deliver encrypted message
        msg = (MessageImpl<byte[]>) consumer.receive(5, TimeUnit.SECONDS);
        String receivedMessage = new String(msg.getData());
        String expectedMessage = "my-message-" + msgNum++;
        Assert.assertNotEquals(receivedMessage, expectedMessage, "Received encrypted message " + receivedMessage + " should not match the expected message " + expectedMessage);
        consumer.acknowledgeCumulative(msg);
    } catch (Exception e) {
        e.printStackTrace();
        Assert.fail("Failed to receive message even after ConsumerCryptoFailureAction.CONSUME is set.");
    }
    // 5. Set keyreader and failure action
    consumer.close();
    // Set keyreader
    consumer = pulsarClient.newConsumer().topic("persistent://my-property/use/myenc-ns/myenc-topic1").subscriptionName("my-subscriber-name").cryptoFailureAction(ConsumerCryptoFailureAction.FAIL).cryptoKeyReader(new EncKeyReader()).acknowledgmentGroupTime(0, TimeUnit.SECONDS).subscribe();
    for (int i = msgNum; i < totalMsg - 1; i++) {
        msg = (MessageImpl<byte[]>) consumer.receive(5, TimeUnit.SECONDS);
        // verify that encrypted message contains encryption-context
        msg.getEncryptionCtx().orElseThrow(() -> new IllegalStateException("encryption-ctx not present for encrypted message"));
        String receivedMessage = new String(msg.getData());
        log.debug("Received message: [{}]", receivedMessage);
        String expectedMessage = "my-message-" + i;
        testMessageOrderAndDuplicates(messageSet, receivedMessage, expectedMessage);
    }
    // Acknowledge the consumption of all messages at once
    consumer.acknowledgeCumulative(msg);
    consumer.close();
    // 6. Set consumer config to discard if decryption fails
    consumer.close();
    consumer = pulsarClient.newConsumer().topic("persistent://my-property/use/myenc-ns/myenc-topic1").subscriptionName("my-subscriber-name").cryptoFailureAction(ConsumerCryptoFailureAction.DISCARD).acknowledgmentGroupTime(0, TimeUnit.SECONDS).subscribe();
    // Receive should proceed and discard encrypted messages
    msg = (MessageImpl<byte[]>) consumer.receive(5, TimeUnit.SECONDS);
    assertNull(msg, "Message received even aftet ConsumerCryptoFailureAction.DISCARD is set.");
}

