            assertEquals(toWriteEntry.getLength(), toTestEntry.getLength());
            assertEquals(toWriteEntry.getEntryBuffer(), toTestEntry.getEntryBuffer());
        }
        Assert.assertFalse(toWriteIter.hasNext());
        Assert.assertFalse(toTestIter.hasNext());
    }
