            int ret = inputStream.read(buf);
            for (int i = 0; i < ret; i++) {
                padding[offset++] = buf[i];
            }
            len -= ret;
        }
    }
    ByteBuf paddingBuf = Unpooled.wrappedBuffer(padding);
    IntStream.range(0, paddingBuf.capacity() / 4).forEach(i -> assertEquals(Integer.toHexString(paddingBuf.readInt()), Integer.toHexString(0xFEDCDEAD)));
